_confuse.push(
  { id: "cf1", title: { ja: "限界利益 と 営業利益", en: "Contribution margin vs. operating profit" },
    wrong: { ja: "限界利益＝最終的な儲け、と思ってしまう。", en: "Thinking contribution margin is the final profit." },
    right: { ja: "限界利益は固定費回収前。固定費を引いて初めて営業利益になる。", en: "CM is before fixed cost; operating profit only results after deducting fixed cost." } },
  { id: "cf2", title: { ja: "埋没原価 と 機会原価", en: "Sunk cost vs. opportunity cost" },
    wrong: { ja: "どちらも無視してよい、と混同する。", en: "Treating both as ignorable." },
    right: { ja: "埋没原価は無関連で無視。機会原価は帳簿外でも関連原価として必ず考慮する。", en: "Sunk costs are irrelevant; opportunity costs, though unbooked, must be counted." } },
  { id: "cf3", title: { ja: "固定費 と 直接費", en: "Fixed cost vs. direct cost" },
    wrong: { ja: "固定費＝間接費、変動費＝直接費と一対一で対応づける。", en: "Mapping fixed=indirect and variable=direct one-to-one." },
    right: { ja: "固定/変動（操業度軸）と直接/間接（跡付け軸）は別次元。直接固定費も存在する。", en: "Fixed/variable (behavior) and direct/indirect (traceability) are separate axes; direct fixed costs exist." } },
  { id: "cf4", title: { ja: "予算 と 予測", en: "Budget vs. forecast" },
    wrong: { ja: "予測を達成すべき目標と捉える。", en: "Treating a forecast as a target to hit." },
    right: { ja: "予算は固定した目標、予測は最新情報での着地見込み。予測は更新され続ける。", en: "A budget is a fixed target; a forecast is the latest best estimate and keeps updating." } },
  { id: "cf5", title: { ja: "ROI と RI（残余利益）", en: "ROI vs. Residual Income" },
    wrong: { ja: "ROIが高い事業部ほど常に正しい投資判断をする、と考える。", en: "Assuming high-ROI divisions always invest correctly." },
    right: { ja: "ROI評価は資本コスト超の良い投資を棄却させうる（過少投資）。RIはこれを防ぐ。", en: "ROI evaluation can reject good above-cost investments (underinvestment); RI prevents this." } },
);

/* =========================================================================
/* =========================================================================
 * GLOSSARY
 * ========================================================================= */
_glossary.push(
  {"term":"限界利益","ja":"限界利益（貢献利益）","en":"Contribution Margin","descJa":"売上 − 変動費。固定費の回収と利益の源泉。CVP分析の中核。","descEn":"Sales − variable cost; the source for covering fixed cost and earning profit, central to CVP."},{"term":"限界利益率","ja":"限界利益率","en":"Contribution Margin Ratio","descJa":"限界利益 ÷ 売上。1円の売上が固定費・利益にどれだけ貢献するか。","descEn":"Contribution ÷ sales — how much each sales yen contributes to fixed cost and profit."},{"term":"BEP","ja":"損益分岐点（BEP）","en":"Break-Even Point (BEP)","descJa":"BEP＝Break-Even Point。営業利益がゼロになる売上。固定費 ÷ 限界利益率で算定。","descEn":"The sales level at which operating profit is zero; fixed cost ÷ CM ratio."},{"term":"安全余裕率","ja":"安全余裕率","en":"Margin of Safety","descJa":"(売上 − BEP売上) ÷ 売上。どれだけ売上が落ちても黒字を保てるかの余裕。","descEn":"(Sales − BEP)/Sales — how far sales can fall before a loss."},{"term":"DOL","ja":"経営（営業）レバレッジ係数（DOL）","en":"Degree of Operating Leverage (DOL)","descJa":"DOL＝Degree of Operating Leverage。限界利益 ÷ 営業利益。固定費が大きいほど高く、売上変動が利益を増幅する度合い。","descEn":"Contribution ÷ operating profit; higher with more fixed cost, amplifying how sales swings hit profit."},{"term":"変動費・固定費","ja":"変動費・固定費","en":"Variable / Fixed Cost","descJa":"操業度に比例する費用(変動費)と、一定の費用(固定費)。原価分解の出発点。","descEn":"Costs that scale with activity (variable) vs. costs that stay flat (fixed)."},{"term":"標準原価計算","ja":"標準原価計算","en":"Standard Costing","descJa":"あるべき消費量×標準単価で目標原価を定め、実際との差異を分析して統制する。","descEn":"Setting a target cost as std quantity × std rate and controlling via variances vs. actual."},{"term":"原価差異分析","ja":"原価差異分析","en":"Variance Analysis","descJa":"標準と実際の差を価格系・数量系に分解し、原因と責任を特定する手法。","descEn":"Decomposing standard-vs-actual into price and quantity legs to pinpoint cause and accountability."},{"term":"ABC","ja":"活動基準原価計算（ABC）","en":"Activity-Based Costing (ABC)","descJa":"ABC＝Activity-Based Costing。資源→活動→製品の2段階で間接費を跡づけ、配賦の歪みを減らす。","descEn":"Tracing overhead resources → activities → products in two stages to reduce allocation distortion."},{"term":"ABM","ja":"活動基準管理（ABM）","en":"Activity-Based Management (ABM)","descJa":"ABM＝Activity-Based Management。ABCで見えた活動コストを基に、非付加価値活動の削減や価格改定へつなぐ管理手法。","descEn":"Using ABC's activity costs to cut non-value-added work, reprice, or reshape the mix."},{"term":"TDABC","ja":"時間主導型ABC（TDABC）","en":"Time-Driven Activity-Based Costing (TDABC)","descJa":"TDABC＝Time-Driven ABC。時間方程式で活動コストを配賦する、ABCの簡素化手法。","descEn":"A simplified ABC that allocates activity cost via time equations."},{"term":"原価企画","ja":"原価企画（ターゲット・コスティング）","en":"Target Costing","descJa":"目標価格−目標利益＝許容原価を上流の設計段階で作り込む手法。","descEn":"Designing to an allowable cost = target price − target profit, set upstream at design."},{"term":"スループット会計","ja":"スループット会計","en":"Throughput Accounting","descJa":"制約(ボトルネック)を軸に、スループット(売上−真の変動費)最大化で意思決定する管理会計。","descEn":"Constraint-focused managerial accounting maximizing throughput (sales − truly variable cost)."},{"term":"埋没原価","ja":"埋没原価","en":"Sunk Cost","descJa":"すでに支出済みで意思決定により変わらない過去原価。判断に無関連。","descEn":"An already-incurred past cost, unchanged by the decision — irrelevant to it."},{"term":"機会原価","ja":"機会原価（機会費用）","en":"Opportunity Cost","descJa":"ある案を選ぶことで諦めた最善の代替案の利益。見えない関連原価。","descEn":"The profit of the best alternative forgone by choosing an option — a hidden relevant cost."},{"term":"関連原価","ja":"関連原価（差額原価）","en":"Relevant Cost","descJa":"意思決定で変わる将来の差額原価。埋没原価は関連原価に含めない。","descEn":"Future differential costs that change with the decision; sunk costs are excluded."},{"term":"変動予算","ja":"変動予算（フレキシブル予算）","en":"Flexible Budget","descJa":"実際操業度に組み替えた予算。固定予算より差異分析の精度が高い。","descEn":"A budget flexed to actual activity, giving sharper variance analysis than a static budget."},{"term":"ZBB","ja":"ゼロベース予算（ZBB）","en":"Zero-Based Budgeting (ZBB)","descJa":"ZBB＝Zero-Based Budgeting。前年実績を前提とせず、全費用をゼロから正当化して積み上げる予算手法。","descEn":"Budgeting that justifies every cost from zero rather than basing it on last year's run-rate."},{"term":"ローリング予測","ja":"ローリング予測（ローリング・フォーキャスト）","en":"Rolling Forecast","descJa":"毎期更新し常に先12〜18カ月を見る予測。固定年次予算の陳腐化を補う。","descEn":"A continuously updated forecast always covering 12–18 months ahead."},{"term":"ドライバーベース予測","ja":"ドライバーベース予測","en":"Driver-Based Forecasting","descJa":"売上等を生む少数の主要ドライバーで予測を組み立てる手法。全科目積上げを避ける。","descEn":"Building forecasts from the few key drivers that generate results, not every line."},{"term":"MAPE","ja":"平均絶対パーセント誤差（MAPE）","en":"Mean Absolute Percentage Error (MAPE)","descJa":"MAPE＝Mean Absolute Percentage Error。予測の精度を測る指標。実績に対する誤差率の平均。","descEn":"A forecast-accuracy metric: the average absolute percent error vs. actuals."},{"term":"ROIC","ja":"投下資本利益率（ROIC）","en":"Return on Invested Capital (ROIC)","descJa":"ROIC＝Return on Invested Capital。NOPAT ÷ 投下資本。事業が資本をどれだけ効率的に利益化したか。WACCと比較する。","descEn":"NOPAT ÷ invested capital — how efficiently the business turns capital into profit; compared to WACC."},{"term":"NOPAT","ja":"税引後営業利益（NOPAT）","en":"Net Operating Profit After Tax (NOPAT)","descJa":"NOPAT＝Net Operating Profit After Tax。営業利益×(1−税率)。資本構成に依らない本業の税引後利益。","descEn":"EBIT × (1 − tax rate); after-tax core profit independent of capital structure."},{"term":"WACC","ja":"加重平均資本コスト（WACC）","en":"Weighted Average Cost of Capital (WACC)","descJa":"WACC＝Weighted Average Cost of Capital。負債と資本のコストを構成比で加重平均した資本コスト。","descEn":"The blended cost of debt and equity weighted by their proportions."},{"term":"EVA","ja":"経済的付加価値（EVA）","en":"Economic Value Added (EVA)","descJa":"EVA＝Economic Value Added。NOPAT − 投下資本×WACC。資本コストを超えて稼いだ価値創造額。","descEn":"NOPAT − invested capital × WACC; the value created above the cost of capital."},{"term":"BSC","ja":"バランスト・スコアカード（BSC）","en":"Balanced Scorecard (BSC)","descJa":"BSC＝Balanced Scorecard。財務・顧客・内部プロセス・学習と成長の4視点で戦略を業績管理する枠組み。","descEn":"A framework managing strategy across financial, customer, internal-process, and learning & growth perspectives."},{"term":"CCC","ja":"キャッシュ・コンバージョン・サイクル（CCC）","en":"Cash Conversion Cycle (CCC)","descJa":"CCC＝Cash Conversion Cycle。在庫日数+売上債権日数−仕入債務日数。短いほど運転資金効率が良い。","descEn":"DIO + DSO − DPO; shorter means better working-capital efficiency."},{"term":"デュポン分解","ja":"デュポン分解（デュポン・システム）","en":"DuPont Analysis","descJa":"ROEを純利益率×総資産回転率×財務レバレッジに分解する手法。","descEn":"Decomposing ROE into net margin × asset turnover × financial leverage."},{"term":"FP&A","ja":"財務計画・分析（FP&A）","en":"Financial Planning & Analysis (FP&A)","descJa":"FP&A＝Financial Planning and Analysis。予算・予測・予実分析で経営意思決定を支える財務機能。","descEn":"The finance function of budgeting, forecasting, and variance analysis that supports decisions."},{"term":"Rule of 40","ja":"ルール・オブ・40","en":"Rule of 40","descJa":"SaaS等で『売上成長率＋利益率 ≧ 40%』を健全性の目安とする経験則。","descEn":"A SaaS rule of thumb: revenue growth % + profit margin % should be ≥ 40%."}
);


