function t(lang, key) { const v = UI[key]; return v ? v[lang === "en" ? 1 : 0] : key; }
// ノードの表示ラベル: EN時は英語(en)、JP時は日本語(label)
function nodeLabel(n, lang) { return lang === "en" ? (n.en || n.label) : n.label; }
