// ===== 青基調パレット =====
const BLUE = {
  primary: "#1E63C4",      // メインの青
  deep: "#0C447C",         // 濃い青
  light: "#E6F1FB",        // 淡い青
  mid: "#7FAEDD",          // 中間
};
// 分野アクセント（青の濃淡グラデーション）
const CAT_ORDER = [
  "用語・基礎", "01_コンピュート", "02_ストレージ", "03_データベース", "04_ネットワーク",
  "05_データ分析", "06_AI・生成AI", "07_AI・ML機能", "08_既製AIサービス",
  "09_セキュリティ", "10_管理・移行・料金", "4社の強み",
];
const CAT_HUE = {
  "用語・基礎": "#0C447C", "01_コンピュート": "#114E8E", "02_ストレージ": "#1659A0",
  "03_データベース": "#1B63B2", "04_ネットワーク": "#206DC4", "05_データ分析": "#2E78CC",
  "06_AI・生成AI": "#3C82D4", "07_AI・ML機能": "#4A8CDC", "08_既製AIサービス": "#5896E0",
  "09_セキュリティ": "#1E63C4", "10_管理・移行・料金": "#16518F", "4社の強み": "#0F3F73",
};

const CLOUD_STORE_KEY = "cloud_study_progress_v2";

function shuffle(arr, seed) {
  const a = arr.slice();
  let s = seed;
  for (let i = a.length - 1; i > 0; i--) {
    s = (s * 9301 + 49297) % 233280;
    const j = Math.floor((s / 233280) * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function todayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function dayDiff(a, b) {
  return Math.round((new Date(b) - new Date(a)) / 86400000);
}

const DAILY_GOAL = 20;

// CloudDojoは元々ライトモード設計（白背景×濃い文字）のため、無理にダーク化せず
// 全画面オーバーレイとして表示し、ハブの暗いテーマとの色の衝突を避ける。
function CloudDojoWrapper() {
  const [open, setOpen] = useState(false);

  if (!open) {
    return (
      <div style={{ textAlign: "center", padding: "60px 20px" }}>
        <div style={{ fontSize: 40, marginBottom: 16 }}>☁️</div>
        <div className="gh-display" style={{ fontSize: 18, color: C.text, marginBottom: 8 }}>
          4大クラウド 学習ダッシュボード
        </div>
        <div style={{ fontSize: 12.5, color: C.muted, marginBottom: 24, lineHeight: 1.8 }}>
          AWS・Azure・GCP・OCIを500問のクイズと図解で。全画面表示で開きます。
        </div>
        <button className="gh-btn gh-btn-primary" onClick={() => setOpen(true)} style={{ fontSize: 14, padding: "10px 24px" }}>
          クラウド道場を開く →
        </button>
      </div>
    );
  }

  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 9999,
      background: "#F7F7FA", overflow: "auto",
      ["--color-text-primary"]: "#1A1A2E",
      ["--color-text-secondary"]: "#5A5A6E",
      ["--color-text-tertiary"]: "#8A8A9E",
      ["--color-text-danger"]: "#A32D2D",
      ["--color-text-success"]: "#3B6D11",
      ["--color-background-danger"]: "#FCEBEB",
      ["--color-background-success"]: "#EAF3DE",
      ["--color-border-danger"]: "#A32D2D",
      ["--color-border-success"]: "#3B6D11",
      ["--border-radius-lg"]: "12px",
      ["--border-radius-md"]: "8px",
      ["--font-sans"]: "inherit",
    }}>
      <button
        onClick={() => setOpen(false)}
        style={{
          position: "fixed", top: 16, right: 16, zIndex: 10000,
          background: "#1E63C4", color: "#fff", border: "none", borderRadius: 8,
          padding: "8px 16px", fontSize: 13, fontWeight: 600, cursor: "pointer",
          boxShadow: "0 2px 8px rgba(0,0,0,0.2)", fontFamily: "inherit",
        }}
      >
        ✕ 閉じてハブへ戻る
      </button>
      <div style={{ padding: "18px 18px 24px" }}>
        <CloudDojo />
      </div>
    </div>
  );
}

function CloudDojo() {
  const [tab, setTab] = useState("home");
  const [progress, setProgress] = useState({});
  const [meta, setMeta] = useState({ streak: 0, lastDay: null, dailyDay: null, dailyCount: 0 });
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const r = await window.storage.get(CLOUD_STORE_KEY);
        if (r && r.value) {
          const parsed = JSON.parse(r.value);
          setProgress(parsed.progress || {});
          setMeta(parsed.meta || { streak: 0, lastDay: null, dailyDay: null, dailyCount: 0 });
        }
      } catch (e) { /* first run */ }
      setLoaded(true);
    })();
  }, []);

  const persist = async (nextProgress, nextMeta) => {
    setProgress(nextProgress);
    setMeta(nextMeta);
    try { await window.storage.set(CLOUD_STORE_KEY, JSON.stringify({ progress: nextProgress, meta: nextMeta })); } catch (e) {}
  };

  const recordAnswer = (cat, correct) => {
    const cur = progress[cat] || { correct: 0, attempts: 0 };
    const nextProgress = {
      ...progress,
      [cat]: { correct: cur.correct + (correct ? 1 : 0), attempts: cur.attempts + 1 },
    };
    // ストリーク & デイリー更新
    const t = todayStr();
    let { streak, lastDay, dailyDay, dailyCount } = meta;
    if (dailyDay !== t) { dailyDay = t; dailyCount = 0; }
    dailyCount += 1;
    if (lastDay !== t) {
      if (lastDay && dayDiff(lastDay, t) === 1) streak += 1;
      else streak = 1;
      lastDay = t;
    }
    persist(nextProgress, { streak, lastDay, dailyDay, dailyCount });
  };

  const resetAll = () => persist({}, { streak: 0, lastDay: null, dailyDay: null, dailyCount: 0 });

  const counts = useMemo(() => {
    const c = {};
    BANK.forEach((q) => { c[q.d] = (c[q.d] || 0) + 1; });
    return c;
  }, []);

  const totals = useMemo(() => {
    let att = 0, cor = 0;
    Object.values(progress).forEach((p) => { att += p.attempts || 0; cor += p.correct || 0; });
    return { att, cor, rate: att ? Math.round((cor / att) * 100) : 0 };
  }, [progress]);

  const dailyToday = meta.dailyDay === todayStr() ? meta.dailyCount : 0;

  return (
    <div style={{ fontFamily: "var(--font-sans, sans-serif)", color: "var(--color-text-primary)", maxWidth: 880, margin: "0 auto", padding: "8px 12px 40px" }}>
      <Header tab={tab} setTab={setTab} />
      {!loaded && <p style={{ color: "var(--color-text-tertiary)", fontSize: 14 }}>読み込み中…</p>}
      {loaded && tab === "home" && <Home counts={counts} progress={progress} totals={totals} setTab={setTab} resetAll={resetAll} meta={meta} dailyToday={dailyToday} />}
      {loaded && tab === "quiz" && <Quiz counts={counts} progress={progress} recordAnswer={recordAnswer} />}
      {loaded && tab === "exam" && <Exam recordAnswer={recordAnswer} />}
      {loaded && tab === "diagram" && <Diagrams />}
      {loaded && tab === "interactive" && <Interactive />}
      {loaded && tab === "glossary" && <Glossary />}
    </div>
  );
}

function Header({ tab, setTab }) {
  const tabs = [["home", "進捗"], ["quiz", "クイズ"], ["exam", "模擬試験"], ["diagram", "図解"], ["interactive", "体感学習"], ["glossary", "用語集"]];
  return (
    <div style={{ marginBottom: 18 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "6px 0 2px" }}>
        <div style={{ width: 30, height: 30, borderRadius: 8, background: `linear-gradient(135deg, ${BLUE.primary}, ${BLUE.deep})`, flexShrink: 0 }} />
        <h1 style={{ fontSize: 22, fontWeight: 500, margin: 0, color: BLUE.deep }}>4大クラウド 学習ダッシュボード</h1>
      </div>
      <p style={{ fontSize: 13, color: "var(--color-text-tertiary)", margin: "0 0 14px" }}>AWS・Azure・GCP・OCI を {BANK.length}問のクイズと図解で。進捗は自動保存。</p>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        {tabs.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)} style={{
            padding: "8px 18px", borderRadius: "var(--border-radius-md, 8px)", cursor: "pointer",
            fontSize: 14, fontWeight: tab === k ? 500 : 400,
            background: tab === k ? BLUE.primary : BLUE.light,
            color: tab === k ? "#fff" : BLUE.deep,
            border: `0.5px solid ${tab === k ? BLUE.primary : BLUE.mid}`,
          }}>{label}</button>
        ))}
      </div>
    </div>
  );
}

function pct(p) { return p && p.attempts ? Math.round((p.correct / p.attempts) * 100) : null; }

function Home({ counts, progress, totals, setTab, resetAll, meta, dailyToday }) {
  // 苦手分野: 5回以上回答かつ正答率60%未満
  const weak = CAT_ORDER.filter((c) => {
    const p = progress[c];
    return p && p.attempts >= 5 && pct(p) < 60;
  });
  const goalPct = Math.min(100, Math.round((dailyToday / DAILY_GOAL) * 100));

  return (
    <div>
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 16 }}>
        <Stat label="総回答数" value={totals.att} />
        <Stat label="正解数" value={totals.cor} />
        <Stat label="通算正答率" value={totals.rate + "%"} />
        <Stat label="連続学習日数" value={(meta.streak || 0) + "日"} accent />
      </div>

      {/* デイリー目標 */}
      <div style={{ padding: "14px 16px", borderRadius: "var(--border-radius-lg,12px)", background: BLUE.light, border: `0.5px solid ${BLUE.mid}`, marginBottom: 18 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 8 }}>
          <span style={{ fontSize: 14, fontWeight: 500, color: BLUE.deep }}>今日の目標</span>
          <span style={{ fontSize: 13, color: BLUE.deep }}>{dailyToday} / {DAILY_GOAL} 問{goalPct >= 100 ? "  達成 🎉" : ""}</span>
        </div>
        <div style={{ height: 12, borderRadius: 999, background: "#fff", overflow: "hidden", border: `0.5px solid ${BLUE.mid}` }}>
          <div style={{ width: goalPct + "%", height: "100%", background: `linear-gradient(90deg, ${BLUE.primary}, ${BLUE.deep})`, transition: "width .3s" }} />
        </div>
      </div>

      {/* 苦手分野 */}
      {weak.length > 0 && (
        <div style={{ padding: "12px 16px", borderRadius: "var(--border-radius-lg,12px)", background: "var(--color-background-danger)", border: "0.5px solid var(--color-border-danger)", marginBottom: 18 }}>
          <div style={{ fontSize: 14, fontWeight: 500, color: "var(--color-text-danger)", marginBottom: 6 }}>苦手分野（正答率60%未満）</div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {weak.map((c) => (
              <span key={c} style={{ fontSize: 12, padding: "3px 10px", borderRadius: 999, background: "#fff", color: "var(--color-text-danger)", border: "0.5px solid var(--color-border-danger)" }}>
                {c}（{pct(progress[c])}%）
              </span>
            ))}
          </div>
        </div>
      )}

      <h2 style={{ fontSize: 16, fontWeight: 500, margin: "0 0 10px", color: BLUE.deep }}>分野ごとの習熟度</h2>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {CAT_ORDER.map((cat) => {
          const p = progress[cat]; const rate = pct(p); const hue = CAT_HUE[cat];
          const isWeak = p && p.attempts >= 5 && rate < 60;
          return (
            <div key={cat} style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <span style={{ width: 150, fontSize: 13, color: isWeak ? "var(--color-text-danger)" : "var(--color-text-secondary)", flexShrink: 0, fontWeight: isWeak ? 500 : 400 }}>{cat}</span>
              <div style={{ flex: 1, height: 18, borderRadius: 999, background: BLUE.light, overflow: "hidden" }}>
                <div style={{ width: (rate ?? 0) + "%", height: "100%", background: hue, transition: "width .3s" }} />
              </div>
              <span style={{ width: 90, textAlign: "right", fontSize: 12, color: "var(--color-text-tertiary)" }}>
                {p && p.attempts ? `${rate}% (${p.attempts}回)` : `未着手 (${counts[cat]||0}問)`}
              </span>
            </div>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 10, marginTop: 22, flexWrap: "wrap" }}>
        <button onClick={() => setTab("quiz")} style={primaryBtn}>クイズを始める</button>
        <button onClick={() => setTab("exam")} style={secondaryBtn}>模擬試験に挑戦</button>
        <button onClick={resetAll} style={ghostBtn}>進捗をリセット</button>
      </div>
    </div>
  );
}

function Stat({ label, value, accent }) {
  return (
    <div style={{ flex: 1, minWidth: 110, padding: "14px 16px", borderRadius: "var(--border-radius-lg, 12px)",
      background: accent ? `linear-gradient(135deg, ${BLUE.primary}, ${BLUE.deep})` : "#fff",
      border: accent ? "none" : `0.5px solid ${BLUE.mid}` }}>
      <div style={{ fontSize: 26, fontWeight: 500, color: accent ? "#fff" : BLUE.deep }}>{value}</div>
      <div style={{ fontSize: 12, color: accent ? "rgba(255,255,255,0.85)" : "var(--color-text-tertiary)", marginTop: 2 }}>{label}</div>
    </div>
  );
}

const primaryBtn = { padding: "10px 20px", borderRadius: "var(--border-radius-md,8px)", cursor: "pointer", fontSize: 14, fontWeight: 500, background: BLUE.primary, color: "#fff", border: "none" };
const secondaryBtn = { padding: "10px 20px", borderRadius: "var(--border-radius-md,8px)", cursor: "pointer", fontSize: 14, fontWeight: 500, background: BLUE.deep, color: "#fff", border: "none" };
const ghostBtn = { padding: "10px 20px", borderRadius: "var(--border-radius-md,8px)", cursor: "pointer", fontSize: 14, background: BLUE.light, color: BLUE.deep, border: `0.5px solid ${BLUE.mid}` };

const MIX = "★全分野ミックス";
const CLOUD_QUIZ = { "☁AWSの問題": "AWS", "☁Azureの問題": "Azure", "☁GCPの問題": "GCP", "☁OCIの問題": "OCI" };

// 正解選択肢がそのクラウドのサービスかを判定するためのキーワード
const CLOUD_KW = {
  AWS: ["AWS", "Amazon", "EC2", "Lambda", "EKS", "ECS", "Fargate", "Beanstalk", "ECR", "Outposts", "Braket", "S3", "EBS", "EFS", "FSx", "Glacier", "Snow", "DataSync", "Athena", "Glue", "EMR", "Kinesis", "QuickSight", "OpenSearch", "MWAA", "RDS", "Aurora", "DynamoDB", "Redshift", "Neptune", "QLDB", "ElastiCache", "DocumentDB", "VPC", "Route 53", "CloudFront", "ALB", "NLB", "Direct Connect", "Transit Gateway", "PrivateLink", "Global Accelerator", "EventBridge", "SQS", "Bedrock", "SageMaker", "Nova", "Titan", "Trainium", "Inferentia", "Comprehend", "Transcribe", "Polly", "Rekognition", "Textract", "Kendra", "Personalize", "Fraud Detector", "Forecast", "Connect", "Lex", "IAM", "KMS", "CloudHSM", "GuardDuty", "Detective", "Macie", "Inspector", "Shield", "WAF", "Security Hub", "Cognito", "Secrets Manager", "CloudFormation", "CDK", "CloudWatch", "X-Ray", "DMS", "Migration Hub", "Cost Explorer", "Budgets", "Well-Architected", "Systems Manager", "Fault Injection", "Trusted Advisor", "Config", "Cloud9", "Ground Station", "EC2 Mac", "7R", "Savings Plans", "Reserved Instances", "Cost Anomaly", "Compute Optimizer", "Cost and Usage", "Audit Manager", "Firewall Manager", "Access Analyzer", "Cognito", "ACM", "S3 Object Lambda", "S3 Select", "Object Lock", "Intelligent-Tiering", "io2", "Application Signals", "CloudTrail", "Knowledge Bases", "Bedrock Agents", "Bedrock Guardrails", "Model Distillation", "Clarify", "Feature Store", "Model Registry", "Ground Truth", "Model Monitor", "Canvas", "Autopilot", "Pipelines", "Comprehend Medical", "Amazon Q", "Nova Sonic", "Amazon Connect", "Network Firewall", "Managed Microsoft AD", "Managed Grafana", "Managed", "RUM", "Synthetics"],
  Azure: ["Azure", "Virtual Machines", "Functions", "AKS", "Container Apps", "Container Instances", "App Service", "VM Scale Sets", "VMSS", "Arc", "Blob", "Managed Disks", "Files", "Data Box", "Synapse", "Fabric", "Data Factory", "Databricks", "Power BI", "Data Explorer", "Purview", "SQL Database", "SQL Hyperscale", "Cosmos", "Cache for Redis", "VNet", "Front Door", "Application Gateway", "ExpressRoute", "Virtual WAN", "Private Link", "Private Endpoint", "Service Bus", "Event Grid", "Event Hubs", "OpenAI", "Foundry", "Machine Learning", "Prompt Shields", "Agent Framework", "Copilot", "AI Search", "AI Language", "Translator", "AI Speech", "Speech Translation", "Face", "Custom Vision", "Video Indexer", "Document Intelligence", "Anomaly Detector", "Bot Service", "CLU", "Entra", "Key Vault", "Managed HSM", "Defender", "Sentinel", "ARM", "Bicep", "Azure Monitor", "Application Insights", "Migrate", "Cost Management", "Hybrid Benefit", "Azure Policy", "Chaos Studio", "Automation", "Codespaces", "GitHub Copilot", "Transparency Note", "Responsible AI", "Personalizer", "Health Insights", "Healthcare NLP", "B2C", "Domain Services", "スポットVM", "Spot VM", "Log Analytics", "Stack", "Resource Manager"],
  GCP: ["GCP", "Google", "Compute Engine", "Cloud Run", "GKE", "App Engine", "MIG", "Anthos", "Cloud Storage", "Persistent Disk", "Hyperdisk", "Filestore", "Coldline", "Nearline", "Autoclass", "Transfer Appliance", "Parallelstore", "Cloud SQL", "AlloyDB", "Firestore", "Bigtable", "BigQuery", "Spanner", "Memorystore", "Cloud DNS", "Cloud CDN", "Cloud Load Balancing", "Cloud Interconnect", "Apigee", "VPC Service Controls", "Pub/Sub", "Eventarc", "NCC", "Vertex AI", "Gemini", "Gemma", "Imagen", "Veo", "Agent Builder", "ADK", "TPU", "Natural Language", "Cloud Translation", "Document Translation", "Speech-to-Text", "Text-to-Speech", "Gemini Live", "Cloud Vision", "Document AI", "Recommendations AI", "Cloud IAM", "Cloud KMS", "CSEK", "Security Command Center", "Sensitive Data Protection", "BeyondCorp", "IAP", "Cloud Armor", "Chronicle", "SecOps", "reCAPTCHA", "Cloud Audit Logs", "Terraform", "Deployment Manager", "Cloud Monitoring", "Cloud Trace", "Migration Center", "Cloud Billing", "継続利用割引", "SUD", "SRE", "Cloud Build", "Dataflow", "Dataproc", "Looker", "Cloud Composer", "Analytics Hub", "Dataplex", "Cloud Data Fusion", "Storage Transfer", "Cloud Asset Inventory", "Recommender", "Uptime Checks", "Cloud Logging", "Confidential Computing", "Identity Platform", "BigQuery ML", "Model Garden", "Cloud Shell", "プリエンプティブル"],
  OCI: ["OCI", "Oracle", "OKE", "Roving Edge", "Dedicated Region", "Object Storage", "Block Volume", "File Storage", "Archive Storage", "Base Database", "Autonomous", "Exadata", "23ai", "HeatWave", "GoldenGate", "Datastream", "VCN", "FastConnect", "DRG", "Generative AI", "Data Science", "T-Few", "GenAI Agents", "Language", "Speech", "Vision", "Document Understanding", "Anomaly Detection", "Forecasting", "MSET-2", "Vault", "Cloud Guard", "Data Safe", "Universal Credits", "Always Free", "Resource Manager", "OCI Monitoring", "Database Migration", "OS Management", "Big Data Service", "Oracle Analytics", "Streaming", "Data Integration", "コンパートメント", "ベアメタル", "SELECT AI", "Model Catalog", "文字単位"],
};

// 各問題の正解選択肢から「主に問われているクラウド」を判定
function cloudOfQuestion(item) {
  const ans = item.o[item.a];
  // 「どのクラウドか」を答える問題は正解そのものがクラウド名
  if (["AWS", "Azure", "GCP", "OCI", "Google", "Oracle"].includes(ans.trim())) {
    if (ans.includes("Google")) return "GCP";
    if (ans.includes("Oracle")) return "OCI";
    return ans.trim();
  }
  // それ以外はキーワードで判定（最も多くヒットしたクラウド）
  let best = null, bestScore = 0;
  for (const [cloud, kws] of Object.entries(CLOUD_KW)) {
    let score = 0;
    for (const kw of kws) { if (ans.includes(kw)) score += kw.length; }
    if (score > bestScore) { bestScore = score; best = cloud; }
  }
  return bestScore > 0 ? best : null;
}

// クラウド別の問題インデックスを事前計算
const CLOUD_IDX = { AWS: [], Azure: [], GCP: [], OCI: [] };
BANK.forEach((item, i) => {
  const c = cloudOfQuestion(item);
  if (c && CLOUD_IDX[c]) CLOUD_IDX[c].push(i);
});

function Quiz({ counts, progress, recordAnswer }) {
  const [cat, setCat] = useState(null);
  const [order, setOrder] = useState([]);
  const [idx, setIdx] = useState(0);
  const [sel, setSel] = useState(null);
  const [answered, setAnswered] = useState({});
  const [reviewMode, setReviewMode] = useState(false);
  const [sessionCorrect, setSessionCorrect] = useState(0);
  const [sessionWrong, setSessionWrong] = useState(0);

  const startCat = (c) => {
    let pool;
    if (c === MIX) {
      pool = BANK.map((q, i) => i);
    } else if (CLOUD_QUIZ[c]) {
      pool = CLOUD_IDX[CLOUD_QUIZ[c]].slice();
    } else {
      pool = BANK.map((q, i) => ({ q, i })).filter((x) => x.q.d === c).map((x) => x.i);
    }
    const seed = Date.now() % 233280;
    let ord = pool.slice(); // 既定は固定順（収録順）
    if (c === MIX) ord = ord.slice(0, 30); // ミックスは30問
    setCat(c); setOrder(ord); setIdx(0); setSel(null); setAnswered({});
    setReviewMode(false); setSessionCorrect(0); setSessionWrong(0);
  };

  if (!cat) {
    return (
      <div>
        <button onClick={() => startCat(MIX)} style={{
          width: "100%", textAlign: "left", padding: "16px 18px", borderRadius: "var(--border-radius-lg,12px)", cursor: "pointer",
          background: `linear-gradient(135deg, ${BLUE.primary}, ${BLUE.deep})`, border: "none", marginBottom: 16,
        }}>
          <div style={{ fontSize: 16, fontWeight: 500, color: "#fff" }}>全分野ミックス（ランダム30問）</div>
          <div style={{ fontSize: 12, color: "rgba(255,255,255,0.85)", marginTop: 4 }}>全{BANK.length}問からランダムに出題。腕試しに最適。</div>
        </button>

        <h2 style={{ fontSize: 16, fontWeight: 500, margin: "0 0 12px", color: BLUE.deep }}>クラウド別で解く</h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(140px,1fr))", gap: 10, marginBottom: 18 }}>
          {Object.entries(CLOUD_QUIZ).map(([label, cloud]) => {
            const cc = CLOUD_DATA[cloud];
            const p = progress[label]; const rate = pct(p);
            return (
              <button key={label} onClick={() => startCat(label)} style={{
                textAlign: "left", padding: "12px 14px", borderRadius: "var(--border-radius-lg,12px)", cursor: "pointer",
                background: "#fff", border: `1px solid ${cc.color}`,
              }}>
                <div style={{ fontSize: 15, fontWeight: 500, color: cc.color }}>{cloud}</div>
                <div style={{ fontSize: 12, color: "var(--color-text-tertiary)", marginTop: 4 }}>
                  {CLOUD_IDX[cloud].length}問{p && p.attempts ? ` ・ 正答率${rate}%` : ""}
                </div>
              </button>
            );
          })}
        </div>

        <h2 style={{ fontSize: 16, fontWeight: 500, margin: "0 0 12px", color: BLUE.deep }}>分野を選んでください</h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(200px,1fr))", gap: 10 }}>
          {CAT_ORDER.map((c) => {
            const p = progress[c]; const rate = pct(p);
            return (
              <button key={c} onClick={() => startCat(c)} style={{
                textAlign: "left", padding: "12px 14px", borderRadius: "var(--border-radius-lg,12px)", cursor: "pointer",
                background: "#fff", border: `0.5px solid ${BLUE.mid}`,
              }}>
                <div style={{ fontSize: 14, fontWeight: 500, color: BLUE.deep }}>{c}</div>
                <div style={{ fontSize: 12, color: "var(--color-text-tertiary)", marginTop: 4 }}>
                  {counts[c]}問{p && p.attempts ? ` ・ 正答率${rate}%` : " ・ 未着手"}
                </div>
                <div style={{ marginTop: 8, height: 5, borderRadius: 999, background: BLUE.light, overflow: "hidden" }}>
                  <div style={{ width: (rate ?? 0) + "%", height: "100%", background: CAT_HUE[c] }} />
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  const accent = cat === MIX ? BLUE.primary : (CLOUD_QUIZ[cat] ? CLOUD_DATA[CLOUD_QUIZ[cat]].color : CAT_HUE[cat]);
  const headLabel = cat === MIX ? "全分野ミックス" : (CLOUD_QUIZ[cat] ? `${CLOUD_QUIZ[cat]} の問題` : cat);
  const showCatTag = cat === MIX || !!CLOUD_QUIZ[cat];
  const view = reviewMode
    ? order.filter((i) => answered[i] !== undefined && answered[i] !== BANK[i].a)
    : order;
  const gi = view[idx];
  const item = gi != null ? BANK[gi] : null;
  const ad = item ? answered[gi] : undefined;

  const check = () => {
    if (sel == null || ad !== undefined) return;
    const correct = sel === item.a;
    setAnswered({ ...answered, [gi]: sel });
    if (correct) setSessionCorrect((n) => n + 1); else setSessionWrong((n) => n + 1);
    recordAnswer(item.d, correct);
    setSel(null);
  };

  const allDone = view.length > 0 && view.every((i) => answered[i] !== undefined);

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, flexWrap: "wrap", gap: 8 }}>
        <button onClick={() => setCat(null)} style={ghostBtn}>← 分野選択</button>
        <span style={{ fontSize: 15, fontWeight: 500, color: BLUE.deep }}>{headLabel}</span>
        <button onClick={() => { setReviewMode(!reviewMode); setIdx(0); setSel(null); }} style={ghostBtn}>
          {reviewMode ? "全問に戻す" : "間違いだけ復習"}
        </button>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14, color: "var(--color-text-secondary)", marginBottom: 6 }}>
        <span>第 {view.length ? idx + 1 : 0} / {view.length} 問</span>
        <span>正解 {sessionCorrect} ・ 誤答 {sessionWrong}</span>
      </div>
      <div style={{ height: 6, borderRadius: 999, background: BLUE.light, marginBottom: 14, overflow: "hidden" }}>
        <div style={{ width: view.length ? ((idx + 1) / view.length * 100) + "%" : "0%", height: "100%", background: accent, transition: "width .2s" }} />
      </div>

      {!item && (
        <div style={{ padding: 24, textAlign: "center", color: "var(--color-text-secondary)", fontSize: 14 }}>
          {reviewMode ? "復習する間違いはありません。" : "問題がありません。"}
        </div>
      )}

      {item && (
        <div style={{ background: "#fff", border: `0.5px solid ${BLUE.mid}`, borderRadius: "var(--border-radius-lg,12px)", padding: "20px" }}>
          {showCatTag && <div style={{ fontSize: 11, color: accent, marginBottom: 6 }}>{item.d}</div>}
          <p style={{ fontSize: 16, fontWeight: 500, margin: "0 0 4px", lineHeight: 1.6 }}>Q. {item.q}</p>
          <p style={{ fontSize: 13, color: "var(--color-text-tertiary)", margin: "0 0 16px" }}>正しいものを選んでください</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {item.o.map((opt, i) => {
              let bg = "#fff", bd = BLUE.mid, col = "var(--color-text-primary)";
              if (ad !== undefined) {
                if (i === item.a) { bg = "var(--color-background-success)"; bd = "var(--color-border-success)"; col = "var(--color-text-success)"; }
                else if (i === ad) { bg = "var(--color-background-danger)"; bd = "var(--color-border-danger)"; col = "var(--color-text-danger)"; }
              } else if (sel === i) { bg = BLUE.light; bd = BLUE.primary; }
              return (
                <button key={i} onClick={() => ad === undefined && setSel(i)} style={{
                  textAlign: "left", padding: "10px 14px", borderRadius: "var(--border-radius-md,8px)", lineHeight: 1.5,
                  background: bg, border: `0.5px solid ${bd}`, color: col, cursor: ad === undefined ? "pointer" : "default", fontSize: 14,
                }}>{["A", "B", "C", "D"][i]}. {opt}</button>
              );
            })}
          </div>
          {ad !== undefined && (
            <div style={{ marginTop: 14, padding: 12, borderRadius: "var(--border-radius-md,8px)", fontSize: 14, lineHeight: 1.6,
              background: ad === item.a ? "var(--color-background-success)" : "var(--color-background-danger)",
              color: ad === item.a ? "var(--color-text-success)" : "var(--color-text-danger)" }}>
              {ad === item.a ? <b>正解</b> : <><b>不正解</b>（正解は {["A", "B", "C", "D"][item.a]}. {item.o[item.a]}）</>} — {item.e}
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "space-between", gap: 10, marginTop: 18 }}>
            <button onClick={() => { if (idx > 0) { setIdx(idx - 1); setSel(null); } }} style={{ ...ghostBtn, flex: 1, opacity: idx > 0 ? 1 : 0.5 }}>前へ</button>
            <button onClick={check} disabled={ad !== undefined || sel == null} style={{ ...primaryBtn, flex: 1, opacity: (ad !== undefined || sel == null) ? 0.5 : 1 }}>回答する</button>
            <button onClick={() => { if (idx < view.length - 1) { setIdx(idx + 1); setSel(null); } }} style={{ ...ghostBtn, flex: 1, opacity: idx < view.length - 1 ? 1 : 0.5 }}>次へ</button>
          </div>
        </div>
      )}

      {allDone && (
        <p style={{ marginTop: 14, fontSize: 14, color: "var(--color-text-secondary)", lineHeight: 1.6 }}>
          この範囲は完了。正解 {view.filter((i) => answered[i] === BANK[i].a).length} / {view.length}。誤答は「間違いだけ復習」で見直せます。
        </p>
      )}
    </div>
  );
}

// ===== 模擬試験モード =====
const EXAM_N = 30;

function Exam({ recordAnswer }) {
  const [phase, setPhase] = useState("intro"); // intro / running / result
  const [order, setOrder] = useState([]);
  const [idx, setIdx] = useState(0);
  const [sel, setSel] = useState(null);
  const [answers, setAnswers] = useState({}); // gi -> selected
  const [secs, setSecs] = useState(EXAM_N * 60);

  useEffect(() => {
    if (phase !== "running") return;
    if (secs <= 0) { finish(); return; }
    const t = setTimeout(() => setSecs((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [phase, secs]);

  const start = () => {
    const ord = shuffle(BANK.map((q, i) => i), Date.now() % 233280).slice(0, EXAM_N);
    setOrder(ord); setIdx(0); setSel(null); setAnswers({}); setSecs(EXAM_N * 60); setPhase("running");
  };

  const finish = () => {
    // 採点を記録
    order.forEach((gi) => {
      if (answers[gi] !== undefined) recordAnswer(BANK[gi].d, answers[gi] === BANK[gi].a);
    });
    setPhase("result");
  };

  if (phase === "intro") {
    return (
      <div style={{ background: "#fff", border: `0.5px solid ${BLUE.mid}`, borderRadius: "var(--border-radius-lg,12px)", padding: "24px" }}>
        <h2 style={{ fontSize: 18, fontWeight: 500, margin: "0 0 12px", color: BLUE.deep }}>模擬試験モード</h2>
        <ul style={{ fontSize: 14, color: "var(--color-text-secondary)", lineHeight: 1.8, paddingLeft: 20, margin: "0 0 18px" }}>
          <li>全{BANK.length}問からランダムに <b>{EXAM_N}問</b> 出題</li>
          <li>制限時間 <b>{EXAM_N}分</b>（1問1分目安）</li>
          <li>解答中は正誤を表示しません。最後にまとめて採点</li>
          <li>結果は分野別の進捗にも反映されます</li>
        </ul>
        <button onClick={start} style={{ ...primaryBtn, width: "100%" }}>試験を開始する</button>
      </div>
    );
  }

  if (phase === "result") {
    const correct = order.filter((gi) => answers[gi] === BANK[gi].a).length;
    const rate = Math.round((correct / order.length) * 100);
    const pass = rate >= 70;
    // 分野別内訳
    const byCat = {};
    order.forEach((gi) => {
      const c = BANK[gi].d;
      if (!byCat[c]) byCat[c] = { t: 0, ok: 0 };
      byCat[c].t += 1;
      if (answers[gi] === BANK[gi].a) byCat[c].ok += 1;
    });
    return (
      <div>
        <div style={{ background: pass ? "var(--color-background-success)" : "var(--color-background-danger)", border: `0.5px solid ${pass ? "var(--color-border-success)" : "var(--color-border-danger)"}`, borderRadius: "var(--border-radius-lg,12px)", padding: "24px", textAlign: "center", marginBottom: 16 }}>
          <div style={{ fontSize: 14, color: pass ? "var(--color-text-success)" : "var(--color-text-danger)" }}>{pass ? "合格ライン到達 🎉" : "あと一歩"}</div>
          <div style={{ fontSize: 44, fontWeight: 500, color: pass ? "var(--color-text-success)" : "var(--color-text-danger)", margin: "4px 0" }}>{rate}%</div>
          <div style={{ fontSize: 14, color: "var(--color-text-secondary)" }}>{correct} / {order.length} 問正解（合格目安 70%）</div>
        </div>

        <h3 style={{ fontSize: 15, fontWeight: 500, margin: "0 0 10px", color: BLUE.deep }}>分野別の結果</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 18 }}>
          {Object.entries(byCat).map(([c, v]) => {
            const r = Math.round((v.ok / v.t) * 100);
            return (
              <div key={c} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ width: 150, fontSize: 12, color: "var(--color-text-secondary)", flexShrink: 0 }}>{c}</span>
                <div style={{ flex: 1, height: 14, borderRadius: 999, background: BLUE.light, overflow: "hidden" }}>
                  <div style={{ width: r + "%", height: "100%", background: r >= 70 ? BLUE.primary : "var(--color-text-danger)" }} />
                </div>
                <span style={{ width: 70, textAlign: "right", fontSize: 12, color: "var(--color-text-tertiary)" }}>{v.ok}/{v.t}</span>
              </div>
            );
          })}
        </div>

        <h3 style={{ fontSize: 15, fontWeight: 500, margin: "0 0 10px", color: BLUE.deep }}>解答の見直し</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 18 }}>
          {order.map((gi, n) => {
            const it = BANK[gi]; const ua = answers[gi]; const ok = ua === it.a;
            return (
              <div key={gi} style={{ padding: "10px 14px", borderRadius: "var(--border-radius-md,8px)", background: "#fff", border: `0.5px solid ${ok ? "var(--color-border-success)" : "var(--color-border-danger)"}` }}>
                <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 4, color: ok ? "var(--color-text-success)" : "var(--color-text-danger)" }}>
                  {n + 1}. {ok ? "正解" : "不正解"} <span style={{ color: BLUE.primary, fontWeight: 400 }}>［{it.d}］</span>
                </div>
                <div style={{ fontSize: 13, color: "var(--color-text-primary)", lineHeight: 1.5, marginBottom: 4 }}>Q. {it.q}</div>
                {!ok && (
                  <div style={{ fontSize: 12, color: "var(--color-text-secondary)", marginBottom: 2 }}>
                    あなたの解答: {ua !== undefined ? `${["A","B","C","D"][ua]}. ${it.o[ua]}` : "未解答"}
                  </div>
                )}
                <div style={{ fontSize: 12, color: "var(--color-text-secondary)" }}>
                  正解: {["A","B","C","D"][it.a]}. {it.o[it.a]} — {it.e}
                </div>
              </div>
            );
          })}
        </div>

        <button onClick={() => setPhase("intro")} style={{ ...primaryBtn, width: "100%" }}>もう一度挑戦する</button>
      </div>
    );
  }

  // phase === "running"
  const gi = order[idx];
  const item = BANK[gi];
  const cur = answers[gi];
  const mm = String(Math.floor(secs / 60)).padStart(2, "0");
  const ss = String(secs % 60).padStart(2, "0");
  const answeredCount = Object.keys(answers).length;
  const lowTime = secs <= 60;

  const pick = (i) => {
    setSel(i);
    setAnswers({ ...answers, [gi]: i });
  };

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, flexWrap: "wrap", gap: 8 }}>
        <span style={{ fontSize: 15, fontWeight: 500, color: BLUE.deep }}>模擬試験</span>
        <span style={{ fontSize: 18, fontWeight: 500, fontVariantNumeric: "tabular-nums", color: lowTime ? "var(--color-text-danger)" : BLUE.deep }}>{mm}:{ss}</span>
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13, color: "var(--color-text-secondary)", marginBottom: 6 }}>
        <span>第 {idx + 1} / {order.length} 問</span>
        <span>解答済 {answeredCount} / {order.length}</span>
      </div>
      <div style={{ height: 6, borderRadius: 999, background: BLUE.light, marginBottom: 14, overflow: "hidden" }}>
        <div style={{ width: ((idx + 1) / order.length * 100) + "%", height: "100%", background: BLUE.primary, transition: "width .2s" }} />
      </div>

      <div style={{ background: "#fff", border: `0.5px solid ${BLUE.mid}`, borderRadius: "var(--border-radius-lg,12px)", padding: "20px" }}>
        <div style={{ fontSize: 11, color: BLUE.primary, marginBottom: 6 }}>{item.d}</div>
        <p style={{ fontSize: 16, fontWeight: 500, margin: "0 0 16px", lineHeight: 1.6 }}>Q. {item.q}</p>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {item.o.map((opt, i) => {
            const on = cur === i;
            return (
              <button key={i} onClick={() => pick(i)} style={{
                textAlign: "left", padding: "10px 14px", borderRadius: "var(--border-radius-md,8px)", lineHeight: 1.5,
                background: on ? BLUE.light : "#fff", border: `0.5px solid ${on ? BLUE.primary : BLUE.mid}`,
                color: "var(--color-text-primary)", cursor: "pointer", fontSize: 14,
              }}>{["A", "B", "C", "D"][i]}. {opt}</button>
            );
          })}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 10, marginTop: 18 }}>
          <button onClick={() => { if (idx > 0) { setIdx(idx - 1); setSel(null); } }} style={{ ...ghostBtn, flex: 1, opacity: idx > 0 ? 1 : 0.5 }}>前へ</button>
          {idx < order.length - 1
            ? <button onClick={() => { setIdx(idx + 1); setSel(null); }} style={{ ...primaryBtn, flex: 1 }}>次へ</button>
            : <button onClick={finish} style={{ ...secondaryBtn, flex: 1 }}>採点する</button>}
        </div>
      </div>

      <button onClick={finish} style={{ ...ghostBtn, width: "100%", marginTop: 12 }}>ここで終了して採点する</button>
    </div>
  );
}

