// 4社カラー（識別のため図解では維持）
const RAMP = { amber: "#FAEEDA", amberS: "#BA7517", amberT: "#854F0B", blue: "#E6F1FB", blueS: "#185FA5", blueT: "#0C447C", green: "#EAF3DE", greenS: "#3B6D11", greenT: "#27500A", red: "#FCEBEB", redS: "#A32D2D", redT: "#791F1F", gray: "#F1EFE8", grayS: "#888780", grayT: "#444441" };

function Cell({ x, y, w, h, fill, stroke, txt, color, sub }) {
  return (
    <g>
      <rect x={x} y={y} width={w} height={h} rx={6} fill={fill} stroke={stroke} strokeWidth={0.5} />
      <text x={x + w / 2} y={sub ? y + h / 2 - 9 : y + h / 2} textAnchor="middle" dominantBaseline="central" fontSize={12} fill={color}>{txt}</text>
      {sub && <text x={x + w / 2} y={y + h / 2 + 9} textAnchor="middle" dominantBaseline="central" fontSize={11} fill={color}>{sub}</text>}
    </g>
  );
}

function DiagServices() {
  const rows = [
    ["コンピュート", "EC2 / Lambda", "VM / Functions", "Compute / GKE", "OCI Compute / 関数"],
    ["ストレージ", "S3 / EBS", "Blob / Disks", "Cloud Storage", "Object / Block"],
    ["データベース", "RDS / DynamoDB", "SQL DB / Cosmos", "Spanner / BigQuery", "Autonomous DB"],
    ["ネットワーク", "VPC / Route 53", "VNet / Azure DNS", "VPC / Cloud DNS", "VCN / OCI DNS"],
    ["データ分析", "Athena / Redshift", "Synapse / Fabric", "BigQuery", "Autonomous DWH"],
    ["生成AI", "Bedrock", "Azure OpenAI", "Vertex AI", "OCI Generative AI"],
    ["ML基盤", "SageMaker", "Azure ML", "Vertex AI", "Data Science"],
    ["IAM", "AWS IAM", "Entra ID", "Cloud IAM", "OCI IAM"],
    ["IaC", "CloudFormation", "ARM / Bicep", "Terraform", "Resource Manager"],
    ["監視", "CloudWatch", "Azure Monitor", "Cloud Monitoring", "OCI Monitoring"],
  ];
  const heads = [["AWS", RAMP.amberS], ["Azure", RAMP.blueS], ["GCP", RAMP.greenS], ["OCI", RAMP.redS]];
  const colF = [RAMP.amber, RAMP.blue, RAMP.green, RAMP.red];
  const colS = [RAMP.amberS, RAMP.blueS, RAMP.greenS, RAMP.redS];
  const colT = [RAMP.amberT, RAMP.blueT, RAMP.greenT, RAMP.redT];
  const rowH = 46, top = 50, x0 = 10, wc = 110, wd = 138, gap = 6;
  const H = top + rows.length * (rowH + gap) + 10;
  return (
    <svg width="100%" viewBox={`0 0 680 ${H}`} role="img" style={{ display: "block" }}>
      <title>4社の主要サービス対応表</title>
      <desc>10分野について各クラウドの代表サービスを並べた表</desc>
      <Cell x={x0} y={10} w={wc} h={32} fill={RAMP.gray} stroke={RAMP.grayS} txt="分野" color={RAMP.grayT} />
      {heads.map(([h, s], i) => (
        <g key={h}><rect x={x0 + wc + gap + i * (wd + gap)} y={10} width={wd} height={32} rx={6} fill={RAMP.gray} stroke={RAMP.grayS} strokeWidth={0.5} />
          <text x={x0 + wc + gap + i * (wd + gap) + wd / 2} y={26} textAnchor="middle" dominantBaseline="central" fontSize={14} fontWeight={500} fill={s}>{h}</text></g>
      ))}
      {rows.map((r, ri) => {
        const y = top + ri * (rowH + gap);
        return (
          <g key={ri}>
            <Cell x={x0} y={y} w={wc} h={rowH} fill={RAMP.gray} stroke={RAMP.grayS} txt={r[0]} color={RAMP.grayT} />
            {r.slice(1).map((c, ci) => (
              <Cell key={ci} x={x0 + wc + gap + ci * (wd + gap)} y={y} w={wd} h={rowH} fill={colF[ci]} stroke={colS[ci]} txt={c} color={colT[ci]} />
            ))}
          </g>
        );
      })}
    </svg>
  );
}

