// ===== 追加図解3: 移行7R =====
function DiagMigration() {
  const items = [
    ["1. Retire（廃止）", "使われていないシステムを停止・廃棄する", false],
    ["2. Retain（保持）", "移行せず現状のオンプレに残す", false],
    ["3. Relocate（移設）", "構成を変えずVMware等ごと移す", false],
    ["4. Rehost（リホスト）", "ほぼそのままクラウドに載せ替え（リフト&シフト）", true],
    ["5. Replatform（リプラットフォーム）", "一部をマネージド化など最適化して移す", true],
    ["6. Repurchase（買い替え）", "自前をやめSaaS等に切り替える", true],
    ["7. Refactor（リファクタ）", "クラウドネイティブに作り直す", true],
  ];
  const x0 = 10, top = 50, rowH = 50, gap = 8, w = 660;
  const H = top + items.length * (rowH + gap) + 44;
  return (
    <svg width="100%" viewBox={`0 0 680 ${H}`} role="img" style={{ display: "block" }}>
      <title>クラウド移行の7R戦略</title>
      <desc>移行の7つの戦略を、難易度の低い順に並べた図</desc>
      <rect x={x0} y={10} width={w} height={30} rx={6} fill={BLUE.primary} stroke={BLUE.deep} strokeWidth={0.5} />
      <text x={x0 + w / 2} y={25} textAnchor="middle" dominantBaseline="central" fontSize={14} fontWeight={500} fill="#fff">クラウド移行の7R（AWSは7戦略・他社は6R相当）</text>
      {items.map((it, i) => {
        const y = top + i * (rowH + gap);
        const cloudMove = it[2];
        const f = cloudMove ? RAMP.blue : RAMP.gray;
        const s = cloudMove ? RAMP.blueS : RAMP.grayS;
        const t = cloudMove ? RAMP.blueT : RAMP.grayT;
        return (
          <g key={i}>
            <rect x={x0} y={y} width={w} height={rowH} rx={7} fill={f} stroke={s} strokeWidth={0.5} />
            <text x={x0 + 16} y={y + rowH / 2 - 8} dominantBaseline="central" fontSize={13.5} fontWeight={500} fill={t}>{it[0]}</text>
            <text x={x0 + 16} y={y + rowH / 2 + 10} dominantBaseline="central" fontSize={11.5} fill={t}>{it[1]}</text>
            <text x={x0 + w - 14} y={y + rowH / 2} textAnchor="end" dominantBaseline="central" fontSize={10.5} fill={t}>{cloudMove ? "クラウドへ移行" : "移行しない"}</text>
          </g>
        );
      })}
      <text x={x0} y={H - 18} dominantBaseline="central" fontSize={11.5} fill={RAMP.grayT}>下に行くほど手間と効果が大きい。まず棚卸し（Retire/Retain）→Rehostで素早く移行、が定石。</text>
    </svg>
  );
}
function TabDojo() {
  const dlang = useLang();
  const { jump, setJump } = useJump();
  const [view, setView] = useState("mcq");
  // 辞書からのジャンプを受けたらクイズ(mcq)ビューへ切り替え
  useEffect(() => {
    if (jump && jump.tab === "dojo" && jump.dojoView) setView(jump.dojoView);
  }, [jump && jump.nonce]);
  const [key, setKey] = useState("basics");
  const [sel, setSel] = useState("usr");
  const [drill, setDrill] = useState(false);
  const [revealed, setRevealed] = useState(false);
  const [gradeInput, setGradeInput] = useState("");
  const [grade, setGrade] = useState("");
  const [gradeBusy, setGradeBusy] = useState(false);
  const [gradeErr, setGradeErr] = useState("");
  const [drillSteps, setDrillSteps] = useState({});
  const [layouts, setLayouts] = useState({}); // 図面key -> {nodeId: {x,y}}
  const [picked, setPicked] = useState(false); // 図面を選んで表示中か（false=一覧表示）
  const d = DIAGRAMS[key];
  const det = d.details[sel] || null;
  const node = d.nodes.find((n) => n.id === sel);

  const dragNode = (id, x, y) => {
    setLayouts((prev) => ({ ...prev, [key]: { ...(prev[key] || {}), [id]: { x, y } } }));
  };
  const resetLayout = () => {
    setLayouts((prev) => { const c = { ...prev }; delete c[key]; return c; });
  };

  const resetGrade = () => { setGradeInput(""); setGrade(""); setGradeErr(""); };
  const nextDrill = (dg) => {
    const ns = (dg || d).nodes;
    const n = ns[Math.floor(Math.random() * ns.length)];
    setSel(n.id); setRevealed(false); resetGrade();
  };
  const switchDiagram = (k) => {
    setKey(k); resetGrade(); setPicked(true);
    if (drill) nextDrill(DIAGRAMS[k]); else setSel(DIAGRAMS[k].nodes[0].id);
  };
  const toggleDrill = () => {
    const on = !drill; setDrill(on); resetGrade();
    if (on) nextDrill(); else setRevealed(false);
  };

  const gradeIt = async () => {
    if (!gradeInput.trim() || gradeBusy || !det || !node) return;
    setGradeBusy(true); setGradeErr("");
    try {
      const en = dlang === "en";
      const sys = en
        ? "You are an examiner for an AI-architecture oral exam. Using the reference information as the standard, grade the candidate's 30-second explanation strictly. Output format (these 4 lines only, concise):\nScore: n/5\nStrengths: …\nGaps: …\nRephrase: one sentence usable as-is in an interview"
        : "あなたはAIアーキテクチャ口頭試問の採点官。模範情報を基準に、受験者の30秒説明を厳しめに採点する。出力形式（この4行のみ・簡潔に）:\n点数: n/5\n良い点: …\n不足: …\n言い直し例: 面接でそのまま使える1文";
      const usr = en
        ? "Component: " + (node.en || node.label) + " (" + node.label + ")\nReference:\nRole: " + (det.roleEn || det.role) + "\nTech choices: " + (det.techEn || det.tech) + "\nBusiness translation: " + (det.bizEn || det.biz) + "\nCost lens: " + (det.costEn || det.cost) + "\n\nCandidate's explanation:\n" + gradeInput.trim()
        : "構成要素: " + node.label + " (" + node.en + ")\n模範情報:\n役割: " + det.role + "\n技術選定: " + det.tech + "\nビジネス翻訳: " + det.biz + "\nコスト視点: " + det.cost + "\n\n受験者の説明:\n" + gradeInput.trim();
      const g = await callClaude(sys, [{ role: "user", content: usr }]);
      setGrade(g);
    } catch (e) { setGradeErr((dlang === "en" ? "Grading failed: " : "採点に失敗: ") + e.message); }
    setGradeBusy(false);
  };

  const stepOf = (i) => drillSteps[i] || 0;
  const advance = (i, max) => setDrillSteps({ ...drillSteps, [i]: Math.min(stepOf(i) + 1, max) });
  const closeDrill = (i) => setDrillSteps({ ...drillSteps, [i]: 0 });

  return (
    <div>
      <SectionTitle jp="技術道場 — 構成を「語れる」まで" en="Architecture Dojo" />
      <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
        {[["mcq", "d_mcq"], ["diagrams", "d_diagrams"], ["archquiz", "d_archquiz"], ["industry", "d_industry"], ["versus", "d_versus"], ["drills", "d_drills"], ["mock", "d_mock"], ["devlang", "d_devlang"], ["cloud", "d_cloud"]].map(([v, k]) => (
          <button key={v} className="gh-btn" onClick={() => { setView(v); if (v === "diagrams") setPicked(false); }}
                  style={view === v ? { borderColor: C.wine, color: C.wine, fontWeight: 700 } : {}}>{t(dlang, k)}</button>
        ))}
      </div>

      {view === "diagrams" && !picked && (
        <div>
          <div style={{ fontSize: 12, color: C.muted, marginBottom: 14, lineHeight: 1.7 }}>
            {t(dlang, "dg_intro")}
          </div>
          {[[t(dlang, "dg_basic"), ["basics", "distributed", "llmapp", "rag", "inference", "kvopt"]],
            [t(dlang, "dg_applied"), ["datapipeline", "vectorsearch", "staircase", "tuning", "agent", "multiagent", "toolexec", "platform", "llmops"]],
            [t(dlang, "dg_advanced"), ["mcp", "contexteng", "security", "defense", "safety_levels", "resilience", "finops", "ondevice"]]].map(([grp, keys]) => (
            <div key={grp} style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 11, color: C.teal, letterSpacing: ".15em", marginBottom: 8 }}>{grp}</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(220px,1fr))", gap: 10 }}>
                {keys.filter((k) => DIAGRAMS[k]).map((k) => (
                  <button key={k} onClick={() => switchDiagram(k)}
                          style={{ textAlign: "left", background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 10, padding: "12px 14px", cursor: "pointer", color: C.text, transition: "border-color .15s" }}
                          onMouseEnter={(e) => (e.currentTarget.style.borderColor = C.gold)}
                          onMouseLeave={(e) => (e.currentTarget.style.borderColor = C.line)}>
                    <div style={{ fontSize: 13, fontWeight: 700, color: C.gold, marginBottom: 4 }}>{diagramTitle(DIAGRAMS[k], dlang)}</div>
                    <div style={{ fontSize: 10.5, color: C.muted, lineHeight: 1.55 }}>{(dlang === "en" ? (DIAGRAMS[k].subEn || DIAGRAMS[k].sub) : DIAGRAMS[k].sub).replace("ノードをクリック。", "").replace("ノードをクリック", "").replace("Click a node.", "").replace("Click a node", "").trim()}</div>
                    <div style={{ fontSize: 10, color: C.teal, marginTop: 6 }}>{t(dlang, "dg_open")}</div>
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {view === "diagrams" && picked && (
        <div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12, flexWrap: "wrap" }}>
            <button className="gh-btn" onClick={() => setPicked(false)} style={{ borderColor: C.teal, color: C.teal }}>{t(dlang, "back_list")}</button>
            <span className="gh-display" style={{ fontSize: 18, color: C.gold }}>{diagramTitle(d, dlang)}</span>
            <span style={{ flex: 1 }} />
            {layouts[key] && (
              <button className="gh-btn" onClick={resetLayout} style={{ fontSize: 11 }}>{t(dlang, "reset_layout")}</button>
            )}
            <button className="gh-btn" onClick={toggleDrill}
                    style={drill ? { borderColor: C.wine, color: C.wine, fontWeight: 700 } : {}}>
              {drill ? t(dlang, "oral_off") : t(dlang, "oral_on")}
            </button>
          </div>
          <div style={{ fontSize: 11, color: C.dim, marginBottom: 8 }}>{t(dlang, "dg_draghint")}</div>
          <Card>
            <div style={{ fontSize: 12, color: C.muted, marginBottom: 8 }}>{dlang === "en" ? (d.subEn || d.sub) : d.sub}</div>
            <ArchDiagram diagram={d} selected={sel} positions={layouts[key]} onDrag={dragNode} lang={dlang}
                         onSelect={(id) => { setSel(id); if (drill) { setRevealed(false); resetGrade(); } }} />
          </Card>

          {drill && node && (
            <Card style={{ marginTop: 12, borderColor: C.wine }}>
              <div style={{ fontSize: 11, color: C.wine, letterSpacing: ".2em", marginBottom: 6 }}>{t(dlang, "oe_title")}</div>
              <div className="gh-display" style={{ fontSize: 18, marginBottom: 6 }}>
                {t(dlang, "oe_prompt_a")}{nodeLabel(node, dlang)}{t(dlang, "oe_prompt_b")}
              </div>
              <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>
                {t(dlang, "oe_hint")}
              </div>
              <textarea className="gh-input" rows={3} style={{ width: "100%", boxSizing: "border-box", resize: "vertical", fontFamily: "inherit", marginBottom: 8 }}
                        value={gradeInput} onChange={(e) => setGradeInput(e.target.value)}
                        placeholder={t(dlang, "oe_inputph")} />
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
                <button className="gh-btn gh-btn-primary" onClick={gradeIt} disabled={gradeBusy || !gradeInput.trim()}>{t(dlang, "oe_grade")}</button>
                {!revealed && <button className="gh-btn" onClick={() => setRevealed(true)}>{t(dlang, "oe_reveal")}</button>}
                <button className="gh-btn" onClick={() => nextDrill()}>{t(dlang, "oe_next")}</button>
                {gradeBusy && <span className="gh-pulse" style={{ fontSize: 12, color: C.gold }}>{t(dlang, "oe_grading")}</span>}
              </div>
              {gradeErr && <div style={{ color: C.wine, fontSize: 12, marginTop: 8 }}>{gradeErr}</div>}
              {grade && (
                <div style={{ marginTop: 10, fontSize: 12.5, lineHeight: 1.8, background: C.bg, border: `1px solid ${C.gold}`, borderRadius: 8, padding: "10px 12px", whiteSpace: "pre-wrap" }}>
                  <span style={{ color: C.gold, fontWeight: 700 }}>{t(dlang, "oe_result")}</span>{"\n"}{grade}
                </div>
              )}
            </Card>
          )}

          {det && node && (!drill || revealed) && (
            <Card style={{ marginTop: 12, borderColor: C.gold }}>
              <div className="gh-display" style={{ fontSize: 17, marginBottom: 10 }}>{nodeLabel(node, dlang)} <span style={{ fontSize: 11, color: C.muted }}>{dlang === "en" ? node.label : node.en}</span></div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(260px,1fr))", gap: 10, fontSize: 12.5, lineHeight: 1.7 }}>
                <div><span style={{ color: C.teal, fontWeight: 700 }}>{t(dlang, "dp_role")}</span><br />{dlang === "en" ? (det.roleEn || det.role) : det.role}<br /><br /><span style={{ color: C.teal, fontWeight: 700 }}>{t(dlang, "dp_tech")}</span><br />{dlang === "en" ? (det.techEn || det.tech) : det.tech}</div>
                <div><span style={{ color: C.gold, fontWeight: 700 }}>{t(dlang, "dp_biz")}</span><br />{dlang === "en" ? (det.bizEn || det.biz) : det.biz}<br /><br /><span style={{ color: C.wine, fontWeight: 700 }}>{t(dlang, "dp_qa")}</span><br />{dlang === "en" ? (det.qaEn || det.qa) : det.qa}</div>
                <div><span style={{ color: "#C9A0DC", fontWeight: 700 }}>{t(dlang, "dp_cost")}</span><br />{dlang === "en" ? (det.costEn || det.cost) : det.cost}</div>
              </div>
              {(() => {
                const hay = [det.role, det.tech, det.biz, det.qa, det.cost, node.label, node.en].filter(Boolean).join(" ");
                const hit = findLexTerm(hay);
                if (!hit) return null;
                const label = dlang === "en" ? (hit.en || hit.t) : hit.t;
                return (
                  <div style={{ marginTop: 10 }}>
                    <button onClick={() => setJump({ tab: "lexicon", lexTerm: dlang === "en" ? (hit.en || hit.t) : hit.t })}
                            style={{ background: "transparent", border: `1px solid ${C.line}`, borderRadius: 6, color: C.gold, fontSize: 11, padding: "4px 10px", cursor: "pointer", fontFamily: "inherit" }}>
                      {t(dlang, "xlink_tolex")}（{label}）
                    </button>
                  </div>
                );
              })()}
              <EvidenceLinks refs={d.refs} />
            </Card>
          )}
        </div>
      )}

      {view === "versus" && (
        <div>
          <div style={{ fontSize: 12, color: C.muted, marginBottom: 12 }}>
            {t(dlang, "vs_intro")}
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%, 300px),1fr))", gap: 12 }}>
            {VERSUS.map((v) => {
              const en = dlang === "en";
              return (
              <Card key={v.theme}>
                <div className="gh-display" style={{ fontSize: 15, color: C.gold, marginBottom: 8 }}>{en && v.themeEn ? v.themeEn : v.theme}</div>
                <div style={{ fontSize: 12, lineHeight: 1.8 }}>
                  <div style={{ marginBottom: 6 }}><span style={{ color: C.teal, fontWeight: 700 }}>{t(dlang, "vs_axes")}</span>{en && v.axesEn ? v.axesEn : v.axes}</div>
                  <div style={{ marginBottom: 8 }}><span style={{ color: C.wine, fontWeight: 700 }}>{t(dlang, "vs_rule")}</span>{en && v.ruleEn ? v.ruleEn : v.rule}</div>
                  <div style={{ fontSize: 11.5, color: C.muted, fontStyle: "italic", borderTop: `1px solid ${C.line}`, paddingTop: 8 }}>{en && v.sayEn ? v.sayEn : v.say}</div>
                </div>
                {(() => {
                  const hay = [v.theme, v.axes, v.rule].filter(Boolean).join(" ");
                  const hit = findLexTerm(hay);
                  if (!hit) return null;
                  const label = en ? (hit.en || hit.t) : hit.t;
                  return (
                    <div style={{ marginTop: 8 }}>
                      <button onClick={() => setJump({ tab: "lexicon", lexTerm: en ? (hit.en || hit.t) : hit.t })}
                              style={{ background: "transparent", border: `1px solid ${C.line}`, borderRadius: 6, color: C.gold, fontSize: 10.5, padding: "3px 9px", cursor: "pointer", fontFamily: "inherit" }}>
                        {t(dlang, "xlink_tolex")}（{label}）
                      </button>
                    </div>
                  );
                })()}
              </Card>
              );
            })}
          </div>
        </div>
      )}

      {view === "drills" && (
        <div>
          <div style={{ fontSize: 12, color: C.muted, marginBottom: 12 }}>
            {t(dlang, "dr_intro")}
          </div>
          <div style={{ display: "grid", gap: 12 }}>
            {DRILLS.map((dr, i) => {
              const shown = stepOf(i);
              const en = dlang === "en";
              const steps = en && dr.stepsEn ? dr.stepsEn : dr.steps;
              const total = steps.length + 1; // steps + 答え/教訓
              return (
                <Card key={i}>
                  <div style={{ display: "flex", gap: 10, alignItems: "baseline" }}>
                    <span className="gh-display" style={{ color: C.gold, fontSize: 18 }}>{"Q" + (i + 1)}</span>
                    <span style={{ fontSize: 14, fontWeight: 700 }}>{en && dr.qEn ? dr.qEn : dr.q}</span>
                  </div>
                  <div style={{ fontSize: 12, color: C.muted, margin: "6px 0 10px" }}>{t(dlang, "dr_given")}{en && dr.givenEn ? dr.givenEn : dr.given}</div>
                  {steps.slice(0, shown).map((st, j) => (
                    <div key={j} style={{ fontFamily: "monospace", fontSize: 12.5, color: C.teal, background: C.bg, padding: "7px 10px", borderRadius: 6, marginBottom: 6 }}>
                      {"STEP " + (j + 1) + " ｜ " + st}
                    </div>
                  ))}
                  {shown > steps.length && (
                    <div style={{ fontSize: 12.5, lineHeight: 1.8, borderTop: `1px solid ${C.line}`, paddingTop: 8, marginTop: 4 }}>
                      <div><span style={{ color: C.gold, fontWeight: 700 }}>{t(dlang, "dr_ans")}</span>{en && dr.ansEn ? dr.ansEn : dr.ans}</div>
                      <div style={{ color: C.muted, marginTop: 4 }}><span style={{ color: C.wine, fontWeight: 700 }}>{t(dlang, "dr_lesson")}</span>{en && dr.lessonEn ? dr.lessonEn : dr.lesson}</div>
                    </div>
                  )}
                  <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                    {shown < total && <button className="gh-btn gh-btn-primary" onClick={() => advance(i, total)}>{shown < steps.length ? t(dlang, "dr_next") : t(dlang, "dr_reveal")}</button>}
                    {shown > 0 && <button className="gh-btn" onClick={() => closeDrill(i)}>{t(dlang, "dr_close")}</button>}
                  </div>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {view === "industry" && <IndustryView />}

      {view === "mock" && <MockInterview />}

      {view === "devlang" && <DevLangView />}

      {view === "cloud" && <CloudDojoWrapper />}

      {view === "archquiz" && <ArchQuizView />}

      {view === "mcq" && <McqView />}
    </div>
  );
}

