      {cell(155, 40, "TP", "TP", C.green, t("正しく陽性", "true positive"))}
      {cell(335, 40, "FP", "FP", C.crimson, t("誤検知", "false positive"))}
      {cell(155, 125, "FN", "FN", C.crimson, t("見逃し", "false negative"))}
