var DOMAINS = [
  {id:"D1", name:"クラウドのコンセプト", weight:24, color:"#1d9e75", bg:"#e1f5ee", tx:"#0f6e56"},
  {id:"D2", name:"セキュリティとコンプライアンス", weight:30, color:"#7f77dd", bg:"#eeedfe", tx:"#3c3489"},
  {id:"D3", name:"クラウドテクノロジーとサービス", weight:34, color:"#378add", bg:"#e6f1fb", tx:"#0c447c"},
  {id:"D4", name:"請求・料金・サポート", weight:12, color:"#ba7517", bg:"#faeeda", tx:"#633806"}
];
function dom(id){ for(var i=0;i<DOMAINS.length;i++) if(DOMAINS[i].id===id) return DOMAINS[i]; }

/* ===== 選択肢シャッフル（シード付き決定論的）=====
   元データは正解が常に o[0]（a:0）。表示時にシードで並べ替え、
   同じ設問は常に同じ並びになるよう固定。返り値は {o:[...], a:正解位置}。 */
function seededShuffleChoices(opts, ansIdx, seed){
  var n = opts.length;
  var order = [];
  for(var i=0;i<n;i++) order.push(i);
  // mulberry32 系の簡易PRNG
  var s = seed >>> 0;
  function rnd(){
    s |= 0; s = (s + 0x6D2B79F5) | 0;
    var t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
  // Fisher-Yates
  for(var j=n-1;j>0;j--){
    var k = Math.floor(rnd()*(j+1));
    var tmp = order[j]; order[j] = order[k]; order[k] = tmp;
  }
  var newOpts = [], newAns = 0;
  for(var m=0;m<n;m++){
    newOpts.push(opts[order[m]]);
    if(order[m] === ansIdx) newAns = m;
  }
  return {o:newOpts, a:newAns};
}
// 設問テキストから安定したシード値を生成（文字列ハッシュ）
function strSeed(str){
  var h = 2166136261;
  for(var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
// 設問オブジェクトに対しシャッフル済みの {o,a} を返す（接頭辞でシードを分離可能）
function shuffledQ(q, salt){
  var seed = strSeed((salt||"") + q.q);
  return seededShuffleChoices(q.o, q.a, seed);
}

/* データはこの後 __DATA__ プレースホルダに注入 */
