// ===== 階層関係：Organizations =====
function OrgHierarchy({ lang }) {
  const en = lang === "en";
  const Node = ({ label, sub, hue, indent }) => (
    <div style={{ marginLeft: indent * 22, marginBottom: 8, position: "relative" }}>
      {indent > 0 && <span style={{ position: "absolute", left: -14, top: 0, bottom: 0, width: 2, background: C.mid }} />}
      <div style={{ background: hue, color: "#fff", borderRadius: 9, padding: "9px 13px", display: "inline-block", minWidth: 180 }}>
        <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
        <div style={{ fontSize: 11, opacity: 0.9 }}>{sub}</div>
      </div>
    </div>
  );
  return (
    <div>
      <Node label={en ? "Management Account" : "管理アカウント"} sub={en ? "Root of the organization" : "組織のルート・一括請求"} hue={C.deep} indent={0} />
      <Node label="Root" sub={en ? "Top of OU tree" : "OU ツリーの最上位"} hue={C.accent} indent={1} />
      <Node label={en ? "OU: Production" : "OU：本番"} sub={en ? "SCP applies here" : "SCP を適用"} hue="#CC7000" indent={2} />
      <Node label={en ? "Account A / B" : "アカウント A / B"} sub={en ? "Max perms capped by SCP" : "最大権限は SCP で制限"} hue={C.primary} indent={3} />
      <Node label={en ? "OU: Sandbox" : "OU：サンドボックス"} sub={en ? "Looser guardrails" : "緩いガードレール"} hue="#CC7000" indent={2} />
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8, lineHeight: 1.6 }}>
        {en ? "SCPs flow down the tree, capping the maximum permissions of every account below." : "SCP はツリーを下方向に流れ、配下の全アカウントの最大権限を制限します（権限の付与はしません）。"}
      </div>
    </div>
  );
}

// ===== 階層関係：IAM 権限スコープ =====
function IamScopeHierarchy({ lang }) {
  const en = lang === "en";
  const rings = [
    [en ? "SCP (organization cap)" : "SCP（組織の上限）", C.deep, en ? "Caps the account's max permissions" : "アカウントの最大権限を制限"],
    [en ? "Permissions boundary" : "許可境界", C.accent, en ? "Caps an individual principal" : "個別主体の上限を制限"],
    [en ? "Identity-based policy" : "アイデンティティベースポリシー", "#CC7000", en ? "Grants permissions to the principal" : "主体に権限を付与"],
    [en ? "Session policy" : "セッションポリシー", C.primary, en ? "Further narrows a single session" : "セッションを更に限定"],
  ];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>
        {en ? "Effective permissions = intersection of all caps AND an explicit allow, with any explicit deny winning." : "実効権限 = すべての上限の積集合 ∩ 明示的許可。明示的拒否があれば最優先で覆りません。"}
      </div>
      {rings.map(([label, hue, desc], i) => (
        <div key={i} style={{ marginLeft: i * 16, marginBottom: 7, background: "#fff", border: `2px solid ${hue}`, borderRadius: 10, padding: "9px 12px" }}>
          <span style={{ background: hue, color: "#fff", borderRadius: 5, padding: "2px 8px", fontSize: 11, fontWeight: 700, marginRight: 8 }}>{i + 1}</span>
          <strong style={{ fontSize: 13, color: C.deep }}>{label}</strong>
          <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 3 }}>{desc}</div>
        </div>
      ))}
    </div>
  );
}

// ===== 上下関係：多層防御レイヤー =====
function DefenseLayers({ lang }) {
  const en = lang === "en";
  const [sel, setSel] = useState(null);
  const layers = [
    [en ? "Edge: Shield + WAF + CloudFront" : "エッジ：Shield + WAF + CloudFront", "#232F3E", en ? "Mitigate DDoS and block L7 attacks before they reach the app." : "DDoS を緩和し L7 攻撃をアプリ到達前に遮断。"],
    [en ? "Network ACL (subnet)" : "ネットワーク ACL（サブネット）", "#146EB4", en ? "Stateless allow/deny at the subnet boundary." : "サブネット境界でステートレスに許可/拒否。"],
    [en ? "Security Group (instance)" : "セキュリティグループ（インスタンス）", "#CC7000", en ? "Stateful allow-only rules at the ENI." : "ENI 単位でステートフルな許可ルール。"],
    [en ? "IAM + encryption (data)" : "IAM＋暗号化（データ）", "#FF9900", en ? "Least-privilege access and encryption at rest/in transit." : "最小権限と保管時/転送時の暗号化。"],
  ];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>{en ? "Outer to inner: each layer backs up the others. Tap a layer." : "外側から内側へ、各層が互いを補完。層をタップ。"}</div>
      {layers.map(([label, hue, desc], i) => (
        <div key={i} onClick={() => setSel(sel === i ? null : i)}
          style={{ marginBottom: 6, marginLeft: i * 14, marginRight: i * 14, background: hue, color: "#fff", borderRadius: 10, padding: "12px 14px", cursor: "pointer", textAlign: "center", boxShadow: sel === i ? "0 0 0 3px rgba(255,153,0,.4)" : "none" }}>
          <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
          {sel === i && <div style={{ fontSize: 12, marginTop: 6, opacity: 0.95, lineHeight: 1.5 }}>{desc}</div>}
        </div>
      ))}
      <div style={{ textAlign: "center", fontSize: 11, color: "#9b8d82", marginTop: 4 }}>↓ {en ? "deeper = closer to data" : "下ほどデータに近い"}</div>
    </div>
  );
}

// ===== 上下関係：DR の RTO 階段 =====
function DrLadder({ lang }) {
  const en = lang === "en";
  const steps = [
    [en ? "Multi-Site (active/active)" : "マルチサイト（アクティブ/アクティブ）", en ? "Near-zero RTO, highest cost" : "RTO ほぼゼロ・最高コスト", "#232F3E"],
    [en ? "Warm Standby" : "ウォームスタンバイ", en ? "Scaled-down always-on, short RTO" : "縮小版を常時稼働・短い RTO", "#146EB4"],
    [en ? "Pilot Light" : "パイロットライト", en ? "Core (DB) only running" : "中核（DB）のみ稼働", "#CC7000"],
    [en ? "Backup & Restore" : "バックアップ＆リストア", en ? "Cheapest, largest RTO/RPO" : "最安・RTO/RPO 最大", "#FF9900"],
  ];
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "#9b8d82", marginBottom: 8 }}>
        <span>← {en ? "lower cost" : "低コスト"}</span><span>{en ? "shorter RTO" : "短い RTO"} →</span>
      </div>
      {steps.map(([label, sub, hue], i) => (
        <div key={i} style={{ marginBottom: 6, marginLeft: (3 - i) * 30, background: hue, color: "#fff", borderRadius: 9, padding: "10px 14px" }}>
          <div style={{ fontWeight: 700, fontSize: 13 }}>{label}</div>
          <div style={{ fontSize: 11.5, opacity: 0.9 }}>{sub}</div>
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Higher steps = shorter RTO but higher cost. Pick by RTO/RPO requirement and budget." : "上の段ほど RTO が短いがコストも高い。RTO/RPO 要件と予算で選ぶ。"}</div>
    </div>
  );
}

// ===== 並列関係：ストレージ =====
function StorageParallel({ lang }) {
  const en = lang === "en";
  const cards = [
    ["Amazon EBS", "#232F3E", [en ? "Block, single AZ" : "ブロック・単一 AZ", en ? "1 instance (usually)" : "原則 1 インスタンス", en ? "Persistent" : "永続"]],
    ["Amazon EFS", "#146EB4", [en ? "File (NFS), multi-AZ" : "ファイル(NFS)・複数 AZ", en ? "Many concurrent" : "多数で同時共有", en ? "Auto-scaling" : "自動拡張"]],
    [en ? "Instance Store" : "インスタンスストア", "#CC7000", [en ? "Block, ephemeral" : "ブロック・一時", en ? "Ultra fast" : "超高速", en ? "Lost on stop" : "停止で消失"]],
    ["Amazon S3", "#FF9900", [en ? "Object, 11x9 durability" : "オブジェクト・高耐久", en ? "Internet-scale" : "ほぼ無制限", en ? "Class by access" : "クラスで最適化"]],
  ];
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
      {cards.map(([name, hue, items], i) => (
        <div key={i} style={{ border: `1.5px solid ${hue}`, borderRadius: 11, overflow: "hidden" }}>
          <div style={{ background: hue, color: "#fff", padding: "8px 10px", fontWeight: 700, fontSize: 13 }}>{name}</div>
          <div style={{ padding: "8px 10px" }}>
            {items.map((it, j) => <div key={j} style={{ fontSize: 12, color: C.ink, padding: "3px 0", lineHeight: 1.4 }}>・{it}</div>)}
          </div>
        </div>
      ))}
    </div>
  );
}

// ===== 並列関係：メッセージング =====
function MsgParallel({ lang }) {
  const en = lang === "en";
  const cards = [
    ["SQS", "#232F3E", en ? "Queue (pull)" : "キュー（プル）", en ? "One consumer pulls and processes. Buffers spikes." : "1 つのコンシューマーが取得し処理。急増を吸収。"],
    ["SNS", "#146EB4", en ? "Pub/Sub (push)" : "Pub/Sub（プッシュ）", en ? "Broadcasts one message to many subscribers." : "1 件を複数の購読先へ同報。"],
    ["EventBridge", "#FF9900", en ? "Event bus" : "イベントバス", en ? "Routes events by rules to many targets; SaaS integration." : "ルールで複数ターゲットへ振り分け。SaaS 連携。"],
  ];
  return (
    <div>
      {cards.map(([name, hue, kind, desc], i) => (
        <div key={i} style={{ display: "flex", alignItems: "stretch", marginBottom: 8, border: `1.5px solid ${hue}`, borderRadius: 11, overflow: "hidden" }}>
          <div style={{ background: hue, color: "#fff", padding: "10px 12px", fontWeight: 700, fontSize: 14, minWidth: 110, display: "flex", flexDirection: "column", justifyContent: "center" }}>
            {name}<span style={{ fontSize: 11, opacity: 0.9, fontWeight: 500 }}>{kind}</span>
          </div>
          <div style={{ padding: "10px 12px", fontSize: 12.5, color: C.ink, lineHeight: 1.5, display: "flex", alignItems: "center" }}>{desc}</div>
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 4 }}>{en ? "Common fan-out: SNS → multiple SQS queues for independent, scalable consumers." : "定番のファンアウト：SNS → 複数 SQS で独立・スケール可能な消費者を構成。"}</div>
    </div>
  );
}

// ===== フロー：3 層 Web リクエスト =====
function FlowChain({ nodes }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
      {nodes.map((n, i) => (
        <div key={i}>
          <div style={{ background: n[1], color: "#fff", borderRadius: 9, padding: "10px 13px" }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{n[0]}</div>
            {n[2] && <div style={{ fontSize: 11.5, opacity: 0.92, marginTop: 2 }}>{n[2]}</div>}
          </div>
          {i < nodes.length - 1 && <div style={{ textAlign: "center", color: C.mid, fontSize: 18, lineHeight: "20px" }}>↓</div>}
        </div>
      ))}
    </div>
  );
}

function RequestFlow({ lang }) {
  const en = lang === "en";
  return (
    <div>
      <FlowChain nodes={[
        [en ? "User" : "ユーザー", "#9b8d82", en ? "Browser request" : "ブラウザからの要求"],
        ["Route 53", "#232F3E", en ? "DNS resolves to CloudFront/ALB" : "DNS で CloudFront/ALB へ解決"],
        ["CloudFront (+WAF)", "#146EB4", en ? "Edge cache, blocks L7 attacks" : "エッジキャッシュ・L7 攻撃を遮断"],
        ["ALB", "#CC7000", en ? "L7 routing to healthy targets" : "正常ターゲットへ L7 振り分け"],
        [en ? "EC2 ASG (web/app)" : "EC2 ASG（Web/アプリ）", "#FF9900", en ? "Auto-scales across AZs" : "複数 AZ で自動スケール"],
        [en ? "RDS Multi-AZ / cache" : "RDS マルチ AZ / キャッシュ", "#2E7D5B", en ? "DB in private subnet + ElastiCache" : "プライベートサブネットの DB＋ElastiCache"],
      ]} />
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Classic highly-available 3-tier flow. Each hop adds scaling or protection." : "高可用な 3 層構成の典型フロー。各段でスケールや防御を付加。"}</div>
    </div>
  );
}

function QueueFlow({ lang }) {
  const en = lang === "en";
  return (
    <div>
      <FlowChain nodes={[
        [en ? "Producer (API)" : "プロデューサー（API）", "#232F3E", en ? "Accepts requests fast, returns immediately" : "要求を素早く受け即応答"],
        ["Amazon SQS", "#146EB4", en ? "Buffers and persists messages" : "メッセージを蓄積・永続化"],
        [en ? "Worker ASG" : "ワーカー ASG", "#CC7000", en ? "Scales on queue length (idempotent)" : "キュー長でスケール（冪等処理）"],
        [en ? "Downstream DB" : "下流 DB", "#FF9900", en ? "Protected from spikes" : "急増から保護される"],
      ]} />
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Decoupling with a queue smooths spikes and isolates failures." : "キューによる疎結合で急増を平準化し障害を分離する。"}</div>
    </div>
  );
}

function FailoverFlow({ lang }) {
  const en = lang === "en";
  const [step, setStep] = useState(0);
  const frames = [
    [en ? "Normal: app → primary (AZ-a)" : "通常時：アプリ → プライマリ（AZ-a）", en ? "Synchronous replication to standby in AZ-b." : "AZ-b のスタンバイへ同期複製。", "#2E7D5B"],
    [en ? "Failure: primary in AZ-a goes down" : "障害発生：AZ-a のプライマリが停止", en ? "RDS detects the failure automatically." : "RDS が障害を自動検知。", "#C0392B"],
    [en ? "Failover: standby promoted (AZ-b)" : "フェイルオーバー：スタンバイ昇格（AZ-b）", en ? "Same endpoint (DNS) now points to AZ-b." : "同一エンドポイント（DNS）が AZ-b を指す。", "#CC7000"],
    [en ? "Recovered: app reconnects, continues" : "復旧：アプリは再接続し継続", en ? "App just needs retry logic; no manual change." : "アプリは再試行のみで手動変更は不要。", "#2E7D5B"],
  ];
  return (
    <div>
      <div style={{ background: frames[step][2], color: "#fff", borderRadius: 11, padding: 16, marginBottom: 10, minHeight: 70 }}>
        <div style={{ fontSize: 11, opacity: 0.85, fontWeight: 700 }}>STEP {step + 1} / 4</div>
        <div style={{ fontSize: 15, fontWeight: 800, margin: "4px 0" }}>{frames[step][0]}</div>
        <div style={{ fontSize: 12.5, opacity: 0.95, lineHeight: 1.5 }}>{frames[step][1]}</div>
      </div>
      <div style={{ display: "flex", gap: 8 }}>
        <button onClick={() => setStep(s => Math.max(0, s - 1))} disabled={step === 0}
          style={{ flex: 1, padding: 10, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: step === 0 ? "#bcae9f" : C.ink, fontWeight: 700, fontSize: 13, cursor: step === 0 ? "default" : "pointer" }}>← {en ? "Prev" : "前へ"}</button>
        <button onClick={() => setStep(s => Math.min(3, s + 1))} disabled={step === 3}
          style={{ flex: 1, padding: 10, borderRadius: 9, border: "none", background: step === 3 ? C.mid : C.primary, color: C.deep, fontWeight: 700, fontSize: 13, cursor: step === 3 ? "default" : "pointer" }}>{en ? "Next" : "次へ"} →</button>
      </div>
      <div style={{ display: "flex", gap: 5, marginTop: 10, justifyContent: "center" }}>
        {frames.map((_, i) => <div key={i} onClick={() => setStep(i)} style={{ width: 10, height: 10, borderRadius: 5, background: i === step ? C.primary : C.mid, cursor: "pointer" }} />)}
      </div>
    </div>
  );
}

// ===== 概念図：VPC =====
function VpcConcept({ lang }) {
  const en = lang === "en";
  const Box = ({ label, sub, hue, children, dashed }) => (
    <div style={{ border: `${dashed ? "2px dashed" : "1.5px solid"} ${hue}`, borderRadius: 10, padding: 10, marginBottom: 8 }}>
      <div style={{ fontWeight: 700, fontSize: 12.5, color: hue }}>{label}{sub && <span style={{ fontSize: 11, color: "#9b8d82", fontWeight: 500 }}> — {sub}</span>}</div>
      {children && <div style={{ marginTop: 8 }}>{children}</div>}
    </div>
  );
  const Chip = ({ t, hue }) => <span style={{ display: "inline-block", background: hue, color: "#fff", borderRadius: 6, padding: "4px 9px", fontSize: 11.5, fontWeight: 600, margin: "0 6px 6px 0" }}>{t}</span>;
  return (
    <div>
      <Box label="VPC (10.0.0.0/16)" sub={en ? "isolated network" : "隔離ネットワーク"} hue={C.deep}>
        <Box label={en ? "Public subnet" : "パブリックサブネット"} sub={en ? "route to IGW" : "IGW への経路あり"} hue={C.accent}>
          <Chip t="ALB" hue={C.accent} /><Chip t="NAT GW" hue={C.accent} /><Chip t={en ? "Bastion (rare)" : "踏み台(まれ)"} hue={C.accent} />
        </Box>
        <Box label={en ? "Private subnet" : "プライベートサブネット"} sub={en ? "no inbound from internet" : "インターネットから受信不可"} hue="#CC7000">
          <Chip t={en ? "App EC2 (ASG)" : "アプリ EC2(ASG)"} hue="#CC7000" /><Chip t="Lambda" hue="#CC7000" />
        </Box>
        <Box label={en ? "Private (DB) subnet" : "プライベート(DB)サブネット"} sub={en ? "most protected" : "最も保護"} hue={C.primary}>
          <Chip t={en ? "RDS Multi-AZ" : "RDS マルチ AZ"} hue={C.primary} /><Chip t="ElastiCache" hue={C.primary} />
        </Box>
        <Box label={en ? "Gateway endpoint" : "ゲートウェイエンドポイント"} sub={en ? "free private path to S3/DynamoDB" : "S3/DynamoDB へ無料の閉域経路"} hue="#2E7D5B" dashed />
      </Box>
      <div style={{ fontSize: 12, color: "#6b5d52", lineHeight: 1.6 }}>
        {en ? "Public subnet = has a route to the Internet Gateway. Private subnets reach the internet only outbound via NAT, and reach S3/DynamoDB free via a gateway endpoint." : "パブリック＝IGW への経路あり。プライベートは NAT 経由で外向きのみ、S3/DynamoDB へはゲートウェイエンドポイントで無料の閉域接続。"}
      </div>
    </div>
  );
}

// ===== 概念図：エッジ防御 =====
function EdgeConcept({ lang }) {
  const en = lang === "en";
  const items = [
    [en ? "Internet (users + attackers)" : "インターネット（利用者＋攻撃者）", "#9b8d82"],
    ["Route 53", "#232F3E", en ? "DNS + health-based failover" : "DNS＋ヘルスチェックで切替"],
    ["AWS Shield", "#146EB4", en ? "L3/L4 DDoS mitigation" : "L3/L4 の DDoS 緩和"],
    ["AWS WAF", "#CC7000", en ? "L7: blocks SQLi / XSS / rate" : "L7：SQLi/XSS/レート遮断"],
    ["CloudFront (+OAC)", "#FF9900", en ? "Edge cache, keeps origin private" : "エッジキャッシュ・オリジン非公開"],
    [en ? "Origin (S3 / ALB)" : "オリジン（S3 / ALB）", "#2E7D5B", en ? "Only reachable via CloudFront" : "CloudFront 経由のみ到達可"],
  ];
  return (
    <div>
      {items.map((it, i) => (
        <div key={i}>
          <div style={{ background: it[1], color: "#fff", borderRadius: 9, padding: "10px 13px", textAlign: "center" }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{it[0]}</div>
            {it[2] && <div style={{ fontSize: 11.5, opacity: 0.92, marginTop: 2 }}>{it[2]}</div>}
          </div>
          {i < items.length - 1 && <div style={{ textAlign: "center", color: C.mid, fontSize: 16 }}>↓</div>}
        </div>
      ))}
      <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 8 }}>{en ? "Layered edge: Shield (DDoS) → WAF (app attacks) → CloudFront (cache + OAC) protects the origin." : "層状のエッジ防御：Shield(DDoS)→WAF(アプリ攻撃)→CloudFront(キャッシュ＋OAC)でオリジンを守る。"}</div>
    </div>
  );
}

// ===== 決定木：オンプレ接続 =====
function ConnectTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "Top priority?" : "最優先事項は？", opts: [[en ? "Stable bandwidth / low latency" : "安定帯域・低遅延", "dx"], [en ? "Low cost / quick setup" : "低コスト・手早く", "vpn"], [en ? "Stable + encrypted" : "安定かつ暗号化", "both"], [en ? "Connect many VPCs centrally" : "多数の VPC を集約", "tgw"]] },
  };
  const leaves = {
    dx: ["Direct Connect", en ? "Dedicated line: stable bandwidth and low latency. Higher cost." : "専用線で安定帯域・低遅延。コストは高め。"],
    vpn: ["Site-to-Site VPN", en ? "IPsec over internet: cheap and quick, best-effort quality." : "インターネット経由 IPsec で安価・手早い。品質はベストエフォート。"],
    both: ["Direct Connect + VPN", en ? "Stable DX path with an encrypted VPN on top." : "DX で安定帯域を確保し VPN を重ねて暗号化。"],
    tgw: ["Transit Gateway", en ? "Central hub aggregating many VPCs and on-prem connections." : "多数の VPC とオンプレ接続を集約する中央ハブ。"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

// ===== 決定木：ロードバランサー =====
function LbTree({ lang }) {
  const en = lang === "en";
  const steps = {
    start: { q: en ? "Traffic type?" : "トラフィックの種類は？", opts: [[en ? "HTTP/HTTPS (L7)" : "HTTP/HTTPS（L7）", "alb"], [en ? "TCP/UDP, ultra-low latency (L4)" : "TCP/UDP・超低遅延（L4）", "nlb"], [en ? "3rd-party appliances" : "サードパーティ仮想アプライアンス", "glb"]] },
  };
  const leaves = {
    alb: ["Application Load Balancer", en ? "L7 path/host routing for HTTP(S), microservices, WAF integration." : "L7 でパス/ホスト振り分け。マイクロサービスや WAF 連携に。"],
    nlb: ["Network Load Balancer", en ? "L4, static IP, millions of connections at ultra-low latency." : "L4・固定 IP・超低遅延で大量接続を処理。"],
    glb: ["Gateway Load Balancer", en ? "Deploy and scale third-party virtual appliances (firewalls, IDS)." : "FW/IDS 等のサードパーティ仮想アプライアンスを集約・スケール。"],
  };
  return <DecisionWidget lang={lang} steps={steps} leaves={leaves} />;
}

// ===== 階層：責任共有モデル =====
