// クイズ全問題（BANK + BANK_EXTRA + BANK_EXTRA2 を結合）
const ALL_QUESTIONS = BANK.concat(BANK_EXTRA).concat(BANK_EXTRA2).filter((q, i, a) => a.findIndex(x => x.q.replace(/\s+/g, "") === q.q.replace(/\s+/g, "")) === i);

// ===== 永続化 =====
async function loadState() {
  try {
    const r = await window.storage.get(STORE_KEY);
    return r ? JSON.parse(r.value) : null;
  } catch { return null; }
}
async function saveState(s) {
  try { await window.storage.set(STORE_KEY, JSON.stringify(s)); } catch {}
}

function todayStr() { return new Date().toISOString().slice(0, 10); }
function domName(id) { return DOM_NAME[id]; }
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ===== 決定的シャッフル：選択肢の順序を入れ替え、正解が先頭固定にならないようにする =====
// 問題文から安定したシード値を生成（同じ問題は常に同じ並びになる＝学習の一貫性）
function hashString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
// シード付き擬似乱数（mulberry32）
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// 問題オブジェクトを受け取り、シャッフル済みの選択肢配列と新しい正解indexを返す
// 戻り値: { opts: [...], a: 新正解index }
function shuffleOptions(Q) {
  const rng = mulberry32(hashString(Q.q));
  // インデックス配列をFisher-Yatesでシャッフル
  const idx = Q.o.map((_, i) => i);
  for (let i = idx.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  // 万一、正解がまだ先頭(0番目)に来てしまった場合は、別の位置と入れ替える
  let pos = idx.indexOf(Q.a);
  if (pos === 0) {
    // rngで0以外の位置を選んで交換
    const swapWith = 1 + Math.floor(rng() * (idx.length - 1));
    [idx[0], idx[swapWith]] = [idx[swapWith], idx[0]];
    pos = idx.indexOf(Q.a);
  }
  const opts = idx.map(i => Q.o[i]);
  return { opts, a: pos };
}

// ===== メインアプリ =====
const PL900_EXAM_CASES = [{"id":"pl900-1","title":{"ja":"ケース：製造現場の点検アプリと承認自動化の内製","en":"Case: In-house Inspection App and Approval Automation on the Manufacturing Floor"},"body":{"ja":["中堅の精密部品メーカー「山陽精密工業」では、設備保全部門が毎日の設備点検を紙とExcelで記録している。転記ミスや承認の遅延が慢性化し、現場のリーダー田中は「IT部門に頼らず自分たちでデジタル化したい」と考えている。同社は既にMicrosoft 365 E3を全社員に配布済みで、追加コストは経営層の承認が必要な状況である。","田中はまず、現場作業員がスマートフォンとタブレットで点検結果を入力できるモバイル業務アプリを作りたい。カメラで異常箇所を撮影し、GPSで設備位置を記録する機能も求められている。作業員はITに詳しくないため、画面は業務に合わせて自由にデザインしたいという要望が強い。","点検で異常が見つかった場合、修理依頼が保全課長へ自動で回付され、承認されると購買部門に通知が飛ぶ仕組みも欲しい。承認はTeamsとメールの両方で受け取りたい。データは全社の設備マスタと関連付けて管理し、設備ごとの点検履歴やリレーションを保持する必要がある。将来は数万件規模に増える見込みで、行レベルのアクセス制御も検討している。","情報システム部門の鈴木は、データの置き場所として既存のSharePointリストで十分か、それとも別の基盤が必要かを整理するよう求められた。また外部の基幹システム（オンプレミスSQL Server）から部品在庫を参照する要件もあり、利用するコネクタの種別とライセンス影響を明確にしたい。","経営層はROIを重視しており、ローコードによる内製化で外注費と開発期間をどれだけ削減できるかを説明する必要がある。田中と鈴木は、Power Platformの各コンポーネントを適切に選定し、必要なライセンスとガバナンス上の留意点を提案書にまとめることになった。"],"en":["At Sanyo Precision, a mid-sized precision-parts maker, the facility-maintenance team records daily equipment inspections on paper and in Excel. Transcription errors and slow approvals are chronic, and floor lead Tanaka wants to digitize the process himself without relying on IT. The company already licenses Microsoft 365 E3 for all staff, and any added cost needs executive approval.","Tanaka first wants a mobile business app so workers can enter inspection results on phones and tablets. He needs the camera to photograph anomalies and GPS to record equipment location. Because the workers are not tech-savvy, there is strong demand to design the screens freely to match the task.","When an anomaly is found, a repair request should route automatically to the maintenance manager, and once approved, notify the purchasing team. Approvals should arrive in both Teams and email. Data must be linked to a company-wide equipment master, preserving inspection history and relationships per asset. Volume is expected to reach tens of thousands of rows, and row-level access control is under consideration.","Suzuki from IT was asked to determine whether an existing SharePoint list suffices as the data store or whether a different platform is needed. There is also a requirement to reference parts inventory from an on-premises SQL Server core system, so the connector type and its licensing impact must be clarified.","Executives care about ROI and need to understand how much low-code in-house development can cut outsourcing costs and delivery time. Tanaka and Suzuki must select the right Power Platform components and summarize the required licenses and governance considerations in a proposal."]},"tables":[{"title":{"ja":"候補コンポーネントと主な特性","en":"Candidate Components and Key Characteristics"},"headers":{"ja":["コンポーネント","画面設計","主なデータ基盤","モバイル/カメラ"],"en":["Component","Screen Design","Primary Data Store","Mobile/Camera"]},"rows":{"ja":[["キャンバスアプリ","自由配置で作り込み","任意コネクタ/Dataverse","対応（カメラ・GPS可）"],["モデル駆動アプリ","データ主導で自動生成","Dataverse必須","対応（設計自由度低）"],["Power Pages","外部公開Webサイト","Dataverse","ブラウザ中心"],["Power BI","レポート/ダッシュボード","各種データソース","閲覧中心"]],"en":[["Canvas app","Freeform pixel layout","Any connector/Dataverse","Yes (camera, GPS)"],["Model-driven app","Data-driven, auto-generated","Dataverse required","Yes (low layout freedom)"],["Power Pages","External-facing website","Dataverse","Browser-centric"],["Power BI","Reports/dashboards","Many data sources","View-centric"]]}},{"title":{"ja":"データ基盤の比較（想定規模：数万行・リレーションあり）","en":"Data Store Comparison (target: tens of thousands of rows, with relationships)"},"headers":{"ja":["観点","SharePointリスト","Dataverse"],"en":["Aspect","SharePoint list","Dataverse"]},"rows":{"ja":[["大量データ/リレーション","大規模・複雑な関係は不得手","リレーショナルで得意"],["セキュリティ","リスト/アイテム権限","セキュリティロール・行レベル制御"],["ライセンス","M365内で利用可（標準）","プレミアム（Power Apps有償）"],["業務ロジック","限定的","ビジネスルール・列計算等が充実"]],"en":[["Large data/relationships","Weak for large, complex relations","Strong, relational"],["Security","List/item permissions","Security roles, row-level control"],["Licensing","Included with M365 (standard)","Premium (paid Power Apps)"],["Business logic","Limited","Rich business rules, calculated columns"]]}}],"questions":[{"n":1,"q":{"ja":"作業員が業務に合わせて自由にレイアウトしたモバイル画面から、カメラ撮影とGPS記録を行える点検アプリを内製する。最も適したアプリ種別はどれか。","en":"The team will build an inspection app whose mobile screens are freely laid out to fit the task, with camera capture and GPS. Which app type fits best?"},"options":[{"label":{"ja":"キャンバスアプリ","en":"Canvas app"},"exp":{"ja":"画面をピクセル単位で自由設計でき、カメラ・位置情報コントロールを備えモバイル入力に最適。要件の「自由なデザイン」と撮影・GPSに合致するため正しい。","en":"Canvas apps allow freeform, pixel-level screen design and include camera and location controls, ideal for mobile capture, matching the freeform-design and camera/GPS needs."},"ok":true},{"label":{"ja":"モデル駆動アプリ","en":"Model-driven app"},"exp":{"ja":"データモデルから画面が自動生成されるため、業務に合わせた自由なレイアウト設計には不向き。Dataverse前提でもある点で今回の第一要件と外れる。","en":"Screens are auto-generated from the data model, so it is poorly suited to freeform, task-tailored layouts, and it also requires Dataverse."}},{"label":{"ja":"Power Pages で作る外部公開サイト","en":"An external-facing site built with Power Pages"},"exp":{"ja":"Power Pagesは社外向けWebサイト構築が目的で、社内作業員のモバイル業務アプリ用途とは異なる。カメラ主体の現場入力にも最適ではない。","en":"Power Pages targets external websites, not internal mobile line-of-business apps, and is not ideal for camera-first field entry."}},{"label":{"ja":"Power BI のレポート","en":"A Power BI report"},"exp":{"ja":"Power BIはデータの可視化・分析が目的で、データ入力アプリではない。点検結果の入力やカメラ撮影といった要件を満たせない。","en":"Power BI is for visualization and analysis, not a data-entry app, so it cannot satisfy inspection input or camera capture."}}]},{"n":2,"q":{"ja":"点検データは全社設備マスタとリレーションを持ち、数万行規模・行レベルのアクセス制御が必要である。データ基盤として最も適切な選択はどれか。","en":"Inspection data must relate to a company-wide equipment master, reach tens of thousands of rows, and support row-level access control. Which data store is most appropriate?"},"options":[{"label":{"ja":"Excelブックを共有フォルダに置いて利用する。詳細はライセンス条件により異なることがある","en":"Use a shared Excel workbook in a common folder , with specifics varying by licensing terms"},"exp":{"ja":"Excelはリレーションや行レベルのセキュリティ、大量同時更新に不向きで、業務基盤としての整合性・拡張性を欠くため不適切。","en":"Excel is poor at relationships, row-level security, and concurrent large-scale updates, lacking integrity and scalability as a data platform."}},{"label":{"ja":"SharePointリストで各点検を管理する","en":"Manage each inspection in a SharePoint list"},"exp":{"ja":"M365標準で手軽だが、複雑なリレーションや厳密な行レベル制御・大規模運用には限界がある。要件の細粒度セキュリティを満たしにくい。","en":"Included with M365 and easy, but limited for complex relationships, strict row-level control, and large scale, so it struggles to meet fine-grained security."}},{"label":{"ja":"Dataverse にテーブルを作成しセキュリティロールで制御する","en":"Create tables in Dataverse and control access with security roles"},"exp":{"ja":"Dataverseはリレーショナル構造・セキュリティロールと行レベルの制御を備え、数万行規模にも耐える。全要件に合致するため正しい。","en":"Dataverse provides relational structure, security roles, and row-level control and scales to tens of thousands of rows, meeting all requirements."},"ok":true},{"label":{"ja":"各作業員のOneDrive上のCSVに保存する","en":"Store data in a CSV on each worker's OneDrive"},"exp":{"ja":"個人ストレージ上のCSVは一元管理・リレーション・セキュリティ制御ができず、全社マスタ連携や監査に耐えないため不適切。","en":"A CSV on personal storage offers no central management, relationships, or security control and cannot support master linkage or auditing."}}]},{"n":3,"q":{"ja":"異常検知時に修理依頼を保全課長へ回付し、承認後に購買へ通知する。承認はTeamsとメールで受け取りたい。実装に用いるべきものはどれか。","en":"When an anomaly is detected, route a repair request to the maintenance manager and, once approved, notify purchasing, with approvals in Teams and email. What should be used?"},"options":[{"label":{"ja":"Power Automate のクラウドフロー（承認アクション）","en":"A Power Automate cloud flow with the Approvals action"},"exp":{"ja":"クラウドフローの承認機能はTeamsとメールに承認要求を送り、結果に応じて後続処理を分岐できる。回付・通知の自動化要件に合致し正しい。","en":"Cloud-flow Approvals send requests to both Teams and email and branch on the outcome, matching the routing and notification automation requirement."},"ok":true},{"label":{"ja":"Power Automate のデスクトップフロー（RPA）。管理者が環境ごとに個別確認する前提となる","en":"A Power Automate desktop flow (RPA) , assuming administrators verify this per environment"},"exp":{"ja":"デスクトップフローはUI操作を自動化するRPA用途で、レガシー画面操作向け。API連携で完結する承認・通知にはクラウドフローが適切。","en":"Desktop flows are RPA for UI automation of legacy screens; API-based approvals and notifications are better served by a cloud flow."}},{"label":{"ja":"Power BI のデータアラート","en":"A Power BI data alert"},"exp":{"ja":"データアラートは閾値超過を本人へ知らせるだけで、多段の承認回付や部門横断の通知フローは実装できず要件を満たさない。","en":"Data alerts merely notify the owner when a threshold is crossed and cannot implement multi-step approval routing or cross-team notifications."}},{"label":{"ja":"モデル駆動アプリのビジネスルール","en":"A business rule in a model-driven app"},"exp":{"ja":"ビジネスルールはフォーム上の値検証や表示制御が目的で、承認回付や外部通知のワークフローを担うものではないため不適切。","en":"Business rules handle form-level validation and display logic, not approval routing or external notification workflows."}}]},{"n":4,"q":{"ja":"アプリからオンプレミスSQL Serverの在庫を参照する。SQL Serverコネクタの分類と、DataverseやSQL利用時のライセンスに関する説明として正しいものはどれか。","en":"The app must reference inventory in an on-premises SQL Server. Which statement about the SQL Server connector's classification and the licensing of Dataverse/SQL use is correct?"},"options":[{"label":{"ja":"SQL ServerもDataverseも標準コネクタで、M365 E3のみで追加費用なく利用できる","en":"Both SQL Server and Dataverse are standard connectors, usable with M365 E3 at no extra cost"},"exp":{"ja":"SQL ServerとDataverseはいずれもプレミアム扱いで、M365付帯のシード権では不足する。追加費用なしとする点が誤り。","en":"Both SQL Server and Dataverse are premium; the M365 seeded rights are insufficient, so the no-extra-cost claim is wrong."}},{"label":{"ja":"SQL Serverはプレミアムコネクタで、利用にはPower Apps有償プラン等が必要。オンプレ接続にはオンプレミスデータゲートウェイを使う","en":"SQL Server is a premium connector requiring a paid Power Apps plan, and on-premises connectivity uses an on-premises data gateway"},"exp":{"ja":"SQL Serverはプレミアムコネクタで有償プランが必要、かつオンプレ参照にはデータゲートウェイが必須。分類・接続方式ともに正確で正しい。","en":"SQL Server is a premium connector needing a paid plan, and an on-premises data gateway is required for on-prem access, so both the class and method are correct."},"ok":true},{"label":{"ja":"SQL Serverはプレミアムだが、オンプレミスデータゲートウェイは不要でクラウド同様に直接接続できる。ただし運用要件に応じて見直しを要する場合がある","en":"SQL Server is premium, but no on-premises data gateway is needed and it connects directly like cloud , though it may require review depending on operational requirements"},"exp":{"ja":"分類は正しいが、オンプレミスのSQL Server参照にはデータゲートウェイが必要。ゲートウェイ不要とする点が誤り。","en":"The class is right, but referencing an on-prem SQL Server requires a data gateway, so the no-gateway claim is wrong."}},{"label":{"ja":"Dataverseは標準コネクタなので、プレミアム不要でモバイルアプリから自由に使える","en":"Dataverse is a standard connector, so it can be used freely from a mobile app without premium"},"exp":{"ja":"Dataverseの利用にはプレミアムのPower Apps権利が必要で、標準コネクタ扱いではない。前提が誤っている。","en":"Using Dataverse requires premium Power Apps entitlements and is not a standard connector, so the premise is wrong."}}]}]},{"id":"pl900-2","title":{"ja":"ケース：全社ガバナンスと環境戦略の確立","en":"Case: Establishing Enterprise Governance and Environment Strategy"},"body":{"ja":["全国に店舗を展開する小売企業「マルワ流通」では、各店舗や本部の従業員が自発的にPower Appsやクラウドフローを作り始めた。いわゆる市民開発が急拡大した結果、既定環境（Default環境）に数百のアプリとフローが乱立し、IT部門の情報システム課長・佐藤は統制が効かない状況に危機感を抱いている。","ある部門の担当者が、顧客情報を扱うアプリで社外向けのTwitterコネクタやパブリックなクラウドストレージへデータを送る動きを見せ、情報漏えいリスクが顕在化した。佐藤は、業務用コネクタと非業務用コネクタの間でデータが混在しないよう、テナント全体でポリシーを適用したいと考えている。","同社は開発・検証・本番のライフサイクルを分け、市民開発者には自由に試せる場を与えつつ、本番は厳格に管理する方針を打ち出した。作成物を環境間で正しく移送し、バージョン管理と配布を再現性のある形で行いたい。あわせて、共有先の上限設定や利用状況の可視化、週次のガバナンスレポートといった高度な統制機能も求められている。","経営会議では「市民開発は推進したいが、無秩序は困る」という相反する要求が示された。佐藤は、どの環境をどの用途に使うか、どのポリシーでリスクをどう抑えるか、そして本番配布をどう仕組み化するかを整理し、ガバナンス基本方針として提案する必要がある。","ライセンス面では、高度なガバナンス機能に伴う追加要件や、環境ごとのデータベース構成、既定環境の扱いについても正しく理解しておく必要がある。佐藤はPower Platform管理センターを起点に、環境・ポリシー・ソリューションを組み合わせた統制設計をまとめることになった。"],"en":["Maruwa Retail, a nationwide chain, saw employees across stores and headquarters start building Power Apps and cloud flows on their own. As citizen development exploded, hundreds of apps and flows piled up in the Default environment, and IT systems manager Sato is alarmed that governance is slipping.","A staffer built an app handling customer data that began sending data to an external Twitter connector and public cloud storage, surfacing a data-leak risk. Sato wants to apply a tenant-wide policy so data cannot mix between business and non-business connectors.","The company decided to separate development, test, and production lifecycles, giving citizen developers a free space to experiment while managing production strictly. Artifacts must move correctly between environments with repeatable versioning and distribution. It also wants advanced controls such as sharing limits, usage visibility, and a weekly governance report.","Executives voiced conflicting demands: promote citizen development, but avoid chaos. Sato must clarify which environment serves which purpose, how policies mitigate risk, and how to systematize production distribution, then propose a governance baseline.","On licensing, Sato must correctly understand the added requirements for advanced governance, per-environment database configuration, and how the Default environment is treated, then assemble a control design from the Power Platform admin center combining environments, policies, and solutions."]},"tables":[{"title":{"ja":"環境の種類と主な用途","en":"Environment Types and Typical Use"},"headers":{"ja":["環境種別","主な用途","Dataverse DB"],"en":["Environment type","Typical use","Dataverse DB"]},"rows":{"ja":[["既定(Default)","全ユーザーが自動所属・試作向け","既定で作成される"],["運用(Production)","本番運用アプリの配置先","作成可（1環境1DB）"],["サンドボックス","開発・検証・リセット可能","作成可"],["開発者(Developer)","個人開発・学習用","作成可"]],"en":[["Default","All users auto-join; ad hoc trials","Created by default"],["Production","Hosting production apps","Can create (1 DB/env)"],["Sandbox","Dev/test, resettable","Can create"],["Developer","Individual dev/learning","Can create"]]}},{"title":{"ja":"DLPポリシーのコネクタ分類とデータ移動可否","en":"DLP Policy Connector Groups and Data-Movement Rules"},"headers":{"ja":["分類","例","同一アプリ/フロー内の混在"],"en":["Group","Examples","Mixing within one app/flow"]},"rows":{"ja":[["業務用(Business)","Dataverse, SharePoint","非業務用とは混在不可"],["非業務用(Non-Business)","Twitter, 一部公開ストレージ","業務用とは混在不可"],["ブロック(Blocked)","禁止対象コネクタ","利用自体を禁止"]],"en":[["Business","Dataverse, SharePoint","Cannot mix with Non-Business"],["Non-Business","Twitter, some public storage","Cannot mix with Business"],["Blocked","Prohibited connectors","Use is blocked entirely"]]}}],"questions":[{"n":1,"q":{"ja":"顧客情報を扱う業務用コネクタと、社外向けの非業務用コネクタの間でデータが混在しないよう、テナント全体で制御したい。用いるべき仕組みはどれか。","en":"Sato wants tenant-wide control so data cannot mix between business connectors handling customer data and external non-business connectors. What mechanism should be used?"},"options":[{"label":{"ja":"各アプリの共有設定を手動で見直す","en":"Manually review each app's sharing settings"},"exp":{"ja":"共有設定はアクセス範囲の管理であり、コネクタ間のデータ混在を防ぐ仕組みではない。テナント全体の一貫した制御にもならない。","en":"Sharing settings manage access scope, not data mixing between connectors, and do not provide consistent tenant-wide control."}},{"label":{"ja":"データ損失防止(DLP)ポリシーを作成しコネクタを業務用/非業務用/ブロックに分類する","en":"Create a data loss prevention (DLP) policy classifying connectors as Business/Non-Business/Blocked"},"exp":{"ja":"DLPポリシーはコネクタを分類し、業務用と非業務用の間のデータ移動を禁止できる。テナント/環境単位で一貫適用でき要件に合致するため正しい。","en":"A DLP policy classifies connectors and blocks data movement between Business and Non-Business groups, applied consistently at tenant/environment scope, matching the requirement."},"ok":true},{"label":{"ja":"各ユーザーのライセンスを剥奪して利用を止める","en":"Revoke each user's license to stop usage"},"exp":{"ja":"ライセンス剥奪は業務を止めるだけで、コネクタ間のデータ移動制御という目的を果たさない。市民開発推進の方針とも矛盾する。","en":"Revoking licenses merely halts work and does not control connector data movement, conflicting with the goal of enabling citizen development."}},{"label":{"ja":"Power BI の行レベルセキュリティを設定する。詳細はライセンス条件により異なることがある","en":"Configure Power BI row-level security , with specifics varying by licensing terms"},"exp":{"ja":"行レベルセキュリティはレポート閲覧範囲の制御で、アプリやフローのコネクタ間データ混在を防ぐ機能ではないため無関係である。","en":"Row-level security scopes report viewing and does not prevent connector data mixing in apps or flows, so it is unrelated."}}]},{"n":2,"q":{"ja":"開発・検証・本番のライフサイクルを分離しつつ、市民開発者に試作の場を与えたい。既定環境と環境戦略に関する説明として最も適切なものはどれか。","en":"Sato wants to separate dev/test/production while giving citizen developers a place to prototype. Which statement about the Default environment and environment strategy is most appropriate?"},"options":[{"label":{"ja":"既定環境を本番専用として全社アプリを集約し、他の環境は作らない","en":"Use the Default environment as production-only and consolidate all apps there, creating no other environments"},"exp":{"ja":"既定環境は全ユーザーが自動所属し統制が難しいため本番集約に不向き。ライフサイクル分離の要件にも反するため不適切。","en":"All users auto-join the Default environment, making it hard to govern and unsuitable for consolidating production, contradicting lifecycle separation."}},{"label":{"ja":"環境は1つしか作れないため、開発も本番も同じ環境で運用する","en":"Only one environment can exist, so run dev and production in the same environment"},"exp":{"ja":"Power Platformでは目的別に複数環境を作成できる。1つしか作れないという前提が誤りで、分離要件も満たせない。","en":"Power Platform allows multiple purpose-specific environments; the single-environment premise is false and fails the separation requirement."}},{"label":{"ja":"用途別に本番・サンドボックス等の環境を分け、試作は専用環境に誘導して既定環境の乱立を抑える","en":"Separate environments by purpose (production, sandbox, etc.) and steer prototyping to a dedicated environment to curb Default-environment sprawl"},"exp":{"ja":"目的別に環境を分離し、試作を専用環境へ誘導すれば既定環境の乱立を抑えつつライフサイクルを管理できる。要件に最も合致し正しい。","en":"Separating environments by purpose and steering prototyping to a dedicated one curbs Default sprawl while managing the lifecycle, best matching the requirement."},"ok":true},{"label":{"ja":"各環境には複数のDataverseデータベースを持たせて本番と開発を同居させる。管理者が環境ごとに個別確認する前提となる","en":"Give each environment multiple Dataverse databases to co-locate production and dev , assuming administrators verify this per environment"},"exp":{"ja":"1つの環境が持てるDataverseデータベースは1つだけで、複数同居はできない。前提が誤っており分離の解にもならない。","en":"An environment can host only one Dataverse database, so multiple databases cannot co-locate, making the premise false."}}]},{"n":3,"q":{"ja":"共有先の上限設定、利用状況の可視化、週次のガバナンスレポートといった高度な統制機能を利用したい。必要となるものはどれか。","en":"Sato wants advanced controls such as sharing limits, usage visibility, and a weekly governance report. What is required?"},"options":[{"label":{"ja":"マネージド環境(Managed Environments)を有効化する","en":"Enable Managed Environments"},"exp":{"ja":"マネージド環境は共有制限・使用状況分析・週次ダイジェスト等の高度なガバナンスを提供する。要件を包括的に満たすため正しい。","en":"Managed Environments provide advanced governance such as sharing limits, usage insights, and a weekly digest, comprehensively meeting the requirement."},"ok":true},{"label":{"ja":"既定環境のままセキュリティロールを増やす","en":"Keep the Default environment and add more security roles"},"exp":{"ja":"セキュリティロールはデータアクセス制御であり、共有上限や利用分析・週次レポートという運用ガバナンス機能は提供しない。","en":"Security roles control data access and do not provide sharing limits, usage analytics, or weekly reports."}},{"label":{"ja":"各アプリを個別にエクスポートして手作業で棚卸しする。ただし運用要件に応じて見直しを要する場合がある","en":"Export each app individually and inventory them by hand , though it may require review depending on operational requirements"},"exp":{"ja":"手作業の棚卸しは継続的な可視化や共有制御を自動化できず、規模拡大に耐えない。要件の高度な統制機能には該当しない。","en":"Manual inventory cannot automate ongoing visibility or sharing control and does not scale, failing to deliver the advanced controls needed."}},{"label":{"ja":"Power BI の無料ライセンスを全員に配る","en":"Hand every user a free Power BI license"},"exp":{"ja":"Power BIライセンスは分析コンテンツ利用のためのもので、Power Platform環境のガバナンス統制機能とは無関係である。","en":"Power BI licenses are for analytics content, unrelated to Power Platform environment governance controls."}}]},{"n":4,"q":{"ja":"サンドボックスで作った複数のアプリとフローを、本番環境へ再現性をもって移送し、バージョン管理と配布を行いたい。用いるべき仕組みはどれか。","en":"Sato wants to move several apps and flows built in a sandbox to production with repeatability, versioning, and distribution. What mechanism should be used?"},"options":[{"label":{"ja":"各アプリを1つずつ手動で作り直す","en":"Recreate each app one by one, manually"},"exp":{"ja":"手動での作り直しは再現性・バージョン管理を欠き、ミスや工数が増大する。環境間の一括移送という要件を満たさない。","en":"Manual recreation lacks repeatability and versioning and increases errors and effort, failing the bulk cross-environment move requirement."}},{"label":{"ja":"本番環境の既定環境フラグを切り替える","en":"Toggle the Default-environment flag on the production environment"},"exp":{"ja":"そのような切替でアプリが移送される仕組みは存在しない。移送・バージョン管理・配布のいずれの要件も満たさない。","en":"No such toggle moves apps; it satisfies none of the move, versioning, or distribution requirements."}},{"label":{"ja":"ソリューションに components をまとめ、環境間でエクスポート/インポートして配布する","en":"Group components into a solution and export/import it across environments to distribute"},"exp":{"ja":"ソリューションは複数のアプリ・フローをまとめ、環境間の移送とバージョン管理・配布を実現するALMの標準手段。要件に合致し正しい。","en":"Solutions bundle apps and flows and provide ALM-standard cross-environment movement, versioning, and distribution, matching the requirement."},"ok":true},{"label":{"ja":"DLPポリシーを本番環境に適用して移送する。詳細はライセンス条件により異なることがある。詳細はライセンス条件により異なることがある","en":"Apply a DLP policy to production to move the artifacts , with specifics varying by licensing terms , with specifics varying by licensing terms"},"exp":{"ja":"DLPはコネクタのデータ移動制御であり、アプリやフローを環境間で移送する機能ではない。目的が異なるため不適切。","en":"DLP governs connector data movement, not moving apps or flows between environments, so it serves a different purpose."}}]}]},{"id":"pl900-3","title":{"ja":"ケース：外部公開ポータルと分析・AIアシスタントの統合","en":"Case: Integrating an External Portal with Analytics and an AI Assistant"},"body":{"ja":["生命保険会社「あすなろ生命」は、契約者が自分の契約内容を確認し、各種申請を行える顧客向けポータルを新設する。契約者はインターネット経由でアクセスするため、社外の一般ユーザーが安全にサインインできる認証の仕組みが必要である。デジタル推進部の高橋が全体設計を任された。","ポータルの背後には契約・請求データを一元管理する基盤が必要で、社内の担当者はモデル駆動アプリで同じデータを扱う。経営層は、契約動向や請求件数の推移を役員会でダッシュボードとして共有したいと考えており、データに基づく意思決定を重視している。","契約者から日々届く申請書はPDFや画像で、氏名・証券番号・金額などの項目を人手で転記している。高橋はこの読み取りを自動化したいが、新たに機械学習の専門家を雇う予算はない。あわせて、ポータル上でよくある質問に自然言語で答え、簡単な手続き案内までこなす会話型アシスタントを設けたいという要望がある。","情報セキュリティ部門は、外部公開ゆえに認証・アクセス範囲・データ分類の徹底を強く求めている。一方で現場は、専門家に頼らずローコードで素早く立ち上げたいと考えており、両者の折り合いが論点となっている。","高橋は、外部公開サイト・分析・書類読み取り・会話型AIという4つの要件それぞれに、Power Platformのどのコンポーネントを割り当てるべきかを明確化し、ライセンスと認証の考え方を含む構成案を提案することになった。"],"en":["Asunaro Life, a life insurer, is launching a customer portal where policyholders check their policies and file various requests. Since policyholders access over the internet, a mechanism is needed for external general users to sign in securely. Takahashi of the digital team owns the overall design.","Behind the portal, a platform is needed to centrally manage policy and billing data, and internal staff will work with the same data via a model-driven app. Executives want to share trends in policies and claim volumes as a dashboard in board meetings, valuing data-driven decisions.","Daily requests from policyholders arrive as PDFs and images, and fields such as name, policy number, and amount are transcribed by hand. Takahashi wants to automate this reading but has no budget to hire ML experts. They also want a conversational assistant that answers FAQs in natural language and even guides simple procedures on the portal.","Information security strongly demands rigorous authentication, access scoping, and data classification because the site is public. Meanwhile the field team wants to launch quickly with low-code and no experts, and reconciling the two is the key issue.","Takahashi must clarify which Power Platform component maps to each of the four needs, external site, analytics, document reading, and conversational AI, and propose an architecture including licensing and authentication considerations."]},"tables":[{"title":{"ja":"要件とコンポーネントの対応候補","en":"Requirements and Candidate Components"},"headers":{"ja":["要件","主な候補","認証/前提"],"en":["Requirement","Primary candidate","Auth/Prerequisite"]},"rows":{"ja":[["外部公開ポータル","Power Pages","外部ID(サインイン)対応・Dataverse"],["役員会ダッシュボード","Power BI","組織内配布"],["書類の項目読み取り","AI Builder(フォロセッシング)","クレジット消費・ノーコード"],["会話型アシスタント","Copilot Studio","トピック/生成回答"]],"en":[["External portal","Power Pages","External identity sign-in; Dataverse"],["Board dashboard","Power BI","In-org distribution"],["Document field reading","AI Builder (form processing)","Consumes credits; no-code"],["Conversational assistant","Copilot Studio","Topics/generative answers"]]}}],"questions":[{"n":1,"q":{"ja":"契約者がインターネット経由でサインインし、契約内容を確認できる外部公開ポータルを構築する。最も適したコンポーネントはどれか。","en":"The company will build an external-facing portal where policyholders sign in over the internet to view their policies. Which component fits best?"},"options":[{"label":{"ja":"Power Pages","en":"Power Pages"},"exp":{"ja":"Power Pagesは外部ユーザー向けの公開Webサイトを構築でき、外部IDによるサインインとDataverse連携を備える。認証付き公開ポータル要件に合致し正しい。","en":"Power Pages builds public websites for external users with external-identity sign-in and Dataverse integration, matching the authenticated public-portal requirement."},"ok":true},{"label":{"ja":"キャンバスアプリを社外に配布する","en":"Distribute a canvas app to external parties"},"exp":{"ja":"キャンバスアプリは基本的に組織内ユーザー向けで、一般の契約者への外部公開・匿名/外部サインインには適さない。用途が異なる。","en":"Canvas apps target in-org users and are unsuited to public distribution or external/anonymous sign-in for general policyholders."}},{"label":{"ja":"モデル駆動アプリを外部公開する","en":"Publish a model-driven app externally"},"exp":{"ja":"モデル駆動アプリは社内担当者の業務用で、外部の一般ユーザーへ公開するポータル用途には設計されていないため不適切。","en":"Model-driven apps are for internal staff and are not designed as portals for external general users."}},{"label":{"ja":"Power BI レポートを公開リンクで共有する","en":"Share a Power BI report via a public link"},"exp":{"ja":"Power BIは分析の可視化が目的で、契約確認や申請といった双方向のポータル機能や個別認証を提供しないため要件を満たさない。","en":"Power BI is for analytics visualization and does not provide interactive portal features or per-user authentication for viewing policies and filing requests."}}]},{"n":2,"q":{"ja":"PDFや画像の申請書から氏名・証券番号・金額を自動で読み取りたいが、機械学習の専門家を雇う予算はない。最も適したものはどれか。","en":"The team wants to auto-extract name, policy number, and amount from PDF and image requests, with no budget to hire ML experts. Which fits best?"},"options":[{"label":{"ja":"自社でディープラーニングモデルをゼロから開発する","en":"Develop a deep-learning model in-house from scratch"},"exp":{"ja":"モデルのゼロ開発は専門知識と工数を要し、予算・体制の制約に反する。ローコードで素早く立ち上げたい方針にも合わない。","en":"Building a model from scratch needs expertise and effort, violating budget and staffing limits and the low-code, fast-launch goal."}},{"label":{"ja":"AI Builder のフォーム処理モデルを使う","en":"Use an AI Builder form processing model"},"exp":{"ja":"AI Builderのフォーム処理はノーコードで文書から項目を抽出でき、専門家不要で導入できる。予算・スキル制約と読み取り要件に合致し正しい。","en":"AI Builder form processing extracts fields from documents with no code and no experts, matching the budget/skill limits and the reading requirement."},"ok":true},{"label":{"ja":"Power BI で画像を取り込みメジャーで解析する","en":"Ingest images in Power BI and analyze with measures"},"exp":{"ja":"Power BIは数値・データの可視化ツールで、画像やPDFからの項目抽出（OCR/文書AI）は担わない。読み取り要件を満たさない。","en":"Power BI visualizes numeric data and does not perform field extraction (OCR/document AI) from images or PDFs."}},{"label":{"ja":"デスクトップフローで担当者の転記操作をそのまま録画する","en":"Record the staffer's manual transcription with a desktop flow"},"exp":{"ja":"UI録画は決まった画面操作の自動化向けで、書式が多様な文書からの項目認識には不安定。文書AIによる抽出の方が適切である。","en":"UI recording suits fixed screen automation and is unreliable for recognizing fields across varied document formats; document AI extraction is more appropriate."}}]},{"n":3,"q":{"ja":"ポータル上でよくある質問に自然言語で答え、簡単な手続き案内までこなす会話型アシスタントを、専門家に頼らず作りたい。最も適したものはどれか。","en":"The team wants a conversational assistant that answers FAQs in natural language and guides simple procedures on the portal, built without experts. Which fits best?"},"options":[{"label":{"ja":"Power Automate のスケジュール済みクラウドフロー。詳細はライセンス条件により異なることがある","en":"A scheduled Power Automate cloud flow , with specifics varying by licensing terms"},"exp":{"ja":"スケジュールフローは定時のバックエンド処理向けで、利用者と自然言語で対話するアシスタントを構成するものではない。用途が異なる。","en":"A scheduled flow is for timed back-end processing, not for a natural-language conversational assistant with users."}},{"label":{"ja":"Power BI の Q&A ビジュアル","en":"The Power BI Q&A visual"},"exp":{"ja":"Q&Aはレポート内のデータに自然言語で問い合わせる機能で、手続き案内まで行う汎用の会話型アシスタントではない。要件と一致しない。","en":"Q&A queries report data in natural language and is not a general conversational assistant that also guides procedures."}},{"label":{"ja":"Copilot Studio でトピックと生成回答を持つエージェントを作る","en":"Build an agent in Copilot Studio with topics and generative answers"},"exp":{"ja":"Copilot Studioはローコードで会話トピックや生成AI回答を持つエージェントを作成でき、FAQ応答と手続き案内に対応。要件に合致し正しい。","en":"Copilot Studio builds low-code agents with conversation topics and generative answers, handling FAQ responses and procedure guidance, matching the requirement."},"ok":true},{"label":{"ja":"モデル駆動アプリのビジネスプロセスフロー","en":"A business process flow in a model-driven app"},"exp":{"ja":"ビジネスプロセスフローは業務担当者の入力段階を案内する機能で、契約者との自然言語対話を担う会話型アシスタントではない。","en":"Business process flows guide staff through data-entry stages and are not a conversational assistant for natural-language dialogue with policyholders."}}]},{"n":4,"q":{"ja":"契約・請求データを一元管理し、社内はモデル駆動アプリ、外部はポータルから同じデータを扱う。この共通データ基盤として正しいものはどれか。","en":"Policy and billing data must be centralized, with internal staff using a model-driven app and external users a portal against the same data. Which is the correct common data platform?"},"options":[{"label":{"ja":"各部門のExcelブックを都度統合する","en":"Consolidate each team's Excel workbooks as needed"},"exp":{"ja":"都度統合するExcelは一元管理・整合性・同時アクセスに欠け、モデル駆動アプリや外部ポータルの共通基盤にはならない。","en":"Ad hoc Excel consolidation lacks central management, integrity, and concurrency and cannot serve as a common platform for a model-driven app and portal."}},{"label":{"ja":"Dataverse に契約・請求テーブルを作り共通基盤にする","en":"Create policy and billing tables in Dataverse as the common platform"},"exp":{"ja":"モデル駆動アプリはDataverse必須で、Power Pagesも標準でDataverseと連携する。両者が同一データを扱う共通基盤として最適で正しい。","en":"Model-driven apps require Dataverse and Power Pages integrates with it natively, making Dataverse the ideal common platform both can share."},"ok":true},{"label":{"ja":"Power BI データセットを唯一の書き込み先にする","en":"Use a Power BI dataset as the single write target"},"exp":{"ja":"Power BIデータセットは分析用の読み取り主体で、業務アプリやポータルからの書き込み・更新を担う基幹データ基盤ではない。","en":"A Power BI dataset is read-oriented for analytics and is not a system-of-record for writes from business apps or portals."}},{"label":{"ja":"各アプリが個別のSharePointリストを持ち後で突き合わせる","en":"Have each app keep its own SharePoint list and reconcile later"},"exp":{"ja":"リストが分散すると一元管理が崩れ、モデル駆動アプリの前提であるDataverseも満たさない。共通基盤の要件に反するため不適切。","en":"Separate lists break central management and do not satisfy the Dataverse prerequisite of model-driven apps, violating the common-platform requirement."}}]}]}];

function ExamCaseRunner({ cases, lang, onBack }) {
  const g = (o) => (o && (o[lang] != null ? o[lang] : o.ja));
  const clist = Array.isArray(cases) ? cases : [cases];
  const [pick, setPick] = useState(clist.length === 1 ? 0 : null);
  const [qi, setQi] = useState(0);
  const [answers, setAnswers] = useState({});
  const [finished, setFinished] = useState(false);

  const th = { textAlign: "left", padding: "7px 9px", background: "#EDE9E0", color: C.deep, fontSize: 11.5, fontWeight: 700, borderBottom: `1px solid ${C.mid}`, whiteSpace: "nowrap" };
  const td = { padding: "7px 9px", fontSize: 12, borderBottom: `1px solid ${C.mid}`, verticalAlign: "top", lineHeight: 1.45 };

  const openCase = (i) => { setPick(i); setQi(0); setAnswers({}); setFinished(false); };
  const backToList = () => { if (clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); } else onBack(); };

  if (pick === null) {
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <button onClick={onBack} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{lang === "ja" ? "← 戻る" : "← Back"}</button>
        </div>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 4 }}>{lang === "ja" ? "本試験形式ケース" : "Exam-style cases"}</div>
        <div style={{ fontSize: 12, color: "#8595ad", marginBottom: 12 }}>{lang === "ja" ? "資料表つき・僅差4択・全選択肢に根拠解説" : "Data tables, 4 close options, rationale for each"}</div>
        {clist.map((c, i) => (
          <button key={i} onClick={() => openCase(i)}
            style={{ width: "100%", textAlign: "left", padding: "14px 15px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5, color: C.deep, lineHeight: 1.45, paddingRight: 10 }}>{g(c.title)}</span>
            <span style={{ fontSize: 11.5, color: "#8595ad", whiteSpace: "nowrap" }}>{c.questions.length}{lang === "ja" ? "問" : "Q"}</span>
          </button>
        ))}
      </div>
    );
  }

  const data = clist[pick];
  const qs = data.questions;
  const Q = qs[qi];
  const sel = answers[qi] != null ? answers[qi] : null;
  const choose = (i) => { if (sel !== null) return; setAnswers(a => ({ ...a, [qi]: i })); };
  const prev = () => { if (qi > 0) setQi(qi - 1); };
  const next = () => { if (qi < qs.length - 1) setQi(qi + 1); };
  const restart = () => { setQi(0); setAnswers({}); setFinished(false); };

  let correct = 0;
  for (let k = 0; k < qs.length; k++) { const a = answers[k]; if (a != null && qs[k].options[a] && qs[k].options[a].ok) correct++; }
  const answeredCount = Object.keys(answers).length;
  const rate = qs.length ? Math.round((correct / qs.length) * 100) : 0;

  const navBtn = (label, onClick, enabled, primary) => (
    <button onClick={enabled ? onClick : undefined} disabled={!enabled}
      style={{ flex: 1, padding: "11px 12px", borderRadius: 9, fontSize: 13.5, fontWeight: 700,
        cursor: enabled ? "pointer" : "default",
        border: primary ? "none" : `1.5px solid ${enabled ? C.primary : C.mid}`,
        background: primary ? (enabled ? C.primary : C.mid) : "#fff",
        color: primary ? "#fff" : (enabled ? C.primary : "#b9c4d6") }}>{label}</button>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={backToList} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{clist.length > 1 ? (lang === "ja" ? "← ケース一覧" : "← Case list") : (lang === "ja" ? "← 戻る" : "← Back")}</button>
        {!finished && <span style={{ fontSize: 12, color: "#8595ad" }}>{lang === "ja" ? `問 ${qi + 1} / ${qs.length}` : `Q ${qi + 1} / ${qs.length}`}</span>}
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 12 }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 10 }}>{g(data.title)}</div>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 6 }}>{lang === "ja" ? "ケース本文（資料）" : "Case (materials)"}</div>
        {g(data.body).map((p, i) => (<div key={i} style={{ fontSize: 13, lineHeight: 1.7, marginBottom: 8, color: C.ink }}>{p}</div>))}
        {(data.tables || []).map((tb, ti) => (
          <div key={ti} style={{ marginTop: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: C.deep, marginBottom: 5 }}>{g(tb.title)}</div>
            <div style={{ overflowX: "auto", border: `1px solid ${C.mid}`, borderRadius: 8 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 320 }}>
                <thead><tr>{g(tb.headers).map((h, hi) => (<th key={hi} style={th}>{h}</th>))}</tr></thead>
                <tbody>{g(tb.rows).map((r, ri) => (<tr key={ri}>{r.map((cell, ci) => (<td key={ci} style={td}>{cell}</td>))}</tr>))}</tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {finished ? (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ textAlign: "center", marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "#5a6a85", fontWeight: 600, marginBottom: 6 }}>{lang === "ja" ? "ケース完了" : "Case complete"}</div>
            <div style={{ fontSize: 32, fontWeight: 800, color: rate >= PASS ? C.ok : C.ng }}>{rate}%</div>
            <div style={{ fontSize: 12.5, color: "#8595ad", marginTop: 2 }}>{lang === "ja" ? `正解 ${correct} / ${qs.length} 問` : `${correct} / ${qs.length} correct`}</div>
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
          <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
            <button onClick={() => { setFinished(false); setQi(0); }} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "解答を見直す" : "Review answers"}</button>
            <button onClick={restart} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "もう一度" : "Retry"}</button>
          </div>
        </div>
      ) : (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: 14.5, fontWeight: 700, marginBottom: 12, color: C.deep }}>{lang === "ja" ? `問${Q.n}. ` : `Q${Q.n}. `}{g(Q.q)}</div>
          {Q.options.map((opt, i) => {
            let bg = "#fff", bd = C.mid, col = C.ink;
            if (sel !== null) { if (opt.ok) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; } else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; } }
            return (
              <button key={i} onClick={() => choose(i)} disabled={sel !== null}
                style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.5, fontWeight: sel !== null && opt.ok ? 700 : 500 }}>
                <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && opt.ok ? "✓" : sel !== null && i === sel ? "✗" : "ABCD"[i]}</span>{g(opt.label)}
              </button>
            );
          })}
          {sel !== null && (
            <div style={{ marginTop: 12 }}>
              {Q.options.map((opt, i) => (
                <div key={i} style={{ background: opt.ok ? "#E6F4EC" : (i === sel ? "#FBEAE8" : C.light), borderRadius: 8, padding: "9px 11px", marginBottom: 6, fontSize: 12.5, lineHeight: 1.55 }}>
                  <span style={{ fontWeight: 700, marginRight: 6, color: opt.ok ? C.ok : (i === sel ? C.ng : "#8595ad") }}>{"ABCD"[i]}{opt.ok ? (lang === "ja" ? "（正解）" : " (correct)") : ""}</span>{g(opt.exp)}
                </div>
              ))}
            </div>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            {navBtn(lang === "ja" ? "← 前の問題" : "← Previous", prev, qi > 0, false)}
            {qi < qs.length - 1
              ? navBtn(lang === "ja" ? "次の問題 →" : "Next →", next, sel !== null, true)
              : navBtn(lang === "ja" ? "結果を見る →" : "See result →", () => setFinished(true), answeredCount === qs.length, true)}
          </div>
        </div>
      )}
    </div>
  );
}

function App() {
  const [tab, _setTab] = useState("home");
  const [tabHist, setTabHist] = useState([]);
  const setTab = (k) => { if (k !== tab) setTabHist(h => [...h, tab]); _setTab(k); };
  const goBackTab = () => { if (!tabHist.length) return; const prev = tabHist[tabHist.length - 1]; setTabHist(tabHist.slice(0, -1)); _setTab(prev); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); };
  const [state, setState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const t = T;

  useEffect(() => {
    loadState().then(s => {
      setState(s || { progress: {}, meta: { streak: 0, lastDay: "", dailyDay: "", dailyCount: 0 } });
      setLoaded(true);
    });
  }, []);

  const persist = (next) => { setState(next); saveState(next); };

  const record = (domId, correct) => {
    const next = JSON.parse(JSON.stringify(state));
    if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
    next.progress[domId].attempts++;
    if (correct) next.progress[domId].correct++;
    const today = todayStr();
    if (next.meta.dailyDay !== today) { next.meta.dailyDay = today; next.meta.dailyCount = 0; }
    next.meta.dailyCount++;
    if (next.meta.lastDay !== today) {
      const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
      next.meta.streak = next.meta.lastDay === yesterday ? next.meta.streak + 1 : 1;
      next.meta.lastDay = today;
    }
    persist(next);
  };

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const TABS = [
    ["home", t.tabHome], ["quiz", t.tabQuiz], ["exam", t.tabExam], ["scenario", t.tabScenario],
    ["compare", t.tabCompare], ["diagram", t.tabDiagram], ["confuse", t.tabConfuse], ["glossary", t.tabGlossary], ["examcase", "本試験形式ケース"],
  ];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#FAFEFF", minHeight: "100vh" }}>
      <div style={{ background: C.deep, color: "#fff", padding: "16px 18px" }}>
        <div style={{ fontSize: 19, fontWeight: 700 }}>{t.appTitle}</div>
        <div style={{ fontSize: 12, opacity: 0.85, marginTop: 2 }}>{t.appSub}</div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{
              flex: "1 1 auto", padding: "11px 8px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent",
              color: tab === k ? C.deep : C.ink, fontWeight: tab === k ? 700 : 500,
              fontSize: 13, borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent",
            }}>
            {label}
          </button>
        ))}
      </div>
      {tabHist.length > 0 && (
        <button onClick={goBackTab}
          aria-label="Back"
          style={{ position: "fixed", right: 16, bottom: 104, zIndex: 45, border: `1.5px solid ${C.deep}`, cursor: "pointer", borderRadius: 22, padding: "9px 15px", background: "#fff", color: C.deep, fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.20)" }}>
          ← 戻る
        </button>
      )}
      {tab !== "home" && (
        <button onClick={() => { setTab("home"); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); }}
          aria-label="Back to top"
          style={{ position: "fixed", right: 16, bottom: 60, zIndex: 45, border: "none", cursor: "pointer", borderRadius: 22, padding: "10px 15px", background: C.deep, color: "#fff", fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.28)" }}>
          ↑ トップへ
        </button>
      )}
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <Home state={state} t={t} />}
        {tab === "quiz" && <Quiz onAnswer={record} t={t} questions={ALL_QUESTIONS} />}
        {tab === "exam" && <Exam onAnswer={record} t={t} />}
        {tab === "scenario" && <Scenario t={t} />}
        {tab === "compare" && <Compare t={t} />}
        {tab === "diagram" && <Diagrams t={t} />}
        {tab === "confuse" && <Confuse t={t} />}
        {tab === "glossary" && <Glossary t={t} />}
        {tab === "examcase" && <ExamCaseRunner cases={PL900_EXAM_CASES} lang="ja" onBack={() => setTab("home")} />}
      </div>
    </div>
  );
}

// ===== 進捗 =====
function Home({ state, t }) {
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);

  const weak = useMemo(() => {
    return DOMAINS.map(d => {
      const p = state.progress[d.id] || { correct: 0, attempts: 0 };
      const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
      return { ...d, rate, attempts: p.attempts };
    }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate);
  }, [state]);

  const dailyPct = Math.min(100, Math.round((state.meta.dailyCount / DAILY_GOAL) * 100));

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={`${totals.c}/${totals.a}${t.questionsUnit}`} color={totals.rate >= PASS ? C.ok : C.primary} />
        <Stat label={t.streak} value={`${state.meta.streak}日`} sub={t.streakSub} color={C.primary} />
      </div>

      <Card title={`${t.dailyGoal} (${state.meta.dailyCount}/${DAILY_GOAL})`}>
        <Bar pct={dailyPct} color={dailyPct >= 100 ? C.ok : C.primary} />
        <div style={{ fontSize: 12, marginTop: 6, color: "#5a7780" }}>
          {dailyPct >= 100 ? t.dailyDone : t.dailyRemain(DAILY_GOAL - state.meta.dailyCount)}
        </div>
      </Card>

      <Card title={t.domMastery}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>
                  <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
                  {domName(d.id)}
                </span>
                <span style={{ color: "#5a7780" }}>{d.pct}% · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>

      {weak.length > 0 && (
        <Card title={t.weakDomains}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
              {domName(d.id)} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#5a7780" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color }}>{value}</div>
      <div style={{ fontSize: 11, color: "#86a6b0" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

// ===== クイズ =====
function Quiz({ onAnswer, t, questions }) {
  const [filter, setFilter] = useState("ALL");
  const [pos, setPos] = useState(0);
  const [history, setHistory] = useState({}); // {globalIndex: selectedOption}
  const [stats, setStats] = useState({ c: 0, a: 0 });

  const pool = useMemo(() => {
    const idxs = filter === "ALL" ? questions.map((_, i) => i) : questions.map((_, i) => i).filter(i => questions[i].d === filter);
    return idxs; // 既定は固定順（収録順）
  }, [filter, questions]);

  useEffect(() => { setPos(0); setHistory({}); setStats({ c: 0, a: 0 }); }, [pool]);

  const total = pool.length;
  const qi = pool[pos];
  const Q = questions[qi];
  // 選択肢を決定的にシャッフル（正解が先頭固定にならない）
  const { opts, a: correctIdx } = useMemo(() => shuffleOptions(Q), [qi]);
  const sel = history[qi] ?? null;

  const choose = (i) => {
    if (sel !== null) return;
    setHistory(h => ({ ...h, [qi]: i }));
    const correct = i === correctIdx;
    setStats(s => ({ c: s.c + (correct ? 1 : 0), a: s.a + 1 }));
    onAnswer(Q.d, correct);
  };
  const next = () => { if (pos + 1 < total) setPos(p => p + 1); };
  const prev = () => { if (pos > 0) setPos(p => p - 1); };

  const rate = stats.a ? Math.round((stats.c / stats.a) * 100) : 0;

  return (
    <div>
      <div style={{ fontSize: 12.5, color: "#476770", marginBottom: 8 }}>全{total}問</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{
              padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer",
              border: `1px solid ${filter === k ? C.primary : C.mid}`,
              background: filter === k ? C.primary : "#fff", color: filter === k ? "#fff" : C.ink, fontWeight: 600,
            }}>
            {k === "ALL" ? t.allFields : k}
          </button>
        ))}
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={prev} disabled={pos === 0}
          style={{
            padding: "8px 14px", borderRadius: 9, fontSize: 12.5, fontWeight: 600,
            border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`,
            background: "#fff", color: pos === 0 ? "#a8c2cc" : C.primary,
            cursor: pos === 0 ? "not-allowed" : "pointer",
          }}>
          ← 前の問題
        </button>
        <span style={{ fontSize: 13, color: "#5a7780", fontWeight: 600 }}>{pos + 1} / {total}</span>
      </div>

      {stats.a > 0 && (
        <div style={{ marginBottom: 10 }}>
          <div style={{ fontSize: 12, color: "#5a7780", marginBottom: 3 }}>
            {t.sessionRate} {rate}%（{stats.c}/{stats.a}）
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
        </div>
      )}

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
          {Q.d} · {domName(Q.d)}
        </div>
        <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{Q.q}</div>
        {opts.map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (sel !== null) {
            if (i === correctIdx) { bg = "#E4F6EC"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBE9E7"; bd = C.ng; col = C.ng; }
          }
          return (
            <button key={i} onClick={() => choose(i)} disabled={sel !== null}
              style={{
                display: "block", width: "100%", textAlign: "left", marginBottom: 8,
                padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`,
                background: bg, color: col, cursor: sel === null ? "pointer" : "default",
                fontSize: 13.5, lineHeight: 1.4, fontWeight: sel !== null && i === correctIdx ? 700 : 500,
              }}>
              <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && (i === correctIdx) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
            </button>
          );
        })}
        {sel !== null && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
              <strong style={{ color: sel === correctIdx ? C.ok : C.ng }}>{sel === correctIdx ? t.correct : t.incorrect}</strong>
              ・{t.answerIs("ABCD"[correctIdx])}{Q.e}
            </div>
            {pos + 1 < total && (
              <button onClick={next}
                style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
                {t.nextQ}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ===== 模擬試験（演習モード / 本番モード）=====
function Exam({ onAnswer, t }) {
  const [mode, setMode] = useState("practice");
  const [kind, setKind] = useState("normal");
  const [setNo, setSetNo] = useState(null);
  const [phase, setPhase] = useState("select");
  const [pos, setPos] = useState(0);
  const [picks, setPicks] = useState({}); // {qIndex: selectedOption(シャッフル後index)}
  const [sel, setSel] = useState(null);

  const rawQs = setNo ? (kind === "domain" ? (DOMAIN_SETS[setNo] || []) : EXAM_SETS[setNo]) : [];
  // 各問の選択肢を決定的シャッフル（セット固定でも並びは安定）
  const qs = useMemo(() => rawQs.map(Q => {
    const { opts, a } = shuffleOptions(Q);
    return { ...Q, o: opts, a };
  }), [setNo]);

  const start = (n) => { setSetNo(n); setPos(0); setPicks({}); setSel(null); setPhase("run"); };

  const choosePractice = (i) => {
    if (sel !== null) return;
    setSel(i);
    const Q = qs[pos];
    const correct = i === Q.a;
    onAnswer(Q.d, correct);
    setPicks(p => ({ ...p, [pos]: i }));
  };
  const chooseReal = (i) => { setPicks(p => ({ ...p, [pos]: i })); };

  const next = () => {
    if (mode === "practice") {
      setSel(null);
      if (pos + 1 >= qs.length) finishExam();
      else setPos(pos + 1);
    } else {
      if (pos + 1 >= qs.length) finishExam();
      else setPos(pos + 1);
    }
  };
  const prev = () => { if (pos > 0) { setPos(pos - 1); if (mode === "practice") setSel(picks[pos - 1] ?? null); } };

  const finishExam = () => {
    if (mode === "real") {
      qs.forEach((Q, i) => {
        if (picks[i] !== undefined) onAnswer(Q.d, picks[i] === Q.a);
      });
    }
    setPhase("result");
  };

  if (phase === "select") {
    return (
      <div>
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 14 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 8 }}>{t.examTitle}</div>
          <div style={{ fontSize: 13, lineHeight: 1.6, color: "#476770", marginBottom: 12, whiteSpace: "pre-line" }}>{t.examDesc}</div>
          <div style={{ display: "flex", background: C.light, borderRadius: 24, padding: 4 }}>
            {[["practice", t.modePractice], ["real", t.modeReal]].map(([m, label]) => (
              <button key={m} onClick={() => setMode(m)}
                style={{
                  flex: 1, border: "none", cursor: "pointer", borderRadius: 20, padding: "10px 8px",
                  fontSize: 13.5, fontWeight: 700,
                  background: mode === m ? "#fff" : "transparent",
                  color: mode === m ? C.deep : "#86a6b0",
                  boxShadow: mode === m ? "0 1px 4px rgba(11,110,143,.18)" : "none",
                  transition: "all .2s",
                }}>
                {label}
              </button>
            ))}
          </div>
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
          {[["normal", t.kindNormal], ["domain", t.kindDomain]].map(([kk, label]) => (
            <button key={kk} onClick={() => setKind(kk)}
              style={{ flex: 1, padding: "11px 8px", borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: "pointer",
                border: `1.5px solid ${kind === kk ? C.primary : C.mid}`,
                background: kind === kk ? C.primary : "#fff", color: kind === kk ? "#fff" : C.ink }}>
              {label}
            </button>
          ))}
        </div>
        {kind === "domain" && DOMAINS.map(d => (
          <button key={d.id} onClick={() => start(d.id)}
            style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer",
              display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span style={{ background: d.hue, color: "#fff", borderRadius: 5, padding: "3px 8px", fontSize: 12, fontWeight: 800 }}>{d.id}</span>
              <span>
                <span style={{ fontWeight: 700, fontSize: 14, color: C.deep }}>{d.name}</span>
                <span style={{ fontSize: 12, color: "#86a6b0", marginLeft: 8 }}>{t.domainSetCount(DOMAIN_SETS[d.id].length)}</span>
              </span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: C.primary, flexShrink: 0 }}>{t.start}</span>
          </button>
        ))}
        {kind === "normal" && [1, 2, 3, 4, 5].map(n => (
          <button key={n} onClick={() => SET_READY[n] && start(n)} disabled={!SET_READY[n]}
            style={{
              width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${SET_READY[n] ? C.primary : C.mid}`,
              background: SET_READY[n] ? "#fff" : C.light, cursor: SET_READY[n] ? "pointer" : "not-allowed",
              display: "flex", justifyContent: "space-between", alignItems: "center",
            }}>
            <span>
              <span style={{ fontWeight: 700, fontSize: 15, color: SET_READY[n] ? C.deep : "#86a6b0" }}>{t.setLabel} {n}</span>
              <span style={{ fontSize: 12, color: "#86a6b0", marginLeft: 10 }}>50{t.questionsUnit}</span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: SET_READY[n] ? C.primary : "#a8c2cc" }}>
              {SET_READY[n] ? `${mode === "practice" ? t.modePractice : t.modeReal}で${t.start}` : t.preparing}
            </span>
          </button>
        ))}
      </div>
    );
  }

  if (phase === "result") {
    const graded = qs.map((Q, i) => ({ q: Q, sel: picks[i] ?? null, correct: picks[i] === Q.a }));
    const answered = graded.filter(g => g.sel !== null);
    const c = graded.filter(g => g.correct).length;
    const rate = Math.round((c / qs.length) * 100);
    const passed = rate >= PASS;
    const byDom = DOMAINS.map(d => {
      const sub = graded.filter(g => g.q.d === d.id);
      const cc = sub.filter(g => g.correct).length;
      return { ...d, total: sub.length, correct: cc };
    }).filter(d => d.total > 0);
    const wrong = graded.filter(g => !g.correct);

    return (
      <div>
        <div style={{ background: passed ? "#E4F6EC" : "#FBE9E7", border: `2px solid ${passed ? C.ok : C.ng}`, borderRadius: 12, padding: 18, textAlign: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: "#5a7780" }}>{t.setLabel}{setNo} · {mode === "practice" ? t.modePractice : t.modeReal} {t.result}</div>
          <div style={{ fontSize: 40, fontWeight: 800, color: passed ? C.ok : C.ng }}>{rate}%</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: passed ? C.ok : C.ng }}>{passed ? t.reachedPass : t.needMore(PASS - rate)}</div>
          <div style={{ fontSize: 12, color: "#5a7780", marginTop: 4 }}>{t.correctOf(c, qs.length)}{answered.length < qs.length ? `（${t.unanswered} ${qs.length - answered.length}）` : ""}</div>
        </div>

        <Card title={t.domBreakdown}>
          {byDom.map(d => (
            <div key={d.id} style={{ marginBottom: 9 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span><span style={{ background: d.hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>{domName(d.id)}</span>
                <strong style={{ color: d.correct / d.total >= PASS / 100 ? C.ok : C.ng }}>{d.correct}/{d.total}</strong>
              </div>
              <Bar pct={Math.round(d.correct / d.total * 100)} color={d.correct / d.total >= PASS / 100 ? C.ok : C.ng} />
            </div>
          ))}
        </Card>

        <Card title={t.wrongTitle(wrong.length)}>
          {wrong.length === 0 ? (
            <div style={{ fontSize: 13, color: C.ok }}>{t.allCorrect}</div>
          ) : wrong.map((a, idx) => (
            <div key={idx} style={{ padding: "8px 0", borderBottom: `1px solid ${C.light}`, fontSize: 13 }}>
              <div style={{ fontWeight: 600, marginBottom: 4 }}>
                <span style={{ background: DOM_HUE[a.q.d], color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{a.q.d}</span>
                {a.q.q}
              </div>
              <div style={{ color: C.ng, fontSize: 12.5 }}>{t.yourAnswer}：{a.sel !== null ? `${"ABCD"[a.sel]} ${a.q.o[a.sel]}` : "—"}</div>
              <div style={{ color: C.ok, fontSize: 12.5 }}>{t.answer}：{"ABCD"[a.q.a]} {a.q.o[a.q.a]}</div>
              <div style={{ color: "#476770", fontSize: 12.5, marginTop: 2 }}>{a.q.e}</div>
            </div>
          ))}
        </Card>

        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={() => start(setNo)} style={{ flex: 1, padding: 13, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.retrySet}</button>
          <button onClick={() => setPhase("select")} style={{ flex: 1, padding: 13, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.toSetSelect}</button>
        </div>
      </div>
    );
  }

  // 出題
  const Q = qs[pos];
  const opts = Q.o;
  const curPick = picks[pos] ?? null;
  const answeredCount = Object.keys(picks).length;
  const showFeedback = mode === "practice" && sel !== null;
  const isLast = pos + 1 >= qs.length;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, fontSize: 12.5, color: "#5a7780" }}>
        <span>
          <span style={{ background: mode === "practice" ? C.primary : C.deep, color: "#fff", borderRadius: 4, padding: "1px 8px", fontSize: 11, fontWeight: 700, marginRight: 8 }}>
            {mode === "practice" ? t.modePractice : t.modeReal}
          </span>
          {t.setLabel}{setNo} · {t.questionNo(pos + 1, qs.length)}
        </span>
        <span>{t.answered} {answeredCount}/{qs.length}</span>
      </div>
      <Bar pct={Math.round(((pos + 1) / qs.length) * 100)} color={C.primary} />

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", margin: "12px 0 0" }}>
        <button onClick={prev} disabled={pos === 0}
          style={{
            padding: "8px 14px", borderRadius: 9, fontSize: 12.5, fontWeight: 600,
            border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`,
            background: "#fff", color: pos === 0 ? "#a8c2cc" : C.primary,
            cursor: pos === 0 ? "not-allowed" : "pointer",
          }}>
          ← 前の問題
        </button>
        <span style={{ fontSize: 13, color: "#5a7780", fontWeight: 600 }}>{pos + 1} / {qs.length}</span>
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginTop: 12 }}>
        <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
          {Q.d} · {domName(Q.d)}
        </div>
        <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{Q.q}</div>
        {opts.map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (mode === "practice" && sel !== null) {
            if (i === Q.a) { bg = "#E4F6EC"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBE9E7"; bd = C.ng; col = C.ng; }
          } else if (mode === "real" && curPick === i) {
            bg = C.light; bd = C.primary; col = C.deep;
          }
          const disabled = mode === "practice" && sel !== null;
          return (
            <button key={i} onClick={() => mode === "practice" ? choosePractice(i) : chooseReal(i)} disabled={disabled}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: disabled ? "default" : "pointer", fontSize: 13.5, lineHeight: 1.4, fontWeight: (mode === "practice" && sel !== null && i === Q.a) || (mode === "real" && curPick === i) ? 700 : 500 }}>
              <span style={{ fontWeight: 700, marginRight: 8 }}>{(mode === "practice" && sel !== null) && (i === Q.a) ? "✓" : (mode === "practice" && sel !== null) && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
            </button>
          );
        })}

        {showFeedback && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
              <strong style={{ color: sel === Q.a ? C.ok : C.ng }}>{sel === Q.a ? t.correct : t.incorrect}</strong>
              ・{t.answerIs("ABCD"[Q.a])}{Q.e}
            </div>
            <button onClick={next} style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
              {isLast ? t.seeResult : t.nextQ}
            </button>
          </div>
        )}

        {mode === "real" && (
          <button onClick={next}
            style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: isLast ? C.deep : C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
            {isLast ? t.finish : t.nextQ}
          </button>
        )}
      </div>
    </div>
  );
}

// ===== 図解（インタラクティブ）=====
function Diagrams({ t }) {
  const [open, setOpen] = useState("domains");
  const Section = ({ id, title, children }) => (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, marginBottom: 12, overflow: "hidden" }}>
      <button onClick={() => setOpen(open === id ? "" : id)}
        style={{ width: "100%", textAlign: "left", padding: "13px 15px", border: "none", background: open === id ? C.light : "#fff", color: C.deep, fontWeight: 700, fontSize: 13.5, cursor: "pointer", display: "flex", justifyContent: "space-between" }}>
        <span>{title}</span><span>{open === id ? "−" : "+"}</span>
      </button>
      {open === id && <div style={{ padding: 15, borderTop: `1px solid ${C.light}` }}>{children}</div>}
    </div>
  );
  return (
    <div>
      <div style={{ fontSize: 12, color: "#86a6b0", marginBottom: 10 }}>{t.diagIntro}</div>
      <Section id="domains" title="① 5領域の出題比率"><DomainBars /></Section>
      <Section id="overview" title="② Power Platform 全体構成（タップで解説）"><Overview /></Section>
      <Section id="appchoice" title="③ アプリ形式の決定木（クイズ形式）"><AppDecision /></Section>
      <Section id="trigger" title="④ クラウドフローのトリガー（タップ）"><Triggers /></Section>
      <Section id="security" title="⑤ セキュリティの多層モデル（タップ）"><SecurityLadder /></Section>
      <Section id="roi" title="⑥ 自動化の削減効果シミュレータ"><RoiSim /></Section>
      <Section id="data" title="⑦ Dataverse のデータ構造（展開ツリー）"><InteractiveTree data={DV_TREE} /></Section>
      <Section id="admin" title="⑧ 管理階層（展開ツリー）"><InteractiveTree data={ADMIN_TREE} /></Section>
    </div>
  );
}

// ① 全体構成
function Overview() {
  const items = [
    ["Power Apps", "作る", "ローコードで業務アプリを構築(キャンバス/モデル駆動型)"],
    ["Power Automate", "自動化", "クラウドフローとRPAで繰り返し作業を自動化"],
    ["Power Pages", "公開する", "外部向けのセルフサービスWebサイトを構築"],
    ["Power BI", "見える化", "データを可視化・分析し意思決定を支援"],
    ["Dataverse", "データ基盤", "全サービス共通の安全なデータ基盤"],
    ["コネクタ", "つなぐ", "1,000以上の外部サービスをコードなしで接続"],
  ];
  const [sel, setSel] = useState(null);
  const colors = [C.deep, "#1A86A8", C.primary, "#3BB8D4", "#6CCBDE", "#8FD9E8"];
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 10 }}>
        {items.map((it, i) => (
          <div key={i} onClick={() => setSel(sel === i ? null : i)}
            style={{ background: colors[i], color: "#fff", borderRadius: 9, padding: "12px 10px", cursor: "pointer", border: sel === i ? `3px solid ${C.ink}` : "3px solid transparent" }}>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{it[0]}</div>
            <div style={{ fontSize: 11, opacity: 0.9 }}>{it[1]}</div>
          </div>
        ))}
      </div>
      {sel !== null ? (
        <div style={{ background: C.light, borderRadius: 9, padding: 12 }}>
          <div style={{ fontWeight: 700, color: C.deep, fontSize: 14 }}>{items[sel][0]}</div>
          <div style={{ fontSize: 13, marginTop: 4, lineHeight: 1.5 }}>{items[sel][2]}</div>
        </div>
      ) : (
        <div style={{ fontSize: 12.5, color: "#476770" }}>各タイルをタップ。Dataverseとコネクタが基盤、その上に4サービスが乗る。</div>
      )}
    </div>
  );
}

// ② アプリ形式の決定木
function AppDecision() {
  const steps = {
    start: { q: "利用者は誰か？", opts: [["社内の担当者", "internal"], ["外部の顧客", "pages"]] },
    internal: { q: "重視するのは？", opts: [["自由なデザイン・特定タスク", "canvas"], ["複雑なデータ・多数の表", "model"]] },
  };
  const leaves = {
    canvas: ["キャンバスアプリ", "デザイン主導で自由に配置。軽量・タスク特化のモバイルアプリに向く"],
    model: ["モデル駆動型アプリ", "データ主導でDataverseから自動生成。複雑なデータ管理に向く"],
    pages: ["Power Pages", "認証とWebロールを備えた外部向けセルフサービスサイト"],
  };
  const [path, setPath] = useState([]);
  const cur = path.length === 0 ? "start" : path[path.length - 1];
  const leaf = leaves[cur];
  return (
    <div>
      <div style={{ marginBottom: 10, fontSize: 12, color: "#86a6b0" }}>
        {path.length > 0 && <button onClick={() => setPath(p => p.slice(0, -1))} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, padding: 0 }}>← 戻る</button>}
      </div>
      {!leaf && steps[cur] && (
        <div>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.deep, marginBottom: 12 }}>{steps[cur].q}</div>
          {steps[cur].opts.map(([label, to]) => (
            <button key={to} onClick={() => setPath(p => [...p, to])}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "12px 14px", borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, cursor: "pointer", fontSize: 14, fontWeight: 600 }}>
              {label} →
            </button>
          ))}
        </div>
      )}
      {leaf && (
        <div style={{ background: "#E4F6EC", border: `2px solid ${C.ok}`, borderRadius: 10, padding: 14 }}>
          <div style={{ fontSize: 11, color: C.ok, fontWeight: 700 }}>結論</div>
          <div style={{ fontSize: 16, fontWeight: 800, color: C.deep, margin: "4px 0" }}>{leaf[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5 }}>{leaf[1]}</div>
          <button onClick={() => setPath([])} style={{ marginTop: 12, padding: "8px 14px", borderRadius: 8, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>最初から</button>
        </div>
      )}
    </div>
  );
}

// ③ トリガー
function Triggers() {
  const items = [
    ["自動化", "イベント", "メール受信時などイベント発生で自動開始。手動操作が不要"],
    ["インスタント", "手動", "必要なときボタンで手動開始。即時の処理に向く"],
    ["スケジュール", "時刻", "毎朝9時など指定時刻で開始。定型処理を自動化"],
  ];
  const [sel, setSel] = useState(null);
  const colors = [C.deep, C.primary, "#6CCBDE"];
  return (
    <div>
      {items.map((it, i) => (
        <div key={i} onClick={() => setSel(sel === i ? null : i)} style={{ display: "flex", alignItems: "center", marginBottom: 8, cursor: "pointer" }}>
          <div style={{ flex: 1, background: colors[i], color: "#fff", borderRadius: 8, padding: "10px 13px", border: sel === i ? `2px solid ${C.ink}` : "2px solid transparent" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5 }}>{it[0]}</span>
            <span style={{ fontSize: 11.5, marginLeft: 8, opacity: 0.9 }}>開始: {it[1]}</span>
          </div>
        </div>
      ))}
      {sel !== null ? (
        <div style={{ background: C.light, borderRadius: 9, padding: 11, fontSize: 13, lineHeight: 1.5, marginTop: 4 }}>{items[sel][2]}</div>
      ) : (
        <div style={{ fontSize: 12, color: "#476770", marginTop: 6 }}>各段をタップ。トリガーはフローを開始するきっかけで、開始条件で種類が決まる。</div>
      )}
    </div>
  );
}

// ④ セキュリティ多層モデル
function SecurityLadder() {
  const items = [
    ["認証(Entra ID)", "誰かを確認", "サインイン時にユーザーの本人確認を行う"],
    ["認可(セキュリティロール)", "何を許すか", "役割ごとに何にアクセスできるか付与(最小権限)"],
    ["行/列レベルセキュリティ", "アクセスを絞る", "レコード単位・項目単位でアクセスを制御"],
    ["DLPポリシー", "流出を防ぐ", "コネクタの組み合わせを制限しデータ流出を防ぐ"],
  ];
  const [sel, setSel] = useState(null);
  const colors = [C.deep, "#1A86A8", C.primary, "#3BB8D4"];
  return (
    <div>
      {items.map((it, i) => (
        <div key={i} onClick={() => setSel(sel === i ? null : i)} style={{ display: "flex", alignItems: "center", marginBottom: 8, cursor: "pointer" }}>
          <div style={{ width: 26, fontSize: 11, color: "#86a6b0" }}>{i + 1}</div>
          <div style={{ flex: 1, background: colors[i], color: "#fff", borderRadius: 8, padding: "9px 12px", border: sel === i ? `2px solid ${C.ink}` : "2px solid transparent" }}>
            <span style={{ fontWeight: 700, fontSize: 13 }}>{it[0]}</span>
            <span style={{ fontSize: 11.5, marginLeft: 8, opacity: 0.9 }}>{it[1]}</span>
          </div>
        </div>
      ))}
      {sel !== null ? (
        <div style={{ background: C.light, borderRadius: 9, padding: 11, fontSize: 13, lineHeight: 1.5, marginTop: 4 }}>{items[sel][2]}</div>
      ) : (
        <div style={{ fontSize: 12, color: "#476770", marginTop: 6 }}>各層をタップ。本人確認→権限→絞り込み→流出防止の多層で守る。</div>
      )}
    </div>
  );
}

// ⑤ 自動化の削減効果シミュレータ
function RoiSim() {
  const [minPer, setMinPer] = useState(15);
  const [count, setCount] = useState(200);
  const savedMin = minPer * count;
  const savedHr = (savedMin / 60).toFixed(1);
  const fmt = (n) => n.toLocaleString();
  return (
    <div>
      <div style={{ marginBottom: 14 }}>
        <label style={{ fontSize: 12.5, fontWeight: 600 }}>1件あたり削減分：{minPer}分</label>
        <input type="range" min="1" max="60" step="1" value={minPer} onChange={e => setMinPer(+e.target.value)} style={{ width: "100%", accentColor: C.primary }} />
      </div>
      <div style={{ marginBottom: 14 }}>
        <label style={{ fontSize: 12.5, fontWeight: 600 }}>月あたり件数：{count}</label>
        <input type="range" min="10" max="2000" step="10" value={count} onChange={e => setCount(+e.target.value)} style={{ width: "100%", accentColor: C.primary }} />
      </div>
      <div style={{ display: "flex", gap: 10, marginBottom: 12 }}>
        <div style={{ flex: 1, background: C.light, borderRadius: 9, padding: 11, textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#5a7780" }}>月の削減</div>
          <div style={{ fontSize: 19, fontWeight: 800, color: C.deep }}>{fmt(savedMin)}分</div>
        </div>
        <div style={{ flex: 1, background: "#E4F6EC", borderRadius: 9, padding: 11, textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#5a7780" }}>時間換算</div>
          <div style={{ fontSize: 19, fontWeight: 800, color: C.ok }}>約{savedHr}時間</div>
        </div>
      </div>
      <div style={{ fontSize: 12, color: "#476770", lineHeight: 1.5 }}>→ Power Automate の効果は件数が多いほど大きい。繰り返し作業を自動化し、人を価値の高い業務へ振り向けられる。</div>
    </div>
  );
}

