function buildBank() {
  const out = [];
  let id = 0;
  CORE.forEach(([d,q,o,a,e,qEn,oEn,eEn]) => out.push({ id:`c${id++}`, d, q, o:[...o], a, e, qEn, oEn:oEn?[...oEn]:null, eEn }));
  const allNames = FACTS.map(f => f[1]);
  // 日本語サービス名 → 英語名（x[9]があればそれ、なければ同名=言語非依存）
  const EN_NAME = {};
  FACTS.forEach(x => { EN_NAME[x[1]] = x[9] || x[1]; });
  const enName = (jp) => EN_NAME[jp] || jp;
  const enOpts = (opts) => opts.map(enName);
  const pickDistractors = (correct, pool, n) => shuffle(pool.filter(x => x !== correct)).slice(0, n);
  FACTS.forEach((f) => {
    const [d, name, role, use, rival, diff, roleEn, useEn, diffEn] = f;
    const hasEn = !!roleEn;
    const nameE = enName(name);
    const rivalE = rival ? enName(rival) : rival;
    const sameD = FACTS.filter(x => x[0] === d && x[1] !== name).map(x => x[1]);
    // 角度1：役割→サービス
    {
      const distract = pickDistractors(name, sameD.length >= 3 ? sameD : allNames, 3);
      const opts = shuffle([name, ...distract]);
      out.push({ id:`g${id++}`, d, q:`${role}はどれか。`, o:opts, a:opts.indexOf(name), e:`${name}：${use}`,
        qEn: hasEn?`Which is ${roleEn}?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE}: ${useEn}`:null });
    }
    // 角度2：用途→サービス
    {
      const distract = pickDistractors(name, sameD.length >= 3 ? sameD : allNames, 3);
      const opts = shuffle([name, ...distract]);
      out.push({ id:`g${id++}`, d, q:`次の用途に最も適すのはどれか：「${use}」`, o:opts, a:opts.indexOf(name), e:`${name}は${role}。`,
        qEn: hasEn?`Which best fits this use case: "${useEn}"?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} is ${roleEn}.`:null });
    }
    // 角度3：対比（前者）
    if (rival) {
      const opts = shuffle([name, rival, ...pickDistractors(name, sameD.filter(x=>x!==rival), 2)]);
      out.push({ id:`g${id++}`, d, q:`${diff}という違いがある。前者に当たるのはどれか。`, o:opts, a:opts.indexOf(name), e:`${name} vs ${rival}：${diff}`,
        qEn: hasEn?`There is a difference: ${diffEn}. Which is the former?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} vs ${rivalE}: ${diffEn}`:null });
    }
    // 角度4：特徴説明の正誤
    {
      const wrongPool = FACTS.filter(x => x[1] !== name && x[6]);
      const wrongFacts = shuffle(wrongPool).slice(0,3);
      const wrongs = wrongFacts.map(x => `${name}は${x[2]}`);
      const correctStmt = `${name}は${role}`;
      const opts = shuffle([correctStmt, ...wrongs]);
      let oEn = null;
      if (hasEn && wrongFacts.length === 3) {
        const correctEn = `${nameE} is ${roleEn}`;
        const map = new Map();
        map.set(correctStmt, correctEn);
        wrongFacts.forEach((x, i) => map.set(wrongs[i], `${nameE} is ${x[6]}`));
        oEn = opts.map(o => map.get(o));
      }
      out.push({ id:`g${id++}`, d, q:`${name}の説明として正しいのはどれか。`, o:opts, a:opts.indexOf(correctStmt), e:`${name}：${use}`,
        qEn: hasEn?`Which statement about ${nameE} is correct?`:null, oEn, eEn: hasEn?`${nameE}: ${useEn}`:null });
    }
    // 角度5：シナリオ
    {
      const distract = pickDistractors(name, sameD.length >= 3 ? sameD : allNames, 3);
      const opts = shuffle([name, ...distract]);
      out.push({ id:`g${id++}`, d, q:`ある要件で「${use}」が求められている。最も適すサービスはどれか。`, o:opts, a:opts.indexOf(name), e:`${name}は${role}。要件に合致する。`,
        qEn: hasEn?`A requirement calls for "${useEn}". Which service fits best?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} is ${roleEn}; it matches the requirement.`:null });
    }
    // 角度6：グループ該当
    if (sameD.length >= 3) {
      const others = shuffle(sameD).slice(0, 3);
      const opts = shuffle([name, ...others]);
      out.push({ id:`g${id++}`, d, q:`「${role}」に該当するサービスはどれか。`, o:opts, a:opts.indexOf(name), e:`${name}が該当。${use}`,
        qEn: hasEn?`Which service is "${roleEn}"?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} applies. ${useEn}`:null });
    }
    // 角度7：対比（後者）
    if (rival) {
      const sameOfRival = FACTS.filter(x => x[0] === d && x[1] !== rival && x[1] !== name).map(x => x[1]);
      const opts = shuffle([rival, name, ...shuffle(sameOfRival).slice(0,2)]);
      out.push({ id:`g${id++}`, d, q:`${name}と対比される「${diff}」。後者(対比相手)はどれか。`, o:opts, a:opts.indexOf(rival), e:`${name} ⇔ ${rival}：${diff}`,
        qEn: hasEn?`"${diffEn}" — which is the latter (the counterpart to ${nameE})?`:null, oEn: enOpts(opts), eEn: hasEn?`${nameE} ⇔ ${rivalE}: ${diffEn}`:null });
    }
  });
  return out;
}

function buildExamSets(bank) {
  const byDom = {};
  DOMAINS.forEach(d => { byDom[d.id] = bank.filter(q => q.d === d.id); });
  const plan = { D1:20, D2:17, D3:12, D4:16 };
  const sets = {};
  for (let s = 0; s < 5; s++) {
    const arr = [];
    Object.entries(plan).forEach(([dom, n]) => {
      const pool = byDom[dom];
      for (let i = 0; i < n; i++) arr.push(pool[(i + s * 11) % pool.length]);
    });
    sets[s + 1] = arr;
  }
  return sets;
}

function shuffle(arr) { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

// 各問題の選択肢順をシャッフルし、正解index(a)とoEnを連動させる
function shuffleChoices(q) {
  const idxs = shuffle(q.o.map((_, i) => i));
  const o = idxs.map(i => q.o[i]);
  const oEn = q.oEn ? idxs.map(i => q.oEn[i]) : q.oEn;
  const a = idxs.indexOf(q.a);
  return { ...q, o, oEn, a };
}

const BANK = buildBank().map(shuffleChoices);
const ADP_HARD = ([{"id":"h0","d":"D1","q":"あるEC企業は、オンプレミスのMySQLデータベース（約2TB）をGoogle Cloudへ移行したいと考えています。移行中もソースDBは稼働を続け、ダウンタイムは最小限に抑える必要があります。移行後の宛先はCloud SQL for MySQLです。継続的レプリケーションで差分を同期しながら計画的に切り替えたい場合、最も適切なマネージドサービスはどれですか。","o":["Database Migration Service を使い、継続的レプリケーションで初期ダンプ後の変更を同期する","Storage Transfer Service で mysqldump をエクスポートして定期転送する","Transfer Appliance にダンプを書き出して物理輸送する","Dataflow のバッチジョブで毎晩全テーブルを洗い替えする"],"a":0,"e":"Database Migration Service (DMS) はソースの初期スナップショット後にCDCで継続的レプリケーションを行い、最小ダウンタイムでCloud SQL等へ移行できるマネージドサービスです。Storage TransferやTransfer Applianceはファイル/オブジェクト転送用で継続的DB同期には不適。全洗い替えはダウンタイムと負荷が大きく不適です。","qEn":"An e-commerce company wants to migrate an on-premises MySQL database (~2TB) to Google Cloud. The source must keep serving traffic during migration with minimal downtime, and the target is Cloud SQL for MySQL. To continuously replicate changes and cut over on a planned schedule, which managed service is most appropriate?","oEn":["Use Database Migration Service with continuous replication to sync changes after the initial dump","Use Storage Transfer Service to periodically move a mysqldump export","Write a dump to a Transfer Appliance and ship it physically","Run a nightly Dataflow batch job that fully reloads every table"],"eEn":"Database Migration Service (DMS) performs an initial snapshot then continuous CDC replication, enabling minimal-downtime migration to Cloud SQL. Storage Transfer and Transfer Appliance move files/objects, not live DB replication. A full reload creates heavy downtime and load."},{"id":"h1","d":"D1","q":"転送は自動化して人手を介さず、失敗時の再試行と進捗の可視化も求められています。データエンジニアは、AWS S3バケットに毎日蓄積される数百万件のJSONログを、追加コードを書かずにスケジュールでCloud Storageへ同期したいと考えています。差分検出と再試行を備え、フルマネージドで運用したいという要件があります。最も適したサービスはどれですか。","o":["Transfer Appliance を米国リージョンに発送して差分を取り込む","gcloud storage cp を cron で毎日手動実行する","Dataproc の Spark ジョブでS3から読み込みGCSへ書き出す","Storage Transfer Service でS3をソースにスケジュール転送ジョブを構成する"],"a":3,"e":"Storage Transfer Service はS3など他クラウドやオンプレをソースに、スケジュール・差分検出・再試行を備えたフルマネージド転送を提供します。Transfer Applianceは物理輸送用でクラウド間の定期同期には不適。cronスクリプトやSparkは運用負荷が高く要件に反します。","qEn":"Transfers must be automated without manual steps, with retries on failure and progress visibility. A data engineer wants to sync millions of daily JSON logs from an AWS S3 bucket to Cloud Storage on a schedule, without writing custom code, with change detection, retries, and fully managed operation. Which service fits best?","oEn":["Ship a Transfer Appliance to a US region to ingest the deltas","Run gcloud storage cp daily via cron manually","Use a Dataproc Spark job to read from S3 and write to GCS","Configure a scheduled Storage Transfer Service job with S3 as the source"],"eEn":"Storage Transfer Service offers fully managed, scheduled transfers from sources like S3 with change detection and retries. Transfer Appliance is for physical shipping, not recurring cross-cloud sync. Cron scripts or Spark add operational burden and miss the requirement."},{"id":"h2","d":"D1","q":"現地の回線増強は予算・期間の制約から現実的でなく、一度きりの初期移行として計画されています。ある製造業は、ネットワーク帯域が限られた工場から500TBの過去センサーデータを一度だけGoogle Cloudへ移行する必要があります。現行の10Mbps回線ではオンライン転送に数か月かかると見積もられています。最もコストと時間の効率が良い移行手段はどれですか。","o":["gcloud storage の並列アップロードで直接送る","Datastream でセンサーDBから継続レプリケーションする","Transfer Appliance を利用してデータを物理デバイスに書き込み輸送する","Storage Transfer Service のオンライン転送ジョブを並列実行する"],"a":2,"e":"帯域が細く一度限りの大容量（500TB）移行では、Transfer Appliance に物理デバイスへ書き込んで輸送するのが時間・コスト効率的です。10Mbpsのオンライン転送は非現実的に長時間かかります。Datastreamは継続CDC用で一括過去データ移行には不向きです。","qEn":"Upgrading the local link is impractical due to budget and timeline, and this is planned as a one-time initial migration. A manufacturer must do a one-time migration of 500TB of historical sensor data from a factory with limited network bandwidth. Their 10Mbps link would take months for online transfer. Which migration approach is most time- and cost-efficient?","oEn":["Send it directly with gcloud storage parallel uploads","Use Datastream to continuously replicate from the sensor DB","Use Transfer Appliance to write data to a physical device and ship it","Run parallel online Storage Transfer Service jobs"],"eEn":"For a one-time, very large (500TB) move over a thin link, Transfer Appliance (write to a physical device and ship) is most efficient. Online transfer over 10Mbps would take impractically long. Datastream is for continuous CDC, not bulk historical migration."},{"id":"h3","d":"D1","q":"同社ではダウンタイムやデータ整合性のリスクを厳しく管理しており、切り替えは業務時間外に短時間で完了させたいと考えています。分析チームはOracleデータベースの変更をほぼリアルタイムでBigQueryに反映し、常に最新の状態で分析したいと考えています。サーバーレスのCDCで、ソースへの負荷を抑えつつ挿入・更新・削除をストリーミングで取り込みたい場合、最適なサービスはどれですか。","o":["Cloud Data Fusion のバッチパイプラインを日次で走らせる","Datastream を使ってOracleからBigQueryへCDCストリームを構成する","BigQuery Data Transfer Service で毎時フルロードする","Dataproc の Sqoop ジョブを1時間ごとに実行する"],"a":1,"e":"Datastream はサーバーレスのCDCサービスで、OracleやMySQLの変更（INSERT/UPDATE/DELETE）をほぼリアルタイムにBigQueryへストリーミングでき、ソース負荷を抑えます。フルロードやバッチ（Sqoop、日次Data Fusion）はリアルタイム性に欠け、削除の反映も困難です。","qEn":"The company strictly manages downtime and data-consistency risk and wants cutover completed quickly outside business hours. An analytics team wants to reflect Oracle database changes in BigQuery in near real time for always-fresh analysis. Using serverless CDC that streams inserts, updates, and deletes with low source impact, which service is best?","oEn":["Run a daily Cloud Data Fusion batch pipeline","Use Datastream to configure an Oracle-to-BigQuery CDC stream","Full-load hourly with BigQuery Data Transfer Service","Run a Dataproc Sqoop job every hour"],"eEn":"Datastream is a serverless CDC service that streams Oracle/MySQL changes (INSERT/UPDATE/DELETE) to BigQuery in near real time with low source load. Full loads and batch (Sqoop, daily Data Fusion) lack real-time freshness and struggle to propagate deletes."},{"id":"h4","d":"D1","q":"あるゲーム会社は、Pub/Subに秒間10万件流入するイベントを、ウィンドウ集計や重複排除などの変換を施しながらBigQueryへストリーミングで書き込みたいと考えています。Apache Beamで記述したパイプラインをオートスケールで運用したい場合、最適なサービスはどれですか。","o":["BigQuery の load ジョブでファイルを定期取り込みする","Dataflow のストリーミングジョブでBeamパイプラインを実行する","Dataproc の常時起動Sparkクラスタで処理する","Cloud Data Fusion のバッチ実行で1時間ごとに集計する"],"a":1,"e":"Dataflow は Apache Beam のマネージド実行基盤で、ストリーミングのウィンドウ集計や重複排除をオートスケールで処理しBigQueryへ書き込めます。Dataprocは手動クラスタ運用でストリーム自動スケールに劣り、Data Fusionバッチやloadジョブはリアルタイム要件を満たしません。","qEn":"A gaming company wants to stream events arriving at 100k/sec on Pub/Sub into BigQuery while applying transforms like windowed aggregation and deduplication, running an Apache Beam pipeline with autoscaling. Which service is best?","oEn":["Periodically ingest files with BigQuery load jobs","Run the Beam pipeline as a Dataflow streaming job","Process on an always-on Dataproc Spark cluster","Aggregate hourly with Cloud Data Fusion batch runs"],"eEn":"Dataflow is the managed runner for Apache Beam, handling streaming windowed aggregation and dedup with autoscaling and writing to BigQuery. Dataproc needs manual cluster management, and Data Fusion batch or load jobs don't meet the real-time requirement."},{"id":"h5","d":"D1","q":"イベントは急峻なバーストを伴い、遅延なく確実に取り込めるスケーラビリティが強く求められています。あるチームは既存のオンプレHadoop/Sparkジョブ群（PySpark、Hive）を最小限の書き換えでGoogle Cloudへ移行し、ジョブ実行時のみクラスタを起動してコストを抑えたいと考えています。既存エコシステムとの互換性を重視する場合、最適なサービスはどれですか。","o":["Dataproc でエフェメラルクラスタを起動しジョブごとに実行する","Dataflow へ全ジョブをApache Beamで書き直す","Cloud Data Fusion でGUIパイプラインに再構築する","BigQuery のストアドプロシージャに全ロジックを移す"],"a":0,"e":"Dataproc はマネージドHadoop/Sparkで、既存のPySparkやHiveジョブをほぼそのまま実行でき、ジョブ単位のエフェメラルクラスタでコストを抑えられます。DataflowはBeamへの書き直しが必要、Data FusionやBigQueryへの再構築は移行コストが大きく互換性重視の要件に反します。","qEn":"Events come in sharp bursts, so scalable, low-latency, reliable ingestion is strongly required. A team wants to migrate existing on-prem Hadoop/Spark jobs (PySpark, Hive) to Google Cloud with minimal rewrites, spinning up clusters only during job runs to save cost, prioritizing ecosystem compatibility. Which service is best?","oEn":["Use Dataproc ephemeral clusters, one per job run","Rewrite all jobs in Apache Beam on Dataflow","Rebuild them as GUI pipelines in Cloud Data Fusion","Move all logic into BigQuery stored procedures"],"eEn":"Dataproc is managed Hadoop/Spark that runs existing PySpark and Hive jobs largely unchanged, using per-job ephemeral clusters to cut cost. Dataflow requires a Beam rewrite; Data Fusion or BigQuery rebuilds are costly and conflict with the compatibility goal."},{"id":"h6","d":"D1","q":"このチームはSparkやHiveの既存資産を多く抱え、再教育コストを避けたいと考えており、運用の手離れの良さも重視しています。データ統合チームには、SQLやコードに不慣れなアナリストが多く、GUIでドラッグ＆ドロップにより複数ソースを結合・クレンジングするETLパイプラインを構築したいという要望があります。事前構築コネクタとメタデータ管理を備えたマネージドサービスはどれですか。","o":["Dataflow でJavaのBeamコードを書く","Dataproc で Scala の Spark を実装する","Compute Engine上に独自ETLサーバを構築する","Cloud Data Fusion でビジュアルパイプラインを構築する"],"a":3,"e":"Cloud Data Fusion はCDAPベースのGUIデータ統合サービスで、コードなしのドラッグ＆ドロップ、豊富な事前構築コネクタ、メタデータ/リネージ管理を提供します。DataflowやDataprocはコード記述が必要で、独自サーバは運用負荷が高くGUI要件を満たしません。","qEn":"The team has substantial existing Spark and Hive assets, wants to avoid retraining costs, and values low operational overhead. A data integration team has many analysts unfamiliar with SQL or code and wants to build ETL pipelines that join and cleanse multiple sources via drag-and-drop GUI, with prebuilt connectors and metadata management. Which managed service fits?","oEn":["Write Java Beam code in Dataflow","Implement Scala Spark on Dataproc","Build a custom ETL server on Compute Engine","Build visual pipelines in Cloud Data Fusion"],"eEn":"Cloud Data Fusion is a CDAP-based GUI integration service offering no-code drag-and-drop, many prebuilt connectors, and metadata/lineage. Dataflow and Dataproc require coding, and a custom server adds operational burden, missing the GUI requirement."},{"id":"h7","d":"D1","q":"導入部門はセルフサービスでの内製化を志向し、専門エンジニアへの依存を減らしたいと考えています。複数のマイクロサービスが不定期にバースト的なイベントを生成し、下流の分析パイプラインがそれを取りこぼさず非同期に受け取れる仕組みが必要です。プロデューサとコンシューマを疎結合にし、少なくとも1回配信とスケーラブルなバッファリングを提供するサービスはどれですか。","o":["Cloud SQL のテーブルにINSERTしてポーリングする","BigQuery に直接ストリーミング挿入して仲介させる","Pub/Sub をメッセージングバッファとして導入する","Cloud Storage にファイルとして直接書き込む"],"a":2,"e":"Pub/Sub はスケーラブルな非同期メッセージングで、プロデューサとコンシューマを疎結合にし、少なくとも1回配信とバッファリングを提供します。GCSファイルやCloud SQLポーリングはバースト吸収や疎結合に劣り、BigQuery直挿入はメッセージバッファの役割を果たしません。","qEn":"The adopting team favors self-service in-house work and wants to reduce reliance on specialist engineers. Several microservices emit bursty events irregularly, and a downstream analytics pipeline must receive them asynchronously without loss. Which service decouples producers and consumers with at-least-once delivery and scalable buffering?","oEn":["INSERT into a Cloud SQL table and poll it","Stream-insert directly into BigQuery as the broker","Introduce Pub/Sub as a messaging buffer","Write files directly to Cloud Storage"],"eEn":"Pub/Sub is scalable async messaging that decouples producers and consumers with at-least-once delivery and buffering. GCS files or Cloud SQL polling handle bursts and decoupling poorly, and direct BigQuery inserts don't serve as a message buffer."},{"id":"h8","d":"D1","q":"下流の処理速度は一定でないため、流入の急増を吸収するバッファリングが不可欠だと考えられています。あるデータチームはBigQueryにデータを取り込むにあたり、変換ロジックが複雑でも強力な演算能力を活用したいと考えています。まず生データをそのままBigQueryにロードし、SQLで変換して分析用テーブルを作る方針です。この設計思想を最もよく表す用語はどれですか。","o":["CDC（変更データキャプチャ）","MDM（マスターデータ管理）","ELT（抽出・ロード後にBigQuery内で変換）","ETL（ロード前に外部で全変換）"],"a":2,"e":"生データを先にロードし、BigQueryのSQL処理能力で変換する方式はELT（Extract-Load-Transform）です。ETLはロード前に外部エンジンで変換します。BigQueryのスケーラブルな演算を活かす近年の主流はELTで、CDCやMDMは別概念です。","qEn":"Downstream throughput varies, so buffering to absorb spikes is considered essential. A data team wants to load raw data into BigQuery first and transform it with SQL to build analytics tables, leveraging BigQuery's compute for complex logic. Which term best describes this design?","oEn":["CDC (change data capture)","MDM (master data management)","ELT (extract and load, then transform inside BigQuery)","ETL (transform fully externally before loading)"],"eEn":"Loading raw data first and transforming with BigQuery SQL is ELT (Extract-Load-Transform). ETL transforms externally before loading. Leveraging BigQuery's scalable compute favors ELT; CDC and MDM are unrelated concepts."},{"id":"h9","d":"D1","q":"この組織はデータウェアハウスを刷新中で、変換処理をどこで実行するかによってコストと保守性が変わることを理解しています。データエンジニアは、BigQueryに毎日ロードする大量の分析データについて、ストレージと読み取りバイト数を最小化したいと考えています。列指向で高い圧縮率を持ち、スキーマを内包しBigQueryロードにも効率的なファイル形式はどれですか。","o":["固定長テキスト","Parquet","CSV","改行区切りJSON（NDJSON）"],"a":1,"e":"Parquet は列指向でスキーマを内包し、高圧縮かつBigQueryロードで効率的に読み取れます。CSVやNDJSONは行指向でスキーマ情報が乏しく圧縮率も低め、固定長テキストも同様に非効率です。列指向はスキャン列の絞り込みにも有利です。","qEn":"The organization is modernizing its data warehouse and understands that where transformation runs affects cost and maintainability. A data engineer wants to minimize storage and bytes read for large analytics data loaded into BigQuery daily. Which file format is columnar, highly compressible, self-describing, and efficient for BigQuery loads?","oEn":["Fixed-width text","Parquet","CSV","Newline-delimited JSON (NDJSON)"],"eEn":"Parquet is columnar, self-describing, highly compressed, and efficient for BigQuery loads. CSV and NDJSON are row-oriented with weak schema info and lower compression; fixed-width text is similarly inefficient. Columnar formats also help prune scanned columns."},{"id":"h10","d":"D1","q":"このデータは日次でテラバイト規模に達し、下流の分析クエリでも読み取り効率が重要になると想定されています。あるストリーミングパイプラインでは、上流のスキーマが頻繁に進化（フィールド追加）します。生産側と消費側でスキーマ互換性を保ち、行指向で書き込みに強く、スキーマ進化をネイティブにサポートするデータシリアライズ形式はどれですか。","o":["Avro","Parquet","CSV","XML"],"a":0,"e":"Avro は行指向でスキーマをファイルに内包し、後方・前方互換のスキーマ進化をネイティブにサポートするため、書き込みが多くスキーマが変化するストリーミングに適します。Parquetは列指向で読み取り分析向き、CSV/XMLはスキーマ進化管理が弱いです。","qEn":"The data reaches terabytes daily, and downstream analytics queries also depend on efficient reads. In a streaming pipeline, the upstream schema evolves frequently (fields added). Which serialization format keeps producer/consumer schema compatibility, is row-oriented for write-heavy workloads, and natively supports schema evolution?","oEn":["Avro","Parquet","CSV","XML"],"eEn":"Avro is row-oriented, embeds its schema, and natively supports backward/forward-compatible schema evolution, ideal for write-heavy streaming with changing schemas. Parquet is columnar for read analytics; CSV/XML handle schema evolution poorly."},{"id":"h11","d":"D1","q":"このパイプラインは複数の外部システムからデータを集約しており、下位互換・上位互換の両立が運用上の要件になっています。BigQueryに数年分のイベントログを蓄積しており、分析クエリはほぼ常に直近30日など特定の日付範囲に限定されます。スキャンするバイト数とコストを大幅に削減するために、テーブル設計で最初に検討すべき手法はどれですか。","o":["全行を1つのパーティションに格納し圧縮を上げる","テーブルを日付ごとに手動で分割し UNION する","結果を毎回マテリアライズドビューに複製する","取り込み日または日付列によるパーティション分割"],"a":3,"e":"日付でパーティション分割すると、クエリの日付フィルタでプルーニングが効き、スキャンバイト数とコストを大幅に削減できます。手動分割＋UNIONは管理が煩雑、単一パーティションはプルーニング不可、マテビューは補助策で第一選択ではありません。","qEn":"The pipeline aggregates data from several external systems, so both backward and forward compatibility are operational requirements. You store years of event logs in BigQuery, and queries almost always filter to a date range like the last 30 days. Which table design technique should you consider first to greatly reduce bytes scanned and cost?","oEn":["Put all rows in one partition and increase compression","Manually split tables by date and UNION them","Copy results into a materialized view every time","Partition by ingestion date or a date column"],"eEn":"Date partitioning lets date filters prune partitions, greatly cutting bytes scanned and cost. Manual splitting with UNION is unwieldy, a single partition can't be pruned, and materialized views are a complementary tactic, not the first choice."},{"id":"h12","d":"D1","q":"このテーブルはコスト最適化の主要対象で、オンデマンド課金のためスキャン量が直接料金に響くことがわかっています。日付でパーティション分割済みの大規模BigQueryテーブルで、さらにcustomer_idやregionといった高カーディナリティ列での絞り込みクエリが多発しています。パーティション内でこれらの列の絞り込みとソートを最適化する追加手法はどれですか。","o":["パーティションをさらに時間単位に細分化する","全列にわたって二次パーティションを作る","各クエリで SELECT * を用いて統計を集める","よく絞り込む列でクラスタリングを設定する"],"a":3,"e":"クラスタリングはパーティション内でデータを指定列（例: customer_id, region）でソート・ブロック化し、絞り込みクエリのスキャン量を減らします。BigQueryはパーティション＋クラスタリングの併用が推奨。時間細分化や二次パーティションはこの目的には不適で、SELECT *は逆効果です。","qEn":"This table is a primary cost-optimization target, and under on-demand billing scanned volume directly drives charges. On a large date-partitioned BigQuery table, many queries also filter on high-cardinality columns like customer_id and region. Which additional technique optimizes filtering and sorting on these columns within partitions?","oEn":["Subdivide partitions further into hourly granularity","Create a secondary partition across all columns","Use SELECT * in each query to gather statistics","Enable clustering on the frequently filtered columns"],"eEn":"Clustering sorts and blocks data within partitions by columns like customer_id/region, reducing scanned data for filters. BigQuery recommends combining partitioning and clustering. Finer time partitions or secondary partitions don't help here, and SELECT * is counterproductive."},{"id":"h13","d":"D1","q":"このテーブルは既にコスト削減のため日付でパーティション分割されていますが、それでも一部クエリが高額になっています。あるチームは、コンプライアンス目的で7年間保持が必要なログをCloud Storageに保管します。アクセスは年に1回未満と極めて稀ですが、取得時の待ち時間よりも長期保管コストの最小化を最優先したいと考えています。最適なストレージクラスはどれですか。","o":["Nearline ストレージクラス","Coldline ストレージクラス","Archive ストレージクラス","Standard ストレージクラス"],"a":2,"e":"年1回未満の極めて稀なアクセスで長期保管コスト最小化を最優先するなら Archive が最適です。Standardは頻繁アクセス向け、Nearlineは月1回程度、Coldlineは四半期に1回程度が目安。保持年数と最小アクセス頻度から Archive が要件に合致します。","qEn":"This table is already date-partitioned for cost savings, yet some queries remain expensive. A team stores logs that must be retained 7 years for compliance in Cloud Storage. Access is extremely rare (less than once a year), and minimizing long-term storage cost matters more than retrieval latency. Which storage class is best?","oEn":["Nearline storage class","Coldline storage class","Archive storage class","Standard storage class"],"eEn":"For access less than once a year prioritizing minimal long-term cost, Archive is best. Standard suits frequent access, Nearline ~monthly, Coldline ~quarterly. Given the retention and minimal access frequency, Archive matches the requirement."},{"id":"h14","d":"D1","q":"保管対象は法令上の長期保持が義務付けられ、総保有コストの最小化が最重要の評価軸になっています。データレイクとしてCloud Storageに格納したParquetファイル群を、BigQueryへ物理ロードせずにクエリしたいと考えています。さらに、行・列レベルのアクセス制御を効かせつつBigQueryのSQLで直接分析したい場合、最適なアプローチはどれですか。","o":["Dataproc でParquetを都度スキャンし結果を手元に保存する","BigLake テーブルを作成しGCS上のParquetをガバナンス付きで参照する","毎回 gcloud でファイルをダウンロードしローカル分析する","Cloud SQL に全Parquetをインポートしてから参照する"],"a":1,"e":"BigLake テーブルはGCS上のParquet等をBigQueryから直接クエリでき、行・列レベルのセキュリティなどガバナンスを適用できます。ローカルダウンロードやCloud SQLインポートは非効率でガバナンスも弱く、Dataproc都度スキャンはSQL直接分析要件に合いません。","qEn":"The data is legally mandated for long-term retention, and minimizing total cost of ownership is the top criterion. You want to query Parquet files in a Cloud Storage data lake without physically loading them into BigQuery, while enforcing row/column-level access control and analyzing directly with BigQuery SQL. Which approach is best?","oEn":["Scan Parquet ad hoc with Dataproc and save results locally","Create a BigLake table referencing the GCS Parquet with governance","Download files with gcloud each time and analyze locally","Import all Parquet into Cloud SQL first, then query"],"eEn":"BigLake tables let BigQuery query GCS Parquet directly while applying governance like row/column-level security. Local downloads or Cloud SQL imports are inefficient and weakly governed, and ad-hoc Dataproc scans don't meet the direct-SQL requirement."},{"id":"h15","d":"D1","q":"データ量は継続的に増加しており、物理ロードを繰り返す運用は避けたいという方針があります。マーケティングチームは、Google広告とYouTubeのレポートデータを毎日自動でBigQueryに取り込み、社内ダッシュボードを更新したいと考えています。コードを書かずにSaaSソースからスケジュール取り込みできるBigQuery純正の仕組みはどれですか。","o":["BigQuery Data Transfer Service で定期転送を構成する","Dataflow のカスタムコネクタを自作する","Storage Transfer Service でSaaS APIを叩く","Transfer Appliance でレポートを物理輸送する"],"a":0,"e":"BigQuery Data Transfer Service はGoogle広告・YouTube・Google Analyticsなど各種SaaSからコード不要でスケジュール取り込みできるマネージド機能です。Dataflow自作は開発負荷が高く、Storage TransferはオブジェクトストレージやファイルソースでSaaS APIレポート用ではありません。","qEn":"Data volume keeps growing, and the policy is to avoid repeatedly physically loading it. A marketing team wants to automatically ingest Google Ads and YouTube report data into BigQuery daily to refresh internal dashboards, without writing code, on a schedule from SaaS sources. Which native BigQuery capability fits?","oEn":["Configure recurring transfers with BigQuery Data Transfer Service","Build a custom Dataflow connector","Call the SaaS APIs via Storage Transfer Service","Physically ship reports with Transfer Appliance"],"eEn":"BigQuery Data Transfer Service ingests from SaaS sources like Google Ads, YouTube, and Google Analytics on a schedule without code. A custom Dataflow build is heavy, and Storage Transfer targets object/file sources, not SaaS API reports."},{"id":"h16","d":"D1","q":"このデータはAPI経由でのみ取得でき、認証やスキーマ変更の追従を自前で実装すると保守負荷が高くなります。あるパイプラインでは、Cloud Storageに1日1回まとめて到着する大容量CSVをBigQueryへ取り込みます。リアルタイム性は不要で、取り込みコストを最小化したい要件があります。BigQueryへのデータ投入方法として最も適切なのはどれですか。","o":["無料のバッチ load ジョブでファイルをロードする","ストリーミング挿入APIで1行ずつ挿入する","Storage Write API を常時接続で使う","外部テーブル経由で毎回フルスキャンする"],"a":0,"e":"日次バッチでリアルタイム不要なら、無料のバッチloadジョブが最もコスト効率的です。ストリーミング挿入やStorage Write APIのストリーミングは課金され低レイテンシ用途向け。外部テーブルの都度フルスキャンはクエリコストが増え取り込み手段としても非効率です。","qEn":"The data is available only via APIs, and implementing auth and schema tracking yourself would be high-maintenance. A pipeline ingests large CSVs that arrive once daily in Cloud Storage into BigQuery. Real-time is not needed and ingestion cost should be minimized. What is the most appropriate way to load into BigQuery?","oEn":["Load the files with free batch load jobs","Insert row by row via the streaming insert API","Use the Storage Write API in always-connected mode","Full-scan via an external table every time"],"eEn":"For daily batches without real-time needs, free batch load jobs are most cost-efficient. Streaming inserts and streaming Storage Write API are billed and meant for low latency. Repeated external-table full scans raise query cost and are inefficient for ingestion."},{"id":"h17","d":"D1","q":"複数のBigQueryのSQL変換、Dataflowジョブ、外部API呼び出しを、依存関係を持つ複雑なワークフローとして毎晩オーケストレーションしたいと考えています。Apache AirflowベースでDAGを記述でき、リッチなスケジューリングと監視を備えたマネージドサービスはどれですか。","o":["Cloud Workflows","Cloud Scheduler 単体","Pub/Sub のトリガのみ","Cloud Composer"],"a":3,"e":"Cloud Composer はマネージドApache Airflowで、依存関係のある複雑なDAG、リッチなスケジューリング、リトライ、監視を備え、多数のBigQueryやDataflowタスクのオーケストレーションに適します。Workflowsは軽量なサーバーレスオーケストレーション、Schedulerは単純なトリガで複雑DAGには不足です。","qEn":"You need to orchestrate multiple BigQuery SQL transforms, Dataflow jobs, and external API calls as a complex dependency-driven workflow every night, authoring DAGs with rich scheduling and monitoring. Which managed service fits?","oEn":["Cloud Workflows","Cloud Scheduler alone","Only Pub/Sub triggers","Cloud Composer"],"eEn":"Cloud Composer is managed Apache Airflow with complex dependency DAGs, rich scheduling, retries, and monitoring, ideal for orchestrating many BigQuery/Dataflow tasks. Workflows is lightweight serverless orchestration, and Scheduler is a simple trigger insufficient for complex DAGs."},{"id":"h18","d":"D1","q":"これらのタスクは相互に依存し、失敗時のリトライや通知、実行履歴の追跡も必要とされています。チームは、数個のサーバーレスAPI呼び出しとFunctionを、軽量で低コストなステートマシンとして順次・条件分岐で連携させたいと考えています。Airflowほどの重厚なDAG基盤は不要で、YAML/JSONで定義しサーバー管理不要にしたい場合、最適なサービスはどれですか。","o":["Dataproc Workflow Template","Compute Engine上の自作スケジューラ","Cloud Workflows","Cloud Composer"],"a":2,"e":"Cloud Workflows はサーバーレスで軽量なオーケストレーションを提供し、YAML/JSONでAPI・Functionの順次実行や条件分岐を低コストに定義できます。Composerは重厚なAirflowで小規模用途には過剰、Dataproc Workflow TemplateはHadoop向け、自作スケジューラは運用負荷が高いです。","qEn":"The tasks are interdependent and need retries, notifications on failure, and run-history tracking. A team wants to chain a few serverless API calls and Functions as a lightweight, low-cost state machine with sequencing and branching, without heavy Airflow DAG infrastructure, defined in YAML/JSON and serverless. Which service fits best?","oEn":["Dataproc Workflow Template","A custom scheduler on Compute Engine","Cloud Workflows","Cloud Composer"],"eEn":"Cloud Workflows provides serverless, lightweight orchestration to define sequential and branching API/Function execution in YAML/JSON at low cost. Composer's heavy Airflow is overkill for small cases, Dataproc Workflow Templates target Hadoop, and a custom scheduler adds operational burden."},{"id":"h19","d":"D1","q":"このチームは軽量さと低コストを重視し、フルマネージドでインフラ管理を避けたいと考えています。Pub/Subでイベントを受けるパイプラインで、一部メッセージがコンシューマの処理に繰り返し失敗し、再配信がループしています。問題のあるメッセージを隔離して他の処理を止めないようにするための、Pub/Subのネイティブ機能はどれですか。","o":["メッセージ保持期間を0にする","デッドレタートピック（dead-letter topic）を構成する","サブスクリプションの ack 期限を無限に延ばす","トピックを削除して作り直す"],"a":1,"e":"Pub/Sub のデッドレタートピックは、指定回数を超えて配信失敗したメッセージを別トピックへ退避させ、処理ループを断ち切って他メッセージの流れを維持します。ack期限延長や保持0、トピック再作成は問題解決にならず、むしろデータ喪失や滞留を招きます。","qEn":"The team values lightness and low cost and wants fully managed operation without infrastructure management. In a Pub/Sub pipeline, some messages repeatedly fail consumer processing and redelivery loops. Which native Pub/Sub feature isolates the problematic messages so other processing isn't blocked?","oEn":["Set message retention to zero","Configure a dead-letter topic","Extend the subscription ack deadline indefinitely","Delete and recreate the topic"],"eEn":"Pub/Sub dead-letter topics move messages that exceed a delivery-attempt threshold to a separate topic, breaking the loop while keeping other messages flowing. Extending ack deadlines, zero retention, or recreating the topic don't fix it and risk loss or backlog."},{"id":"h20","d":"D1","q":"この問題はコンシューマ側のバグに起因することがあり、原因調査の間も他メッセージの処理は継続させたいと考えています。あるチームは、数百万個の小さなファイルをローカルからCloud Storageへできるだけ高速にアップロードしたいと考えています。単一スレッドの逐次アップロードでは遅すぎます。CLIで並列・複合アップロードを活用して転送を高速化する最適な方法はどれですか。","o":["Cloud SQL に一度入れてからGCSへ書き出す","gcloud storage cp を並列処理で実行しスループットを上げる","1ファイルずつ Web コンソールで手動アップロードする","全ファイルを1つのファイルにzipせず個別にcurlする"],"a":1,"e":"gcloud storage コマンドは並列・複合アップロードに対応し、多数の小ファイルを高スループットで転送できます。Webコンソール手動や個別curlは遅く、Cloud SQL経由は不要な迂回で非効率。大量ファイルはCLIの並列転送が最適です。","qEn":"The issue can stem from consumer-side bugs, and other messages should keep processing during investigation. A team wants to upload millions of small files from local to Cloud Storage as fast as possible; single-threaded sequential upload is too slow. What is the best way to speed transfer using the CLI's parallel/composite upload?","oEn":["Load into Cloud SQL first, then write out to GCS","Run gcloud storage cp with parallelism to increase throughput","Upload files one by one manually in the web console","curl each file individually without zipping"],"eEn":"The gcloud storage command supports parallel/composite uploads to move many small files at high throughput. Manual console uploads or per-file curl are slow, and routing through Cloud SQL is an unnecessary detour. CLI parallel transfer is best for many files."},{"id":"h21","d":"D1","q":"これらのファイルはサイズが小さくオブジェクト数が膨大で、逐次処理では所要時間が現実的でないことがわかっています。BigQueryに既にあるトランザクションデータと、Cloud SQL上でリアルタイム更新される小さなマスターテーブルを結合して分析したいと考えています。マスターをBigQueryに複製せず、常に最新の値で結合する最適な方法はどれですか。","o":["EXTERNAL_QUERyでCloud SQLへのフェデレーテッドクエリを使う","毎晩マスターをエクスポートしBigQueryへロードする","Cloud SQL に全トランザクションを移してから結合する","Transfer Appliance でマスターを物理コピーする"],"a":0,"e":"BigQueryのフェデレーテッドクエリ（EXTERNAL_QUERY）はCloud SQLへ直接問い合わせ、複製せずに常に最新のマスターと結合できます。日次エクスポートは鮮度が落ち、全トランザクション移動はBigQueryの利点を失い、Transfer Applianceはリアルタイム結合用途に不適です。","qEn":"The files are small but enormous in count, making sequential processing impractically slow. You want to join transactional data already in BigQuery with a small master table updated in real time on Cloud SQL, joining against always-fresh values without replicating the master into BigQuery. What is best?","oEn":["Use a federated query to Cloud SQL via EXTERNAL_QUERY","Export the master nightly and load it into BigQuery","Move all transactions into Cloud SQL, then join","Physically copy the master with Transfer Appliance"],"eEn":"BigQuery federated queries (EXTERNAL_QUERY) reach into Cloud SQL directly, joining always-fresh master data without replication. Nightly exports lose freshness, moving all transactions forfeits BigQuery's strengths, and Transfer Appliance doesn't fit real-time joins."},{"id":"h22","d":"D1","q":"このパイプラインはコスト最適化が重視されており、取り込み手段の選択が月次のBigQuery料金に直結します。あるアナリストは、複数のCSVに混在する欠損値・型不整合・重複を、コードを書かずにインタラクティブに探索・クレンジングし、変換レシピを組んでスケーラブルに実行したいと考えています。データラングリングに特化した最適なサービスはどれですか。","o":["BigQuery で手書きの巨大なCASE式を書く","Compute Engine 上のpandasスクリプトを手動運用する","Cloud SQL のトリガで逐次補正する","Cloud Dataprep でビジュアルにデータをクレンジングする"],"a":3,"e":"Cloud Dataprep はコード不要でデータの探索・クレンジング・変換レシピ作成を行い、内部でスケーラブルに実行するデータラングリング特化サービスです。BigQueryの手書きCASEや手動pandas、Cloud SQLトリガは対話的ラングリング体験や規模の点で要件に劣ります。","qEn":"Cost optimization matters here, and the ingestion method chosen directly affects the monthly BigQuery bill. An analyst wants to interactively explore and cleanse missing values, type mismatches, and duplicates across several CSVs without code, build transformation recipes, and run them at scale. Which service specializes in data wrangling?","oEn":["Write huge hand-coded CASE expressions in BigQuery","Manually run a pandas script on Compute Engine","Correct rows via Cloud SQL triggers","Cleanse data visually with Cloud Dataprep"],"eEn":"Cloud Dataprep is a data-wrangling service for no-code exploration, cleansing, and recipe building that executes at scale. Hand-coded BigQuery CASE, manual pandas, or Cloud SQL triggers fall short on interactive wrangling and scale."},{"id":"h23","d":"D1","q":"このマスターテーブルは頻繁に更新されるため、鮮度の低下は分析結果の正確性を損なうリスクがあります。ストリーミングパイプラインでは、ネットワーク再送などにより同一イベントが重複してPub/Subに配信されることがあります。BigQueryへ書き込む際に重複行を防ぎたい場合、Dataflowなどで実装すべき最も効果的な考え方はどれですか。","o":["ランダムなUUIDを毎回付け直して区別する","重複は後で手動で削除する前提で無視する","イベントの一意なIDを用いて冪等・重複排除を行う","全行に現在時刻を付与し常にユニークにする"],"a":2,"e":"重複配信に対しては、イベント固有の一意ID（例: event_id）をキーに冪等な書き込みや重複排除ウィンドウを行うのが最も効果的です。現在時刻や毎回のUUID付与は同一イベントを別物にしてしまい重複を助長。手動削除は運用負荷が高くスケールしません。","qEn":"The master table updates frequently, so staleness risks the accuracy of analytics results. In a streaming pipeline, network retries can deliver the same event to Pub/Sub more than once. To prevent duplicate rows when writing to BigQuery, which is the most effective approach to implement (e.g., in Dataflow)?","oEn":["Re-assign a random UUID each time to differentiate them","Ignore duplicates and delete them manually later","Use each event's unique ID for idempotent deduplication","Attach the current time to every row to make them unique"],"eEn":"For duplicate delivery, deduplicating idempotently on a unique event ID (e.g., event_id) is most effective. Adding current time or fresh UUIDs makes identical events look distinct, worsening duplication. Manual deletion is high-effort and doesn't scale."},{"id":"h24","d":"D1","q":"このアナリストはSQLに不慣れで、変換の試行錯誤を対話的に行いつつ最終的には大規模データにも適用したいと考えています。あるチームは、BigQueryのステージングテーブルから本番テーブルへ、変更された行のみを効率的に反映（挿入・更新）したいと考えています。1つの文でマッチ条件に応じて挿入・更新・削除を行える最適なSQL構文はどれですか。","o":["全行 DELETE してから INSERT で入れ直す","SELECT でループしながら1行ずつ更新する","MERGE 文を使って条件付きで UPSERT する","毎回 DROP TABLE して CREATE TABLE で作り直す"],"a":2,"e":"BigQueryの MERGE 文はマッチ条件に応じてINSERT/UPDATE/DELETEを1文で行えるUPSERTに最適です。DROP&CREATEや全DELETE&INSERTは無駄なスキャンとコスト、履歴喪失リスクを生み、行単位ループはスケールしません。差分反映にはMERGEが標準です。","qEn":"The analyst is unfamiliar with SQL, wants to iterate transformations interactively, and ultimately apply them to large data. A team wants to efficiently apply only changed rows (inserts/updates) from a BigQuery staging table into a production table. Which SQL construct can insert, update, or delete based on match conditions in a single statement?","oEn":["DELETE all rows then re-INSERT everything","Loop with SELECT and update one row at a time","Use a MERGE statement to conditionally UPSERT","DROP TABLE and CREATE TABLE anew each time"],"eEn":"BigQuery's MERGE statement performs INSERT/UPDATE/DELETE based on match conditions in one statement, ideal for UPSERT. DROP&CREATE or full DELETE&INSERT waste scans and cost and risk history loss; row-by-row loops don't scale. MERGE is standard for change application."},{"id":"h25","d":"D1","q":"このパイプラインは高スループットで、重複がダッシュボードの指標を歪めることが運用上の懸念になっています。IoTデバイスからのテレメトリを、少ないコード運用でPub/SubからBigQueryへ直接ストリーミングしたいと考えています。単純なパススルー（変換なし）で、Dataflowジョブを自分で書かずに済ませたい場合、最も簡素で運用負荷の低い方法はどれですか。","o":["一旦GCSに保存し日次でloadする","Pub/Sub の BigQuery サブスクリプションを使って直接書き込む","自作Dataflowストリーミングジョブを常時運用する","Cloud Functions で1メッセージずつ挿入する"],"a":1,"e":"変換不要の単純なストリーミングなら、Pub/SubのBigQueryサブスクリプションがトピックから直接BigQueryへ書き込め、Dataflowコード不要で運用負荷が最小です。自作Dataflowやfunctionは開発・運用負荷が増え、GCS経由日次はリアルタイム要件を満たしません。","qEn":"The pipeline is high-throughput, and duplicates skewing dashboard metrics is an operational concern. You want to stream IoT telemetry directly from Pub/Sub to BigQuery with minimal code and operations, as a simple passthrough (no transforms), without writing a Dataflow job. Which is the simplest, lowest-ops approach?","oEn":["Stage to GCS and load daily","Use a Pub/Sub BigQuery subscription to write directly","Operate a custom Dataflow streaming job continuously","Insert one message at a time with Cloud Functions"],"eEn":"For simple transform-free streaming, a Pub/Sub BigQuery subscription writes directly from the topic to BigQuery with no Dataflow code and minimal ops. Custom Dataflow or Functions add dev/ops burden, and GCS-then-daily-load misses the real-time requirement."},{"id":"h26","d":"D2","q":"この構成は運用の簡素化を最重視し、変換ロジックを持たない純粋な取り込みだけを担わせたいと考えています。あるダッシュボードでは、巨大なファクトテーブルに対する同一の集計クエリ（日次のGROUP BY集計）が、多数のユーザーによって繰り返し実行されコストと待ち時間が問題になっています。ベーステーブル更新時に増分的に自動更新される、集計結果を事前計算する最適な機能はどれですか。","o":["マテリアライズドビューで集計を事前計算し自動増分更新する","通常のビューを作成してクエリを短くする","毎回 CREATE TABLE AS SELECT で手動更新する","結果をスプレッドシートにコピーして共有する"],"a":0,"e":"マテリアライズドビューは集計結果を事前計算・保存し、ベーステーブル更新時に増分的に自動更新されるため、繰り返す集計のコストと待ち時間を削減します。通常ビューは実行時に毎回計算し、手動CTASは鮮度管理が煩雑、スプレッドシートコピーは論外です。","qEn":"This design prioritizes operational simplicity and should handle pure ingestion with no transformation logic. On a dashboard, the same aggregation query (daily GROUP BY) over a huge fact table is run repeatedly by many users, causing cost and latency issues. Which feature precomputes aggregates and refreshes incrementally when base data changes?","oEn":["Use a materialized view that precomputes aggregates and auto-refreshes incrementally","Create a regular view to shorten the query","Manually refresh with CREATE TABLE AS SELECT each time","Copy results into a spreadsheet to share"],"eEn":"Materialized views precompute and store aggregates and refresh incrementally as base data changes, cutting cost and latency for repeated aggregations. Regular views recompute at query time, manual CTAS complicates freshness, and spreadsheet copies are unsuitable."},{"id":"h27","d":"D2","q":"この集計は多数の同時ユーザーに参照され、リアルタイム性より応答の速さとコスト効率が重視されます。データサイエンティストは、住宅の広さや部屋数から販売価格（連続値）を予測するモデルをBigQuery ML上のSQLで構築します。この回帰モデルの予測精度を評価する際、予測誤差の大きさを元の単位で表す代表的な指標はどれですか。","o":["Precision（適合率）","Recall（再現率）","AUC（ROC曲線下面積）","RMSE（二乗平均平方根誤差）"],"a":3,"e":"連続値を予測する回帰では RMSE（Root Mean Squared Error）が代表的な評価指標で、誤差を元の単位で表し大きな誤差に敏感です。Precision/Recall/AUCは分類モデルの指標で、連続値予測の回帰評価には用いません。","qEn":"The aggregate is viewed by many concurrent users, prioritizing response speed and cost efficiency over real-time freshness. A data scientist builds a BigQuery ML model in SQL to predict house sale price (a continuous value) from size and room count. Which is a standard metric to evaluate this regression's error magnitude in the original units?","oEn":["Precision","Recall","AUC (area under the ROC curve)","RMSE (root mean squared error)"],"eEn":"For regression predicting continuous values, RMSE is a standard metric expressing error in original units and sensitive to large errors. Precision/Recall/AUC are classification metrics, not used for continuous-value regression evaluation."},{"id":"h28","d":"D2","q":"このモデルは不動産評価のワークフローに組み込まれ、誤差の大きさを担当者が直感的に理解できることが重要です。不正取引検知の分類モデルを評価しています。不正の見逃し（実際に不正なのに正常と判定）を最小化することが最優先で、正常を誤って不正とする程度のコストは許容できます。この目的に最も直結する評価指標はどれですか。","o":["Precision（適合率）だけを最大化する","RMSE を最小化する","決定係数 R^2 を最大化する","Recall（再現率）を最大化する"],"a":3,"e":"見逃し（偽陰性）の最小化を最優先するなら、実際の陽性を捕捉する割合であるRecall（再現率）が最も直結します。Precisionのみでは見逃しを見落とし、RMSEやR^2は回帰指標で分類の見逃し評価には不適です。","qEn":"The model feeds a property-valuation workflow, and stakeholders must intuitively grasp the error magnitude. You evaluate a fraud-detection classifier. Minimizing missed fraud (actually fraud but predicted normal) is the top priority, and the cost of flagging normal as fraud is acceptable. Which metric most directly serves this goal?","oEn":["Maximize Precision only","Minimize RMSE","Maximize the coefficient of determination R^2","Maximize Recall"],"eEn":"To minimize missed fraud (false negatives), Recall, the fraction of actual positives caught, is most directly relevant. Precision alone ignores misses, and RMSE or R^2 are regression metrics unsuited to classification miss evaluation."},{"id":"h29","d":"D2","q":"このモデルは金融取引の監視に用いられ、見逃しが直接的な金銭的損失につながる点が経営から強く懸念されています。組織は、複数チームが一貫した指標定義（例: 売上、解約率）で分析できるよう、集中管理されたセマンティックモデルとガバナンス、埋め込み分析やモデリング層を求めています。単なるレポート作成を超えたエンタープライズBIプラットフォームとして最適なのはどれですか。","o":["スプレッドシートのピボットテーブル","BigQuery コンソールのクエリ履歴","Looker（LookMLでセマンティック層を集中管理）","Looker Studio（無料の簡易ダッシュボード）"],"a":2,"e":"Looker はLookMLによる集中管理されたセマンティックモデルで指標定義を統一し、ガバナンス・埋め込み分析・モデリング層を備えるエンタープライズBIプラットフォームです。Looker Studioは軽量な可視化向けでセマンティック層の集中管理には不足、他選択肢はBIプラットフォームではありません。","qEn":"The model monitors financial transactions, and management is strongly concerned that misses cause direct monetary loss. An organization wants centrally governed, consistent metric definitions (e.g., revenue, churn) across teams, with a semantic model, embedded analytics, and a modeling layer, beyond simple reporting. Which is the enterprise BI platform of choice?","oEn":["Spreadsheet pivot tables","BigQuery console query history","Looker (centrally governed semantic layer via LookML)","Looker Studio (free lightweight dashboards)"],"eEn":"Looker provides a centrally governed semantic model via LookML for consistent metric definitions, with governance, embedded analytics, and a modeling layer, an enterprise BI platform. Looker Studio is lightweight visualization lacking a governed semantic layer; the others aren't BI platforms."},{"id":"h30","d":"D2","q":"この組織では部門ごとに指標の定義がばらつき、レポート間で数値が食い違う問題が長年の課題になっています。小規模チームが、BigQueryとGoogleスプレッドシートのデータを手早く接続し、無料で共有可能なインタラクティブダッシュボードを作りたいと考えています。LookMLのようなモデリング層は不要で、素早く可視化することが目的です。最適なツールはどれですか。","o":["BigQuery のクエリ結果をCSVで毎回配布する","Looker Studio で手軽にダッシュボードを作成する","Looker のフルLookMLプロジェクトを構築する","Dataproc でカスタムWebアプリを開発する"],"a":1,"e":"Looker Studio（旧Data Studio）は無料で、BigQueryやスプレッドシートに素早く接続しインタラクティブなダッシュボードを共有できる軽量ツールです。フルLookMLのLookerは重厚で目的に過剰、Dataproc自作やCSV配布は手間がかかり共有・対話性に劣ります。","qEn":"Metric definitions vary by department, and mismatched numbers across reports have been a long-standing problem. A small team wants to quickly connect BigQuery and Google Sheets data and build free, shareable interactive dashboards, without needing a modeling layer like LookML, prioritizing speed to visualization. Which tool is best?","oEn":["Distribute BigQuery query results as CSV each time","Build dashboards quickly with Looker Studio","Stand up a full LookML project in Looker","Develop a custom web app with Dataproc"],"eEn":"Looker Studio (formerly Data Studio) is a free lightweight tool that quickly connects to BigQuery and Sheets to build and share interactive dashboards. Full-LookML Looker is overkill, and custom Dataproc apps or CSV distribution are laborious with poor sharing/interactivity."},{"id":"h31","d":"D2","q":"このチームは予算が限られ、専任のBI管理者を置かずに素早く価値を出すことを最優先しています。アナリストは、各顧客の注文について、同一顧客内での購入金額の累計や、直前の注文からの差分を1つのクエリで計算したいと考えています。行をグループに折り畳まずに、パーティション・並び順を指定して行ごとに計算するSQL機能はどれですか。","o":["ウィンドウ関数（OVER句によるPARTITION BY / ORDER BY）","単純な GROUP BY 集計","INNER JOIN の多用","サブクエリのCOUNT(*)だけ"],"a":0,"e":"OVER句を使うウィンドウ（分析）関数は、行を折り畳まずにPARTITION BY・ORDER BYで顧客ごとの累計（SUM OVER）や直前値との差分（LAG）を計算できます。GROUP BYは行を集約してしまい、JOIN多用やサブクエリCOUNTでは同等の行単位計算を簡潔に表現できません。","qEn":"The team has a limited budget and prioritizes quick value without a dedicated BI administrator. An analyst wants to compute, per customer order, a running total of spend within the same customer and the difference from the previous order, in one query, without collapsing rows into groups. Which SQL feature applies per-row with partitioning and ordering?","oEn":["Window functions (OVER with PARTITION BY / ORDER BY)","A simple GROUP BY aggregation","Heavy use of INNER JOINs","Only a subquery COUNT(*)"],"eEn":"Window (analytic) functions with OVER compute per-row running totals (SUM OVER) and previous-value differences (LAG) using PARTITION BY/ORDER BY without collapsing rows. GROUP BY aggregates rows away, and heavy JOINs or subquery COUNTs can't express this per-row logic concisely."},{"id":"h32","d":"D2","q":"このレポートはリテンション分析に用いられ、顧客単位の時系列的な振る舞いを1つのクエリで表現する必要があります。数十億行のイベントテーブルで、ユニークユーザー数の概算をダッシュボードで頻繁に表示します。厳密な精度は不要で、スキャンコストとレイテンシを抑えたいという要件があります。BigQueryで最も効率的な方法はどれですか。","o":["APPROX_COUNT_DISTINCT を使って近似ユニーク数を高速計算する","COUNT(DISTINCT ...) を毎回正確に計算する","全行を配列に集めてアプリ側で数える","データを一旦Cloud SQLに移して数える"],"a":0,"e":"厳密な精度が不要で規模が大きい場合、BigQueryのAPPROX_COUNT_DISTINCT（HyperLogLog++ベース）はメモリとレイテンシを抑えつつ近似ユニーク数を高速に返します。正確なCOUNT(DISTINCT)は重く、アプリ集計やCloud SQL移送は非効率です。","qEn":"The report supports retention analysis and must express per-customer time-ordered behavior in one query. On a table of billions of events, a dashboard frequently shows approximate unique user counts. Exact precision isn't needed and you want to reduce scan cost and latency. What is the most efficient approach in BigQuery?","oEn":["Use APPROX_COUNT_DISTINCT for fast approximate uniques","Compute exact COUNT(DISTINCT ...) every time","Collect all rows into an array and count in the app","Move the data to Cloud SQL first and count there"],"eEn":"When exact precision isn't needed at large scale, BigQuery's APPROX_COUNT_DISTINCT (HyperLogLog++) returns approximate uniques fast with low memory and latency. Exact COUNT(DISTINCT) is heavy, and app-side counting or moving to Cloud SQL is inefficient."},{"id":"h33","d":"D2","q":"この指標はリアルタイムダッシュボードで頻繁に更新表示され、応答時間の短縮がユーザー体験に直結します。経営ダッシュボードでは、BigQuery上の同じ集計を多数の同時ユーザーが操作し、サブ秒のインタラクティブな応答が求められます。SQLを書き換えずにBigQueryのクエリ応答を高速化する、インメモリ分析アクセラレーションはどれですか。","o":["スロットを0にして待機させる","結果を毎回CSVエクスポートする","テーブルを暗号化して再ロードする","BI Engine を有効化してインメモリでクエリを高速化する"],"a":3,"e":"BigQuery BI Engine はインメモリ分析アクセラレーションで、SQLを変えずにダッシュボードのクエリをサブ秒に高速化し多数の同時アクセスに応えます。スロット0は逆効果、CSVエクスポートや再暗号化は応答高速化と無関係です。","qEn":"This metric refreshes frequently on a real-time dashboard, and shorter response times directly improve UX. An executive dashboard has many concurrent users interacting with the same BigQuery aggregates, requiring sub-second interactive responses. Which in-memory analytics acceleration speeds up BigQuery responses without rewriting SQL?","oEn":["Set slots to zero to make it wait","Export results to CSV every time","Encrypt the table and reload it","Enable BI Engine to accelerate queries in memory"],"eEn":"BigQuery BI Engine is in-memory analytics acceleration that speeds dashboard queries to sub-second without changing SQL, serving high concurrency. Zero slots is counterproductive, and CSV export or re-encryption are unrelated to response speed."},{"id":"h34","d":"D2","q":"このダッシュボードは経営会議で使われ、遅延なくドリルダウンできる操作性が強く求められています。データガバナンス担当は、複数のBigQueryテーブルに対して、鮮度（最終更新）、NULL率、値の範囲などのルールを定義し自動でデータ品質を監視・スコアリングしたいと考えています。データカタログと統合されたGoogle Cloudのサービスはどれですか。","o":["BigQuery のクエリ履歴タブ","Cloud Monitoring の CPU アラート","Dataplex のデータ品質（自動データ品質/データプロファイリング）","Looker Studio のグラフ機能"],"a":2,"e":"Dataplex はデータ品質ルールの定義・自動チェック・プロファイリングやカタログ/リネージを統合的に提供し、鮮度やNULL率、範囲などを監視・スコアリングできます。Looker Studioは可視化、クエリ履歴やCPUアラートはデータ品質監視の専用機能ではありません。","qEn":"The dashboard is used in executive meetings and must support drill-down without lag. A data governance lead wants to define rules like freshness, null rate, and value ranges across multiple BigQuery tables and automatically monitor and score data quality, integrated with a data catalog. Which Google Cloud service fits?","oEn":["The BigQuery query history tab","Cloud Monitoring CPU alerts","Dataplex data quality (auto data quality / data profiling)","Looker Studio charting"],"eEn":"Dataplex provides data-quality rule definition, automated checks, profiling, and catalog/lineage integration, monitoring and scoring freshness, null rate, ranges, etc. Looker Studio is visualization, and query history or CPU alerts aren't dedicated data-quality features."},{"id":"h35","d":"D2","q":"この組織は監査対応のためデータ品質の証跡を残す必要があり、手作業のチェックでは追随できなくなっています。あるレポートは、毎朝決まった時刻にBigQueryで集計クエリを実行し、結果を宛先テーブルに保存してダッシュボードを更新する必要があります。外部オーケストレータを持ち込まず、BigQuery内で完結してスケジュール実行する最も簡単な方法はどれですか。","o":["Dataflow ジョブを常時起動しておく","BigQuery のスケジュールされたクエリ（scheduled query）を設定する","手動で毎朝コンソールからクエリを実行する","Compute Engine の cron でCLIを叩く"],"a":1,"e":"BigQueryのスケジュールされたクエリは、指定時刻に定期実行し結果を宛先テーブルへ書き込む機能で、外部オーケストレータ不要で簡単に構成できます。手動実行は非現実的、Compute Engine cronや常時Dataflowは過剰で運用負荷が高いです。","qEn":"The organization must retain data-quality evidence for audits, and manual checks can no longer keep up. A report must run an aggregation query in BigQuery every morning at a fixed time, save results to a destination table, and refresh a dashboard, all within BigQuery without an external orchestrator. What is the simplest scheduled approach?","oEn":["Keep a Dataflow job always running","Set up a BigQuery scheduled query","Run the query manually from the console each morning","Hit the CLI via cron on Compute Engine"],"eEn":"BigQuery scheduled queries run periodically at a set time and write results to a destination table, configured simply without an external orchestrator. Manual runs are impractical, and Compute Engine cron or always-on Dataflow are overkill with high ops burden."},{"id":"h36","d":"D2","q":"あるアナリストのクエリは SELECT * FROM huge_table WHERE ... と書かれ、必要なのは3列だけなのに全列をスキャンして高額になっています。BigQueryはオンデマンド課金で、スキャンしたバイト数で料金が決まります。コストを下げる最も直接的な改善はどれですか。","o":["テーブルを一時テーブルにコピーしてから同じ SELECT * をする","必要な列だけを明示的にSELECTしてスキャン列を絞る","LIMIT を付けてスキャンバイト数を減らす","結果を降順に ORDER BY する"],"a":1,"e":"BigQueryは列指向で、スキャンしたバイト数（列×行）で課金されます。必要な列だけをSELECTすれば読み取り列が減りコストが直接下がります。LIMITは表示行を絞るだけでスキャンは減らず、ORDER BYやコピー後の SELECT * はコスト削減になりません。","qEn":"An analyst's query is SELECT * FROM huge_table WHERE ... but only 3 columns are needed, yet all columns are scanned, driving up cost. BigQuery on-demand billing charges by bytes scanned. What is the most direct cost improvement?","oEn":["Copy the table to a temp table, then run the same SELECT *","Explicitly SELECT only the needed columns to prune scanned columns","Add LIMIT to reduce bytes scanned","ORDER BY the results descending"],"eEn":"BigQuery is columnar and bills by bytes scanned (columns x rows). Selecting only needed columns reduces columns read and directly lowers cost. LIMIT only trims displayed rows without cutting scan, and ORDER BY or copy-then-SELECT-* don't reduce cost."},{"id":"h37","d":"D2","q":"このクエリはオンデマンド課金のプロジェクトで実行されており、無駄なスキャンが月次コストを押し上げています。データチームは、過去24か月の月次売上から今後6か月を予測したいと考えています。SQLだけで、季節性やトレンドを自動で扱う時系列予測モデルをBigQuery ML上で構築したい場合、最適なモデルタイプはどれですか。","o":["ARIMA_PLUS（時系列予測モデル）","LINEAR_REG（単純な線形回帰）","KMEANS（クラスタリング）","LOGISTIC_REG（ロジスティック回帰）"],"a":0,"e":"BigQuery MLのARIMA_PLUSは季節性・トレンド・休日効果などを自動で扱う時系列予測モデルで、月次売上の将来予測に最適です。単純な線形回帰は季節性を捉えにくく、KMEANSはクラスタリング、ロジスティック回帰は分類で時系列予測には不適です。","qEn":"The query runs in an on-demand billing project, and wasted scans inflate monthly cost. A data team wants to forecast the next 6 months from 24 months of monthly sales, building a time-series model in BigQuery ML with SQL that automatically handles seasonality and trend. Which model type is best?","oEn":["ARIMA_PLUS (time-series forecasting model)","LINEAR_REG (simple linear regression)","KMEANS (clustering)","LOGISTIC_REG (logistic regression)"],"eEn":"BigQuery ML ARIMA_PLUS automatically handles seasonality, trend, and holiday effects, ideal for forecasting monthly sales. Simple linear regression struggles with seasonality, KMEANS is clustering, and logistic regression is classification, unsuited to forecasting."},{"id":"h38","d":"D2","q":"この予測は在庫計画に用いられ、季節的な繁閑を織り込めないと発注精度が大きく損なわれます。あるBigQueryデータセットには、機微な個人情報を含む顧客テーブルがあります。アナリストには集計結果は見せたいが、生の行や特定の列（例: マイナンバー相当）は見せたくありません。基盤テーブルへの直接アクセスを与えずに制御する最適な方法はどれですか。","o":["全アナリストにベーステーブルの閲覧権限を直接付与する","テーブルをCSVで全員に配布する","データセットを公開設定にして誰でも読めるようにする","認可済みビュー（authorized view）と列レベルセキュリティで公開範囲を限定する"],"a":3,"e":"認可済みビューはベーステーブルへの直接権限を与えずに、ビュー経由で必要な集計・列だけを公開でき、列レベルセキュリティで機微列を保護できます。ベース直接権限付与やCSV全配布、公開設定は機微情報を露出させ要件に反します。","qEn":"The forecast informs inventory planning, and failing to capture seasonality badly degrades ordering accuracy. A BigQuery dataset has a customer table with sensitive PII. Analysts should see aggregates but not raw rows or certain columns (e.g., national ID). What is the best way to control access without granting direct access to the base table?","oEn":["Grant all analysts direct read on the base table","Distribute the table as CSV to everyone","Make the dataset public so anyone can read it","Use authorized views plus column-level security to limit exposure"],"eEn":"Authorized views expose only needed aggregates/columns via the view without granting direct base-table access, and column-level security protects sensitive columns. Direct grants, CSV distribution, or making it public expose PII and violate the requirement."},{"id":"h39","d":"D2","q":"この要件は個人情報保護規程に基づくもので、違反は重大なコンプライアンスリスクにつながります。あるアナリストは、広告費と売上という2つの連続変数の間に、どの程度の直線的な関連があるかを1つの数値で把握したいと考えています。因果ではなく関連の強さと向きを-1〜1で示す統計量はどれですか。","o":["標準偏差（standard deviation）","最頻値（mode）","相関係数（correlation, CORR）","中央値（median）"],"a":2,"e":"2つの連続変数の直線的関連の強さと向きを-1〜1で示すのは相関係数（BigQueryのCORR）です。相関は因果を意味しません。中央値・標準偏差・最頻値はそれぞれ代表値やばらつき・頻度の指標で、2変数間の関連度は表しません。","qEn":"This requirement stems from privacy policy, and violations pose serious compliance risk. An analyst wants a single number for how strongly two continuous variables, ad spend and revenue, are linearly related. Which statistic shows the strength and direction of association from -1 to 1 (not causation)?","oEn":["Standard deviation","Mode","Correlation coefficient (CORR)","Median"],"eEn":"The correlation coefficient (BigQuery CORR) shows the strength and direction of a linear association between two continuous variables from -1 to 1; correlation isn't causation. Median, standard deviation, and mode describe central tendency, spread, or frequency, not two-variable association."},{"id":"h40","d":"D2","q":"この分析はマーケティング投資の意思決定に用いられ、関連の強さを1つの解釈しやすい数値で伝える必要があります。回帰モデルの評価で、外れ値の影響を過度に強調せず、平均的な予測誤差を元の単位で頑健に把握したいと考えています。誤差を二乗せずに絶対値の平均を取るため大きな外れ値の影響を相対的に抑える指標はどれですか。","o":["Precision（適合率）","AUC（ROC曲線下面積）","MAE（平均絶対誤差）","RMSE（二乗平均平方根誤差）"],"a":2,"e":"MAE（平均絶対誤差）は誤差の絶対値の平均で、二乗しないため大きな外れ値の影響がRMSEより相対的に小さく、頑健に平均誤差を表します。RMSEは外れ値に敏感、Precisionは分類、AUCも分類指標で回帰の頑健な誤差評価には不適です。","qEn":"The analysis informs marketing-investment decisions and must convey association strength as one interpretable number. When evaluating a regression model, you want a robust view of average prediction error in original units without overemphasizing outliers. Which metric averages absolute errors (not squared), relatively dampening large outliers?","oEn":["Precision","AUC (area under the ROC curve)","MAE (mean absolute error)","RMSE (root mean squared error)"],"eEn":"MAE averages the absolute errors and, by not squaring, dampens large outliers relative to RMSE, giving a robust average error. RMSE is outlier-sensitive, and Precision/AUC are classification metrics unsuited to robust regression error evaluation."},{"id":"h41","d":"D2","q":"このモデルは需要予測に用いられ、一部の異常値に評価が過度に引きずられることを避けたいと考えています。マーケティングチームは、購買履歴に基づいて顧客を自然なグループに分けたいと考えていますが、事前のラベル（正解セグメント）はありません。BigQuery MLで教師なし学習により顧客セグメンテーションを行う最適なモデルはどれですか。","o":["ARIMA_PLUS で時系列予測する","KMEANS クラスタリングで教師なしにグループ化する","LOGISTIC_REG で二値分類する","LINEAR_REG で連続値を予測する"],"a":1,"e":"ラベルなしで自然なグループに分ける教師なし学習にはKMEANSクラスタリングが最適で、顧客セグメンテーションに広く使われます。ロジスティック回帰や線形回帰はラベルが必要な教師あり、ARIMA_PLUSは時系列予測でセグメンテーションには不適です。","qEn":"The model supports demand forecasting, and evaluation should not be overly dragged by a few anomalies. A marketing team wants to split customers into natural groups from purchase history, with no predefined labels (ground-truth segments). Which BigQuery ML model does unsupervised customer segmentation best?","oEn":["ARIMA_PLUS for time-series forecasting","KMEANS clustering for unsupervised grouping","LOGISTIC_REG for binary classification","LINEAR_REG to predict a continuous value"],"eEn":"For unsupervised grouping into natural clusters without labels, KMEANS clustering is best and widely used for customer segmentation. Logistic and linear regression are supervised (need labels), and ARIMA_PLUS is forecasting, unsuited to segmentation."},{"id":"h42","d":"D2","q":"この分析はデータ探索の初期段階で行われ、施策判断の前提として関係の傾向を素早く把握したいと考えています。あるデータプロバイダは、パートナー企業に対して、BigQuery上のキュレーション済みデータセットを、コピーや定期エクスポートなしにライブで安全に共有したいと考えています。データを移動させずに横断的に共有・購読できるGoogle Cloudの仕組みはどれですか。","o":["Analytics Hub でデータ共有（データエクスチェンジ/リスティング）を行う","データを毎晩CSVにしてメール添付で送る","相手にプロジェクトのオーナー権限を渡す","Transfer Appliance でデータを郵送する"],"a":0,"e":"Analytics Hub はBigQueryのデータをコピーせずにライブで安全に共有・購読できるデータエクスチェンジ機能で、パートナー間共有に最適です。CSVメールやオーナー権限譲渡はガバナンス・鮮度・セキュリティに劣り、Transfer Applianceは共有用途ではありません。","qEn":"The analysis is exploratory and aims to quickly grasp the trend of the relationship before deciding on actions. A data provider wants to share curated BigQuery datasets with partner companies live and securely, without copies or periodic exports, sharing across organizations without moving data. Which Google Cloud mechanism fits?","oEn":["Share via Analytics Hub (data exchanges/listings)","Email nightly CSVs as attachments","Grant partners project owner permissions","Mail the data with Transfer Appliance"],"eEn":"Analytics Hub is a data-exchange feature to share and subscribe to live BigQuery data securely without copies, ideal for partner sharing. CSV emails or granting owner rights are worse on governance, freshness, and security, and Transfer Appliance isn't for sharing."},{"id":"h43","d":"D2","q":"このデータは第三者に対する有償提供の基盤となるため、鮮度とセキュリティの両立が事業上の要件です。分類モデルでは、確率スコアに対する判定しきい値を上げると、陽性と判定する件数が減ります。この操作をした場合、一般にPrecisionとRecallはどのように変化しますか。トレードオフを正しく説明しているのはどれですか。","o":["PrecisionもRecallも必ず同時に上がる","PrecisionもRecallも必ず同時に下がる","しきい値はPrecisionにもRecallにも影響しない","Precisionは上がりやすく、Recallは下がりやすい"],"a":3,"e":"しきい値を上げると陽性判定が厳しくなり、誤検知が減ってPrecisionは上がりやすい一方、拾える陽性が減ってRecallは下がりやすくなります。両者は一般にトレードオフ関係にあり、同時に必ず上下する、または無関係という説明は誤りです。","qEn":"The data underpins a paid third-party offering, so freshness and security together are business requirements. In a classifier, raising the decision threshold on the probability score reduces the number predicted positive. Generally, how do Precision and Recall change? Which correctly describes the trade-off?","oEn":["Both Precision and Recall always rise together","Both Precision and Recall always fall together","The threshold affects neither Precision nor Recall","Precision tends to rise while Recall tends to fall"],"eEn":"Raising the threshold makes positive calls stricter, reducing false positives so Precision tends to rise, while catching fewer positives so Recall tends to fall. They generally trade off; claims that both always move together or are unaffected are wrong."},{"id":"h44","d":"D2","q":"この評価はモデルの運用しきい値を決める議論の一部で、指標間のトレードオフを正しく理解する必要があります。アナリストは、月次・地域別の売上テーブルを、行に月・列に地域を配置したクロス集計（ピボット）形式でレポートに表示したいと考えています。BigQuery SQLで集計しつつ行を列方向に展開する最適な構文はどれですか。","o":["ORDER BY を複数付けて並べ替えるだけ","DISTINCT で重複を除くだけ","LIMIT で表示件数を絞るだけ","PIVOT 演算子を使って地域を列方向に展開する"],"a":3,"e":"BigQueryのPIVOT演算子は、集計しながら特定列の値（地域）を列方向に展開してクロス集計を作れます。ORDER BYやDISTINCT、LIMITは並び替え・重複除去・件数制限であり、行を列に変換するピボット表示はできません。","qEn":"This evaluation is part of deciding the operating threshold, requiring correct understanding of metric trade-offs. An analyst wants to display a monthly-by-region sales table as a cross-tab (pivot) with months in rows and regions in columns. Which BigQuery SQL construct aggregates while turning rows into columns?","oEn":["Just add multiple ORDER BY clauses to sort","Just use DISTINCT to remove duplicates","Just use LIMIT to cap the row count","Use the PIVOT operator to expand regions into columns"],"eEn":"BigQuery's PIVOT operator aggregates while spreading a column's values (regions) across columns to build a cross-tab. ORDER BY, DISTINCT, and LIMIT sort, dedupe, or cap rows and can't turn rows into columns."},{"id":"h45","d":"D2","q":"このレポートは月次の経営レビューで配布され、地域と期間を一目で比較できる表形式が求められています。データサイエンティストは、BigQuery MLで学習と推論の両方に同じ特徴量前処理（標準化やバケット化など）を適用し、予測時に前処理漏れを防ぎたいと考えています。前処理をモデルに焼き込み、推論時に自動適用する最適な仕組みはどれですか。","o":["予測のたびに前処理を忘れないよう手順書で運用する","前処理はせず生の特徴量をそのまま使う","TRANSFORM 句でモデル内に前処理を定義し推論時も自動適用する","学習前に手動でSQL変換し、推論時は別途書き直す"],"a":2,"e":"BigQuery MLのTRANSFORM句は、標準化やバケット化などの前処理をモデル定義に含め、学習・推論で自動適用するため前処理漏れ（トレーニング/サービングスキュー）を防ぎます。手動再記述や手順書運用はミスを招き、前処理省略は精度を損ないます。","qEn":"The report is distributed at monthly executive reviews and needs a tabular form comparing region and period at a glance. A data scientist wants to apply the same feature preprocessing (standardization, bucketization, etc.) to both training and inference in BigQuery ML, avoiding missed preprocessing at prediction time. Which mechanism bakes preprocessing into the model and applies it automatically at inference?","oEn":["Rely on a runbook to remember preprocessing on each prediction","Skip preprocessing and use raw features","Define preprocessing in the TRANSFORM clause so it auto-applies at inference","Transform manually in SQL before training and rewrite it for inference"],"eEn":"BigQuery ML's TRANSFORM clause embeds preprocessing (standardization, bucketization) in the model and applies it automatically for training and inference, preventing missed preprocessing (training/serving skew). Manual rewrites or runbooks invite errors, and skipping preprocessing hurts accuracy."},{"id":"h46","d":"D2","q":"学習と推論で処理が一致しないと精度が劣化するため、再現性のある一貫した前処理が不可欠だと考えられています。このモデルは頻繁に再学習・再デプロイされ、前処理の不整合がトレーニング/サービングスキューを生む懸念があります。二値分類モデルを、しきい値に依存せずに全体的な判別性能で比較したいと考えています。陽性・陰性の順位付け能力を、しきい値を動かしながら評価する代表的な指標はどれですか。","o":["平均絶対誤差（MAE）","ROC-AUC（ROC曲線下面積）","単一しきい値でのAccuracyのみ","RMSE"],"a":1,"e":"ROC-AUCは全しきい値にわたる真陽性率と偽陽性率の関係を要約し、しきい値に依存しない順位付け（判別）性能を評価できます。単一しきい値のAccuracyは不均衡データで誤解を招き、RMSEやMAEは回帰指標で分類の総合判別評価には不適です。","qEn":"Mismatched training and inference processing degrades accuracy, so reproducible, consistent preprocessing is essential. The model is retrained and redeployed often, raising concern that preprocessing mismatch causes training/serving skew. You want to compare binary classifiers by overall discrimination independent of threshold, evaluating their ability to rank positives above negatives across thresholds. Which is a standard metric?","oEn":["Mean absolute error (MAE)","ROC-AUC (area under the ROC curve)","Only Accuracy at a single threshold","RMSE"],"eEn":"ROC-AUC summarizes true-positive vs false-positive rates across all thresholds, evaluating threshold-independent ranking (discrimination). Single-threshold Accuracy misleads on imbalanced data, and RMSE/MAE are regression metrics unsuited to overall classification discrimination."},{"id":"h47","d":"D2","q":"この比較は複数モデルの選定に用いられ、運用しきい値を固定せずに総合的な判別力を評価する必要があります。あるダッシュボードは日次で十分な鮮度で構いませんが、閲覧のたびにBigQueryへ重いクエリが飛び、コストがかさんでいます。Looker Studioで同一クエリの再実行を抑え、コストとレイテンシを下げる最も直接的な設定はどれですか。","o":["データ抽出やキャッシュ（データの更新頻度設定）を活用して再クエリを減らす","毎回リフレッシュを強制してキャッシュを無効化する","レポートの色数を減らして軽量化する","グラフの種類を棒から円に変えて負荷を下げる"],"a":0,"e":"Looker Studioのキャッシュやデータ抽出（Extract）、更新頻度の設定を使えば、同一クエリの再実行を抑え、BigQueryへのクエリ回数・コスト・レイテンシを下げられます。強制リフレッシュはキャッシュを無効化し逆効果、色数やグラフ種類の変更はクエリコストと無関係です。","qEn":"The comparison guides model selection and must assess overall discrimination without fixing an operating threshold. A dashboard only needs daily freshness, but every view fires a heavy BigQuery query, driving up cost. In Looker Studio, which setting most directly reduces re-running the same query to cut cost and latency?","oEn":["Use data extract/caching (data freshness settings) to reduce re-queries","Force a refresh every time to disable caching","Reduce the number of colors to lighten the report","Change charts from bar to pie to lower load"],"eEn":"Looker Studio caching, data extract, and freshness settings reduce re-running the same query, cutting BigQuery query count, cost, and latency. Forcing refresh disables caching (counterproductive), and changing colors or chart types is unrelated to query cost."},{"id":"h48","d":"D2","q":"この不均衡は業務データでは一般的で、単純な正解率が意思決定を誤らせる危険性が指摘されています。アナリストは、複数の指標を単一のスコアカードで示すのではなく、地域ごとの売上を地図上の色の濃淡で直感的に比較し、地理的な偏りを把握したいと考えています。この目的に最も適した可視化の種類はどれですか。","o":["塗り分け地図（コロプレスマップ）","単純なテキストの表","1つの数値を示すスコアカード","時系列の折れ線グラフ"],"a":0,"e":"地域ごとの値を地図上の色の濃淡で比較し地理的偏りを見るにはコロプレス（塗り分け）マップが最適です。テキストの表は地理的直感に乏しく、スコアカードは単一値、折れ線は時間推移向けで地域比較の地理表現には適しません。","qEn":"Such imbalance is common in business data, and simple accuracy risks misleading decisions. An analyst wants to intuitively compare regional sales by color shading on a map and grasp geographic skew, rather than showing several metrics on a single scorecard. Which visualization type fits best?","oEn":["A choropleth (shaded region) map","A plain text table","A scorecard showing one number","A time-series line chart"],"eEn":"To compare regional values by color shading on a map and see geographic skew, a choropleth map is best. A text table lacks geographic intuition, a scorecard shows one value, and a line chart is for time trends, not geographic regional comparison."},{"id":"h49","d":"D2","q":"この課題はモデルの本番採用可否を左右し、適切な指標選択が評価の信頼性を決めると認識されています。あるチームは、BigQuery MLのロジスティック回帰で解約予測モデルを作りましたが、データの90%が非解約で偏っています。Accuracyが高く見えても実運用で解約者をほとんど捕捉できていません。この不均衡データで解約者の捕捉力を正しく評価する指標の組み合わせはどれですか。","o":["Accuracy だけを見て判断する","学習データのサイズだけを見る","特徴量の数だけを見る","Precision・Recall（およびF1やPR-AUC）で少数クラスを評価する"],"a":3,"e":"90%が多数クラスの不均衡データでは、全て非解約と予測してもAccuracyは高く見えます。少数クラス（解約者）の捕捉はPrecision・Recall（およびF1やPR-AUC）で評価すべきです。Accuracyのみやデータ量・特徴量数だけでは不均衡下の性能を正しく測れません。","qEn":"This issue determines production adoption, and choosing the right metric is recognized as decisive for evaluation reliability. A team built a churn model with BigQuery ML logistic regression, but 90% of data is non-churn. Accuracy looks high yet it captures almost no churners in production. Which metrics correctly evaluate churner capture on this imbalanced data?","oEn":["Look only at Accuracy","Look only at the training data size","Look only at the number of features","Precision and Recall (and F1 or PR-AUC) to assess the minority class"],"eEn":"With 90% majority class, predicting all non-churn still yields high Accuracy. Minority-class (churner) capture should be judged by Precision/Recall (and F1 or PR-AUC). Accuracy alone, data size, or feature count can't correctly measure performance under imbalance."},{"id":"h50","d":"D3","q":"小売企業のデータ基盤チームは、販売・在庫・広告の各ソースを統合する日次ETLを運用しており、処理は20以上のタスクが多段に依存し合う。運用要件として、タスク失敗時の自動リトライ、障害復旧後に過去日付をまとめて再処理するバックフィル、タスクごとのSLA監視が必須である。チームには既にApache Airflowの実装・運用知見がある。これらを運用負荷を最小化しつつ満たす手段として、最も適切なものはどれか。","o":["Workflowsで全タスクを1本のYAMLに直列記述し、失敗時は手動で再実行する","Cloud Schedulerで各タスクを個別に時刻起動し、順序はスクリプトで制御する","Cloud Composer上でDAGとして実装し、依存関係・リトライ・バックフィル・SLAを定義する","Pub/Subメッセージを各タスクが購読し、疎結合に連鎖させる"],"a":2,"e":"複雑な多段依存・リトライ・バックフィル・SLA監視という要件はAirflow(DAG)の中核機能であり、フルマネージドのCloud Composerが最適。既存のAirflow知見も活かせる。Cloud Schedulerは単純な時刻起動のみで依存管理ができない。Workflowsは軽量サーバーレス向きで、この規模の依存・バックフィルには不向き。Pub/Subの連鎖は監視・バックフィルが困難。","qEn":"A nationwide retailer's data platform team runs a daily ETL that integrates sales, inventory, and advertising sources, with 20+ tasks arranged in multi-level dependencies. Operational requirements include automatic retries on task failure, backfill to reprocess past dates in bulk after recovery, and per-task SLA (deadline) monitoring. The team already has Apache Airflow implementation and operations expertise and wants to limit extra learning cost. Which orchestration option best meets these requirements while minimizing operational overhead?","oEn":["Write all tasks serially in one Workflows YAML and re-run manually on failure","Trigger each task individually by time with Cloud Scheduler and control ordering via scripts","Implement as a DAG on Cloud Composer, defining dependencies, retries, backfill, and SLAs","Have each task subscribe to Pub/Sub messages and chain them loosely"],"eEn":"Complex multi-level dependencies, retries, backfill, and SLA monitoring are core Airflow (DAG) features, so fully managed Cloud Composer is the best fit and reuses existing Airflow skills. Cloud Scheduler only triggers by time with no dependency management. Workflows suits lightweight serverless flows, not this scale of dependencies/backfill. Pub/Sub chaining makes monitoring and backfill hard."},{"id":"h51","d":"D3","q":"あるSaaSスタートアップは、Cloud Run上の3つのマイクロサービスAPIを定められた順序で呼び出し、各レスポンスに応じて後続処理を分岐させる軽量な処理を、1時間ごとに定期実行したい。各呼び出しは数秒で完了し状態を持たない。少人数のチームで、Cloud ComposerやAirflowのように常時稼働する重厚な基盤を運用する余力はなく、アイドル時のコストも極力ゼロに近づけたい。この要件に最も適したサーバーレスな構成はどれか。","o":["Cloud Composer環境を常時起動してDAGで3つのAPIを呼び出す","BigQueryのスケジュールクエリで外部APIを呼び出す","Dataflowストリーミングジョブで3つのAPIを順に呼び出す","Workflowsで3つのAPIをステップ定義し、Cloud Schedulerで1時間ごとに起動する"],"a":3,"e":"軽量なサーバーレスのステップ実行・分岐にはWorkflowsが最適で、実行時のみ課金され常時起動コストがない。定期起動はCloud Schedulerと組み合わせる。Cloud Composerは環境が常時稼働しコストが高く、この軽量用途には過剰。Dataflowはデータ並列処理用でAPIオーケストレーション向きでない。BigQueryスケジュールクエリはSQL実行用で外部API呼び出しには不向き。","qEn":"A SaaS startup wants to run a lightweight process hourly that calls three microservice APIs on Cloud Run in a fixed order and branches on the content of each response. Each call finishes in seconds and is stateless. The small team lacks the capacity to operate always-on heavy infrastructure like Cloud Composer or Airflow and wants idle-time cost as close to zero as possible. Which serverless setup best fits this requirement?","oEn":["Keep a Cloud Composer environment always on and call the three APIs via a DAG","Call the external APIs from a BigQuery scheduled query","Call the three APIs sequentially from a Dataflow streaming job","Define the three API calls as steps in Workflows and trigger hourly with Cloud Scheduler"],"eEn":"Workflows is ideal for lightweight serverless step execution and branching, billed per execution with no always-on cost, combined with Cloud Scheduler for periodic triggering. Cloud Composer keeps an environment always running and is overkill/costly here. Dataflow is for parallel data processing, not API orchestration. BigQuery scheduled queries run SQL, not external API calls."},{"id":"h52","d":"D3","q":"データアナリストのチームは、BigQuery内のデータマート向けに、数十のSQLモデルを依存関係を保ちながら順番に変換・更新したい。各テーブルには品質を担保するテスト(アサーション)とドキュメントを紐付け、変換ロジックはGitでバージョン管理してレビュー可能にしたい。チームはSQLファーストで作業したく、Pythonでのコーディングは最小限にとどめたい。この宣言的なSQL変換管理に最も適したBigQueryネイティブのツールはどれか。","o":["Cloud Composerで各SQLをPythonOperatorとして書く","Dataflowで変換パイプラインを実装する","DataformでSQLXの定義と依存関係・アサーションを管理する","Cloud Data Fusionでビジュアルにパイプラインを組む"],"a":2,"e":"BigQuery内のSQL変換を依存グラフ・テスト(assertions)・ドキュメント付きで宣言的に管理し、Gitと連携できるのはDataformが最適。SQLファースト志向にも合致する。Cloud ComposerはSQLを手続き的に書く必要があり冗長。Dataflowはコード中心のデータ処理でSQL変換管理には過剰。Data FusionはビジュアルETL向きで、SQLファースト・Git連携の宣言的変換管理には最適でない。","qEn":"A team of data analysts wants to transform and update dozens of SQL models for a BigQuery data mart in sequence while preserving their mutual dependencies. Each table should have quality-assuring tests (assertions) and documentation attached, with transformation logic version-controlled and reviewable in Git. The team prefers to work SQL-first and keep Python coding to a minimum. Which BigQuery-native tool best fits this declarative SQL transformation management?","oEn":["Write each SQL as a PythonOperator in Cloud Composer","Implement the transformation pipeline in Dataflow","Manage SQLX definitions, dependencies, and assertions in Dataform","Build the pipeline visually in Cloud Data Fusion"],"eEn":"Dataform is best for declaratively managing in-BigQuery SQL transformations with a dependency graph, assertions (tests), and documentation, integrating with Git, matching the SQL-first preference. Cloud Composer requires procedural SQL wrapping and is verbose. Dataflow is code-centric and overkill for SQL transformation management. Data Fusion is visual ETL, not ideal for SQL-first declarative Git-based management."},{"id":"h53","d":"D3","q":"あるデータチームは、パートナー企業がCloud Storageバケットへ不定期にアップロードするCSVファイルを取り込むパイプラインを運用している。ファイルの到着タイミングは予測できず、アップロードのたびに可能な限り遅延なく取り込み処理を開始したい。定期ポーリングによる待ち時間や無駄な実行コストは避けたく、オブジェクト作成をきっかけにイベント駆動で処理を起動したい。この要件に最も適したGoogle Cloudの構成はどれか。","o":["Cloud Schedulerで5分ごとにバケットをポーリングして新規ファイルを探す","BigQueryの外部テーブルを定期的に再スキャンする","Cloud Composerのタイムトリガーで毎時DAGを起動する","EventarcでCloud Storageのオブジェクト作成イベントを受けてCloud RunやWorkflowsを起動する"],"a":3,"e":"オブジェクト作成という単一イベントで即時に処理を起動するにはEventarc(内部でPub/SubやCloud Audit Logs/GCS通知を利用)が最適で、Cloud RunやWorkflowsをターゲットにできる。ポーリング不要で遅延が小さい。Cloud Schedulerのポーリングは遅延とコストが生じる。Composerのタイムトリガーは不規則な到着に即応できない。BigQuery外部テーブルの再スキャンはイベント駆動ではない。","qEn":"A data team runs a pipeline that ingests CSV files uploaded irregularly by a partner company to a Cloud Storage bucket. Arrival timing is unpredictable, and they want ingestion to start with as little delay as possible on each upload. They want to avoid the latency and wasted run cost of periodic polling, triggering processing in an event-driven way on object creation. Which Google Cloud setup best fits this requirement?","oEn":["Poll the bucket every 5 minutes with Cloud Scheduler to find new files","Periodically re-scan a BigQuery external table","Trigger a DAG hourly on a time schedule in Cloud Composer","Use Eventarc to trigger Cloud Run or Workflows on Cloud Storage object-create events"],"eEn":"To start processing immediately on a single object-create event, Eventarc (using Pub/Sub / Cloud Audit Logs / GCS notifications underneath) is best and can target Cloud Run or Workflows, with no polling and low latency. Cloud Scheduler polling adds latency and cost. Composer time triggers can't react promptly to irregular arrivals. Re-scanning a BigQuery external table is not event-driven."},{"id":"h54","d":"D3","q":"データエンジニアが新しく作成したAirflowのDAGは、start_dateが90日前に設定され、日次でスケジュールされている。本番環境へデプロイした直後、Airflowが過去90日分の実行を一斉にスケジュールしてしまい、ワーカーが飽和して環境全体が過負荷に陥った。今後はこのような一括の過去実行を防ぎつつ、必要になったときだけ特定の期間を明示的に選んで再実行できるようにしたい。この状況への対応として最も適切なものはどれか。","o":["schedule_interval を None にしてスケジュール実行を完全にやめる","start_date を毎回当日に手動で書き換える","DAGの catchup を False に設定し、必要時に対象期間を指定してバックフィルを実行する","max_active_runs を無制限にして一気に処理を終わらせる"],"a":2,"e":"catchup=False にすると過去分の自動一括実行(キャッチアップ)を防げる。必要な過去期間だけは backfill コマンドで明示的に実行できるため要件に合致。start_dateの手動書き換えは運用が煩雑でバックフィル不能。schedule_intervalをNoneにすると定期実行自体が失われる。max_active_runsを無制限にすると過負荷が悪化する。","qEn":"A data engineer's newly created Airflow DAG has start_date set to 90 days ago and is scheduled daily. Immediately after deploying to production, Airflow scheduled all 90 days of past runs at once, saturating the workers and overloading the whole environment. Going forward they want to prevent such bulk historical runs while still being able to explicitly select and re-run specific periods only when needed. What is the most appropriate response to this situation?","oEn":["Set schedule_interval to None to stop scheduled runs entirely","Manually rewrite start_date to today each time","Set the DAG's catchup to False and run backfill for the target period when needed","Set max_active_runs to unlimited to finish everything at once"],"eEn":"Setting catchup=False prevents automatic bulk catch-up of past runs, while backfill can explicitly run only the needed historical period, meeting the requirement. Manually rewriting start_date is cumbersome and prevents backfill. Setting schedule_interval to None loses periodic scheduling entirely. Unlimited max_active_runs worsens the overload."},{"id":"h55","d":"D3","q":"あるDAGのタスクは外部SaaSのREST APIを呼び出してデータを取得するが、相手側の一時的なネットワーク不調やレート制限により時々失敗する。恒久的な障害でなければ、数分後に再試行すればたいてい成功する。運用チームは、こうした一過性の失敗を人手の介入なしに自動で吸収しつつ、恒久的な障害についてはリトライ上限を超えた時点で確実にアラートを受け取りたい。Airflowでの設定として最も適切なものはどれか。","o":["DAG全体を1分ごとに再スケジュールして毎回最初からやり直す","失敗したタスクを try/except で握りつぶし常に成功として扱う","タスクに retries と retry_delay(指数バックオフ)を設定し、上限超過でアラートする","タスクのタイムアウトを無限にして成功するまで待つ"],"a":2,"e":"一時障害はタスクレベルの retries と retry_delay(指数バックオフ推奨)で自動的に吸収でき、リトライ上限を超えたら失敗として通知・アラートできる。これが要件に最適。例外を握りつぶすと恒久障害が検知できず、プロジェクト規約にも反する。DAG全体の再実行は非効率で成功済みタスクも巻き戻す。タイムアウト無限は障害時にリソースを占有し続ける。","qEn":"A DAG task calls an external SaaS REST API to fetch data but occasionally fails due to the other side's transient network issues or rate limiting. If it is not a permanent failure, retrying a few minutes later usually succeeds. The ops team wants to automatically absorb such transient failures without human intervention, while reliably receiving an alert for permanent failures once the retry limit is exceeded. Which Airflow setting is most appropriate?","oEn":["Reschedule the whole DAG every minute and restart from the beginning each time","Swallow failed tasks with try/except and always treat them as success","Set retries and retry_delay (exponential backoff) on the task, and alert when the limit is exceeded","Set the task timeout to infinite and wait until it succeeds"],"eEn":"Transient failures are absorbed automatically via task-level retries and retry_delay (exponential backoff recommended), and once retries are exhausted the task fails and can alert, meeting the requirement. Swallowing exceptions hides permanent failures and violates project conventions. Re-running the whole DAG is inefficient and rolls back completed tasks. Infinite timeout holds resources during failures."},{"id":"h56","d":"D3","q":"あるデータエンジニアは、パラメータ化されたDataflowのバッチジョブをFlexテンプレートとして用意しており、これを毎晩決まった時刻に自動実行したい。実行のたびに入力データのGCSパスと出力先を動的に変えて渡す必要がある。この定期実行のためだけにCloud Composerのような常時稼働の基盤を新設して維持するのはコスト面で避けたい。最小の追加コストで定期起動を実現する組み合わせとして最も適切なものはどれか。","o":["BigQueryスケジュールクエリからDataflowを呼び出す","Compute EngineのcronでローカルのDataflow SDKを毎晩起動する","Cloud SchedulerからDataflow Flexテンプレートを起動し、実行ごとにパラメータを渡す","Cloud Composerを常時起動してテンプレートを起動するためだけに使う"],"a":2,"e":"Dataflow Flexテンプレートは、Cloud Scheduler(HTTP/APIターゲット)から起動時パラメータを渡して定期実行でき、常時稼働の基盤が不要でコスト効率が良い。Compute EngineのcronはVM管理が発生し可用性・運用負荷が高い。BigQueryスケジュールクエリはSQL用でDataflow起動に不適。Composerを起動目的だけで常時稼働させるのは過剰コスト。","qEn":"A data engineer has a parameterized Dataflow batch job packaged as a Flex Template and wants to run it automatically at a fixed time every night, passing a dynamically varying input GCS path and output destination per run. For cost reasons they want to avoid standing up and maintaining always-on orchestration infrastructure like Cloud Composer just for this scheduling. Which combination best achieves scheduled launching with the least added cost?","oEn":["Call Dataflow from a BigQuery scheduled query","Run the local Dataflow SDK nightly via cron on a Compute Engine VM","Launch the Dataflow Flex Template from Cloud Scheduler, passing parameters per run","Keep Cloud Composer always on solely to launch the template"],"eEn":"A Dataflow Flex Template can be launched on a schedule from Cloud Scheduler (HTTP/API target) with per-run parameters, needing no always-on infrastructure and being cost-efficient. Compute Engine cron adds VM management and operational burden. BigQuery scheduled queries are for SQL, not launching Dataflow. Keeping Composer always on just to launch is unnecessary cost."},{"id":"h57","d":"D3","q":"あるDAGは、社内の別チームが管理する外部のDAGが特定パーティションのデータ生成を完了してから、はじめて後続の集計処理を実行できる。外部処理の完了時刻は日によって大きく変動し、固定の時刻を前提にはできない。データエンジニアは、外部処理の完了状態をポーリングで待機し、完了を検知した時点で自動的に後続タスクへ処理を進める仕組みを実装したい。Airflowで最も適切な仕組みはどれか。","o":["固定の sleep で外部処理が終わるであろう時間だけ待つ","schedule_interval を極端に遅い時刻にして衝突を避ける","毎回タスクを失敗させてリトライで偶然成功するのを待つ","Sensor(例: 外部タスク/オブジェクトの存在を待つセンサー)で完了を検知してから後続を実行する"],"a":3,"e":"外部の完了を待って後続を進めるには、条件成立まで待機するSensor(ExternalTaskSensorやGCSObjectExistenceSensorなど)が最適で、完了時刻の変動にも柔軟に対応できる。固定sleepは変動に対応できず脆い。失敗リトライ頼みは不確実で無駄が多い。scheduleを遅らせるのは根本的な依存解決にならない。","qEn":"A DAG can run its downstream aggregation only after an external DAG owned by another team finishes producing data for a specific partition. The external completion time varies greatly day to day, so a fixed time cannot be assumed. The engineer wants to implement a mechanism that polls and waits for the external completion state and automatically advances to downstream tasks once completion is detected. Which Airflow mechanism is most appropriate?","oEn":["Wait a fixed sleep for however long the external process usually takes","Set schedule_interval to a very late time to avoid collisions","Fail the task each time and hope a retry happens to succeed","Use a Sensor (e.g., waiting for an external task/object to exist) to detect completion, then run downstream"],"eEn":"To wait for external completion before proceeding, a Sensor (e.g., ExternalTaskSensor or GCSObjectExistenceSensor) that waits until a condition holds is ideal and adapts to varying completion times. A fixed sleep is brittle. Relying on failure retries is unreliable and wasteful. Delaying the schedule does not truly resolve the dependency."},{"id":"h58","d":"D3","q":"あるセキュリティ運用チームは、Cloud Audit Logsに『特定の機密性の高いBigQueryデータセットに対するテーブル削除操作』が記録された瞬間に、直ちに調査・通知パイプラインを起動したい。定期的にログをスキャンする方式では検知が遅れるため避けたく、監査ログの特定イベントを条件にサーバーレスなターゲット(Cloud RunやWorkflows)を即時に起動できるマネージドな仕組みを求めている。最も適切な手段はどれか。","o":["Cloud Loggingのログをエクスポートしたバケットを毎時スキャンする","BigQueryのINFORMATION_SCHEMAをComposerで毎晩集計する","Cloud Schedulerで定期的に監査ログをクエリして差分を探す","EventarcでCloud Audit LogsのイベントをフィルタしCloud Run/Workflowsを起動する"],"a":3,"e":"Cloud Audit Logsの特定イベントを条件にサーバーレスターゲットを即時起動するにはEventarcが最適で、メソッド名やリソースでフィルタしCloud RunやWorkflowsを起動できる。ログをエクスポートして毎時スキャンやスケジュールクエリでは遅延が大きくイベント駆動でない。ComposerでのINFORMATION_SCHEMA集計はリアルタイム性がない。","qEn":"A security operations team wants to immediately trigger an investigation and notification pipeline the moment Cloud Audit Logs record a 'table deletion on a specific highly sensitive BigQuery dataset.' They want to avoid periodic log scanning because it delays detection, and instead seek a managed mechanism that can immediately trigger a serverless target (Cloud Run or Workflows) conditioned on a specific audit log event. Which is the most appropriate means?","oEn":["Scan a bucket exporting Cloud Logging logs every hour","Aggregate BigQuery INFORMATION_SCHEMA nightly via Composer","Periodically query audit logs with Cloud Scheduler to find diffs","Use Eventarc to filter Cloud Audit Logs events and trigger Cloud Run/Workflows"],"eEn":"To trigger a serverless target immediately on a specific Cloud Audit Logs event, Eventarc is best, filtering by method name/resource to invoke Cloud Run or Workflows. Exporting logs and hourly scanning or scheduled queries add latency and aren't event-driven. Aggregating INFORMATION_SCHEMA via Composer is not real-time."},{"id":"h59","d":"D3","q":"あるCloud Composer環境には、上流の取り込みDAGと下流の日次集計DAGがある。下流のDAGは、上流のDAGが当日分のデータ取り込みを正常に完了したときにだけ実行されるべきだが、上流の完了時刻は日によって変動する。データエンジニアは、単なる時刻オフセットではなく、データの準備が完了したという事実を基準にして、DAG間の依存を疎結合に表現したい。現代的なAirflowで推奨されるアプローチとして最も適切なものはどれか。","o":["下流DAGのschedule_intervalを上流より少し遅らせて時間で暗黙依存させる","下流DAGを手動トリガーのみにして自動実行をやめる","2つのDAGを1つに統合して全部を毎回実行する","AirflowのDataset(データ更新)による依存、または上流完了を待つセンサーで明示的に連携する"],"a":3,"e":"データ準備完了を基準にDAG間を連携する現代的な方法は、Airflowのデータセット(Dataset)駆動スケジューリングや、上流完了を待つExternalTaskSensorで明示的に依存を表現することである。時間差での暗黙依存は完了時刻の変動に弱く不整合を招く。1つに統合すると再利用性・独立運用が損なわれる。手動トリガー化は自動化要件を満たさない。","qEn":"A Cloud Composer environment has an upstream ingestion DAG and a downstream daily-aggregation DAG. The downstream DAG should run only when the upstream DAG has successfully completed today's ingestion, but the upstream completion time varies from day to day. The engineer wants to express the inter-DAG dependency loosely based on the fact that the data is ready, rather than on a mere time offset. Which modern Airflow approach is most appropriate?","oEn":["Set the downstream schedule_interval slightly later than upstream to imply a time-based dependency","Make the downstream DAG manual-trigger only and stop auto-running","Merge the two DAGs into one and run everything each time","Use Airflow Datasets (data updates) or a sensor waiting on upstream completion to link them explicitly"],"eEn":"The modern way to link DAGs on data readiness is Airflow Dataset-driven scheduling or an ExternalTaskSensor waiting for upstream completion, expressing the dependency explicitly. Time-offset implicit dependency is fragile to varying completion times and risks inconsistency. Merging into one DAG loses reusability/independent operation. Manual-only triggering fails the automation requirement."},{"id":"h60","d":"D3","q":"あるビジネスアナリストは、BigQuery上のあるレポート用テーブルを、毎朝6時に集計クエリで洗い替え更新するだけの単純な定期処理を実現したい。処理は単一のSQLで完結し、他タスクへの依存関係もなく、外部システムのAPI呼び出しも一切必要ない。専任のエンジニアはおらず、Cloud Composerのような追加基盤を新たに構築・運用することは避けたい。最小コスト・最小構成でこの定期実行を実現する方法として、最も適切なものはどれか。","o":["Cloud Composerを新設してDAGにクエリを1つ書く","Dataflowテンプレートで集計を実装して定時起動する","Workflowsで1ステップのフローを作りCloud Schedulerで起動する","BigQueryのスケジュールクエリで毎朝6時に実行するよう設定する"],"a":3,"e":"依存も外部呼び出しもない単一クエリの定期実行は、BigQueryネイティブのスケジュールクエリで完結し、追加基盤ゼロ・最小コストで実現できる。Composerは環境コストが高く単一クエリには過剰。Workflows+Schedulerは可能だがBigQuery内で完結する方が簡潔。Dataflowは分散処理用でSQL集計には過剰。","qEn":"A business analyst wants a simple recurring job that just refreshes a BigQuery reporting table with an aggregation query every morning at 6 AM. The job is completed by a single SQL statement, has no dependencies on other tasks, and requires no external system API calls at all. There is no dedicated engineer, and they want to avoid building and operating additional infrastructure like Cloud Composer. Which approach best achieves this scheduled run with minimal cost and setup?","oEn":["Stand up Cloud Composer and write a single query in a DAG","Implement the aggregation as a Dataflow template on a schedule","Create a one-step Workflows flow triggered by Cloud Scheduler","Configure a BigQuery scheduled query to run daily at 6 AM"],"eEn":"A single query on a schedule with no dependencies or external calls is fully handled by a BigQuery-native scheduled query, with zero extra infrastructure and minimal cost. Composer has environment cost and is overkill for one query. Workflows+Scheduler works but staying inside BigQuery is simpler. Dataflow is for distributed processing, overkill for a SQL aggregation."},{"id":"h61","d":"D3","q":"あるチームは、複数の外部APIを順番に呼び出す処理をWorkflowsで実装している。途中のあるAPI呼び出しが、相手側の一時的な過負荷により時々HTTP 503を返す。恒久的な障害ではないため、少し待ってから再試行すればたいてい成功する。チームは、ワークフロー全体を最初からやり直すことなく、失敗したそのステップだけを安全に自動再試行して処理を継続させたい。Workflowsでの実装として最も適切なものはどれか。","o":["失敗時にワークフローを最初から全部やり直す","エラーを無視して次のステップへ常に進む","ステップに retry ポリシー(バックオフと再試行対象条件)を定義する","Cloud Schedulerでワークフロー全体を数分おきに多重起動する"],"a":2,"e":"Workflowsはステップ単位で retry ポリシー(バックオフ、再試行対象のエラーコード指定)を定義でき、一時的な503のみを安全に再試行してワークフロー全体を止めない。エラー無視はデータ不整合を招く。全体やり直しは非効率で副作用の恐れ。多重起動は重複実行や競合を起こす。","qEn":"A team implements a process that calls several external APIs in sequence using Workflows. One mid-flow API call sometimes returns HTTP 503 due to the other side's transient overload. Since it is not a permanent failure, retrying after a short wait usually succeeds. The team wants to safely auto-retry only that failed step and continue processing, without restarting the entire workflow from the beginning. Which Workflows implementation is most appropriate?","oEn":["Restart the entire workflow from the beginning on failure","Ignore the error and always proceed to the next step","Define a retry policy (backoff and which errors to retry) on the step","Multi-trigger the whole workflow every few minutes via Cloud Scheduler"],"eEn":"Workflows lets you define a per-step retry policy (backoff, which error codes to retry), safely retrying only transient 503s without stopping the whole workflow. Ignoring errors risks data inconsistency. Restarting the whole flow is inefficient and risks side effects. Multi-triggering causes duplicate runs and contention."},{"id":"h62","d":"D3","q":"あるECサイトは、Pub/Subに届く注文確定イベントをリアルタイムに処理し、集計テーブルを継続的に更新したい。イベントは平常時でも秒間数千件に達し、セール時にはさらに大きなスパイクが発生する。処理は負荷に応じて自動的にスケールし、重複や欠損を極力抑えてBigQueryへ書き込まれる必要がある。この常時稼働のストリーミング取り込みパイプラインとして、最も適したGoogle Cloudの構成はどれか。","o":["Cloud Schedulerで5分ごとにPub/Subをまとめて読み出すバッチ処理","Workflowsで無限ループを回してメッセージを1件ずつ処理する","Composerで毎分DAGを起動してPub/Subをドレインする","DataflowのストリーミングパイプラインでPub/Subを購読しBigQueryへ書き込む"],"a":3,"e":"秒間数千件・スパイクありのストリーミングをスケーラブルに処理しBigQueryへ書き込むにはDataflow(Apache Beam)のストリーミングが最適で、オートスケールと厳密な処理保証を備える。Schedulerの5分バッチはリアルタイム性がない。Composerの毎分DAGはオーバーヘッドが大きくスパイクに弱い。Workflowsの逐次処理は高スループット処理に不向き。","qEn":"An e-commerce site wants to process order-confirmation events arriving in Pub/Sub in real time and continuously update aggregation tables. Events reach thousands per second even under normal load and spike much higher during sales. Processing must scale automatically with load and write to BigQuery while minimizing duplicates and loss. Which Google Cloud setup best fits this always-on streaming ingestion pipeline?","oEn":["A batch that reads Pub/Sub in bulk every 5 minutes via Cloud Scheduler","Run an infinite loop in Workflows processing messages one by one","Trigger a DAG every minute in Composer to drain Pub/Sub","A Dataflow streaming pipeline that subscribes to Pub/Sub and writes to BigQuery"],"eEn":"For scalable streaming of thousands/sec with spikes writing to BigQuery, Dataflow (Apache Beam) streaming is best, with autoscaling and strong processing guarantees. A 5-minute Scheduler batch isn't real-time. A per-minute Composer DAG has high overhead and handles spikes poorly. Sequential Workflows processing isn't suited to high throughput."},{"id":"h63","d":"D3","q":"あるデータチームのCloud Composer環境では、運用するDAGとタスクの数が増え続けた結果、スケジューラとワーカーの処理が逼迫し、タスクがキューに滞留して実行遅延が慢性化している。チームはマネージドサービスの利点を維持したまま、負荷の増減に応じてワーカーの処理能力を柔軟に調整し、安定した実行を取り戻したい。素のAirflowを自前のVMで運用する選択は避けたい。最も適切な対応はどれか。","o":["タスクを減らすためにDAGの半分を削除する","全DAGを1つのVM上の素のAirflowに移して手動管理する","Composer 2(GKE Autopilotベース)を使い、ワーカーのオートスケールやスケジューラ設定を調整する","スケジュール間隔を全て1日1回に統一してタスクを絞る"],"a":2,"e":"Cloud Composer 2はGKE Autopilotベースで、ワーカーのオートスケールや環境サイズ・スケジューラのパラメータ調整により負荷に応じて処理能力を柔軟に拡張でき、マネージドのまま安定運用できる。素のAirflowへの移行は運用負荷を増やす。DAG削除や間引きは要件(処理そのもの)を犠牲にする本末転倒。","qEn":"In a data team's Cloud Composer environment, the ever-growing number of DAGs and tasks has strained the scheduler and workers, causing tasks to back up in the queue and chronic execution delays. The team wants to keep the benefits of a managed service while flexibly adjusting worker capacity with load to restore stable execution, and wants to avoid running plain Airflow on its own VMs. What is the most appropriate action?","oEn":["Delete half the DAGs to reduce task count","Move all DAGs to plain Airflow on a single VM and manage manually","Use Composer 2 (GKE Autopilot-based) and tune worker autoscaling and scheduler settings","Force all schedules to once per day to cut tasks"],"eEn":"Cloud Composer 2 is GKE Autopilot-based and can flexibly scale capacity via worker autoscaling and environment/scheduler tuning, staying managed and stable. Migrating to plain Airflow increases operational burden. Deleting DAGs or throttling sacrifices the actual work and defeats the purpose."},{"id":"h64","d":"D3","q":"あるバッチ取り込みDAGは、リトライやバックフィルによって同じ日付の処理が複数回実行されることがある。現状の実装では同じソースファイルを二重に取り込んでしまい、BigQueryのテーブルに重複行が生じている。データエンジニアは、同一日付が何度実行されても最終結果が壊れず一貫性を保てるように、パイプラインを設計し直したい。この冪等性(idempotency)を確保する設計として、最も適切なものはどれか。","o":["重複が出たら手動でDELETEするのを前提に運用する","毎回テーブル全体を削除して作り直し、履歴は保持しない","取り込み処理を冪等に設計し、パーティション上書き(WRITE_TRUNCATE)やMERGEで重複を防ぐ","リトライを完全に無効化して失敗したら諦める"],"a":2,"e":"リトライ・バックフィルで同一日付が複数回走っても壊れないためには、取り込みを冪等に設計し、対象パーティションのWRITE_TRUNCATE上書きやキーによるMERGEで重複を防ぐのが最適。テーブル全削除は履歴喪失や広範な影響を招く。手動DELETE前提は運用が脆弱でスケールしない。リトライ無効化は一時障害への耐性を失う。","qEn":"A batch ingestion DAG may run the same date multiple times due to retries or backfill. In its current implementation it ingests the same source file twice, producing duplicate rows in a BigQuery table. The engineer wants to redesign the pipeline so the final result stays correct and consistent no matter how many times the same date runs. Which design best ensures this idempotency?","oEn":["Operate on the assumption of manually DELETEing duplicates when they appear","Drop and recreate the whole table each run, keeping no history","Design ingestion to be idempotent, using partition overwrite (WRITE_TRUNCATE) or MERGE to prevent duplicates","Disable retries entirely and give up on failure"],"eEn":"To stay correct under repeated runs from retries/backfill, design ingestion to be idempotent, using WRITE_TRUNCATE overwrite of the target partition or key-based MERGE to prevent duplicates. Dropping the whole table loses history and has broad impact. Relying on manual DELETE is fragile and doesn't scale. Disabling retries loses resilience to transient failures."},{"id":"h65","d":"D3","q":"あるチームは、新しいデータ処理基盤のオーケストレータとして、軽量サーバーレスのWorkflowsと、AirflowベースのフルマネージドなCloud Composerのどちらを採用すべきか検討している。想定される要件は、数百のタスク、複雑な多段依存、豊富な既製Operatorエコシステムの活用、過去分のバックフィル、そして成熟した監視・可視化UIである。これらの要件を踏まえたとき、最も適切な選択とその理由はどれか。","o":["Workflows。ステップが多くても全てYAMLで書けば十分だから","Cloud Scheduler。時刻起動だけで全要件を満たせるから","どちらでも同じなのでコストの安い方を選ぶ","Cloud Composer。複雑な依存・バックフィル・豊富なOperator・監視UIというAirflowの強みに合致するから"],"a":3,"e":"数百タスク・複雑依存・豊富なOperatorエコシステム・バックフィル・成熟した監視UIという要件は、まさにAirflow(Cloud Composer)の強みであり最適。Workflowsは軽量サーバーレス向けで、この規模の依存管理・バックフィル・Operatorエコシステムには不足。Cloud Schedulerは時刻起動のみで依存管理ができない。要件を満たすのはComposer。","qEn":"A team is deciding whether to adopt lightweight serverless Workflows or Airflow-based fully managed Cloud Composer as the orchestrator for a new data processing platform. The expected requirements are hundreds of tasks, complex multi-level dependencies, use of a rich ready-made Operator ecosystem, backfill of past periods, and a mature monitoring and visualization UI. Given these requirements, which is the most appropriate choice and why?","oEn":["Workflows, because even many steps can just be written in YAML","Cloud Scheduler, because time-based triggering alone meets all requirements","Either is the same, so pick whichever is cheaper","Cloud Composer, because complex dependencies, backfill, rich Operators, and monitoring UI match Airflow's strengths"],"eEn":"Hundreds of tasks, complex dependencies, a rich Operator ecosystem, backfill, and a mature monitoring UI are exactly Airflow (Cloud Composer) strengths, making it the best fit. Workflows is for lightweight serverless and falls short on this scale of dependencies/backfill/Operators. Cloud Scheduler only triggers by time with no dependency management. Composer meets the requirements."},{"id":"h66","d":"D4","q":"ある本番プロジェクトで、データ分析者のグループがBigQuery上でクエリを実行して分析業務を行う必要がある。一方でセキュリティ方針上、彼らにテーブルの削除やIAMポリシーの変更といった破壊的・管理的な操作を行う権限は一切与えたくない。最小権限の原則に従い、必要なクエリ実行に足るだけの権限を過不足なく付与したい。このグループへのロール付与として、最も適切なものはどれか。","o":["プロジェクトのOwner基本ロールを付与する","BigQuery Data Viewer と BigQuery Job User の事前定義ロールを付与する","Editor基本ロールを付与する","カスタムロールを作らずroles/ownerを全員に付与する"],"a":1,"e":"クエリ実行にはデータ参照(BigQuery Data Viewer)とジョブ実行権限(BigQuery Job User)の事前定義ロールの組み合わせが最小権限として最適で、削除やIAM変更は含まれない。Owner/Editorの基本ロールは広範すぎて最小権限に反する。ownerを全員に付与するのは重大な過剰付与でセキュリティリスク。","qEn":"In a production project, a group of data analysts needs to run queries in BigQuery for their analysis work. At the same time, per security policy, they must not be granted any destructive or administrative permissions such as deleting tables or changing IAM policies. Following the principle of least privilege, you want to grant exactly the permissions sufficient for running queries and no more. Which role grant to this group is most appropriate?","oEn":["Grant the project Owner basic role","Grant the BigQuery Data Viewer and BigQuery Job User predefined roles","Grant the Editor basic role","Grant roles/owner to everyone instead of creating a custom role"],"eEn":"For running queries, combining the predefined roles BigQuery Data Viewer (read data) and BigQuery Job User (run jobs) is the least-privilege fit and excludes deletion and IAM changes. Owner/Editor basic roles are too broad and violate least privilege. Granting owner to everyone is severe over-provisioning and a security risk."},{"id":"h67","d":"D4","q":"あるセキュリティ監査により、本番プロジェクトにおいて多数のユーザーにEditorやOwnerといった基本ロールが広範に付与されていることが、重大な問題として指摘された。これらの基本ロールは粒度が粗く、各ユーザーの実際の職務に対して過剰な権限を与えてしまっている。セキュリティチームは、最小権限の原則に沿ってこの状態を根本から是正したい。最も適切な是正方針はどれか。","o":["基本ロールを維持しつつパスワードを複雑にする","職務に応じた事前定義ロールやカスタムロールに置き換え、基本ロールの利用を最小化する","全員をViewerに下げて誰も書き込めないようにする","IAMをやめてサービスアカウントキーを共有する"],"a":1,"e":"基本ロール(Owner/Editor/Viewer)は粒度が粗く本番では最小権限に反するため、職務に応じた事前定義ロールや必要なら最小のカスタムロールへ置き換えるのが正しい是正方針。パスワード強化は権限過剰の問題を解決しない。全員Viewerは業務遂行を妨げ極端。キー共有はさらに危険な悪手。","qEn":"A security audit flagged, as a serious issue, that many users in a production project hold broad basic roles such as Editor or Owner. These basic roles are coarse-grained and grant permissions far in excess of each user's actual job. The security team wants to fundamentally remediate this state in line with the principle of least privilege. Which remediation policy is most appropriate?","oEn":["Keep basic roles but require complex passwords","Replace them with job-appropriate predefined or custom roles, minimizing basic role use","Downgrade everyone to Viewer so no one can write","Abandon IAM and share a service account key"],"eEn":"Basic roles (Owner/Editor/Viewer) are coarse-grained and violate least privilege in production, so replacing them with job-appropriate predefined roles or minimal custom roles is the correct remediation. Stronger passwords don't fix over-provisioning. Making everyone Viewer blocks work and is extreme. Sharing keys is an even worse, more dangerous practice."},{"id":"h68","d":"D4","q":"ある金融機関では、コンプライアンス要件により、Cloud StorageとBigQueryに保存するすべての機密データを、自組織が管理・ローテーション・必要時に失効できる暗号鍵で暗号化することが義務付けられている。Googleが管理するデフォルトの暗号鍵では、鍵のライフサイクルを組織が制御できないため監査要件を満たせない。この要件を満たす暗号化方式として、最も適切なものはどれか。","o":["CSEK(顧客が鍵素材を毎リクエスト提供する方式)を全サービスで使う","Cloud KMSで管理するCMEK(顧客管理暗号鍵)を各サービスに設定する","暗号化を無効化してアクセス制御だけで保護する","GMEK(Google管理鍵)のままにして要件は無視する"],"a":1,"e":"組織が鍵をCloud KMSで管理・ローテーション・失効できる要件にはCMEK(顧客管理暗号鍵)が最適で、BigQueryやCloud Storageに設定できる。CSEKは鍵素材を毎回自前で渡す方式でGCSなど限定的、鍵管理の運用負荷が高くBigQueryでは一般的でない。暗号化無効化は不可。GMEK維持では管理要件を満たせない。","qEn":"At a financial institution, compliance requires that all sensitive data stored in Cloud Storage and BigQuery be encrypted with keys the organization itself can manage, rotate, and revoke when necessary. Google-managed default encryption keys do not meet the audit requirement because the organization cannot control the key lifecycle. Which encryption approach best meets this requirement?","oEn":["Use CSEK (customer supplies key material on every request) across all services","Set CMEK (customer-managed encryption keys) managed in Cloud KMS on each service","Disable encryption and protect with access control only","Keep GMEK (Google-managed keys) and ignore the requirement"],"eEn":"For an organization to manage, rotate, and revoke keys via Cloud KMS, CMEK (customer-managed encryption keys) is best and can be set on BigQuery and Cloud Storage. CSEK requires supplying key material each request, is limited (e.g., GCS), operationally heavy, and uncommon for BigQuery. Disabling encryption is not allowed. Keeping GMEK doesn't meet the management requirement."},{"id":"h69","d":"D4","q":"ある大企業のデータ統括チームは、社内のデータレイクに散在するBigQueryのデータセットやCloud Storage上のファイルなど、多数のデータ資産を横断的に発見・分類し、統一的にガバナンスしたい。加えて、メタデータの一元管理、データ品質の評価、そしてデータの系統(リネージ)の追跡も、同じ基盤上で実現したい。この用途に最も適したGoogle Cloudのサービスはどれか。","o":["Compute Engineに自作のカタログアプリを構築する","Cloud Schedulerでメタデータを毎晩CSVに書き出す","Dataplex(データガバナンス・カタログ/メタデータ・品質・系統)を用いる","Cloud Monitoringのダッシュボードでデータ資産を管理する"],"a":2,"e":"BigQueryやCloud Storageを横断したデータ資産の発見・分類・ガバナンス、メタデータ・品質・系統の一元管理にはDataplex(データカタログ機能を含む)が最適。Cloud SchedulerのCSV書き出しは検索・ガバナンス機能を持たない。自作アプリは運用負荷が高く車輪の再発明。Cloud Monitoringはシステム監視用でデータガバナンスの用途ではない。","qEn":"A large enterprise's data governance team wants to discover, classify, and uniformly govern a large number of data assets scattered across the data lake, including BigQuery datasets and Cloud Storage files. In addition, they want centralized metadata management, data quality assessment, and data lineage tracking on the same platform. Which Google Cloud service best fits this purpose?","oEn":["Build a custom catalog app on Compute Engine","Export metadata to CSV nightly via Cloud Scheduler","Use Dataplex (data governance/catalog, metadata, quality, lineage)","Manage data assets with a Cloud Monitoring dashboard"],"eEn":"For cross-service discovery, classification, and governance of data assets across BigQuery and Cloud Storage with centralized metadata, quality, and lineage, Dataplex (including catalog capabilities) is best. Scheduler CSV export lacks search/governance. A custom app is high-effort reinvention. Cloud Monitoring is for system monitoring, not data governance."},{"id":"h70","d":"D4","q":"あるチームは大量のログデータをCloud Storageに保存している。データは書き込みから直近30日間は分析のため頻繁にアクセスされるが、それを過ぎるとアクセスは激減し、さらに90日を超えると年に数回の監査目的で参照されるだけになる。データ自体は長期保管が必要である。ストレージコストを自動的に最適化する、ライフサイクル管理とストレージクラスの設計として、最も適切なものはどれか。","o":["全期間Standardのまま保持する","オブジェクトライフサイクル管理で30日後Nearline、90日後Coldlineへ自動移行する","初日からArchiveに置き頻繁アクセス時も毎回取り出す","30日後に全部削除して監査要件を無視する"],"a":1,"e":"アクセス頻度の変化に応じ、オブジェクトライフサイクル管理で30日後Nearline(月1回程度)、90日後Coldline(四半期〜年数回)へ自動移行するのがコスト最適。全期間Standardは割高。初日からArchiveは頻繁アクセス時の取り出しコストが高い。30日で全削除は監査要件に反する。","qEn":"A team stores large volumes of log data in Cloud Storage. The data is accessed frequently for analysis during the first 30 days after write, but access drops sharply afterward, and beyond 90 days it is only referenced a few times a year for audits. The data itself must be retained long term. Which lifecycle management and storage class design best automatically optimizes storage cost?","oEn":["Keep everything in Standard the whole time","Use Object Lifecycle Management to auto-transition to Nearline after 30 days and Coldline after 90 days","Put it in Archive from day one and retrieve on every frequent access","Delete everything after 30 days, ignoring the audit requirement"],"eEn":"Matching access frequency, Object Lifecycle Management auto-transitioning to Nearline after 30 days (~monthly) and Coldline after 90 days (quarterly to a few times a year) is most cost-optimal. All-Standard is expensive. Archive from day one has high retrieval cost during frequent access. Deleting at 30 days violates the audit requirement."},{"id":"h71","d":"D4","q":"ある企業は、法規制により特定のデータセットを7年間にわたって保持する義務がある。このデータは保持期間中、監査のために年に1回程度アクセスされる可能性がある以外はほとんど参照されず、7年経過後には削除する予定である。取り出し頻度は極めて低いため、単位ストレージあたりの保管コストが最も安いクラスを選びたい。この長期・超低頻度アクセスの要件に、最も適したストレージクラスはどれか。","o":["Standard","Nearline","Coldline","Archive"],"a":3,"e":"7年という超長期・年1回未満の超低頻度アクセスにはArchiveクラスが最適で、保存単価が最も安い(取り出しコストと最低保存期間は長い)。Standardは頻繁アクセス向けで割高。Nearlineは月1回程度、Coldlineは四半期〜年数回程度が目安で、Archiveほど長期保管の単価が安くない。要件にはArchiveが最良。","qEn":"A company is legally required to retain a specific dataset for 7 years. During the retention period the data is rarely referenced, apart from possibly being accessed about once a year for audits, and it will be deleted after 7 years. Because retrieval frequency is extremely low, they want the class with the lowest per-unit storage cost. Which storage class best fits this long-term, ultra-low-frequency access requirement?","oEn":["Standard","Nearline","Coldline","Archive"],"eEn":"For 7-year, less-than-annual ultra-low-frequency access, the Archive class is best with the lowest storage price (retrieval cost and minimum storage duration are higher/longer). Standard is for frequent access and pricey. Nearline (~monthly) and Coldline (quarterly to a few times a year) don't match this longevity as cheaply as Archive. Archive is the best fit."},{"id":"h72","d":"D4","q":"あるBigQuery環境で、機密性の高い営業実績を含むデータセットは営業チームのメンバーだけが参照でき、全社共通のマスタデータを含む別のデータセットは全従業員が参照できるようにしたい。テーブルごとに個別に設定するのは運用負荷が高いため避け、データセットという単位でアクセス権をまとめて制御し、対象となるグループに適切な参照権限を付与したい。最も適切な方法はどれか。","o":["各テーブルをCSVでエクスポートしメールで配布する","データセットのアクセス制御(データセットレベルのIAM/共有設定)で対象グループに適切なロールを付与する","プロジェクトのOwnerを全社員に付与する","BigQueryを使わずスプレッドシートに移す"],"a":1,"e":"BigQueryはデータセット単位でアクセス制御ができ、対象グループにデータセットレベルの適切なロール(例: Data Viewer)を付与するのが最適。CSV配布は制御不能で漏洩リスク。全社にOwner付与は最小権限に反し危険。スプレッドシート移行は分析基盤を捨てる不適切な対応。","qEn":"In a BigQuery environment, a dataset containing sensitive sales performance should be readable only by members of the sales team, while another dataset containing company-wide master data should be readable by all employees. Rather than configuring each table individually, you want to control access at the dataset unit and grant appropriate read permissions to the target groups. Which is the most appropriate method?","oEn":["Export each table to CSV and distribute by email","Use dataset access controls (dataset-level IAM/sharing) to grant appropriate roles to the target groups","Grant project Owner to all employees","Move off BigQuery to spreadsheets"],"eEn":"BigQuery supports dataset-level access control; granting appropriate dataset-level roles (e.g., Data Viewer) to the target groups is best. CSV distribution is uncontrolled and leaky. Granting Owner company-wide violates least privilege and is dangerous. Moving to spreadsheets abandons the analytics platform inappropriately."},{"id":"h73","d":"D4","q":"あるデータ基盤で、分析チームには元テーブルに含まれる全カラムを見せたくなく、集計済み・マスク済みに加工した結果だけを別のデータセット経由で参照させたい。同時に、彼らに元テーブルそのものへの直接的な参照権限を与えることは避けたい。加工ロジックは単一のクエリで表現でき、参照時には常に最新の元データを反映させたい。BigQueryでこれを実現する最適な実装はどれか。","o":["認可済みビュー(Authorized View)を別データセットに作り、元データへの直接権限は与えない","元テーブルにViewerを付与し、見ないよう口頭で依頼する","元データをコピーして手作業でカラムを削る","全員にプロジェクトEditorを付与する"],"a":0,"e":"元データへの直接権限を与えずに加工結果だけを参照させるには、別データセットの認可済みビュー(Authorized View)が最適で、ビュー経由でのみ元データにアクセスできる。元テーブルへのViewer付与は全カラムが見えてしまう。手作業コピーは保守困難で最新性を欠く。Editor付与は過剰権限で危険。","qEn":"In a data platform, you do not want the analytics team to see all columns in a source table—only results processed into aggregated and masked form, exposed through a separate dataset. At the same time, you want to avoid giving them direct read access to the source table itself. The processing logic can be expressed in a single query and must always reflect the latest source data. What is the best BigQuery implementation for this?","oEn":["Create an Authorized View in a separate dataset and grant no direct access to the source data","Grant Viewer on the source table and verbally ask them not to look","Copy the source and manually strip columns","Grant everyone project Editor"],"eEn":"To expose only processed results without direct source access, an Authorized View in a separate dataset is best—it can read the source only through the view. Granting Viewer on the source exposes all columns. A manual copy is hard to maintain and stale. Granting Editor is excessive and dangerous."},{"id":"h74","d":"D4","q":"あるBigQueryのテーブルには従業員の『給与』という機密カラムが含まれている。人事チームはこのカラムを参照できてよいが、一般アナリストには給与カラムだけを見せず、同じテーブルの他のカラムはこれまでどおり参照させたい。テーブルを分割したりデータを加工したりすることなく、特定のカラム単位できめ細かくアクセスを制御したい。この要件に最も適したBigQueryの仕組みはどれか。","o":["テーブルを2つに分割して手動で同期する","ポリシータグ(Data Catalog/Dataplexの分類)による列レベルのアクセス制御を設定する","給与カラムをNULLで上書きして元データを失う","給与カラムを含むデータセット全体を非公開にする"],"a":1,"e":"特定カラムだけをアクセス制御するにはポリシータグ(Data Catalog/Dataplexの分類法)を用いた列レベルセキュリティが最適で、タグを付与したカラムへの参照を権限で制御できる。テーブル分割は同期負荷と不整合を招く。NULL上書きは元データ喪失。データセット全体の非公開は他カラムまで見えなくなり要件過剰。","qEn":"A BigQuery table contains a sensitive 'salary' column for employees. The HR team may view this column, but general analysts should not see the salary column while still viewing the table's other columns as before. Without splitting the table or transforming the data, you want fine-grained access control at the specific column level. Which BigQuery mechanism best fits this requirement?","oEn":["Split the table into two and sync manually","Set column-level access control using policy tags (Data Catalog/Dataplex taxonomy)","Overwrite the salary column with NULL, losing the source data","Make the entire dataset containing salary private"],"eEn":"To control a specific column, column-level security using policy tags (Data Catalog/Dataplex taxonomy) is best, gating access to tagged columns by permission. Splitting tables adds sync burden and inconsistency. NULL overwrite loses source data. Making the whole dataset private hides other columns too and overshoots the requirement."},{"id":"h75","d":"D4","q":"ある企業の顧客データには、クレジットカード番号やメールアドレス、電話番号といった機密性の高い個人情報が、多数のフィールドに混在している。このデータを分析用データセットへコピーして活用する前に、こうした機密情報を自動的にスキャンして検出し、マスキングやトークン化によって匿名化(de-identify)しておきたい。この用途に最も適したGoogle Cloudのサービスはどれか。","o":["Cloud DLP(Sensitive Data Protection)で機密データを検査し、de-identify(マスキング/トークン化)する","BigQueryのSELECTで目視して手動置換する","Cloud Monitoringでカード番号を検知する","そのままコピーしてアクセス制御だけに頼る"],"a":0,"e":"クレジットカード番号やメールなどの機密検出とマスキング/トークン化にはCloud DLP(Sensitive Data Protection)が最適で、infoType検査とde-identify変換を提供する。目視・手動置換はスケールせず漏れる。Cloud Monitoringはシステム監視用で機密検出機能はない。無加工コピーは機密拡散のリスクが高い。","qEn":"A company's customer data mixes highly sensitive personal information—credit card numbers, email addresses, and phone numbers—across a large number of fields. Before copying this data to an analytics dataset for use, they want to automatically scan and detect such sensitive information and anonymize (de-identify) it through masking or tokenization. Which Google Cloud service best fits this purpose?","oEn":["Use Cloud DLP (Sensitive Data Protection) to inspect sensitive data and de-identify (mask/tokenize)","Eyeball it via a BigQuery SELECT and replace manually","Detect card numbers with Cloud Monitoring","Copy as-is and rely on access control only"],"eEn":"For detecting sensitive data like card numbers/emails and masking/tokenizing, Cloud DLP (Sensitive Data Protection) is best, offering infoType inspection and de-identify transforms. Manual review doesn't scale and misses data. Cloud Monitoring is for system monitoring, not sensitive-data detection. Copying as-is risks spreading sensitive data."},{"id":"h76","d":"D4","q":"あるデータ処理パイプラインは専用のサービスアカウントで実行されている。このサービスアカウントに必要な操作は、入力用の特定のCloud Storageバケットからの読み取りと、出力先である特定のBigQueryデータセットへの書き込みだけである。セキュリティチームは最小権限の原則を徹底し、万一この資格情報が漏洩しても影響範囲を限定したい。このサービスアカウントへの権限設計として、最も適切なものはどれか。","o":["SAにプロジェクトのEditorを付与して何でもできるようにする","必要なバケットとデータセットに限定した事前定義ロールを、リソーススコープで付与する","SAキーを複数チームで共有して使い回す","SAにOwnerを付与し将来の変更に備える"],"a":1,"e":"最小権限に従い、必要なバケット(例: Storage Object Viewer)と対象データセット(例: BigQuery Data Editor)に限定した事前定義ロールを、リソース単位のスコープで付与するのが最適。Editor/Ownerの広範付与は最小権限違反。SAキーの共有は資格情報漏洩・追跡不能のリスクで禁忌。将来に備えた過剰付与も不適切。","qEn":"A data processing pipeline runs as a dedicated service account. The only operations this service account needs are reading from a specific input Cloud Storage bucket and writing to a specific output BigQuery dataset. The security team wants to strictly enforce least privilege and limit the blast radius should these credentials ever leak. Which permission design for this service account is most appropriate?","oEn":["Grant the SA project Editor so it can do anything","Grant predefined roles scoped to just the needed bucket and dataset at the resource level","Share the SA key across multiple teams","Grant the SA Owner to prepare for future changes"],"eEn":"Following least privilege, grant predefined roles scoped to the needed bucket (e.g., Storage Object Viewer) and dataset (e.g., BigQuery Data Editor) at the resource level. Broad Editor/Owner grants violate least privilege. Sharing SA keys risks credential leakage and untraceability. Over-provisioning for the future is also inappropriate."},{"id":"h77","d":"D4","q":"ある企業は規制対応のため、Cloud Storageに保存する取引記録を、少なくとも5年間は削除も上書きもできない状態で保持しなければならない。運用担当者による誤操作での削除はもちろん、内部関係者による意図的な改ざんも技術的に防止する必要がある。管理者権限を持つ者であっても、保持期間中はデータを消せないようにしたい。この要件を満たす設定として、最も適切なものはどれか。","o":["バケットに保持ポリシー(Retention Policy)を設定し、必要ならロックして5年間の保持を強制する","オブジェクトのメタデータにコメントで『消さないで』と書く","IAMでdeleteを外すが後でいつでも戻せるようにする","毎日手動でバックアップを取り原本は自由に削除可とする"],"a":0,"e":"一定期間の削除・上書きを強制的に防ぐにはバケットの保持ポリシー(Retention Policy)が最適で、ロックすれば管理者でも短縮・解除できず改ざん・誤削除を防止できる(WORM相当)。メタデータのコメントは何も強制しない。IAMでdeleteを外すだけでは権限変更で戻せてしまう。手動バックアップ+原本削除可では改ざん耐性がない。","qEn":"For regulatory compliance, a company must keep transaction records in Cloud Storage in a state where they cannot be deleted or overwritten for at least 5 years. It must technically prevent not only accidental deletion by operators but also intentional tampering by insiders, so that even someone with administrator privileges cannot erase the data during the retention period. Which setting best meets this requirement?","oEn":["Set a bucket Retention Policy and lock it if needed to enforce 5-year retention","Add a comment 'do not delete' to object metadata","Remove delete via IAM but keep it reversible anytime","Take manual backups daily and allow deleting the originals freely"],"eEn":"To forcibly prevent deletion/overwrite for a period, a bucket Retention Policy is best; locking it prevents even admins from shortening/removing it, blocking tampering and accidental deletion (WORM-like). A metadata comment enforces nothing. Removing delete via IAM alone is reversible by a policy change. Manual backups with deletable originals aren't tamper-resistant."},{"id":"h78","d":"D4","q":"あるチームは、頻繁に更新される重要なBigQueryテーブルについて、誤った更新や削除に備えて特定時点の状態を低コストに保全し、問題が発生した際にはその時点の状態へ迅速に復元できるようにしたい。専用のバックアップ基盤を別途構築・運用するのは避けたく、BigQueryのネイティブ機能で運用負荷を抑えつつ実現したい。この要件に最も適した方法として、最も適切なものはどれか。","o":["テーブルスナップショット(またはタイムトラベルによる復元)を活用する","毎晩テーブルをCSVでエクスポートしてローカルに保管する","テーブルを複製したコピーを手動で大量に作る","バックアップは取らずアクセス制御だけで守る"],"a":0,"e":"BigQueryネイティブのテーブルスナップショットは特定時点の状態を低コストに保全でき、タイムトラベルは既定期間内の過去状態への復元を可能にする。運用負荷が低く要件に最適。CSVエクスポートはスキーマ/型情報の欠落や復元の手間が大きい。手動大量コピーはコスト・管理が煩雑。アクセス制御だけでは誤更新自体からは守れない。","qEn":"A team wants to preserve point-in-time states of a critical, frequently updated BigQuery table cheaply to guard against erroneous updates or deletion, and to be able to restore to that point if a problem occurs. They want to avoid building and operating a separate dedicated backup platform, achieving this with BigQuery native features while keeping operational overhead low. Which method best fits this requirement?","oEn":["Use table snapshots (or time travel restore)","Export the table to CSV nightly and keep locally","Manually create many duplicate copies of the table","Take no backups and rely on access control only"],"eEn":"BigQuery-native table snapshots preserve point-in-time state cheaply, and time travel restores past states within the retention window—low overhead and a great fit. CSV export loses schema/types and is cumbersome to restore. Many manual copies are costly and hard to manage. Access control alone doesn't protect against accidental updates themselves."},{"id":"h79","d":"D4","q":"あるチームは、社外のパートナー企業の担当者に対し、Cloud Storage上にある特定のオブジェクト1つを、24時間だけダウンロードできるように一時的に共有したい。相手はGoogleアカウントを持っておらず、そのためだけにIAMでプリンシパルを追加したり権限を付与したりはしたくない。また、バケット全体を一般公開することも避けたい。この一時的なアクセス提供に、最も適した方法はどれか。","o":["バケットを一般公開(allUsers)にする","期限付きの署名付きURL(Signed URL)を発行して渡す","パートナーにプロジェクトViewerを付与する","オブジェクトをメール添付で送る"],"a":1,"e":"Googleアカウントを持たない相手に一時的なオブジェクトアクセスを与えるには、有効期限付きの署名付きURL(Signed URL)が最適で、IAM付与不要で24時間などの期限も設定できる。バケット公開は無関係な全員に露出し危険。プロジェクトViewer付与は広範かつアカウント前提。メール添付はサイズ・監査・セキュリティ面で不適切。","qEn":"A team wants to temporarily share a single specific object in Cloud Storage with an external partner's staff member so they can download it for only 24 hours. The partner has no Google account, and the team does not want to add a principal or grant permissions via IAM just for this, nor make the entire bucket public. Which method best fits this temporary access provisioning?","oEn":["Make the bucket public (allUsers)","Issue a time-limited Signed URL and share it","Grant the partner project Viewer","Send the object as an email attachment"],"eEn":"To give temporary object access to someone without a Google account, a time-limited Signed URL is best—no IAM grant needed and you can set a 24-hour expiry. Making the bucket public exposes it to everyone and is dangerous. Project Viewer is broad and requires an account. Email attachment is poor for size, audit, and security."},{"id":"h80","d":"D4","q":"ある組織はCMEKを用いてBigQueryとCloud Storageのデータを暗号化しているが、セキュリティ方針により暗号鍵を一定間隔で定期的にローテーションすることが求められている。手作業で新しい鍵を作成して全データを再暗号化するような高コストな運用は避け、鍵の更新をできるだけ自動化して運用負荷を最小化したい。Cloud KMSを用いてこの鍵ローテーション要件を満たす設定として、最も適切なものはどれか。","o":["Cloud KMSで鍵の自動ローテーション期間を設定する","鍵を一切変えずに運用し続ける","毎回手動で新しい鍵を作り全データを再暗号化する","暗号化をGMEKに戻してローテーション要件を無視する"],"a":0,"e":"Cloud KMSは鍵の自動ローテーション期間を設定でき、新しい鍵バージョンを自動生成して以後の暗号化に使うため、運用負荷を抑えつつローテーション要件を満たせる。鍵を変えないのは方針違反。毎回手動作成・全再暗号化は過剰な運用負荷。GMEKに戻すと顧客管理・ローテーション制御の要件を満たせない。","qEn":"An organization encrypts BigQuery and Cloud Storage data using CMEK, but security policy requires rotating the encryption keys periodically at fixed intervals. They want to avoid costly operations such as manually creating new keys and re-encrypting all data, automating key updates as much as possible to minimize operational overhead. Which Cloud KMS setting best meets this key rotation requirement?","oEn":["Configure an automatic rotation period for the key in Cloud KMS","Keep operating without ever changing the key","Manually create a new key each time and re-encrypt all data","Revert to GMEK and ignore the rotation requirement"],"eEn":"Cloud KMS lets you set an automatic rotation period, generating new key versions automatically for subsequent encryption, meeting the requirement with low overhead. Never changing keys violates policy. Manual creation and full re-encryption each time is excessive overhead. Reverting to GMEK fails the customer-managed/rotation-control requirement."},{"id":"h81","d":"D4","q":"あるグローバル企業のBigQueryには、全リージョンの売上を格納した大きなイベントテーブルがある。各地域のアナリストには、自分が担当するリージョンに該当する行だけを参照させ、他リージョンの行は見せたくない。テーブルは1つのまま維持し、リージョンごとに物理的に分割することは避けたい。同一テーブル内で、ユーザー属性に応じて行単位のアクセス制御を適用する、最適なBigQueryの機能はどれか。","o":["リージョンごとにテーブルを分割して権限を分ける","行レベルセキュリティ(Row-Level Security)ポリシーを定義する","各アナリストにテーブル全体のViewerを付与し自己申告に任せる","BigQueryを使わずリージョン別のスプレッドシートを配る"],"a":1,"e":"単一テーブルで行単位のアクセス制御を行うにはBigQueryの行レベルセキュリティ(Row-Level Security)が最適で、ユーザー属性に応じて可視行をフィルタするポリシーを定義できる。テーブル分割は管理・結合の負荷が増える。全体Viewer+自己申告は制御になっていない。スプレッドシート配布は分析基盤を捨て整合性も欠く。","qEn":"A global company's BigQuery has a large event table storing sales for all regions. Each region's analysts should see only the rows corresponding to their assigned region and not rows for other regions. They want to keep it as a single table and avoid physically splitting it by region. Which BigQuery feature best applies row-level access control within the same table based on user attributes?","oEn":["Split the table by region and separate permissions","Define Row-Level Security policies","Grant each analyst Viewer on the whole table and rely on self-restraint","Distribute per-region spreadsheets instead of using BigQuery"],"eEn":"For row-level access control on a single table, BigQuery Row-Level Security is best, defining policies that filter visible rows by user attributes. Splitting tables adds management/join burden. Whole-table Viewer with self-restraint is no control. Spreadsheets abandon the platform and lack consistency."},{"id":"h82","d":"D4","q":"あるチームは、機密データがクライアントとGoogle Cloudのサービスの間でやり取りされる際、その通信経路上で第三者に傍受されないように保護されているかを確認したい。特に、保存時(at-rest)の暗号化とは別に、転送中(in-transit)のデータがどのように守られているのかを正しく理解したい。Google Cloudにおける転送中の暗号化に関する説明として、最も正確なものはどれか。","o":["転送中の暗号化はユーザーが必ず自前で実装しなければならない","Google Cloudのサービス通信はTLSで転送中に暗号化され、保存時の暗号化とは別レイヤで保護される","転送中データは暗号化できず保存時のみ保護される","転送中の暗号化はCSEKを使わないと有効化されない"],"a":1,"e":"Google Cloudではサービスとの通信はTLSにより転送中(in-transit)に暗号化され、保存時(at-rest)の暗号化とは独立したレイヤで保護される。ユーザーが必ず自前実装する必要はない(HTTPS/TLSで保護)。転送中も暗号化される。CSEKは保存時の鍵素材提供の話であり転送中暗号化の前提ではない。","qEn":"A team wants to confirm that when sensitive data is exchanged between a client and Google Cloud services, it is protected from third-party interception on the network path. In particular, apart from at-rest encryption, they want to correctly understand how in-transit data is protected. Which statement about in-transit encryption in Google Cloud is the most accurate?","oEn":["In-transit encryption must always be implemented by the user themselves","Google Cloud service traffic is encrypted in transit via TLS, protected as a separate layer from at-rest encryption","In-transit data cannot be encrypted; only at-rest is protected","In-transit encryption is only enabled if you use CSEK"],"eEn":"In Google Cloud, traffic to services is encrypted in transit via TLS, protected independently from at-rest encryption. Users need not always implement it themselves (HTTPS/TLS protects it). In-transit data is encrypted. CSEK concerns supplying key material for at-rest and is not a prerequisite for in-transit encryption."},{"id":"h83","d":"D4","q":"ある組織のデータガバナンス方針では、各データ資産に対して所有者・機密度・保持期間といったメタデータを付与し、それらをもとに資産を横断的に検索・分類できるようにすることが求められている。さらに、ビジネス部門が使う用語集(ビジネス用語)と技術的なメタデータを結び付け、組織全体で一貫した統制を効かせたい。この要件に最も適したGoogle Cloudの仕組みはどれか。","o":["Dataplex/Data Catalogのメタデータ・タグ・タクソノミーで資産を分類・統制する","各テーブル名に情報を詰め込んで命名規約で管理する","メタデータはスプレッドシートで手管理する","Cloud Loggingのログにメタデータを書き込む"],"a":0,"e":"データ資産へのメタデータ付与・分類・検索、ビジネス用語と技術メタデータの結合による統制にはDataplex(Data Catalog)のタグテンプレート・ポリシータグ/タクソノミーが最適。テーブル名詰め込みは拡張性・検索性に欠ける。スプレッドシート手管理は同期漏れと非統制。Cloud Loggingはメタデータ管理の用途ではない。","qEn":"An organization's data governance policy requires attaching metadata such as owner, sensitivity, and retention period to each data asset so that assets can be searched and classified based on them. It further wants to tie the business glossary used by business units to technical metadata, applying consistent governance across the whole organization. Which Google Cloud mechanism best fits this requirement?","oEn":["Classify and govern assets with Dataplex/Data Catalog metadata, tags, and taxonomies","Cram info into each table name and manage via naming conventions","Manage metadata by hand in a spreadsheet","Write metadata into Cloud Logging logs"],"eEn":"For attaching, classifying, and searching metadata on data assets and tying business glossary to technical metadata for governance, Dataplex (Data Catalog) tag templates and policy tags/taxonomies are best. Cramming into table names lacks extensibility/searchability. A hand-managed spreadsheet drifts and is ungoverned. Cloud Logging isn't for metadata management."},{"id":"h84","d":"D4","q":"あるチームは、BigQueryを操作するサービスアカウントに対し、『クエリの実行はできるが、データセットの作成や削除はできない』という、プロジェクトレベルの特定の権限セットだけを与えたい。既存の事前定義ロールを調べたが、どれも粒度が要件と合わず、余分な権限が含まれてしまう。最小権限を厳密に守るため、必要な権限だけを過不足なく付与したい。このケースで最も適切なアプローチはどれか。","o":["Owner基本ロールを付与し余分な権限は無視する","必要な権限だけを列挙したIAMカスタムロールを作成して付与する","権限管理をやめてSAキーを共有する","Editorを付与して足りない分は都度追加する"],"a":1,"e":"事前定義ロールの粒度が要件に合わず、必要な権限だけを厳密に与えたい特殊ケースでは、必要な権限を列挙したカスタムロールを作成するのが最小権限に最も適う。Owner/Editorは広範すぎて最小権限違反。SAキー共有は資格情報管理の観点で危険。要件に合致するのはカスタムロール。","qEn":"A team wants to give a service account operating BigQuery only a specific project-level permission set: 'can run queries but cannot create or delete datasets.' They examined the existing predefined roles, but none match the required granularity and all include extra permissions. To strictly enforce least privilege, they want to grant exactly the necessary permissions and no more. Which approach is most appropriate in this case?","oEn":["Grant the Owner basic role and ignore the extra permissions","Create and grant an IAM custom role listing only the needed permissions","Stop managing permissions and share the SA key","Grant Editor and add missing permissions as needed"],"eEn":"When predefined role granularity doesn't fit and you want exactly the needed permissions, creating a custom role listing only those permissions best satisfies least privilege. Owner/Editor are too broad and violate least privilege. Sharing SA keys is dangerous for credential management. A custom role is the requirement-fitting choice."},{"id":"h85","d":"D4","q":"ある企業は、極めて機密性の高いデータをBigQueryで扱っており、たとえ正規のユーザーの認証情報が漏洩した場合でも、そのデータが組織のネットワーク境界の外へ持ち出される(exfiltration)リスクを構造的に低減したい。IAMによるアクセス制御だけに頼るのではなく、サービスの境界を定義してAPIレベルでデータの持ち出しを制限する仕組みを追加で導入したい。最も適切なものはどれか。","o":["VPC Service Controlsでサービス境界を設定しデータの外部への持ち出しを制限する","全ユーザーにMFAを課すだけで境界対策は行わない","BigQueryを一般公開して監視だけ強化する","IAMのViewerを剥がして誰も読めなくする"],"a":0,"e":"認証情報漏洩時でもデータの外部持ち出し(exfiltration)を境界で防ぐにはVPC Service Controlsが最適で、サービス境界を定義しAPIレベルで持ち出しを制限できる。MFAは認証強化であって持ち出し境界対策ではない。一般公開は逆効果で危険。Viewer全剥奪は正規業務を止め要件を満たさない。","qEn":"A company handles extremely sensitive data in BigQuery and wants to structurally reduce the risk that the data is exfiltrated beyond the organization's network perimeter even if a legitimate user's credentials leak. Rather than relying solely on IAM access control, they want to additionally introduce a mechanism that defines a service perimeter and restricts data egress at the API level. Which is most appropriate?","oEn":["Use VPC Service Controls to define a service perimeter and restrict data exfiltration","Just require MFA for all users with no perimeter controls","Make BigQuery public and only strengthen monitoring","Strip Viewer via IAM so no one can read"],"eEn":"To block data exfiltration at the perimeter even with leaked credentials, VPC Service Controls is best, defining a service perimeter and restricting egress at the API level. MFA strengthens authentication but isn't an exfiltration perimeter. Making it public is counterproductive and dangerous. Stripping all Viewer halts legitimate work and fails the requirement."},{"id":"h86","d":"D4","q":"あるチームは、特定のIAM権限を常時有効にするのではなく、条件付きで有効範囲を絞りたい。例えば『リソースのタグがproductionである対象だけ』や『特定の業務時間帯だけ』アクセスを許可する、といった制御を実現したい。ロールの付与そのものに条件式を組み込み、宣言的かつ強制力のある形でアクセス範囲を限定したい。この要件に最も適したGoogle CloudのIAMの仕組みはどれか。","o":["IAM Conditions(条件付きロールバインディング)を使う","基本ロールを付与して条件は運用の口約束で守る","権限を毎回手動で付けたり外したりする","Cloud Schedulerでロールを時間帯ごとに付け替えるスクリプトを常時回す"],"a":0,"e":"リソース属性や時間などの条件でロール付与を絞るにはIAM Conditions(条件付きロールバインディング)が最適で、式で有効範囲を制御できる。口約束は強制力がなく統制にならない。手動付け外しはヒューマンエラーとスケール問題。Schedulerでの常時付け替えは脆弱で複雑、IAM Conditionsで宣言的に表現するのが正攻法。","qEn":"A team wants to scope certain IAM permissions conditionally rather than keeping them always active. For example, they want to allow access 'only for resources tagged production' or 'only during certain business hours.' They want to embed a condition expression into the role grant itself, limiting the access scope in a declarative and enforceable way. Which Google Cloud IAM mechanism best fits this requirement?","oEn":["Use IAM Conditions (conditional role bindings)","Grant basic roles and honor conditions by verbal agreement","Manually add/remove permissions every time","Run a script via Cloud Scheduler constantly swapping roles by time of day"],"eEn":"To scope grants by conditions like resource attributes or time, IAM Conditions (conditional role bindings) is best, controlling validity via expressions. Verbal agreements aren't enforceable governance. Manual add/remove is error-prone and unscalable. Constant Scheduler-based swapping is fragile and complex; IAM Conditions expresses it declaratively."},{"id":"h87","d":"D4","q":"あるチームは、比較的短期間で削除・上書きされるデータを、保管コストを抑えるつもりでNearlineストレージクラスに保存していた。ところが、保存から数日後に削除する運用を繰り返した結果、想定していたよりも請求額が大幅に高くなってしまった。Nearline・Coldline・Archiveといったクラスに設定されている『最低保存期間(minimum storage duration)』について、最も正確な理解はどれか。","o":["これらのクラスには最低保存期間があり、期間内に削除/変更しても最低期間分の保存料が課金される","最低保存期間は存在せず、いつ消しても課金は発生しない","最低保存期間はStandardにのみ存在する","最低保存期間を過ぎると取り出しが無料になる"],"a":0,"e":"Nearline(30日)・Coldline(90日)・Archive(365日)などには最低保存期間があり、期間内に削除・上書き・クラス変更しても最低期間分の保存料が課金される。頻繁に短期間で消す用途では割高になるため、アクセス/保持特性に合ったクラス選択が重要。最低保存期間がない、Standardのみに存在、過ぎると取り出し無料、はいずれも誤り。","qEn":"A team stored data that is deleted or overwritten within a relatively short period in the Nearline storage class, intending to reduce storage cost. However, repeatedly deleting data a few days after storage resulted in a bill significantly higher than expected. Which is the most accurate understanding of the 'minimum storage duration' set for classes such as Nearline, Coldline, and Archive?","oEn":["These classes have a minimum storage duration; deleting/changing within it still incurs storage charges for the minimum period","There is no minimum storage duration; deleting anytime incurs no charge","Minimum storage duration exists only for Standard","After the minimum duration, retrieval becomes free"],"eEn":"Nearline (30 days), Coldline (90 days), and Archive (365 days) have minimum storage durations; deleting, overwriting, or changing class within the period still charges storage for the minimum period. For frequent short-lived deletion this is costly, so pick a class matching access/retention. Claims of no minimum, Standard-only, or free retrieval after the period are all wrong."}]).map(shuffleChoices);
const BANK_BY_ID = Object.fromEntries([...BANK, ...ADP_HARD].map(q => [q.id, q]));
const EXAM_SETS = buildExamSets(ADP_HARD);
const DOMAIN_SETS = Object.fromEntries(DOMAINS.map(d => [d.id, ADP_HARD.filter(q => q.d === d.id)]));
const SET_READY = { 1:true, 2:true, 3:true, 4:true, 5:true };

