async function loadJSON(key) { try { const r = await window.storage.get(key); return r ? JSON.parse(r.value) : null; } catch { return null; } }
async function saveJSON(key, v) { try { await window.storage.set(key, JSON.stringify(v)); } catch {} }
function todayStr() { return new Date().toISOString().slice(0, 10); }
function domName(id, lang) { return lang === "en" ? DOM_NAME_EN[id] : DOM_NAME[id]; }

const ADP_EXAM_CASES = [{"id":"adp-1","title":{"ja":"ケース：オンプレDWHからBigQueryへの移行と分析基盤構築","en":"Case: Migrating an On-Premises DWH to BigQuery and Building an Analytics Platform"},"body":{"ja":["小売チェーン「MidoriMart」は、10年以上運用してきたオンプレミスの列指向DWH（約40TB）を Google Cloud へ移行する。夜間バッチのETLが年々長時間化し、繁忙期には翌朝までにレポートが揃わない。経営層はコスト予測性と、店舗別・商品別の対話的分析を求めており、データ基盤チームは BigQuery を中核に据えた設計を任された。","移行対象は、日次で確定する売上明細（1日あたり約2億行）、マスタ系（店舗・商品・顧客）、および POS からのログである。売上明細テーブルは過去5年分を保持し、分析クエリのほぼ全てが特定日付範囲かつ特定店舗に絞り込む。アナリストは主に BI ツールから直近90日を繰り返し照会するが、監査目的で全期間スキャンが月数回発生する。","初期移行では、オンプレの抽出ファイル（Avro/CSV）を Cloud Storage に集約し、そこから BigQuery へロードする方針とした。継続的なCDC（変更データキャプチャ）については、ソースが Oracle であるため専用サービスの利用を検討している。ネットワークは専用線が敷設済みで、初回の一括転送は数十TB規模になる。","コスト面では、財務部門が『月次予算を超過しない予測可能な課金』を強く要望する一方、アナリストは『探索的クエリを制限されたくない』と主張し対立している。データ基盤チームは、パーティション・クラスタリング設計とスロットの購入形態の両面から最適解を提示する必要がある。","可視化層では、経営ダッシュボードを内製 BI に統合し、数百人規模の閲覧者が同時にアクセスする。頻出の集計クエリに対する応答を高速化しつつ、BigQuery のスキャン量を抑える仕組みが求められている。"],"en":["Retail chain 'MidoriMart' is migrating its on-premises columnar DWH (about 40TB), run for over a decade, to Google Cloud. Nightly batch ETL keeps getting longer, and during peak season reports are not ready by morning. Executives want cost predictability and interactive per-store, per-product analysis, and the data platform team must design a solution centered on BigQuery.","In scope are daily-finalized sales line items (about 200 million rows/day), master data (store, product, customer), and POS logs. The sales table retains five years of history, and nearly all analytic queries filter by a specific date range and a specific store. Analysts mostly re-query the last 90 days from a BI tool, but full-history scans occur a few times per month for audit.","For the initial migration, on-prem extract files (Avro/CSV) are consolidated into Cloud Storage and then loaded into BigQuery. For ongoing CDC, since the source is Oracle, they are considering a dedicated service. A leased line is already in place, and the initial bulk transfer will be tens of TB.","On cost, Finance strongly demands 'predictable billing that never exceeds the monthly budget,' while analysts insist they must not be throttled on exploratory queries. The platform team must propose an optimum across partitioning/clustering design and the slot purchasing model.","For visualization, executive dashboards are integrated into an in-house BI tool accessed concurrently by hundreds of viewers. The design must speed up frequent aggregate queries while limiting BigQuery scan volume."]},"tables":[{"title":{"ja":"売上明細テーブルの利用パターンとデータ特性","en":"Usage Patterns and Data Characteristics of the Sales Line-Item Table"},"headers":{"ja":["項目","値","備考"],"en":["Item","Value","Note"]},"rows":{"ja":[["総データ量","約40TB / 5年","日次で約22GB増加"],["1日あたり行数","約2億行","確定は翌日午前"],["典型クエリの絞り込み","日付範囲 + 店舗ID","直近90日が大半"],["全期間スキャン頻度","月2〜3回","監査用途"],["同時閲覧者数","数百人","BIダッシュボード"]],"en":[["Total data volume","~40TB / 5 years","~22GB added daily"],["Rows per day","~200 million","Finalized next morning"],["Typical query filter","date range + store ID","Mostly last 90 days"],["Full-scan frequency","2-3 times/month","Audit purpose"],["Concurrent viewers","Hundreds","BI dashboards"]]}},{"title":{"ja":"BigQuery 課金モデルの比較（概念）","en":"Comparison of BigQuery Billing Models (Conceptual)"},"headers":{"ja":["課金モデル","課金の考え方","適する状況"],"en":["Billing model","Basis","Best fit"]},"rows":{"ja":[["オンデマンド","スキャンしたバイト量に応じて課金","利用が不規則・少量"],["容量ベース（スロット予約）","確保した処理能力の時間課金で予測可能","利用が定常・大量"],["混在","定常分は予約・突発分はオンデマンド","予算固定と柔軟性の両立"]],"en":[["On-demand","Charged by bytes scanned","Irregular, low volume"],["Capacity (slot reservations)","Predictable time-based charge for reserved capacity","Steady, high volume"],["Mixed","Reserve baseline, burst on-demand","Fixed budget plus flexibility"]]}}],"questions":[{"n":1,"q":{"ja":"売上明細テーブルは『日付範囲＋店舗ID』での絞り込みが大半で、スキャンコストを最小化したい。BigQuery テーブル設計として最も適切なものはどれか。","en":"The sales table is mostly filtered by 'date range + store ID', and scan cost should be minimized. Which BigQuery table design is most appropriate?"},"options":[{"label":{"ja":"取引日でパーティション分割し、店舗IDでクラスタリングする","en":"Partition by transaction date and cluster by store ID"},"exp":{"ja":"日付パーティションで期間外を刈り込み、店舗IDのクラスタリングでブロック内も絞れる。両条件が頻出する本ケースに最適。","en":"Date partitioning prunes out-of-range data and clustering by store ID narrows within blocks, ideal since both filters are frequent."},"ok":true},{"label":{"ja":"店舗IDでパーティション分割し、取引日でクラスタリングする","en":"Partition by store ID and cluster by transaction date"},"exp":{"ja":"店舗数が多いと整数範囲/取込時刻以外の列パーティションは非対応または上限超過になりやすく、日付範囲刈り込みの利点も失う。","en":"Many stores exceed partition limits (only integer-range/time columns are supported), and it loses efficient date-range pruning."}},{"label":{"ja":"パーティションもクラスタリングも設定せず、全件を1テーブルに保持する","en":"Use neither partitioning nor clustering; keep everything in one table"},"exp":{"ja":"どのクエリも40TB全体をスキャンしうるため、オンデマンドでコストが跳ね上がり要件に反する。","en":"Every query could scan the full 40TB, spiking on-demand cost and violating the requirement."}},{"label":{"ja":"店舗ごとに別テーブルへ物理分割し、UNIONで集計する","en":"Physically split into per-store tables and UNION them for aggregation"},"exp":{"ja":"テーブル数が膨大化し運用・横断集計が煩雑。パーティション＋クラスタで同等以上の効果が単一テーブルで得られる。","en":"Table count explodes and cross-store aggregation is cumbersome; partition+cluster achieves equal or better on one table."}}]},{"n":2,"q":{"ja":"財務は予測可能な課金を求め、アナリストは探索的クエリの制限を嫌う。この対立を両立させる BigQuery のコスト戦略として最も妥当なものはどれか。","en":"Finance wants predictable billing while analysts dislike being throttled on exploration. Which BigQuery cost strategy best reconciles this conflict?"},"options":[{"label":{"ja":"全プロジェクトでオンデマンド課金のみを使い、ユーザー単位の1日あたりクエリ上限を設定する","en":"Use only on-demand billing everywhere with per-user daily query quotas"},"exp":{"ja":"上限はコスト暴走を防ぐが、探索を直接制限し予測可能性も担保しづらい。アナリストの要望に反する。","en":"Quotas curb runaway cost but directly throttle exploration and give weak predictability, conflicting with analysts' needs."}},{"label":{"ja":"定常的なダッシュボード負荷にスロット予約（容量ベース）を割り当て、突発的な探索クエリはオンデマンドの別割り当てにする","en":"Assign slot reservations (capacity) to steady dashboard load and route bursty exploratory queries to a separate on-demand allocation"},"exp":{"ja":"定常分は予約で予算固定、突発分は従量で柔軟性を確保でき、両部門の要求を同時に満たす現実的な折衷。","en":"Reservations fix the budget for steady load while on-demand keeps flexibility for bursts, satisfying both parties."},"ok":true},{"label":{"ja":"全ワークロードを最大サイズのスロット予約に固定し、オンデマンドは一切使わない","en":"Fix all workloads to a max-size slot reservation and never use on-demand"},"exp":{"ja":"予測可能だが、探索の急増時にスロット不足で待たされ、常時最大確保はコスト過大。最適配分ではない。","en":"Predictable but bursts queue on insufficient slots, and always reserving the max is over-provisioned and costly."}},{"label":{"ja":"クエリ結果を毎回エクスポートし、Cloud Storage 上で集計してBigQueryの利用を止める。IAMロールと権限設計を別途伴う","en":"Export results each time and aggregate on Cloud Storage to avoid using BigQuery , accompanied by separate IAM role and permission design"},"exp":{"ja":"対話的分析の要件を満たせず、運用も複雑化。BigQueryの強みを放棄しており本末転倒。","en":"Fails the interactive requirement and adds complexity, abandoning BigQuery's core strength."}}]},{"n":3,"q":{"ja":"Oracle をソースとする継続的なニアリアルタイムのCDC取り込みを、マネージドに実現する Google Cloud サービスはどれか。","en":"Which managed Google Cloud service best implements ongoing near-real-time CDC ingestion from an Oracle source?"},"options":[{"label":{"ja":"Storage Transfer Service","en":"Storage Transfer Service"},"exp":{"ja":"オブジェクトストレージ間などの大容量転送用で、リレーショナルDBの行レベルCDCは対象外。用途が異なる。","en":"Meant for bulk transfers between object stores, not row-level CDC from relational databases."}},{"label":{"ja":"Datastream","en":"Datastream"},"exp":{"ja":"Oracle/MySQL/PostgreSQL等のCDCを BigQuery や Cloud Storage へ低遅延で連携するサーバーレスCDCサービスで要件に合致。","en":"A serverless CDC service that streams changes from Oracle/MySQL/PostgreSQL into BigQuery or Cloud Storage with low latency, matching the requirement."},"ok":true},{"label":{"ja":"BigQuery Data Transfer Service","en":"BigQuery Data Transfer Service"},"exp":{"ja":"SaaSや他DWHからのスケジュール取り込みが中心で、OracleのログベースCDCを主目的としない。","en":"Focused on scheduled loads from SaaS/other DWHs, not log-based Oracle CDC."}},{"label":{"ja":"Cloud Composer","en":"Cloud Composer"},"exp":{"ja":"Airflowベースのオーケストレーションで、CDCの実処理ではなくジョブの調整役。単体でCDCは行わない。","en":"Airflow-based orchestration that coordinates jobs, not the CDC mechanism itself."}}]},{"n":4,"q":{"ja":"数百人が同時閲覧するダッシュボードで、頻出の集計クエリを高速化しつつ BigQuery のスキャン量を抑えたい。最も効果的な機能はどれか。","en":"For dashboards viewed by hundreds concurrently, you want to speed up frequent aggregate queries while limiting BigQuery scan volume. Which feature is most effective?"},"options":[{"label":{"ja":"クエリごとに maximum bytes billed を0に設定する","en":"Set maximum bytes billed to 0 for each query"},"exp":{"ja":"0にするとほぼ全クエリが失敗する。コスト上限の安全弁であり高速化やスキャン削減の手段ではない。","en":"Setting 0 fails nearly all queries; it is a cost cap, not a speedup or scan-reduction mechanism."}},{"label":{"ja":"BI Engine を有効化し、頻出集計をインメモリで高速化する","en":"Enable BI Engine to accelerate frequent aggregations in memory"},"exp":{"ja":"BI Engineはインメモリ高速化層で、ダッシュボードの反復集計を低レイテンシ化しスキャンも抑えられ、本要件に最適。","en":"BI Engine is an in-memory acceleration layer that lowers latency for repeated dashboard aggregations and reduces scanning, ideal here."},"ok":true},{"label":{"ja":"テーブルの有効期限（table expiration）を短く設定する","en":"Set a short table expiration"},"exp":{"ja":"データを消すだけで高速化やスキャン削減の主目的にならず、5年保持要件にも反する。","en":"Merely deletes data, not a speedup mechanism, and violates the 5-year retention requirement."}},{"label":{"ja":"全ダッシュボードクエリを WITH 句（CTE）で書き換える","en":"Rewrite all dashboard queries using WITH clauses (CTEs)"},"exp":{"ja":"CTEは可読性向上に留まり、スキャン量や同時実行の高速化を本質的には解決しない。","en":"CTEs improve readability but do not fundamentally reduce scan volume or speed up concurrency."}}]}]},{"id":"adp-2","title":{"ja":"ケース：リアルタイム・イベント処理基盤の設計","en":"Case: Designing a Real-Time Event Processing Platform"},"body":{"ja":["モビリティ企業「RideNow」は、全国の車両から送られる位置・速度・センサーのイベント（ピーク時 毎秒約50万件）をリアルタイムに処理する基盤を Google Cloud に構築する。用途は、運行管理画面へのライブ表示、異常検知、そして後続の分析・機械学習である。既存のオンプレ処理は突発負荷でしばしば詰まり、スパイク吸収とスケールが最大の課題だ。","アーキテクトは、取り込みの緩衝と配信の分離のためにメッセージング層を、変換・集計のためにストリーム処理エンジンを置く構成を検討している。イベントは順序が多少前後してもよいが、遅延到着（late data）と重複が現実に起きるため、これらをハンドリングできる処理モデルが必要である。","保存先は二系統に分かれる。1つは運行画面から車両IDをキーに直近状態を数ミリ秒で読み書きする用途、もう1つは全車両の履歴を対象にした大規模分析クエリである。チームは、前者を低レイテンシのキー・バリュー的ストア、後者を分析用DWHへ振り分ける設計思想で合意しつつあるが、具体的な製品選定で意見が割れている。","コスト最適化も論点だ。分析側では、ストリーミングでの逐次挿入と、いったんファイルに溜めてから一括ロードする方式のコスト差が問題になっている。運用チームは『可能な限りリアルタイムに近づけたい』が、財務は『秒間数十万件の逐次挿入は割高では』と懸念する。両者はレイテンシ要件ごとの割り切りを求めている。","最後に、異常検知の一部はストリーム処理内で完結させ、閾値超過時に即時アラートを出す。一方でモデルの再学習や重い集計はバッチで回す。リアルタイムとバッチを1つのパイプラインで無理なく両立させる設計が求められている。"],"en":["Mobility company 'RideNow' is building a Google Cloud platform to process, in real time, location/speed/sensor events from vehicles nationwide (about 500,000 events/sec at peak). Uses include a live fleet-operations screen, anomaly detection, and downstream analytics/ML. The existing on-prem pipeline often stalls under bursts, so absorbing spikes and scaling is the top challenge.","The architect is considering a messaging layer to buffer ingestion and decouple delivery, plus a stream-processing engine for transformation and aggregation. Events may arrive slightly out of order, and since late data and duplicates do occur in practice, a processing model that handles them is required.","Storage splits into two paths: one to read/write the latest state keyed by vehicle ID in a few milliseconds for the ops screen, and one for large-scale analytic queries over all vehicles' history. The team is converging on routing the former to a low-latency key-value-style store and the latter to an analytical DWH, but disagrees on specific products.","Cost optimization is also debated. On the analytics side, the cost gap between per-row streaming inserts and buffering to files then bulk-loading is at issue. Operations wants it 'as near real time as possible,' while Finance worries that 'streaming hundreds of thousands of rows per second is expensive.' Both want a per-latency tradeoff.","Finally, some anomaly detection is completed within stream processing, emitting immediate alerts on threshold breaches, while model retraining and heavy aggregation run in batch. A design that cleanly unifies real-time and batch in one pipeline is required."]},"tables":[{"title":{"ja":"ワークロード別のレイテンシ要件と特性","en":"Latency Requirements and Characteristics by Workload"},"headers":{"ja":["ワークロード","レイテンシ要件","アクセスパターン"],"en":["Workload","Latency need","Access pattern"]},"rows":{"ja":[["運行画面のライブ状態","数〜数十ミリ秒","車両IDキーの点参照/更新"],["ストリーム異常検知","秒未満","ウィンドウ集計+閾値判定"],["全車両の履歴分析","秒〜分","大規模スキャン/集計"],["モデル再学習","時間単位（バッチ）","履歴一括読み出し"]],"en":[["Live ops-screen state","Single to tens of ms","Point lookup/update by vehicle ID"],["Streaming anomaly detection","Sub-second","Windowed aggregation + threshold"],["Fleet-wide history analysis","Seconds to minutes","Large scans/aggregation"],["Model retraining","Hourly (batch)","Bulk history reads"]]}},{"title":{"ja":"分析側への取り込み方式の比較","en":"Comparison of Ingestion Methods into Analytics"},"headers":{"ja":["方式","鮮度","コスト傾向"],"en":["Method","Freshness","Cost tendency"]},"rows":{"ja":[["ストリーミング挿入（Storage Write API）","ほぼ即時","取り込みバイト量に応じ加算"],["ファイルにバッファ→一括ロード","分〜時間遅延","ロード自体は無料枠で安価"],["マイクロバッチ（数分間隔）","数分遅延","鮮度とコストの中間"]],"en":[["Streaming inserts (Storage Write API)","Near real time","Charged by ingested bytes"],["Buffer to files then bulk load","Minutes to hours delay","Bulk load itself is low-cost"],["Micro-batch (every few minutes)","Minutes delay","Middle ground of freshness and cost"]]}}],"questions":[{"n":1,"q":{"ja":"ピーク毎秒約50万件のイベントを緩衝し、取り込みと配信を分離する層として最も適切な Google Cloud サービスはどれか。","en":"Which Google Cloud service best serves as the layer that buffers ~500k events/sec and decouples ingestion from delivery?"},"options":[{"label":{"ja":"Cloud SQL のテーブルにイベントを直接 INSERT する","en":"INSERT events directly into a Cloud SQL table"},"exp":{"ja":"リレーショナルDBはこの書き込みスループットとスパイク吸収に向かず、ボトルネック化する。緩衝層の役割も果たさない。","en":"A relational DB is unsuited to this write throughput and spike absorption and does not act as a buffer."}},{"label":{"ja":"Pub/Sub トピックにイベントを発行し、サブスクライバが購読する","en":"Publish events to a Pub/Sub topic consumed by subscribers"},"exp":{"ja":"Pub/Subはグローバルにスケールするマネージドメッセージングで、スパイクを緩衝し発行と購読を疎結合化する。要件に最適。","en":"Pub/Sub is globally scaling managed messaging that buffers spikes and decouples publishers from subscribers, ideal here."},"ok":true},{"label":{"ja":"各車両が Cloud Storage に小さなオブジェクトを毎秒書き込む","en":"Have each vehicle write tiny objects to Cloud Storage every second"},"exp":{"ja":"膨大な小オブジェクトの生成は非効率で、順序・購読・低遅延配信の仕組みも欠く。メッセージング層の代替にならない。","en":"Generating countless tiny objects is inefficient and lacks ordering, subscription, and low-latency delivery."}},{"label":{"ja":"BigQuery に直接ストリーミング挿入して、そこから各消費者が読む","en":"Stream directly into BigQuery and have each consumer read from it"},"exp":{"ja":"BigQueryは分析用の保存先であり、緩衝・ファンアウト配信の役割は担わない。取り込み分離の設計意図に反する。","en":"BigQuery is an analytical sink, not a buffering/fan-out delivery layer, contradicting the decoupling intent."}}]},{"n":2,"q":{"ja":"遅延到着データや重複を扱いつつ、ウィンドウ集計によるストリーム変換をマネージドに実行したい。最適なサービスはどれか。","en":"You need managed stream transformation with windowed aggregation that also handles late data and duplicates. Which service fits best?"},"options":[{"label":{"ja":"Dataflow（Apache Beam）でストリーミングパイプラインを実行する","en":"Run a streaming pipeline on Dataflow (Apache Beam)"},"exp":{"ja":"Beamのウィンドウ・ウォーターマーク・トリガーで遅延到着や重複制御を扱え、Dataflowがマネージドに自動スケール実行する。最適。","en":"Beam's windows, watermarks, and triggers handle late data and dedup, and Dataflow runs it managed with autoscaling, the best fit."},"ok":true},{"label":{"ja":"Cloud Functions を各メッセージで起動し、逐次処理する","en":"Trigger Cloud Functions per message for sequential processing"},"exp":{"ja":"関数はステートレスな軽処理向けで、ウィンドウ集計やウォーターマークによる遅延処理の枠組みを備えない。","en":"Functions suit stateless light tasks and lack windowing/watermark frameworks for late-data handling."}},{"label":{"ja":"Dataproc 上のバッチ Spark ジョブを1時間ごとに実行する。運用初期の暫定構成として扱われる場合がある","en":"Run a batch Spark job on Dataproc every hour , sometimes treated as an interim setup in early operations"},"exp":{"ja":"1時間バッチでは秒未満の異常検知要件を満たせない。ストリーミングの低遅延処理には不向き。","en":"An hourly batch cannot meet the sub-second anomaly requirement; it is unsuited to low-latency streaming."}},{"label":{"ja":"BigQuery のスケジュールクエリで5分ごとに集計する","en":"Aggregate every 5 minutes with BigQuery scheduled queries"},"exp":{"ja":"分単位の周期処理で秒未満要件に届かず、遅延到着や重複の逐次制御も本質的に扱えない。","en":"Minute-scale scheduling misses the sub-second need and cannot intrinsically manage late/duplicate events."}}]},{"n":3,"q":{"ja":"運行画面が車両IDをキーに直近状態を数ミリ秒で読み書きする用途に、最も適した保存先はどれか。","en":"For the ops screen reading/writing the latest state by vehicle ID within a few milliseconds, which store is most suitable?"},"options":[{"label":{"ja":"BigQuery のテーブルに状態を UPDATE し続ける","en":"Continuously UPDATE state in a BigQuery table"},"exp":{"ja":"BigQueryは分析向けで高頻度の点更新・ミリ秒点参照に不向き。頻繁なDMLは非効率でレイテンシ要件を満たせない。","en":"BigQuery is analytical and poor at high-frequency point updates/ms lookups; frequent DML is inefficient and misses the latency need."}},{"label":{"ja":"Cloud Bigtable に車両IDをキーとして最新状態を保持する","en":"Keep the latest state in Cloud Bigtable keyed by vehicle ID"},"exp":{"ja":"Bigtableは高スループット・低レイテンシのワイドカラムKVストアで、キー点参照/更新に最適。時系列・IoT状態管理の定番。","en":"Bigtable is a high-throughput, low-latency wide-column KV store, ideal for keyed point lookups/updates and IoT state."},"ok":true},{"label":{"ja":"Cloud Storage に車両IDごとのJSONオブジェクトを置いて都度上書きする","en":"Store per-vehicle JSON objects in Cloud Storage and overwrite each time"},"exp":{"ja":"オブジェクトストレージはミリ秒級の頻繁な更新・点参照に向かず、高頻度の小書き込みは非効率。","en":"Object storage is not built for ms-level frequent updates/lookups; high-frequency small writes are inefficient."}},{"label":{"ja":"Pub/Sub の直近メッセージを毎回読み直して現在状態とする","en":"Re-read the latest Pub/Sub messages each time as the current state"},"exp":{"ja":"Pub/Subは配信用で状態ストアではない。任意キーの最新状態を保持・点参照する用途に使えない。","en":"Pub/Sub is for delivery, not a state store; it cannot serve keyed latest-state point lookups."}}]},{"n":4,"q":{"ja":"分析側の取り込みコストについて、財務の懸念に配慮しつつ鮮度要件に応じて最適化する方針として最も妥当なものはどれか。","en":"For analytics ingestion cost, which policy best optimizes per freshness need while respecting Finance's concern?"},"options":[{"label":{"ja":"全データを常にストリーミング挿入し、鮮度を最大化する","en":"Always stream-insert all data to maximize freshness"},"exp":{"ja":"秒間数十万件の全量ストリーミングは取り込みコストがかさむ。全ワークロードに即時鮮度は不要で過剰。","en":"Streaming all hundreds of thousands/sec is costly, and instant freshness is unnecessary for every workload."}},{"label":{"ja":"即時性が要る指標のみストリーミング挿入し、それ以外は数分間隔のマイクロバッチや一括ロードにする","en":"Stream-insert only metrics that need immediacy; micro-batch or bulk-load the rest at intervals"},"exp":{"ja":"鮮度要件で経路を分け、必要な部分だけ従量のストリーミングにすることでコストと鮮度を両立できる現実解。","en":"Splitting by freshness and streaming only what needs it balances cost and freshness, a practical solution."},"ok":true},{"label":{"ja":"全データを1時間ごとの一括ロードのみにし、ストリーミングは一切使わない","en":"Bulk-load everything hourly only and never stream"},"exp":{"ja":"コストは最小だが異常検知など即時性の要る分析の鮮度要件を満たせず、運用の要望に反する。","en":"Cheapest but fails the freshness needs of time-critical analytics like anomaly detection, against operations' wishes."}},{"label":{"ja":"ストリーミングとバッチの判断を避け、Cloud SQL に全イベントを保存する。IAMロールと権限設計を別途伴う","en":"Avoid the streaming-vs-batch choice and store all events in Cloud SQL , accompanied by separate IAM role and permission design"},"exp":{"ja":"Cloud SQLはこの規模の分析スキャンに不向きでスケールせず、コスト・性能の両面で要件を満たさない。","en":"Cloud SQL does not scale to analytic scans at this volume, failing on both cost and performance."}}]}]},{"id":"adp-3","title":{"ja":"ケース：データガバナンスとマルチチーム統制","en":"Case: Data Governance and Multi-Team Control"},"body":{"ja":["金融グループ「Kessai Holdings」は、複数事業部（決済・与信・マーケティング）が同一の Google Cloud データ基盤を共有する。各チームは自分たちのデータを分析したいが、顧客の個人情報や機微な与信データが横断的に混在し、規制対応と最小権限の徹底が経営課題になっている。CDO は、統制と自律のバランスを取るガバナンス設計を求めている。","現状、BigQuery データセットや Cloud Storage バケットが部門ごとに乱立し、どこに何があるか把握できない。メタデータの一元管理、データの発見性、品質・リネージの可視化が急務だ。加えて、機微データが含まれるテーブルには、閲覧を許可された担当者だけがアクセスできる仕組みを、列レベルでも制御したい。","アクセス制御では、『分析者はクエリ実行と結果参照はできるが、テーブルのスキーマ変更や削除はできない』といった職務分掌を、事前定義ロールで簡潔に実現したい。プロジェクト全体のオーナー権限を安易に配ることは監査上避けたい。IAM ロールの粒度と付与範囲（プロジェクト/データセット/テーブル）の設計が問われる。","ストレージのコストとライフサイクルも論点だ。生ログや監査証跡は長期保管が義務づけられるが、アクセス頻度は時間とともに激減する。チームは、一定期間を過ぎたオブジェクトを自動でより安価なストレージクラスへ移し、最終的に削除する運用を、人手を介さず実現したい。","可視化層では、Looker を用いて事業部横断のダッシュボードを提供するが、行レベルで『自部門のデータしか見えない』制御と、機微指標の閲覧者限定が必要である。BI ツール側の権限と、基盤側の IAM をどう役割分担するかが設計の焦点になっている。"],"en":["Financial group 'Kessai Holdings' has multiple divisions (payments, credit, marketing) sharing one Google Cloud data platform. Each team wants to analyze its own data, but customer PII and sensitive credit data are intermixed across the platform, making regulatory compliance and least privilege a board-level concern. The CDO wants governance that balances control with autonomy.","Today, BigQuery datasets and Cloud Storage buckets proliferate per division and no one knows what exists where. Centralized metadata, data discoverability, and quality/lineage visibility are urgent. Additionally, tables containing sensitive data must be accessible only to authorized staff, controllable even at the column level.","For access control, they want to express separation of duties concisely with predefined roles, e.g., 'analysts can run queries and read results but cannot alter schemas or delete tables.' Handing out project-wide owner rights casually must be avoided for audit. The design hinges on IAM role granularity and grant scope (project/dataset/table).","Storage cost and lifecycle are also at issue. Raw logs and audit trails must be retained long-term, but access frequency drops sharply over time. The team wants objects past a certain age to move automatically to cheaper storage classes and eventually be deleted, with no manual intervention.","For visualization, Looker provides cross-division dashboards, but row-level control ('you see only your division's data') and restriction of sensitive metrics to authorized viewers are required. How to divide responsibility between BI-tool permissions and platform IAM is the design focus."]},"tables":[{"title":{"ja":"職務と必要権限のマッピング","en":"Mapping of Roles to Required Permissions"},"headers":{"ja":["職務","必要な操作","避けたい権限"],"en":["Job role","Needed actions","Rights to avoid"]},"rows":{"ja":[["分析者","クエリ実行・結果参照","スキーマ変更・削除"],["データエンジニア","テーブル作成・ロード・変換","IAMポリシー変更"],["監査担当","メタデータ・ログの参照","データ更新・削除"],["部門管理者","自部門データセットの権限付与","他部門データへのアクセス"]],"en":[["Analyst","Run queries, read results","Schema change / delete"],["Data engineer","Create tables, load, transform","Change IAM policy"],["Auditor","View metadata and logs","Update / delete data"],["Division admin","Grant rights on own datasets","Access other divisions' data"]]}},{"title":{"ja":"Cloud Storage ストレージクラスとライフサイクルの目安","en":"Cloud Storage Classes and Lifecycle Guidelines"},"headers":{"ja":["ストレージクラス","想定アクセス頻度","代表的な用途"],"en":["Storage class","Assumed access frequency","Typical use"]},"rows":{"ja":[["Standard","頻繁","直近の稼働データ"],["Nearline","月1回程度","30日超の低頻度データ"],["Coldline","四半期に1回程度","90日超のバックアップ"],["Archive","年1回未満","長期保管の監査証跡"]],"en":[["Standard","Frequent","Recent active data"],["Nearline","About once a month","Low-frequency data over 30 days"],["Coldline","About once a quarter","Backups over 90 days"],["Archive","Less than once a year","Long-term audit trails"]]}}],"questions":[{"n":1,"q":{"ja":"乱立するデータ資産のメタデータ一元管理、データの発見性、品質・リネージの可視化を実現する Google Cloud のサービスはどれか。","en":"Which Google Cloud service delivers centralized metadata, data discoverability, and quality/lineage visibility across proliferating data assets?"},"options":[{"label":{"ja":"Dataplex（データカタログ／データガバナンス機能を含む）","en":"Dataplex (including data catalog / governance features)"},"exp":{"ja":"Dataplexはデータの発見・カタログ・品質・リネージ・統制を横断的に提供する統合ガバナンス基盤で、本要件の中核に合致する。","en":"Dataplex unifies discovery, catalog, quality, lineage, and governance across assets, matching the core requirement."},"ok":true},{"label":{"ja":"Cloud Monitoring。運用初期の暫定構成として扱われる場合がある","en":"Cloud Monitoring , sometimes treated as an interim setup in early operations"},"exp":{"ja":"インフラ/アプリのメトリクス監視が目的で、データ資産のカタログやリネージ管理は担わない。","en":"Aimed at infra/app metrics monitoring, not data-asset cataloging or lineage."}},{"label":{"ja":"Cloud Composer","en":"Cloud Composer"},"exp":{"ja":"ワークフローのオーケストレーションが役割で、メタデータ発見やガバナンスの中枢機能を持たない。","en":"Its role is workflow orchestration, not metadata discovery or governance."}},{"label":{"ja":"Cloud Logging","en":"Cloud Logging"},"exp":{"ja":"ログの収集・検索が目的で、データカタログや品質・リネージの可視化は対象外。","en":"For log collection/search, not data catalog or quality/lineage visualization."}}]},{"n":2,"q":{"ja":"『分析者はクエリ実行と結果参照はできるが、スキーマ変更や削除はできない』を最小権限で実現する BigQuery の付与として最も適切なものはどれか。","en":"To enforce 'analysts can query and read results but not alter schemas or delete' with least privilege, which BigQuery grant is most appropriate?"},"options":[{"label":{"ja":"プロジェクトに対して roles/owner を付与する","en":"Grant roles/owner on the project"},"exp":{"ja":"オーナーは削除やIAM変更まで含む広範な権限で、最小権限と職務分掌に真っ向から反する。監査上も不可。","en":"Owner is far too broad, including delete and IAM changes, directly violating least privilege and separation of duties."}},{"label":{"ja":"対象データセットに roles/bigquery.dataViewer、プロジェクトに roles/bigquery.jobUser を付与する","en":"Grant roles/bigquery.dataViewer on the dataset and roles/bigquery.jobUser on the project"},"exp":{"ja":"dataViewerで参照、jobUserでクエリ実行が可能になり、書き込み・削除は不可。最小権限で要件を的確に満たす。","en":"dataViewer allows reads and jobUser allows running queries, while writes/deletes stay blocked, precisely least privilege."},"ok":true},{"label":{"ja":"対象データセットに roles/bigquery.dataEditor を付与する。コストとリージョン要件により構成が変わり得る。コストとリージョン要件により構成が変わり得る","en":"Grant roles/bigquery.dataEditor on the dataset , where configuration can vary with cost and region requirements , where configuration can vary with cost and region requirements"},"exp":{"ja":"dataEditorはテーブルの作成・更新・削除まで許すため、スキーマ変更禁止の要件を満たさず過大。","en":"dataEditor permits create/update/delete of tables, exceeding the requirement that forbids schema changes."}},{"label":{"ja":"対象データセットに roles/bigquery.admin を付与する","en":"Grant roles/bigquery.admin on the dataset"},"exp":{"ja":"adminはデータセット/テーブルの全操作とアクセス管理を含み、分析者に与えるには広すぎる。","en":"admin includes full control and access management, far too broad for an analyst."}}]},{"n":3,"q":{"ja":"生ログを一定期間後に自動でより安価なストレージクラスへ移し、最終的に削除したい。人手を介さず実現する手段はどれか。","en":"You want raw logs to move automatically to cheaper storage classes after a period and eventually be deleted, with no manual work. Which achieves this?"},"options":[{"label":{"ja":"Cloud Storage のオブジェクトライフサイクル管理でクラス移行と削除のルールを設定する","en":"Configure Cloud Storage Object Lifecycle Management rules for class transitions and deletion"},"exp":{"ja":"経過日数などの条件でNearline/Coldline/Archiveへの自動移行や自動削除を宣言的に定義でき、無人運用の要件に最適。","en":"Rules by age can declaratively transition to Nearline/Coldline/Archive and auto-delete, ideal for hands-off operation."},"ok":true},{"label":{"ja":"毎日 gsutil を手動実行してオブジェクトをコピー・削除する。IAMロールと権限設計を別途伴う","en":"Manually run gsutil daily to copy and delete objects , accompanied by separate IAM role and permission design"},"exp":{"ja":"人手を介する運用で要件（自動化）に反し、ミスや漏れのリスクも高い。","en":"Manual operation violates the automation requirement and is error-prone."}},{"label":{"ja":"バケットの既定ストレージクラスを Archive に固定する","en":"Fix the bucket's default storage class to Archive"},"exp":{"ja":"直近の頻繁アクセスに取り出しコストがかさみ、段階的移行や自動削除も実現しない。","en":"Frequent recent access incurs retrieval costs, and it provides neither staged transitions nor auto-deletion."}},{"label":{"ja":"BigQuery のパーティション有効期限を設定する","en":"Set BigQuery partition expiration"},"exp":{"ja":"対象はBigQueryのパーティションであり、Cloud Storage上の生ログのクラス移行・削除には適用されない。","en":"That targets BigQuery partitions, not class transitions/deletion of raw logs in Cloud Storage."}}]},{"n":4,"q":{"ja":"Looker のダッシュボードで各部門ユーザーに『自部門の行のみ』を見せ、機微指標は限定者のみに見せたい。責任分担として最も妥当な設計はどれか。","en":"In Looker dashboards, each division's users should see 'only their division's rows,' and sensitive metrics only for authorized viewers. Which division of responsibility is most sound?"},"options":[{"label":{"ja":"全ユーザーに同一の管理者ロールを与え、部門ごとにダッシュボードURLを分けて周知する。運用初期の暫定構成として扱われる場合がある。運用初期の暫定構成として扱われる場合がある","en":"Give all users the same admin role and just circulate separate dashboard URLs per division , sometimes treated as an interim setup in early operations , sometimes treated as an interim setup in early operations"},"exp":{"ja":"URL分割は制御にならず、管理者ロールの一律付与は機微データの露出リスクが高い。統制になっていない。","en":"URL splitting is not access control, and uniform admin roles risk exposing sensitive data; no real governance."}},{"label":{"ja":"Looker のユーザー属性とモデルのアクセスフィルタで行レベル制御を行い、機微データ層は基盤側の列レベル/データセット権限で保護する","en":"Use Looker user attributes and model access filters for row-level control, and protect sensitive data with platform-side column-level/dataset permissions"},"exp":{"ja":"BI側で行レベルの絞り込み、基盤側IAM/列レベルで機微保護と多層防御を構成でき、責任分担が明確で堅牢。","en":"BI-side row filtering plus platform-side IAM/column-level protection gives layered defense with clear responsibility, robust and correct."},"ok":true},{"label":{"ja":"行レベル制御は行わず、機微列を含むテーブルをCSVで各部門に配布する","en":"Skip row-level control and distribute tables with sensitive columns as CSV to each division"},"exp":{"ja":"配布したCSVは統制不能で機微データが拡散する。最小権限・規制対応に真っ向から反する。","en":"Distributed CSVs are uncontrollable and spread sensitive data, directly violating least privilege and compliance."}},{"label":{"ja":"全制御を Looker だけに集約し、基盤側の IAM は全員に広く付与する","en":"Concentrate all control in Looker only and grant broad IAM to everyone on the platform"},"exp":{"ja":"BIを迂回した直接クエリで機微データにアクセスできてしまい、基盤側の統制欠如は重大な穴になる。","en":"Direct queries bypassing BI could reach sensitive data; missing platform-side control is a serious gap."}}]}]}];

function ExamCaseRunner({ cases, lang, onBack }) {
  const g = (o) => (o && (o[lang] != null ? o[lang] : o.ja));
  const clist = Array.isArray(cases) ? cases : [cases];
  const [pick, setPick] = useState(clist.length === 1 ? 0 : null);
  const [qi, setQi] = useState(0);
  const [answers, setAnswers] = useState({});
  const [finished, setFinished] = useState(false);

  const th = { textAlign: "left", padding: "7px 9px", background: "#EDE9E0", color: C.deep, fontSize: 11.5, fontWeight: 700, borderBottom: `1px solid ${C.mid}`, whiteSpace: "nowrap" };
  const td = { padding: "7px 9px", fontSize: 12, borderBottom: `1px solid ${C.mid}`, verticalAlign: "top", lineHeight: 1.45 };

  const openCase = (i) => { setPick(i); setQi(0); setAnswers({}); setFinished(false); };
  const backToList = () => { if (clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); } else onBack(); };

  if (pick === null) {
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <button onClick={onBack} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{lang === "ja" ? "← 戻る" : "← Back"}</button>
        </div>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 4 }}>{lang === "ja" ? "本試験形式ケース" : "Exam-style cases"}</div>
        <div style={{ fontSize: 12, color: "#8595ad", marginBottom: 12 }}>{lang === "ja" ? "資料表つき・僅差4択・全選択肢に根拠解説" : "Data tables, 4 close options, rationale for each"}</div>
        {clist.map((c, i) => (
          <button key={i} onClick={() => openCase(i)}
            style={{ width: "100%", textAlign: "left", padding: "14px 15px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5, color: C.deep, lineHeight: 1.45, paddingRight: 10 }}>{g(c.title)}</span>
            <span style={{ fontSize: 11.5, color: "#8595ad", whiteSpace: "nowrap" }}>{c.questions.length}{lang === "ja" ? "問" : "Q"}</span>
          </button>
        ))}
      </div>
    );
  }

  const data = clist[pick];
  const qs = data.questions;
  const Q = qs[qi];
  const sel = answers[qi] != null ? answers[qi] : null;
  const choose = (i) => { if (sel !== null) return; setAnswers(a => ({ ...a, [qi]: i })); };
  const prev = () => { if (qi > 0) setQi(qi - 1); };
  const next = () => { if (qi < qs.length - 1) setQi(qi + 1); };
  const restart = () => { setQi(0); setAnswers({}); setFinished(false); };

  let correct = 0;
  for (let k = 0; k < qs.length; k++) { const a = answers[k]; if (a != null && qs[k].options[a] && qs[k].options[a].ok) correct++; }
  const answeredCount = Object.keys(answers).length;
  const rate = qs.length ? Math.round((correct / qs.length) * 100) : 0;

  const navBtn = (label, onClick, enabled, primary) => (
    <button onClick={enabled ? onClick : undefined} disabled={!enabled}
      style={{ flex: 1, padding: "11px 12px", borderRadius: 9, fontSize: 13.5, fontWeight: 700,
        cursor: enabled ? "pointer" : "default",
        border: primary ? "none" : `1.5px solid ${enabled ? C.primary : C.mid}`,
        background: primary ? (enabled ? C.primary : C.mid) : "#fff",
        color: primary ? "#fff" : (enabled ? C.primary : "#b9c4d6") }}>{label}</button>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={backToList} style={{ border: "none", background: "none", color: C.primary, cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{clist.length > 1 ? (lang === "ja" ? "← ケース一覧" : "← Case list") : (lang === "ja" ? "← 戻る" : "← Back")}</button>
        {!finished && <span style={{ fontSize: 12, color: "#8595ad" }}>{lang === "ja" ? `問 ${qi + 1} / ${qs.length}` : `Q ${qi + 1} / ${qs.length}`}</span>}
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 12 }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 10 }}>{g(data.title)}</div>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 6 }}>{lang === "ja" ? "ケース本文（資料）" : "Case (materials)"}</div>
        {g(data.body).map((p, i) => (<div key={i} style={{ fontSize: 13, lineHeight: 1.7, marginBottom: 8, color: C.ink }}>{p}</div>))}
        {(data.tables || []).map((tb, ti) => (
          <div key={ti} style={{ marginTop: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: C.deep, marginBottom: 5 }}>{g(tb.title)}</div>
            <div style={{ overflowX: "auto", border: `1px solid ${C.mid}`, borderRadius: 8 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 320 }}>
                <thead><tr>{g(tb.headers).map((h, hi) => (<th key={hi} style={th}>{h}</th>))}</tr></thead>
                <tbody>{g(tb.rows).map((r, ri) => (<tr key={ri}>{r.map((cell, ci) => (<td key={ci} style={td}>{cell}</td>))}</tr>))}</tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {finished ? (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ textAlign: "center", marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "#5a6a85", fontWeight: 600, marginBottom: 6 }}>{lang === "ja" ? "ケース完了" : "Case complete"}</div>
            <div style={{ fontSize: 32, fontWeight: 800, color: rate >= PASS ? C.ok : C.ng }}>{rate}%</div>
            <div style={{ fontSize: 12.5, color: "#8595ad", marginTop: 2 }}>{lang === "ja" ? `正解 ${correct} / ${qs.length} 問` : `${correct} / ${qs.length} correct`}</div>
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
          <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
            <button onClick={() => { setFinished(false); setQi(0); }} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "解答を見直す" : "Review answers"}</button>
            <button onClick={restart} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "もう一度" : "Retry"}</button>
          </div>
        </div>
      ) : (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: 14.5, fontWeight: 700, marginBottom: 12, color: C.deep }}>{lang === "ja" ? `問${Q.n}. ` : `Q${Q.n}. `}{g(Q.q)}</div>
          {Q.options.map((opt, i) => {
            let bg = "#fff", bd = C.mid, col = C.ink;
            if (sel !== null) { if (opt.ok) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; } else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; } }
            return (
              <button key={i} onClick={() => choose(i)} disabled={sel !== null}
                style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.5, fontWeight: sel !== null && opt.ok ? 700 : 500 }}>
                <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && opt.ok ? "✓" : sel !== null && i === sel ? "✗" : "ABCD"[i]}</span>{g(opt.label)}
              </button>
            );
          })}
          {sel !== null && (
            <div style={{ marginTop: 12 }}>
              {Q.options.map((opt, i) => (
                <div key={i} style={{ background: opt.ok ? "#E6F4EC" : (i === sel ? "#FBEAE8" : C.light), borderRadius: 8, padding: "9px 11px", marginBottom: 6, fontSize: 12.5, lineHeight: 1.55 }}>
                  <span style={{ fontWeight: 700, marginRight: 6, color: opt.ok ? C.ok : (i === sel ? C.ng : "#8595ad") }}>{"ABCD"[i]}{opt.ok ? (lang === "ja" ? "（正解）" : " (correct)") : ""}</span>{g(opt.exp)}
                </div>
              ))}
            </div>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            {navBtn(lang === "ja" ? "← 前の問題" : "← Previous", prev, qi > 0, false)}
            {qi < qs.length - 1
              ? navBtn(lang === "ja" ? "次の問題 →" : "Next →", next, sel !== null, true)
              : navBtn(lang === "ja" ? "結果を見る →" : "See result →", () => setFinished(true), answeredCount === qs.length, true)}
          </div>
        </div>
      )}
    </div>
  );
}

function App() {
  const [tab, _setTab] = useState("home");
  const [tabHist, setTabHist] = useState([]);
  const setTab = (k) => { if (k !== tab) setTabHist(h => [...h, tab]); _setTab(k); };
  const goBackTab = () => { if (!tabHist.length) return; const prev = tabHist[tabHist.length - 1]; setTabHist(tabHist.slice(0, -1)); _setTab(prev); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); };
  const [state, setState] = useState(null);
  const [review, setReview] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [lang, setLang] = useState("ja");
  const [toast, setToast] = useState("");
  const [confirmCfg, setConfirmCfg] = useState(null); // {msg, onOk}
  const t = T[lang];

  useEffect(() => {
    Promise.all([loadJSON(STORE_KEY), loadJSON(REVIEW_KEY)]).then(([s, r]) => {
      setState(s || { progress: {}, meta: { streak: 0, lastDay: "", dailyDay: "", dailyCount: 0 } });
      setReview(r || []);
      setLoaded(true);
    });
  }, []);

  useEffect(() => { if (toast) { const id = setTimeout(() => setToast(""), 2200); return () => clearTimeout(id); } }, [toast]);

  const persist = (next) => { setState(next); saveJSON(STORE_KEY, next); };
  const persistReview = (next) => { setReview(next); saveJSON(REVIEW_KEY, next); };

  const record = (domId, correct) => {
    const next = JSON.parse(JSON.stringify(state));
    if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
    next.progress[domId].attempts++;
    if (correct) next.progress[domId].correct++;
    const today = todayStr();
    if (next.meta.dailyDay !== today) { next.meta.dailyDay = today; next.meta.dailyCount = 0; }
    next.meta.dailyCount++;
    if (next.meta.lastDay !== today) {
      const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
      next.meta.streak = next.meta.lastDay === yesterday ? next.meta.streak + 1 : 1;
      next.meta.lastDay = today;
    }
    persist(next);
  };

  const addToReview = (ids) => {
    const set = new Set(review);
    let added = 0;
    ids.forEach(i => { if (!set.has(i)) { set.add(i); added++; } });
    if (added > 0) { persistReview([...set]); setToast(t.addedToReview(added)); }
  };
  const removeFromReview = (id) => persistReview(review.filter(x => x !== id));
  const clearReview = () => persistReview([]);
  const askConfirm = (msg, onOk) => setConfirmCfg({ msg, onOk });

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const TABS = [
    ["home", t.tabHome], ["quiz", t.tabQuiz], ["exam", t.tabExam], ["review", t.tabReview],
    ["diagram", t.tabDiagram], ["compare", t.tabCompare], ["confuse", t.tabConfuse], ["glossary", t.tabGlossary], ["examcase", (lang === "en" ? "Exam Cases" : "本試験形式ケース")],
  ];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#FBFCFE", minHeight: "100vh", position: "relative" }}>
      <div style={{ background: C.deep, color: "#fff", padding: "16px 18px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontSize: 19, fontWeight: 700 }}>{t.appTitle}</div>
          <div style={{ fontSize: 12, opacity: 0.85, marginTop: 2 }}>{t.appSub}</div>
        </div>
        <div style={{ display: "flex", background: "rgba(255,255,255,.15)", borderRadius: 20, padding: 3 }}>
          {["ja", "en"].map(l => (
            <button key={l} onClick={() => setLang(l)}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "5px 12px", fontSize: 12, fontWeight: 700,
                background: lang === l ? "#fff" : "transparent", color: lang === l ? C.deep : "#fff" }}>
              {l === "ja" ? "日本語" : "English"}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{ flex: "1 1 auto", padding: "11px 6px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent", color: tab === k ? C.deep : C.ink,
              fontWeight: tab === k ? 700 : 500, fontSize: 12.5, position: "relative",
              borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent" }}>
            {label}
            {k === "review" && review.length > 0 && (
              <span style={{ position: "absolute", top: 4, right: 6, background: C.ng, color: "#fff", borderRadius: 9, fontSize: 9.5, fontWeight: 700, padding: "1px 5px" }}>{review.length}</span>
            )}
          </button>
        ))}
      </div>
      {tabHist.length > 0 && (
        <button onClick={goBackTab}
          aria-label="Back"
          style={{ position: "fixed", right: 16, bottom: 104, zIndex: 45, border: `1.5px solid ${C.deep}`, cursor: "pointer", borderRadius: 22, padding: "9px 15px", background: "#fff", color: C.deep, fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.20)" }}>
          ← {lang === "en" ? "Back" : "戻る"}
        </button>
      )}
      {tab !== "home" && (
        <button onClick={() => { setTab("home"); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); }}
          aria-label="Back to top"
          style={{ position: "fixed", right: 16, bottom: 60, zIndex: 45, border: "none", cursor: "pointer", borderRadius: 22, padding: "10px 15px", background: C.deep, color: "#fff", fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.28)" }}>
          ↑ {lang === "en" ? "Top" : "トップへ"}
        </button>
      )}
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <Home state={state} lang={lang} t={t} reviewCount={review.length} />}
        {tab === "quiz" && <Quiz onAnswer={record} lang={lang} t={t} />}
        {tab === "exam" && <Exam onAnswer={record} lang={lang} t={t} addToReview={addToReview} />}
        {tab === "review" && <Review review={review} onAnswer={record} removeFromReview={removeFromReview} clearReview={clearReview} askConfirm={askConfirm} lang={lang} t={t} />}
        {tab === "diagram" && <Diagrams lang={lang} t={t} />}
        {tab === "compare" && <Compare lang={lang} t={t} />}
        {tab === "confuse" && <Confuse lang={lang} t={t} />}
        {tab === "glossary" && <Glossary lang={lang} t={t} />}
        {tab === "examcase" && <ExamCaseRunner cases={ADP_EXAM_CASES} lang={lang} onBack={() => setTab("home")} />}
      </div>
      {toast && (
        <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", background: C.ink, color: "#fff", padding: "10px 18px", borderRadius: 22, fontSize: 13, fontWeight: 600, boxShadow: "0 4px 16px rgba(0,0,0,.25)", zIndex: 50 }}>{toast}</div>
      )}
      {confirmCfg && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.4)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 60 }} onClick={() => setConfirmCfg(null)}>
          <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: 14, padding: 22, maxWidth: 320, margin: 20, boxShadow: "0 8px 30px rgba(0,0,0,.3)" }}>
            <div style={{ fontSize: 14.5, lineHeight: 1.6, marginBottom: 18, color: C.ink }}>{confirmCfg.msg}</div>
            <div style={{ display: "flex", gap: 10 }}>
              <button onClick={() => setConfirmCfg(null)} style={{ flex: 1, padding: 10, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, fontWeight: 700, fontSize: 13.5, cursor: "pointer" }}>{t.cancel}</button>
              <button onClick={() => { confirmCfg.onOk(); setConfirmCfg(null); }} style={{ flex: 1, padding: 10, borderRadius: 9, border: "none", background: C.ng, color: "#fff", fontWeight: 700, fontSize: 13.5, cursor: "pointer" }}>{t.ok}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Home({ state, lang, t, reviewCount }) {
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);
  const weak = useMemo(() => DOMAINS.map(d => {
    const p = state.progress[d.id] || { correct: 0, attempts: 0 };
    const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
    return { ...d, rate, attempts: p.attempts };
  }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate), [state]);
  const dailyPct = Math.min(100, Math.round((state.meta.dailyCount / DAILY_GOAL) * 100));

  return (
    <div>
      <div style={{ marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={`${totals.c}/${totals.a}${t.questionsUnit}`} color={totals.rate >= PASS ? C.ok : C.primary} />
      </div>
      <Card title={t.domMastery}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}><Badge id={d.id} hue={d.hue} />{domName(d.id, lang)}</span>
                <span style={{ color: "#5f6368" }}>{d.pct}% · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>
      {weak.length > 0 && (
        <Card title={t.weakDomains}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <Badge id={d.id} hue={d.hue} />{domName(d.id, lang)} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
      {reviewCount > 0 && (
        <Card title={t.tabReview}>
          <div style={{ fontSize: 13, color: "#3c4043" }}>{t.reviewCount(reviewCount)}</div>
        </Card>
      )}
    </div>
  );
}

function Badge({ id, hue }) {
  return <span style={{ background: hue, color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{id}</span>;
}
function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#5f6368" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color }}>{value}</div>
      <div style={{ fontSize: 11, color: "#9aa0a6" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children, right }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep }}>{title}</div>
        {right}
      </div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

function QuestionCard({ Q, sel, onChoose, lang, reveal, t }) {
  const en = lang === "en";
  const q = en && Q.qEn ? Q.qEn : Q.q;
  const opts = en && Q.oEn ? Q.oEn : Q.o;
  const exp = en && Q.eEn ? Q.eEn : Q.e;
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
      <div style={{ fontSize: 11, color: "#fff", background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
        {Q.d} · {domName(Q.d, lang)}
      </div>
      <div style={{ fontSize: 15, fontWeight: 600, marginBottom: 14, lineHeight: 1.5 }}>{q}</div>
      {opts.map((opt, i) => {
        let bg = "#fff", bd = C.mid, col = C.ink;
        if (sel !== null) {
          if (reveal) {
            if (i === Q.a) { bg = "#E6F4EA"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FCE8E6"; bd = C.ng; col = C.ng; }
          } else if (i === sel) { bg = C.light; bd = C.primary; col = C.deep; }
        }
        return (
          <button key={i} onClick={() => onChoose(i)} disabled={sel !== null}
            style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.4, fontWeight: sel !== null && reveal && i === Q.a ? 700 : 500 }}>
            <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && (i === Q.a) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
          </button>
        );
      })}
      {sel !== null && reveal && (
        <div style={{ marginTop: 12, background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
          <strong style={{ color: sel === Q.a ? C.ok : C.ng }}>{sel === Q.a ? t.correct : t.incorrect}</strong>・{t.answerIs("ABCD"[Q.a])}{exp}
        </div>
      )}
    </div>
  );
}

function Quiz({ onAnswer, lang, t }) {
  const [filter, setFilter] = useState("ALL");
  const [orderMode, setOrderMode] = useState("fixed");
  const [order, setOrder] = useState([]);
  const [pos, setPos] = useState(0);
  const [picks, setPicks] = useState({});
  const [stats, setStats] = useState({ c: 0, a: 0 });

  const basePool = useMemo(() => filter === "ALL" ? BANK.map((_, i) => i) : BANK.map((_, i) => i).filter(i => BANK[i].d === filter), [filter]);

  const rebuild = (mode) => { setOrder(mode === "random" ? shuffle(basePool) : [...basePool]); setPos(0); setPicks({}); setStats({ c: 0, a: 0 }); };
  useEffect(() => { rebuild(orderMode); /* eslint-disable-next-line */ }, [basePool]);

  const setMode = (mode) => { setOrderMode(mode); rebuild(mode); };

  if (order.length === 0) return null;
  const idx = pos % order.length;
  const Q = BANK[order[idx]];
  const sel = picks[idx] ?? null;

  const choose = (i) => {
    if (sel !== null) return;
    const correct = i === Q.a;
    setPicks(p => ({ ...p, [idx]: i }));
    setStats(s => ({ c: s.c + (correct ? 1 : 0), a: s.a + 1 }));
    onAnswer(Q.d, correct);
  };
  const next = () => { if (pos + 1 < order.length) setPos(pos + 1); };
  const prev = () => { if (pos > 0) setPos(pos - 1); };
  const rate = stats.a ? Math.round((stats.c / stats.a) * 100) : 0;

  return (
    <div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{ padding: "5px 11px", borderRadius: 16, fontSize: 12, cursor: "pointer", border: `1px solid ${filter === k ? C.primary : C.mid}`, background: filter === k ? C.primary : "#fff", color: filter === k ? "#fff" : C.ink, fontWeight: 600 }}>
            {k === "ALL" ? t.allFields : k}
          </button>
        ))}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, fontSize: 12, color: "#5f6368" }}>
        <span style={{ fontWeight: 700, color: C.deep }}>{t.quizTotal(basePool.length)}</span>
        <div style={{ display: "flex", background: C.light, borderRadius: 18, padding: 3 }}>
          {[["fixed", t.orderFixed], ["random", t.orderRandom]].map(([k, label]) => (
            <button key={k} onClick={() => setMode(k)}
              style={{ border: "none", cursor: "pointer", borderRadius: 15, padding: "5px 14px", fontSize: 12, fontWeight: 700,
                background: orderMode === k ? "#fff" : "transparent", color: orderMode === k ? C.deep : "#5f6368",
                boxShadow: orderMode === k ? "0 1px 3px rgba(0,0,0,.12)" : "none" }}>
              {label}
            </button>
          ))}
        </div>
      </div>
      <div style={{ marginBottom: 10 }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: "#5f6368", marginBottom: 3 }}>
          <span>{t.quizProgress(idx + 1, order.length)}</span>
          {stats.a > 0 && <span>{t.sessionRate} {rate}%（{stats.c}/{stats.a}）</span>}
        </div>
        <Bar pct={Math.round((idx / order.length) * 100)} color={C.primary} />
      </div>
      <QuestionCard Q={Q} sel={sel} onChoose={choose} lang={lang} reveal t={t} />
      <div style={{ display: "flex", gap: 10, marginTop: 12 }}>
        <button onClick={prev} disabled={pos === 0}
          style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${pos === 0 ? C.mid : C.primary}`, background: "#fff", color: pos === 0 ? "#9aa0a6" : C.primary, fontSize: 14, fontWeight: 700, cursor: pos === 0 ? "not-allowed" : "pointer" }}>
          ← {t.prevQ}
        </button>
        <button onClick={next} disabled={pos + 1 >= order.length}
          style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: pos + 1 >= order.length ? C.mid : C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: pos + 1 >= order.length ? "not-allowed" : "pointer" }}>
          {t.nextQ}
        </button>
      </div>
    </div>
  );
}

function Exam({ onAnswer, lang, t, addToReview }) {
  const [setNo, setSetNo] = useState(null);
  const [mode, setMode] = useState("practice");
  const [kind, setKind] = useState("normal");
  const [phase, setPhase] = useState("select");
  const [pos, setPos] = useState(0);
  const [answers, setAnswers] = useState([]);
  const [sel, setSel] = useState(null);
  const [submitted, setSubmitted] = useState(false);

  const qs = setNo ? (kind === "domain" ? (DOMAIN_SETS[setNo] || []) : EXAM_SETS[setNo]) : [];
  const start = (n) => { setSetNo(n); setPos(0); setAnswers([]); setSel(null); setSubmitted(false); setPhase("run"); };

  const choose = (i) => {
    if (sel !== null) return;
    setSel(i);
    const Q = qs[pos];
    const correct = i === Q.a;
    onAnswer(Q.d, correct);
    setAnswers(a => [...a, { q: Q, sel: i, correct }]);
  };
  const next = () => {
    setSel(null);
    if (pos + 1 >= qs.length) finish();
    else setPos(pos + 1);
  };
  const finish = () => { setSubmitted(true); setPhase("result"); };

  useEffect(() => {
    if (phase === "result" && submitted) {
      const wrongIds = answers.filter(a => !a.correct).map(a => a.q.id);
      if (wrongIds.length) addToReview(wrongIds);
    }
    /* eslint-disable-next-line */
  }, [phase, submitted]);

  if (phase === "select") {
    return (
      <div>
        <Card title={t.examTitle}>
          <div style={{ fontSize: 13, lineHeight: 1.6, color: "#3c4043", marginBottom: 12 }}>{t.examDesc}</div>
          <div style={{ display: "flex", gap: 8 }}>
            {[["practice", t.modePractice, t.modePracticeDesc], ["exam", t.modeExam, t.modeExamDesc]].map(([k, label, desc]) => (
              <button key={k} onClick={() => setMode(k)}
                style={{ flex: 1, textAlign: "left", padding: "10px 12px", borderRadius: 10, cursor: "pointer",
                  border: mode === k ? `2px solid ${C.primary}` : `1.5px solid ${C.mid}`,
                  background: mode === k ? C.light : "#fff" }}>
                <div style={{ fontWeight: 700, fontSize: 13, color: mode === k ? C.deep : C.ink }}>{label}</div>
                <div style={{ fontSize: 11, color: "#5f6368", marginTop: 2, lineHeight: 1.4 }}>{desc}</div>
              </button>
            ))}
          </div>
        </Card>
        <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
          {[["normal", t.kindNormal], ["domain", t.kindDomain]].map(([kk, label]) => (
            <button key={kk} onClick={() => setKind(kk)}
              style={{ flex: 1, padding: "11px 8px", borderRadius: 10, fontSize: 13.5, fontWeight: 700, cursor: "pointer",
                border: `1.5px solid ${kind === kk ? C.primary : C.mid}`, background: kind === kk ? C.primary : "#fff", color: kind === kk ? "#fff" : C.ink }}>
              {label}
            </button>
          ))}
        </div>
        {kind === "domain" && DOMAINS.map(d => (
          <button key={d.id} onClick={() => start(d.id)}
            style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <span style={{ background: d.hue, color: "#fff", borderRadius: 5, padding: "3px 8px", fontSize: 12, fontWeight: 800 }}>{d.id}</span>
              <span>
                <span style={{ fontWeight: 700, fontSize: 14, color: C.deep }}>{lang === "en" ? d.nameEn : d.name}</span>
                <span style={{ fontSize: 12, color: "#9aa0a6", marginLeft: 8 }}>{t.domainSetCount(DOMAIN_SETS[d.id].length)}</span>
              </span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: C.primary, flexShrink: 0 }}>{t.start}</span>
          </button>
        ))}
        {kind === "normal" && [1, 2, 3, 4, 5].map(n => (
          <button key={n} onClick={() => SET_READY[n] && start(n)} disabled={!SET_READY[n]}
            style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${SET_READY[n] ? C.primary : C.mid}`, background: SET_READY[n] ? "#fff" : C.light, cursor: SET_READY[n] ? "pointer" : "not-allowed", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span>
              <span style={{ fontWeight: 700, fontSize: 15, color: SET_READY[n] ? C.deep : "#9aa0a6" }}>{t.setLabel} {n}</span>
              <span style={{ fontSize: 12, color: "#9aa0a6", marginLeft: 10 }}>65{t.questionsUnit}</span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: SET_READY[n] ? C.primary : "#bdc1c6" }}>{SET_READY[n] ? `${mode === "practice" ? t.modePractice : t.modeExam} ${t.start}` : t.preparing}</span>
          </button>
        ))}
      </div>
    );
  }

  if (phase === "result") {
    return <ExamResult answers={answers} setNo={setNo} onRetry={() => start(setNo)} onBack={() => setPhase("select")} lang={lang} t={t} />;
  }

  const Q = qs[pos];
  const answeredCount = answers.length;
  const correctSoFar = answers.filter(a => a.correct).length;
  const isLast = pos + 1 >= qs.length;
  const reveal = mode === "practice";
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, fontSize: 12.5, color: "#5f6368" }}>
        <button onClick={() => setPhase("select")} style={{ border: "none", background: "none", color: C.primary, fontWeight: 700, cursor: "pointer", padding: 0 }}>← {t.toSetSelect}</button>
        <span>{t.setLabel}{setNo}・{mode === "practice" ? t.modePractice : t.modeExam}・{t.questionNo(pos + 1, qs.length)}</span>
        {reveal ? <span>{t.scoreSoFar} {correctSoFar}/{answeredCount}</span> : <span style={{ width: 1 }} />}
      </div>
      <Bar pct={Math.round((pos / qs.length) * 100)} color={C.primary} />
      <div style={{ marginTop: 12 }}>
        <QuestionCard Q={Q} sel={sel} onChoose={choose} lang={lang} reveal={reveal} t={t} />
      </div>
      {sel !== null && (
        <button onClick={next} style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
          {isLast ? (reveal ? t.seeResult : t.submit) : t.nextQ}
        </button>
      )}
    </div>
  );
}

function ExamResult({ answers, setNo, onRetry, onBack, lang, t }) {
  const c = answers.filter(a => a.correct).length;
  const rate = Math.round((c / answers.length) * 100);
  const passed = rate >= PASS;
  const byDom = DOMAINS.map(d => {
    const sub = answers.filter(a => a.q.d === d.id);
    return { ...d, total: sub.length, correct: sub.filter(a => a.correct).length };
  }).filter(d => d.total > 0);
  const wrong = answers.filter(a => !a.correct);
  return (
    <div>
      <div style={{ background: passed ? "#E6F4EA" : "#FCE8E6", border: `2px solid ${passed ? C.ok : C.ng}`, borderRadius: 12, padding: 18, textAlign: "center", marginBottom: 14 }}>
        <div style={{ fontSize: 13, color: "#5f6368" }}>{t.setLabel}{setNo} {t.result}</div>
        <div style={{ fontSize: 40, fontWeight: 800, color: passed ? C.ok : C.ng }}>{rate}%</div>
        <div style={{ fontSize: 14, fontWeight: 700, color: passed ? C.ok : C.ng }}>{passed ? t.reachedPass : t.needMore(PASS - rate)}</div>
        <div style={{ fontSize: 12, color: "#5f6368", marginTop: 4 }}>{t.correctOf(c, answers.length)}</div>
      </div>
      {wrong.length > 0 && <div style={{ fontSize: 12.5, color: C.warn, fontWeight: 600, marginBottom: 12 }}>↪ {t.addedToReview(wrong.length)}</div>}
      <Card title={t.domBreakdown}>
        {byDom.map(d => (
          <div key={d.id} style={{ marginBottom: 9 }}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
              <span><Badge id={d.id} hue={d.hue} />{domName(d.id, lang)}</span>
              <strong style={{ color: d.correct / d.total >= PASS / 100 ? C.ok : C.ng }}>{d.correct}/{d.total}</strong>
            </div>
            <Bar pct={Math.round(d.correct / d.total * 100)} color={d.correct / d.total >= PASS / 100 ? C.ok : C.ng} />
          </div>
        ))}
      </Card>
      <Card title={t.wrongTitle(wrong.length)}>
        {wrong.length === 0 ? <div style={{ fontSize: 13, color: C.ok }}>{t.allCorrect}</div> : wrong.map((a, idx) => {
          const en = lang === "en";
          const q = en && a.q.qEn ? a.q.qEn : a.q.q;
          const opts = en && a.q.oEn ? a.q.oEn : a.q.o;
          const exp = en && a.q.eEn ? a.q.eEn : a.q.e;
          return (
          <div key={idx} style={{ padding: "8px 0", borderBottom: `1px solid ${C.light}`, fontSize: 13 }}>
            <div style={{ fontWeight: 600, marginBottom: 4 }}><Badge id={a.q.d} hue={DOM_HUE[a.q.d]} />{q}</div>
            <div style={{ color: C.ng, fontSize: 12.5 }}>{t.yourAnswer}：{"ABCD"[a.sel]} {opts[a.sel]}</div>
            <div style={{ color: C.ok, fontSize: 12.5 }}>{t.answer}：{"ABCD"[a.q.a]} {opts[a.q.a]}</div>
            <div style={{ color: "#5f6368", fontSize: 12.5, marginTop: 2 }}>{exp}</div>
          </div>
          );
        })}
      </Card>
      <div style={{ display: "flex", gap: 10 }}>
        <button onClick={onRetry} style={{ flex: 1, padding: 13, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.retrySet}</button>
        <button onClick={onBack} style={{ flex: 1, padding: 13, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.toSetSelect}</button>
      </div>
    </div>
  );
}

function Review({ review, onAnswer, removeFromReview, clearReview, askConfirm, lang, t }) {
  const [phase, setPhase] = useState("home");
  const [order, setOrder] = useState([]);
  const [pos, setPos] = useState(0);
  const [sel, setSel] = useState(null);

  const validIds = review.filter(id => BANK_BY_ID[id]);
  const start = () => { setOrder(validIds); setPos(0); setSel(null); setPhase("run"); };

  if (phase === "home") {
    return (
      <div>
        <Card title={t.reviewTitle} right={validIds.length > 0 ? (
          <button onClick={() => askConfirm(t.reviewClearConfirm, clearReview)} style={{ border: `1px solid ${C.ng}`, background: "#fff", color: C.ng, borderRadius: 16, padding: "4px 12px", fontSize: 11.5, fontWeight: 600, cursor: "pointer" }}>{t.reviewReset}</button>
        ) : null}>
          {validIds.length === 0 ? (
            <div style={{ fontSize: 13, color: "#5f6368", lineHeight: 1.6 }}>{t.reviewEmpty}</div>
          ) : (
            <div>
              <div style={{ fontSize: 14, fontWeight: 700, color: C.deep, marginBottom: 4 }}>{t.reviewCount(validIds.length)}</div>
              <div style={{ fontSize: 12, color: "#5f6368", marginBottom: 12 }}>{t.reviewMastered}</div>
              {DOMAINS.map(d => {
                const n = validIds.filter(id => BANK_BY_ID[id].d === d.id).length;
                if (!n) return null;
                return <div key={d.id} style={{ fontSize: 12.5, padding: "4px 0" }}><Badge id={d.id} hue={d.hue} />{domName(d.id, lang)} — <strong>{n}{t.questionsUnit}</strong></div>;
              })}
              <button onClick={start} style={{ marginTop: 12, width: "100%", padding: 13, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.reviewStart}</button>
            </div>
          )}
        </Card>
      </div>
    );
  }

  if (order.length === 0 || pos >= order.length) {
    return (
      <div style={{ textAlign: "center", padding: 20 }}>
        <div style={{ fontSize: 18, fontWeight: 800, color: C.ok, marginBottom: 10 }}>{t.reviewDone}</div>
        <button onClick={() => setPhase("home")} style={{ padding: "10px 18px", borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.backToReview}</button>
      </div>
    );
  }
  const Q = BANK_BY_ID[order[pos]];
  const choose = (i) => {
    if (sel !== null) return;
    setSel(i);
    const correct = i === Q.a;
    onAnswer(Q.d, correct);
    if (correct) removeFromReview(Q.id);
  };
  const next = () => { setSel(null); setPos(p => p + 1); };
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8, fontSize: 12.5, color: "#5f6368" }}>
        <button onClick={() => setPhase("home")} style={{ border: "none", background: "none", color: C.primary, fontWeight: 700, cursor: "pointer", padding: 0 }}>← {t.backToReview}</button>
        <span>{t.reviewRemaining(order.length - pos)}</span>
      </div>
      <Bar pct={Math.round((pos / order.length) * 100)} color={C.primary} />
      <div style={{ marginTop: 12 }}>
        <QuestionCard Q={Q} sel={sel} onChoose={choose} lang={lang} reveal t={t} />
      </div>
      {sel !== null && (
        <button onClick={next} style={{ marginTop: 12, width: "100%", padding: 12, borderRadius: 9, border: "none", background: C.primary, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{t.nextQ}</button>
      )}
    </div>
  );
}

function Confuse({ lang, t }) {
  const [q, setQ] = useState("");
  const list = CONFUSE.filter(c => !q || c.join("").toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder={t.confuseSearch} style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 14, boxSizing: "border-box" }} />
      {list.map((c, i) => (
        <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 13, marginBottom: 10 }}>
          <div style={{ fontWeight: 700, color: C.deep, fontSize: 13.5, marginBottom: 5 }}>{lang === "en" && c[3] ? c[3] : c[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5, marginBottom: 4 }}>{lang === "en" && c[4] ? c[4] : c[1]}</div>
          <div style={{ fontSize: 12, color: C.primary, fontWeight: 600 }}>{t.judgeAxis}：{lang === "en" && c[5] ? c[5] : c[2]}</div>
        </div>
      ))}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#9aa0a6", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Compare({ lang, t }) {
  const [q, setQ] = useState("");
  const en = lang === "en";
  const list = COMPARE.filter(c => { if (!q) return true; return [c.title, c.titleEn, ...c.cols, ...c.colsEn, ...c.rows.flat(), ...c.rowsEn.flat()].join("").toLowerCase().includes(q.toLowerCase()); });
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder={t.compareSearch} style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 14, boxSizing: "border-box" }} />
      {list.map((c, ci) => {
        const cols = en ? c.colsEn : c.cols; const rows = en ? c.rowsEn : c.rows;
        return (
          <div key={ci} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{en ? c.titleEn : c.title}</div>
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5, minWidth: cols.length > 2 ? 420 : 0 }}>
                <thead><tr style={{ background: C.light }}>
                  <th style={{ textAlign: "left", padding: "8px 10px", borderBottom: `2px solid ${C.mid}` }}></th>
                  {cols.map((col, i) => <th key={i} style={{ textAlign: "left", padding: "8px 10px", borderBottom: `2px solid ${C.mid}`, color: C.deep, fontWeight: 700 }}>{col}</th>)}
                </tr></thead>
                <tbody>{rows.map((row, ri) => (
                  <tr key={ri}>
                    <td style={{ padding: "8px 10px", borderBottom: `1px solid ${C.light}`, fontWeight: 700, whiteSpace: "nowrap" }}>{row[0]}</td>
                    {row.slice(1).map((cell, i) => <td key={i} style={{ padding: "8px 10px", borderBottom: `1px solid ${C.light}`, color: "#3c4043", lineHeight: 1.5 }}>{cell}</td>)}
                  </tr>
                ))}</tbody>
              </table>
            </div>
          </div>
        );
      })}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#9aa0a6", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Diagrams({ lang, t }) {
  const [open, setOpen] = useState("");
  const Section = ({ id, title, badge, children }) => (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, marginBottom: 12, overflow: "hidden" }}>
      <button onClick={() => setOpen(open === id ? "" : id)} style={{ width: "100%", textAlign: "left", padding: "13px 15px", border: "none", background: open === id ? C.light : "#fff", color: C.deep, fontWeight: 700, fontSize: 13.5, cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span><span style={{ background: C.primary, color: "#fff", borderRadius: 5, fontSize: 10, padding: "2px 6px", marginRight: 8 }}>{badge}</span>{title}</span><span>{open === id ? "−" : "+"}</span>
      </button>
      {open === id && <div style={{ padding: 15, borderTop: `1px solid ${C.light}` }}>{children}</div>}
    </div>
  );
  return (
    <div>
      <div style={{ fontSize: 12, color: "#9aa0a6", marginBottom: 10 }}>{t.diagIntro}</div>
      <Section id="domains" badge={lang==="en"?"Weights":"比率"} title={lang==="en"?"Exam weight by domain":"4ドメインの出題比率"}><DomainBars lang={lang} /></Section>
      <Section id="hierarchy" badge={lang==="en"?"Hierarchy":"階層"} title={lang==="en"?"Service map (expandable tree)":"サービス階層（展開ツリー）"}><InteractiveTree data={lang==="en"?SVC_TREE_EN:SVC_TREE} /></Section>
      <Section id="ladder" badge={lang==="en"?"Up/Down":"上下"} title={lang==="en"?"Storage class hierarchy by cost/access":"ストレージクラスの上下関係（コスト/頻度）"}><StorageLadder lang={lang} /></Section>
      <Section id="parallel" badge={lang==="en"?"Parallel":"並列"} title={lang==="en"?"Parallel transform tools (compare side by side)":"変換ツールの並列関係（横並び比較）"}><ParallelTools lang={lang} /></Section>
      <Section id="flow" badge={lang==="en"?"Flow":"フロー"} title={lang==="en"?"Data lifecycle flow (tap each stage)":"データ ライフサイクルのフロー（各工程をタップ）"}><LifecycleFlow lang={lang} /></Section>
      <Section id="concept" badge={lang==="en"?"Concept":"概念"} title={lang==="en"?"Encryption key models (concept map)":"暗号鍵モデルの概念図"}><KeyConcept lang={lang} /></Section>
      <Section id="tree2" badge={lang==="en"?"Decision":"決定木"} title={lang==="en"?"Storage selection (decision tree)":"ストレージ選択の決定木"}><StorageTree lang={lang} /></Section>
    </div>
  );
}

