function NovaRule({ margin }) {
  return (
    <div
      style={{
        height: 1,
        background: `linear-gradient(90deg, ${NOVA.accent} 0%, ${NOVA.line} 35%, ${NOVA.line} 100%)`,
        margin: margin || "0",
      }}
    />
  );
}

function NovaComingSoon({ station, lang }) {
  const Icon = station.Icon;
  const label =
    lang === "ja"
      ? { title: lang === "ja" ? station.ja : station.en, msg: "コンテンツは準備中です。近日中に追加予定です。" }
      : { title: station.en, msg: "Content is coming soon." };
  return (
    <div
      style={{
        minHeight: "calc(100vh - 46px)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: 18,
        fontFamily: NOVA_SANS,
        color: NOVA.ink,
        textAlign: "center",
        padding: 40,
      }}
    >
      <Icon color={station.accent} size={56} />
      <div style={{ fontFamily: NOVA_SERIF, fontSize: 26 }}>{label.title}</div>
      <div style={{ fontSize: 14, color: NOVA.sub }}>{label.msg}</div>
    </div>
  );
}

function NovaStationRow({ st, lang, onEnter }) {
  const [hover, setHover] = useState(false);
  const Icon = st.Icon;
  return (
    <div
      className="nova-row"
      onClick={onEnter}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        cursor: "pointer",
        display: "flex",
        alignItems: "center",
        gap: 26,
        flex: 1,
        padding: "16px 6px",
        borderBottom: `1px solid ${NOVA.line}`,
        borderLeft: `2px solid ${hover ? st.accent : "transparent"}`,
        background: hover ? NOVA.panelSoft : "transparent",
        transition: "background 0.25s ease, border-color 0.25s ease, padding-left 0.25s ease",
        paddingLeft: hover ? 22 : 16,
      }}
    >
      <div
        className="nova-icon"
        style={{
          width: 52,
          flexShrink: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <Icon color={hover ? st.accent : NOVA.faint} size={30} />
      </div>

      <div style={{ flex: 1, minWidth: 0 }}>
        <div
          className="nova-title"
          style={{
            fontFamily: NOVA_SERIF,
            fontSize: 22,
            color: NOVA.ink,
            letterSpacing: 0.2,
          }}
        >
          {lang === "ja" ? st.ja : st.en}
        </div>
      </div>

      <div
        className="nova-tag"
        style={{
          fontFamily: NOVA_SANS,
          fontSize: 11,
          letterSpacing: 1,
          color: NOVA.sub,
          border: `1px solid ${NOVA.line}`,
          borderRadius: 999,
          padding: "4px 12px",
          whiteSpace: "nowrap",
          flexShrink: 0,
        }}
      >
        {lang === "ja" ? st.tagJa : st.tagEn}
      </div>

      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexShrink: 0,
          transition: "transform 0.25s ease",
          transform: hover ? "translateX(4px)" : "translateX(0)",
        }}
      >
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
          <path
            d="M5 12H19M19 12L13 6M19 12L13 18"
            stroke={hover ? st.accent : NOVA.faint}
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ transition: "stroke 0.25s ease" }}
          />
        </svg>
      </div>
    </div>
  );
}

const NOVA_RESPONSIVE_CSS = `
@media (max-width: 480px) {
  .nova-container { padding-left: 16px !important; padding-right: 16px !important; }
  .nova-row { gap: 14px !important; padding-top: 14px !important; padding-bottom: 14px !important; }
  .nova-icon { width: 38px !important; }
  .nova-title { font-size: 17px !important; }
  .nova-tag { font-size: 9.5px !important; padding: 3px 8px !important; letter-spacing: 0.5px !important; }
  .nova-masthead-title { font-size: 17px !important; letter-spacing: 0.8px !important; }
}
`;

function ProjectNova() {
  const [lang, setLang] = useState("ja");
  const [active, setActive] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("nova_lang_v1");
        if (res && (res.value === "ja" || res.value === "en")) setLang(res.value);
      } catch (e) {}
    })();
  }, []);

  const toggleLang = () => {
    const next = lang === "ja" ? "en" : "ja";
    setLang(next);
    window.storage.set("nova_lang_v1", next).catch(() => {});
  };

  const L = NOVA_L[lang];
  const activeStation = NOVA_STATIONS.find((s) => s.id === active);

  let hubEl = null;
  if (active === "finance") hubEl = <FinanceHubModule />;
  else if (active === "megatech") hubEl = <MegaTechHubModule />;
  else if (active === "consulting") hubEl = <ConsultingHubModule />;
  else if (active === "certification") hubEl = <CertHubModule />;
  else if (active === "languagehub") hubEl = <LanguageHubModule />;
  else if (active === "booksummary") hubEl = <BookSummaryModule />;
  else if (active === "tracker") hubEl = <LearningTrackerModule />;
  else if (active === "anythingmemo") hubEl = <AnythingMemoModule />;
  else if (active === "linguisticshub") hubEl = <LinguisticsHubModule />;

  let content;

  if (hubEl) {
    content = (
      <div style={{ minHeight: "100vh", background: NOVA.bg }}>
        <div
          style={{
            position: "sticky",
            top: 0,
            zIndex: 9999,
            height: 46,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "0 18px",
            background: "rgba(255,255,255,0.94)",
            backdropFilter: "blur(8px)",
            borderBottom: `1px solid ${NOVA.line}`,
            fontFamily: NOVA_SANS,
          }}
        >
          <button
            onClick={() => setActive(null)}
            style={{
              background: "transparent",
              border: "none",
              color: NOVA.sub,
              fontSize: 13,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "6px 0",
            }}
            onMouseEnter={(e) => (e.currentTarget.style.color = NOVA.accent)}
            onMouseLeave={(e) => (e.currentTarget.style.color = NOVA.sub)}
          >
            <span style={{ fontSize: 15 }}>←</span> {L.back}
          </button>
          <div
            style={{
              fontSize: 11,
              letterSpacing: 1.5,
              color: activeStation ? activeStation.accent : NOVA.sub,
            }}
          >
            {activeStation ? (lang === "ja" ? activeStation.ja : activeStation.en) : ""}
          </div>
        </div>
        <div>{hubEl}</div>
      </div>
    );
  } else {
    content = (
      <div
        style={{
          position: "relative",
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          background: NOVA.bg,
          color: NOVA.ink,
          fontFamily: NOVA_SANS,
        }}
      >
        <div
          className="nova-container"
          style={{
            maxWidth: 760,
            width: "100%",
            margin: "0 auto",
            padding: "48px 28px 24px",
            display: "flex",
            flexDirection: "column",
            flex: 1,
          }}
        >
          {/* masthead */}
          <NovaRule />
          <div
            style={{
              position: "relative",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: "14px 0",
            }}
          >
            <div
              className="nova-masthead-title"
              style={{ fontSize: 22, letterSpacing: 1.5, color: NOVA.accent, fontWeight: 600 }}
            >
              {L.masthead}
            </div>
            <button
              onClick={toggleLang}
              style={{
                position: "absolute",
                right: 0,
                background: "transparent",
                border: `1px solid ${NOVA.line}`,
                color: NOVA.sub,
                borderRadius: 3,
                padding: "5px 13px",
                fontSize: 11,
                letterSpacing: 1,
                cursor: "pointer",
              }}
            >
              {L.langBtn}
            </button>
          </div>
          <NovaRule />

          <div style={{ fontSize: 11, letterSpacing: 2, color: NOVA.faint, margin: "28px 0 4px" }}>
            {L.index}
          </div>
          <NovaRule margin="0 0 4px" />

          <div style={{ flex: 1, display: "flex", flexDirection: "column" }}>
            {NOVA_STATIONS.map((st) => (
              <NovaStationRow key={st.id} st={st} lang={lang} onEnter={() => setActive(st.id)} />
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ background: NOVA.bg }}>
      <style>{NOVA_FONTS}</style>
      <style>{NOVA_RESPONSIVE_CSS}</style>
      {content}
    </div>
  );
}

export default ProjectNova;
